QW.lxloaded(15,{"ضلل":{"mf":"الضَّلَالُ: العدولُ عن الطّريق المستقيم، ويضادّه الهداية، قال تعالى: فَمَنِ اهْتَدى فَإِنَّما يَهْتَدِي لِنَفْسِهِ وَمَنْ ضَلَّ فَإِنَّما يَضِلُّ عَلَيْها<br>[الإسراء/ ١٥]، ويقال الضَّلَالُ لكلّ عدولٍ عن المنهج، عمدا كان أو سهوا، يسيرا كان أو كثيرا، فإنّ الطّريق المستقيم الذي هو المرتضى<br><br>صعب جدا، قال النبيّ صلّى الله عليه وسلم: <strong>«استقيموا ولن تُحْصُوا»</strong> <strong>«١»</strong> وقال بعض الحكماء: كوننا مصيبين من وجه وكوننا ضَالِّينَ من وجوه كثيرة، فإنّ الاستقامة والصّواب يجري مجرى المقرطس من المرمى، وما عداه من الجوانب كلّها ضَلَالٌ.<br>ولما قلنا روي عن بعض الصالحين أنه رأى النبيّ صلّى الله عليه وسلم في منامه فقال: يا رسول الله يروى لنا أنّك قلت: <strong>«شيّبتني سورة هود وأخواتها فما الذي شيّبك منها؟ فقال: قوله: فَاسْتَقِمْ كَما أُمِرْتَ»</strong> <strong>«٢»</strong>. وإذا كان الضَّلَالُ تركَ الطّريق المستقيم عمدا كان أو سهوا، قليلا كان أو كثيرا، صحّ أن يستعمل لفظ الضَّلَالِ ممّن يكون منه خطأ ما، ولذلك نسب الضَّلَالُ إلى الأنبياء، وإلى الكفّار، وإن كان بين الضَّلَالَيْنِ بون بعيد، ألا ترى أنه قال في النّبي صلّى الله عليه وسلم: وَوَجَدَكَ ضَالًّا فَهَدى<br>[الضحى/ ٧]، أي: غير مهتد لما سيق إليك من النّبوّة. وقال في يعقوب: إِنَّكَ لَفِي ضَلالِكَ الْقَدِيمِ<br><strong>[يوسف/ ٩٥]، وقال أولاده:</strong><br>إِنَّ أَبانا لَفِي ضَلالٍ مُبِينٍ [يوسف/ ٨]، إشارة إلى شغفه بيوسف وشوقه إليه، وكذلك:<br>قَدْ شَغَفَها حُبًّا إِنَّا لَنَراها فِي ضَلالٍ مُبِينٍ [يوسف/ ٣٠]، وقال عن موسى عليه السلام: فَعَلْتُها إِذاً وَأَنَا مِنَ الضَّالِّينَ<br>[الشعراء/ ٢٠]، تنبيه أنّ ذلك منه سهو، وقوله: أَنْ تَضِلَّ إِحْداهُما<br>[البقرة/ ٢٨٢]، أي: تنسى، وذلك من النّسيان الموضوع عن الإنسان. والضَّلَالُ من وجه آخر ضربان: ضَلَالٌ في العلوم النّظريّة، كالضَّلَالِ في معرفة الله ووحدانيّته، ومعرفة النّبوّة، ونحوهما المشار إليهما بقوله: وَمَنْ يَكْفُرْ بِاللَّهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ فَقَدْ ضَلَّ ضَلالًا بَعِيداً<br>[النساء/ ١٣٦]. وضَلَالٌ في العلوم العمليّة، كمعرفة الأحكام الشّرعيّة التي هي العبادات، والضَّلَالُ البعيدُ إشارةٌ إلى ما هو كفر كقوله على ما تقدّم من قوله: وَمَنْ يَكْفُرْ بِاللَّهِ [النساء/ ١٣٦]، وقوله: إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ قَدْ ضَلُّوا ضَلالًا بَعِيداً<br>[النساء/ ١٦٧]، وكقوله: فِي الْعَذابِ وَالضَّلالِ الْبَعِيدِ<br>[سبأ/ ٨]، أي: في عقوبة الضَّلَالِ البعيدِ، وعلى ذلك قوله: إِنْ أَنْتُمْ إِلَّا فِي ضَلالٍ كَبِيرٍ<br>[الملك/ ٩]، قَدْ ضَلُّوا مِنْ قَبْلُ وَأَضَلُّوا كَثِيراً وَضَلُّوا عَنْ سَواءِ السَّبِيلِ<br>[المائدة/ ٧٧]، وقوله: أَإِذا ضَلَلْنا فِي الْأَرْضِ<br>[السجدة/ ١٠]، كناية عن الموت واستحالة البدن. وقوله:<br><br>وَلَا الضَّالِّينَ<br>[الفاتحة/ ٧]، فقد قيل: عني بِالضَّالِّينَ النّصارى <strong>«١»</strong>. وقوله: فِي كِتابٍ لا يَضِلُّ رَبِّي وَلا يَنْسى<br>[طه/ ٥٢]، أي: لا يَضِلُّ عن ربّي، ولا يَضِلُّ ربّي عنه: أي: لا يغفله، وقوله: أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ<br>[الفيل/ ٢]، أي: في باطل وإِضْلَالٍ لأنفسهم.<br>والإِضْلَالُ ضربان: أحدهما: أن يكون سببه الضَّلَالُ، وذلك على وجهين: إمّا بأن يَضِلَّ عنك الشيءُ كقولك: أَضْلَلْتُ البعيرَ، أي: ضَلَّ عنّي، وإمّا أن تحكم بِضَلَالِهِ، والضَّلَالُ في هذين سبب الإِضْلَالِ.<br>والضّرب الثاني: أن يكون الإِضْلَالُ سببا لِلضَّلَالِ، وهو أن يزيّن للإنسان الباطل ليضلّ كقوله: لَهَمَّتْ طائِفَةٌ مِنْهُمْ أَنْ يُضِلُّوكَ وَما يُضِلُّونَ إِلَّا أَنْفُسَهُمْ<br>[النساء/ ١١٣]، أي يتحرّون أفعالا يقصدون بها أن تَضِلَّ، فلا يحصل من فعلهم ذلك إلّا ما فيه ضَلَالُ أنفسِهِم، وقال عن الشيطان: وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ<br>[النساء/ ١١٩]، وقال في الشّيطان: وَلَقَدْ أَضَلَّ مِنْكُمْ جِبِلًّا كَثِيراً<br>[يس/ ٦٢]، وَيُرِيدُ الشَّيْطانُ أَنْ يُضِلَّهُمْ ضَلالًا بَعِيداً<br>[النساء/ ٦٠]، وَلا تَتَّبِعِ الْهَوى فَيُضِلَّكَ عَنْ سَبِيلِ اللَّهِ<br>[ص/ ٢٦]، وإِضْلَالُ اللهِ تعالى للإنسان على أحد وجهين:<br>أحدهما أن يكون سببُهُ الضَّلَالَ، وهو أن يَضِلَّ الإنسانُ فيحكم الله عليه بذلك في الدّنيا، ويعدل به عن طريق الجنّة إلى النار في الآخرة، وذلك إِضْلَالٌ هو حقٌّ وعدلٌ، فالحكم على الضَّالِّ بضَلَالِهِ والعدول به عن طريق الجنّة إلى النار عدل وحقّ.<br>والثاني من إِضْلَالِ اللهِ: هو أنّ الله تعالى وضع جبلّة الإنسان على هيئة إذا راعى طريقا، محمودا كان أو مذموما، ألفه واستطابه ولزمه، وتعذّر صرفه وانصرافه عنه، ويصير ذلك كالطّبع الذي يأبى على الناقل، ولذلك قيل: العادة طبع ثان <strong>«٢»</strong>. وهذه القوّة في الإنسان فعل إلهيّ، وإذا كان كذلك- وقد ذكر في غير هذا الموضع أنّ كلّ شيء يكون سببا في وقوع فعل- صحّ نسبة ذلك الفعل إليه، فصحّ أن ينسب ضلال العبد إلى الله من هذا الوجه، فيقال: أَضَلَّهُ اللهُ لا على الوجه الذي يتصوّره الجهلة، ولما قلناه جعل الإِضْلَالَ المنسوب إلى نفسه للكافر والفاسق دون المؤمن، بل نفى عن نفسه إِضْلَالَ المؤمنِ فقال:<br>وَما كانَ اللَّهُ لِيُضِلَّ قَوْماً بَعْدَ إِذْ هَداهُمْ<br>[التوبة/ ١١٥]، فَلَنْ يُضِلَّ أَعْمالَهُمْ سَيَهْدِيهِمْ<br>[محمد/ ٤- ٥]، وقال في الكافر<br><br>والفاسق: فَتَعْساً لَهُمْ وَأَضَلَّ أَعْمالَهُمْ<br>[محمد/ ٨]، وما يُضِلُّ بِهِ إِلَّا الْفاسِقِينَ<br>[البقرة/ ٢٦]، كَذلِكَ يُضِلُّ اللَّهُ الْكافِرِينَ [غافر/ ٧٤]، وَيُضِلُّ اللَّهُ الظَّالِمِينَ [إبراهيم/ ٢٧]، وعلى هذا النّحو تقليب الأفئدة في قوله: وَنُقَلِّبُ أَفْئِدَتَهُمْ [الأنعام/ ١١٠]، والختم على القلب في قوله: خَتَمَ اللَّهُ عَلى قُلُوبِهِمْ [البقرة/ ٧]، وزيادة المرض في قوله: فِي قُلُوبِهِمْ مَرَضٌ فَزادَهُمُ اللَّهُ مَرَضاً [البقرة/ ١٠].","mq":[["ضياع الشي وذهابه في غير حقه"],"الضاد واللام أصلٌ صحيح يدلُّ على معنًى واحد، وهو ضَياع الشئ وذهابُه فى غير حَقِّه. يقال ضَلّ يَضِلّ ويَضَلّ، لغتان. وكلُّ جائرٍ عن القصد ضالٌّ. والضَّلَال والضَّلَالَة بمعنى. ورجلٌ ضِلِّيل ومُضلَّل، إِذا كان صاحبَ ضَلَالٍ وباطل. وممّا يدُلُّ على أنّ أصل الضّلَال ما ذكرناه، قولُهم أُضِلّ الميّتُ، إذا"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَلَلْتُ</b> , (S, Mgh, * O, Msb, * K,) third pers. <span class=\"ar\">ضَلَّ</span>, (Mgh, Msb,) aor. <b class=\"ar\">ضَلِلَ</b> , (S, Mgh, O, Msb, K,) inf. n. <span class=\"ar\">ضَلَالٌ</span> and <span class=\"ar\">ضَلَالَةٌ</span>; (S, * O, * Msb;) and <span class=\"ar\">ضَلِلْتُ</span>, (S, Mgh, * O, Msb, * K,) third pers. as above; (Mgh;) the former of the dial. of Nejd, and the more chaste; the latter of the dial. of the people of El-'Áliyeh, (S, Msb, TA,) and of El- Hijáz, and Kr has mentioned <span class=\"ar\">ضِلِلْتُ</span> for <span class=\"ar\">ضَلِلْتُ</span> as heard from the tribe of Temeem; (TA;) <i>I erred, strayed,</i> or <i>went astray;</i> (Mgh, Msb;) <i>deviated from the right way</i> or <i>course,</i> or <i>from that which was right; missed,</i> or <i>lost, the right way;</i> or <i>lost my way;</i> <span class=\"ar\">ضَلَالٌ</span> and <span class=\"ar\">ضَلَالَةٌ</span> signifying the <i>contr. of</i> <span class=\"ar\">رَشَادٌ</span>, (S, O, TA,) and <span class=\"ar\">هُدًى</span>. (K, TA.) [See <span class=\"ar\">ضَلَالٌ</span> below.] Hence, in the Kur [xxxiv. 49], <span class=\"ar\">قُلْ إِنْ ضَلَلْتُ فِإِنَّمَا أَضِلُّ عَلَى نَفْسِى</span> [<i>Say thou, If I err, I shall err only against myself,</i> i. e., to my own hurt]. (O, Msb. [See also x. 108 and xvii. 16 of the Kur.]) One says also, <span class=\"ar\">ضَلَّ ضَلَالُهُ</span> [app. <i>His error became error indeed;</i> a phrase similar to <span class=\"ar\">جَدَّ جِدُّهُ</span>, q. v.: or <i>his erring passed away;</i> see 4, latter part]. (TA.) And <span class=\"ar\">ضَلَّ عَنِ القَصْدِ</span> <i>He deviated from the right way</i> or <i>course.</i> (TA.) And the verb is trans. as well as intrans.: you say, <span class=\"ar\">ضَلَّ الطَّرِيقَ</span>, and <span class=\"ar\">ضَلَّ عَنْهُ</span>, aor. <b class=\"ar\">ضَلِلَ</b> and <b class=\"ar\">ضَلَلَ</b> , (Mgh, Msb,) inf. ns. as above, meaning <i>He erred, strayed,</i> or <i>went astray, from the road,</i> or <i>way;</i> (Msb;) <i>he did not find the way to the road:</i> (Mgh, Msb:) and of anything stationary, if you miss the place thereof, you say <span class=\"ar\">ضَلَلْتُهُ</span> and <span class=\"ar\">ضَلِلْتُهُ</span>: (Az, Msb:) or you say, <span class=\"ar\">ضَلِلْتُ الطَّرِيقَ</span>, (K,) or <span class=\"ar\">ضَلِلْتُ المَسْجِدَ</span>, and <span class=\"ar\">الدَّارَ</span>, (ISk, S, O,) [<i>I missed,</i> or <i>lost, the right way to the road,</i> or <i>the mosque,</i> and <i>the house,</i>] when you know not the place thereof: (ISk, S, O:) and in like manner, anything stationary, to which one does not find the way: (ISk, S, O, K:) and AA says the like: but that one says of a thing that falls from his hand, and a thing that quits its place, <span class=\"ar\"> <span class=\"ar\">أَضْلَلْتُهُ</span></span>, (IB, TA,) which means <i>I lost it, and knew not its place;</i> meaning, for instance, a horse, or she-camel, or the like: (Az, Msb:) [thus] one says, <span class=\"ar\">أَضْلَلْتُ بِعِيرِى</span> [<i>I lost my camel, and knew not his place,</i>] (AA, ISk, S, IB, O) when his shank has been tied up to his arm and one does not find the way to him, and when he has been left loose and has gone away whither one knows not: (AA, IB, TA:) but Yoo differs from others respecting this case; for, accord. to him, one says, <span class=\"ar\">اضلّ</span> <span class=\"ar\">فُلَانٌ بَعِيرَهُ</span> and also <span class=\"ar\">ضَلَّهُ</span>, in the same sense; (O, TA;) and the like is said in the K: (TA:) and it is also said in the Bári' that when you seek an animal and miss its place and find not the way to it, it is regarded as in the category of stationary things, and therefore you say <span class=\"ar\">ضَلِلْتُهُ</span>. (Msb.) -b2- <span class=\"ar\">ضَلَّ</span> signifies also <i>He was,</i> or <i>became, confounded,</i> or <i>perplexed, and unable to see his right course.</i> (Ibn-Es-Seed, TA.) -b3- Also, aor. <b class=\"ar\">ضَلِلَ</b> (S, O, K) and <b class=\"ar\">ضَلَلَ</b> , (K,) the pret. being like <span class=\"ar\">زَلَّ</span> and <span class=\"ar\">مَلَّ</span>, (TA,) inf. n. <span class=\"ar\">ضَلَال</span>, <i>It</i> (a thing, S, O, TA) <i>became lost;</i> [as though it went astray;] <i>it perished, came to nought,</i> or <i>passed away.</i> (S, O, K, TA.) Thus in the phrase <span class=\"ar\">ضَلَّ عَنِّى كَذَا</span> <i>Such a thing became lost from me.</i> (Mgh.) One says to him from whom pieces of money have dropped, <span class=\"ar\">قَدْ ضَلَّتْ عَنْكَ</span> [<i>They have become lost from thee</i>]. (TA.) And to him who has done a deed from which no profit has resulted, you say, <span class=\"ar\">قَد ضَلَّ سَعْيُكَ</span> (tropical:) [<i>Thy labour has been lost</i>]: the like occurs in the Kur xviii. 104, meaning <span class=\"ar\">ضَاعَ</span>. (TA, in two places.) -b4- And (tropical:) <i>He</i> (a man, TA) <i>died, and became dust and bones.</i> (K, TA.) In this sense the verb is used in the Kur xxxii. 9: but some there read, in the place of <span class=\"ar\">ضَلَلْنَا</span>, <span class=\"ar\">صَلِلْنَا</span> [q. v.], with <span class=\"ar\">ص</span>: (TA:) or the verb in that instance has the meaning here next following. (S.) -b5- And (assumed tropical:) <i>He,</i> or <i>it,</i> (a man, S, TA, or a camel, Msb, and a thing, TA,) <i>was,</i> or <i>became, unperceived</i> or <i>imperceptible, unapparent, latent, hidden</i> or <i>concealed,</i> or <i>absent,</i> (S, Msb, K, TA.) Hence the phrase, <span class=\"ar\">ضَلَّ المَآءُ فِى اللَّبَنِ</span> (tropical:) [<i>The water became unperceived,</i> or <i>concealed, in the milk</i>]. (TA.) One says of a road to which he has not been able to find the way, <span class=\"ar\">ضَلَّ عَنِّى</span> [<i>It has become hidden from me</i>]. (K, TA.) And hence also the saying of a man, as is related in a trad., (S, O, TA,) after his having charged his sons by saying to them, “ When I die, burn ye me; and when I shall have become ashes, pound me; then scatter me in the water: ” (O, TA:) <span class=\"ar\">لَعَلِّى أَضِلُّ ٱللّٰه</span> (S, O, TA) i. e. (assumed tropical:) <i>May-be, I shall be unperceived by God,</i> or <i>concealed from Him:</i> (S:) or <i>may-be, I shall be hidden,</i> or <i>absent, from God's punishment:</i> (O, TA:) or, as El-'Otbee says, <i>may-be, I shall escape God, and my place will be hidden from Him.</i> (TA.) And <span class=\"ar\">ضَلَّ</span> said of one forgetting means (assumed tropical:) <i>His memory became absent from him.</i> (O, Msb, TA.) <span class=\"ar\">أَنْ تَضِلَّ إِحْدَاهُمَا</span>, or <span class=\"ar\">إِنْ تَضِلَّ</span>, in the Kur [ii. 282], accord. to different readers, (TA,) in which instance <span class=\"ar\">أَنْ</span> and <span class=\"ar\">إِنْ</span> are syn., (Mughnee, [see <span class=\"ar\">أَنْ</span>, in p. 106, cols. 1 and 2,]) means <i>If one of them twain</i> [referring to women] <i>be absent from her memory:</i> or <i>if the memory of one of them twain be absent from her:</i> [or <i>if one of them twain err in her memory:</i>] or, accord. to Zj, the meaning of the verb in this case is that which next follows. (TA.) -b6- <span class=\"ar\">ضَلِلْتُ</span> <span class=\"ar\">الشَّىْءَ</span> also signifies (assumed tropical:) <i>I forgot the thing:</i> whence one says of a woman, <span class=\"ar\">ضَلَّتْ أَيَّامَ حَيْضِهَا</span> (assumed tropical:) [<i>She forgot the days of her menstruation</i>]; and so <span class=\"ar\"> <span class=\"ar\">أَضَلَّتْهَا</span></span>: (Mgh:) or <span class=\"ar\">ضَلَّ فُلَانًا</span> (assumed tropical:) <i>He was made,</i> or <i>caused, to forget such a one.</i> (K. [In the CK, <span class=\"ar\">اُنْسِيْهِ</span> is erroneously put for <span class=\"ar\">أُنْسِيَهُ</span>.]) It is said that <span class=\"ar\">لَا يَضِلُّ رَبِّى</span>, in the Kur xx. 54, means (assumed tropical:) <i>My Lord will not be unmindful:</i> or <i>nothing will escape Him.</i> (TA.) -b7- And one says, <span class=\"ar\">ضَلَّنِى فُلَانٌ</span>, (Msb, K,) or <span class=\"ar\">ضَلَّنِى فُلَانٌ فَلَمْ أَقْدَرْ عَلَيْهِ</span>, (O,) meaning <i>Such a one went away from me,</i> (O, Msb, K,) <i>and I was unable to compass him</i> [or <i>to find him</i>]: so in the Bári'. (Msb.) -A2- <span class=\"ar\">ضُلَّ</span>, as a verb of wonder: see <span class=\"ar\">ضُلٌّ</span>.</p><p><b>2.</b> <b class=\"ar\">ضلَلهُ</b> , (S, MA, O, K,) inf. n. <span class=\"ar\">تَضْلِيلٌ</span> and <span class=\"ar\">تَضْلَالٌ</span>, (K,) <i>He,</i> or <i>it, made,</i> or <i>caused, him to pursue a course that led to error,</i> or <i>deviation from the right way:</i> (K: [see also 4:]) <i>he,</i> or <i>it, led him astray; seduced him:</i> (MA:) [or] <i>he attributed,</i> or <i>imputed, to him error,</i> or <i>deviation from the right way.</i> (S, MA, O.) <span class=\"ar\">ضُلِّلَ سَعْيُهُمْ</span>, a phrase used by a poet, means <i>Error,</i> or <i>deviation from the right way, was attributed to their labour;</i> because they did not reach their goal. (Ham p. 771.) -b2- [Hence,] one says, <span class=\"ar\">ضَلِّلْ مَالَكَ</span> <i>Send forth,</i> or <i>set free, thy cattle to pasture,</i> or <i>to pasture where they please, by themselves.</i> (O.) -b3- See also the next paragraph.</p><p><b>4.</b> <b class=\"ar\">اضلّهُ</b> , inf. n. <span class=\"ar\">إِضْلَالٌ</span>, <i>He,</i> or <i>it, made him,</i> or <i>caused him, to err, stray,</i> or <i>go astray; to deviate from the right way</i> or <i>course,</i> or <i>from that which was right; to miss,</i> or <i>lose, the right way;</i> or <i>to lose his way.</i> (Az, TA.) [See also 2, first sentence.] <span class=\"ar\">الإِضْلَالُ</span> is of two sorts: one of these is the consequence of erring, or straying; either as in the case in which one says <span class=\"ar\">أَضْلَلْتُ البَعِيرَ</span> (expl. above, see 1, former half); or the decreeing that one shall err, or stray, &amp;c., because he has done so already, and this is sometimes the case when the <span class=\"ar\">إِضْلَال</span> of a man is attributed to God: the other sort is the embellishing [or commending] to a man that which is false, or wrong, or vain, in order that he may err, or stray, &amp;c.: and God's <span class=\"ar\">إِضْلَال</span> of a man is of two sorts; one of which has been expl. above; the other is God's so constituting man that when he observes [and pursues] a certain course, or way, [of acting or the like], whether it be such as is commended or such as is discommended, he habituates himself to it, and esteems it pleasant, and keeps to it, and finds it difficult to turn from it, wherefore it is said that custom is a second nature. (Er-Rághib, TA.) -b2- Also <i>He,</i> or <i>it, made,</i> or <i>caused, him,</i> or <i>it, to perish,</i> or <i>become lost;</i> syn. <span class=\"ar\">أَهْلَكَهُ</span>, (S, TA,) and <span class=\"ar\">أَضَاعَهُ</span>, (El-Fárábee, S, O, Msb,) or <span class=\"ar\">ضَيَّعَهُ</span>; (TA;) [<span class=\"ar\">اضاعهُ</span> and <span class=\"ar\">ضيّعهُ</span> signifying the same; and so <span class=\"ar\">اضلّهُ</span> and <span class=\"ar\"> <span class=\"ar\">ضللّٰهُ</span></span>; whence,] <span class=\"ar\">أَلَمْ يَجْعَلْ كَيْدَهُمْ</span> <span class=\"ar\">فِى تَضْلِيلٍ</span>, in the Kur cv. 2, means [<i>Did He not make their plot to be</i> such as ended] <i>in a causing to perish,</i> or <i>become lost,</i> (<span class=\"ar\">فِى تَضْيِيعٍ</span>,) and <i>in annulment?</i> (Ksh, Bd.) <span class=\"ar\">أَضَلَّ أَعْمَالَهُمْ</span>, in the Kur [xlvii. 1 and 9, which may be rendered (assumed tropical:) <i>He will cause their works to be lost,</i> or <i>to be of no effect</i>], means, accord. to Aboo-Is-hák, <i>He will not recompense them for their</i> good <i>works;</i> the phrase being similar to the saying <span class=\"ar\">قَدْ ضَلَّ سَعْيُكَ</span> [expl. above]. (TA.) And <span class=\"ar\">أَضَلَّ ٱللّٰهُ ضَلَالَكَ</span> (assumed tropical:) [<i>May God make thine erring to be no more,</i> or <i>to come to an end,</i>] is expl. by ISk as meaning <i>may thine erring pass away from thee, so that thou shalt not err;</i> and he adds that the saying <span class=\"ar\">مَلَّ مَلَالُكَ</span> means <span class=\"ar\">ذَهَبَ</span> <span class=\"ar\">عَنْكَ حَتَّى لَا تَمَلَّ</span>. (TA.) -b3- Also (tropical:) <i>He buried,</i> and <i>hid,</i> or <i>concealed, him,</i> or <i>it.</i> (K, TA.) You say, <span class=\"ar\">أُضِلَّ المَيِّتُ</span> (tropical:) <i>The dead was buried.</i> (S, O.) The phrase <span class=\"ar\">أَضَلَّتْ بِهِ أُمُّهُ</span>, meaning (tropical:) <i>His mother buried him,</i> in a verse cited by IAar, is extr., or anomalous. (TA.) -b4- And <i>He found him to be erring, straying, going astray; deviating from the right way</i> or <i>course,</i> or <i>from that which was right; missing,</i> or <i>losing, the right way; losing his way; not rightly directed,</i> or <i>not finding the way to the truth:</i> like as one says <span class=\"ar\">أَحْمَدَهُ</span>, and <span class=\"ar\">أَبْخَلَهُ</span>. (TA.) -b5- And you say, <span class=\"ar\">أَضَلَّنِى كَذَا</span>, meaning (assumed tropical:) <i>Such a thing was,</i> or <i>became, beyond my power,</i> or <i>compass.</i> (IAar, Msb, TA.) -b6- See also 1, near the end.</p><p><b>5.</b> <b class=\"ar\">تظلّل</b> <i>It went away:</i> so in the saying, <span class=\"ar\">تضلّل المَآءُ مِنْ تَحْتِ الحَجَرِ</span> [<i>The water went away from beneath the stone</i>]. (O, TA.)</p><p><b>6.</b> <b class=\"ar\">تضالّ</b> <i>He feigned himself to be erring, straying, going astray; deviating from the right way</i> or <i>course,</i> or <i>from that which was right; missing,</i> or <i>losing, the right way;</i> or <i>losing his way.</i> (O, TA.)</p><p><b>10.</b> <b class=\"ar\">استضلّ ضَلَالُهُ</b> <i>His erring demanded that he should err</i> [<i>the more</i>], <i>so that he did err</i> [<i>the more:</i> like as erring is said to be a cause of one's being made to err: see 4: and see also <span class=\"ar\">ضَلَّ ضَلَالُهُ</span>, near the beginning of the art.]: so in the saying of Aboo-Dhu-eyb, <span class=\"ar\">رَآهَا الفُؤَادُ فَٱسْتَضَلَّ ضَلَالُهُ</span> [<i>The heart beheld her, and his erring demanded that he should err</i> &amp;c.]. (Skr, S, TA.)</p><p><b class=\"ar\">ضَلٌّ</b> : see <span class=\"ar\">ضَلَالٌ</span>.</p><p><b class=\"ar\">ضُلٌّ</b> : see <span class=\"ar\">ضَلَالٌ</span>. -b2- [Also, app. as meaning <i>A lost state; a state of perishing, coming to nought,</i> or <i>passing away;</i>] a subst. from <span class=\"ar\">ضَلَّ</span> signifying <span class=\"ar\">ضَاعَ</span> and <span class=\"ar\">هَلَكَ</span>. (S, TA.) -b3- And hence [its usage, in the manner of a proper name, in] the saying, <span class=\"ar\">هُوَ ضُلُّ بْنُ ضُلٍّ</span>, (S,) which means, (S, O, K,) as also <span class=\"ar\">هُوَ ضِلُّ بْنُ <span class=\"ar\">ضِلٍّ</span></span>, (Ibn-'Abbád, O, K,) <i>He is the unknown, the son of the unknown;</i> (S, Z, O, K;) and in like manner, <span class=\"ar\"> <span class=\"ar\">الضَّلَالُ</span>بْنُ التَّلَالِ</span>; (S, O;) and <span class=\"ar\">قُلُّ بْنُ قُلٍّ</span>: (TA:) or <i>he is one in whom is no good:</i> (K:) or <i>he is one who persists in error.</i> (M, K.) -b4- [Hence also, perhaps, it is said that] <span class=\"ar\">يَا ضُلَّ مَا تَجْرِى بِهِ العَصَا</span> [in the CK <span class=\"ar\">ضَلَّ</span>] means <span class=\"ar\">يَا فَقْدَهُ</span> and <span class=\"ar\">يَا تَلَفَهُ</span> [i. e., app., <i>O the loss,</i> or <i>O the coming to nought, of that by reason of which</i> the mare <i>El-'Asà is running!</i>]: (K, TA:) a prov.; said by Kaseer Ibn-Saad to Jedheemeh El-Abrash, when he went with him to Ez-Zebbà; for when they were within her province, he repented, and Kaseer said to him, “ Mount this my horse, and escape upon him, for his dust will not be cloven [by the pursuer, ” i. e. he will not be overtaken]: (TA: [but the mare is thus made a male:]) or it was said by 'Amr Ibn-'Adee, when he saw El-'Asà, the mare of Jedheemeh, with Kaseer upon her: <span class=\"ar\">قَوْمُ</span> is suppressed after <span class=\"ar\">يا</span>; and <span class=\"ar\"> <span class=\"ar\">ضُلَّ</span></span> is of the forms [of verbs] denoting wonder, originally <span class=\"ar\">ضَلُلَ</span>, with damm, like <span class=\"ar\">حُبَّ</span> in the phrase <span class=\"ar\">حُبَّ بِفُلَانٍ</span>, originally <span class=\"ar\">حَبُبَ</span>; and the meaning of the prov. is, <i>O</i> people, <i>what a case of perdition is that by reason of which El-'Asà is running!</i> i. e., the death of Jedheemeh. (Meyd.) -b5- <span class=\"ar\">ضُلٌّ بِتَضْلَالٍ</span> [in CK <span class=\"ar\">ضَلٌّ</span>] means <i>A vain,</i> or <i>futile, thing:</i> (S, O, K:) [or <i>a vain, misleading thing;</i> <span class=\"ar\">تَضْلَالٌ</span> being an inf. n. of <span class=\"ar\">ضَلَّلَ</span>:] 'Amr Ibn-Shás El-Asadee says, <span class=\"ar\">تَذَكَّرْتُ لَيْلَى لَاتَ حِينَ ٱدِكَارِهَا</span> <span class=\"ar\">وَقَدْ حُنِىَ الأَضْلَاعُ ضُلٌّ بِتَضْلَالِ</span> [<i>I remembered Leylà when it was not a time for remembering her, the ribs having become bent</i> by the bending of the back with age: it was <i>a vain, misleading thing</i>]. (S, O.) -b6- <span class=\"ar\">ضُلُّ أَضْلَالٍ</span>: see <span class=\"ar\">ضِلَّةٌ</span>.</p><p><b class=\"ar\">هُوَ ضِلُّ بْنُ ضِلٍّ</b> : see <span class=\"ar\">ضُلٌّ</span>. -b2- <span class=\"ar\">ضِلُّ أَضْلَالٍ</span>: see <span class=\"ar\">ضِلَّةٌ</span>.</p><p><b class=\"ar\">ضَلَّةٌ</b> <i>Confusion,</i> or <i>perplexity, and inability to see the right course:</i> (K:) [or <i>error:</i> for] one says, <span class=\"ar\">فَعَلَ ذٰلِكَ ضَلَّةً</span> <i>He did that in error</i> (<span class=\"ar\">فِى</span> <span class=\"ar\">ضَلَالَةٍ</span>): and <span class=\"ar\">ذَهَبَ ضَلَّةً</span> <i>He went away not knowing whither he went:</i> (TA:) and <span class=\"ar\">فُلَانٌ يَلُومُنِى ضَلَّةً</span> <i>Such a one blames me wrongly:</i> (S, O:) [or, <i>behind my back,</i> or <i>in my absence:</i> for] <span class=\"ar\">ضَلَّةٌ</span> signifies also <i>speech respecting a person behind his back,</i> or <i>in his absence;</i> relating to good and to evil. (M, K, TA.) -A2- [Freytag explains it as signifying also <i>One in whom is no good,</i> on the authority of Meyd.]</p><p><b class=\"ar\">ضُلَّةٌ</b> <i>Skill in guiding,</i> or <i>directing aright, in journeying.</i> (Fr, K, * TA.)</p><p><b class=\"ar\">ضِلَّةٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>. -b2- [Hence,] <span class=\"ar\">هُوَ ٱبْنُهُ لِضِلَّةٍ</span> (tropical:) <i>He is his son unlawfully begotten,</i> or <i>not trueborn.</i> (AZ, A, K, TA.) -b3- <span class=\"ar\">ذَهَبَ دَمُهُ ضِلَّةً</span> (tropical:) <i>His blood went unrevenged,</i> or <i>without retaliation.</i> (K, TA.) -b4- And <span class=\"ar\">هُوَ تِبْعُ ضِلَّةٍ</span>, (Th, O, K, TA,) with kesr to the <span class=\"ar\">ت</span> and to the <span class=\"ar\">ض</span>, (TA,) [in the CK, erroneously, <span class=\"ar\">تَبَعُ</span>,] and <span class=\"ar\">تِبْعٌ ضِلَّةٌ</span>, (K, TA,) thus related by IAar, (TA,) but the former only accord. to Th, (TA in art. <span class=\"ar\">تبع</span>,) (assumed tropical:) <i>He is a follower of women:</i> (TA in that art.:) or <i>he is one in whom is no good, and with whom is no good:</i> (IAar, Th, TA:) or <i>he is a very cunning man</i> (<span class=\"ar\">دَاهِيَةٌ</span>), <i>one in whom is no good;</i> (IAar, O, K, TA;) and so <span class=\"ar\">تِبْعُ صِلَّةٍ</span>, (O, L, TA,) as some relate it; (L, TA;) and in like manner, <span class=\"ar\"> <span class=\"ar\">ضِلُّ</span>أَضْلَالٍ</span>, (Lh, O, K, TA,) and <span class=\"ar\"> <span class=\"ar\">ضُلُّ</span>أَضْلَالٍ</span>, (K, TA,) and <span class=\"ar\">صِلُّ</span> <span class=\"ar\">أَصْلَالٍ</span>, [q. v.,] which is with kesr only, (K, TA,) a phrase similar to <span class=\"ar\">ضِرُّ أَضْرَارٍ</span>. (TA in art. <span class=\"ar\">ضر</span>.)</p><p><b class=\"ar\">ضَلَلٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>. -b2- Also Water (O, K) <i>running</i> (K) <i>beneath a rock, which the sun does not reach:</i> (O, K:) one says <span class=\"ar\">مَآءٌ ضَلَلٌ</span>: (O:) or <i>running among trees.</i> (K.) [See also <span class=\"ar\">ضَلَلٌ</span>.]</p><p><b class=\"ar\">ضَلَالٌ</b> [an inf. n. of 1: used as a simple subst.,] <i>Error; contr. of</i> <span class=\"ar\">رَشَادٌ</span>, (S, O, TA,) and <i>of</i> <span class=\"ar\">هُدًى</span>; (K, TA;) as also <span class=\"ar\"> <span class=\"ar\">ضَلَالَةٌ</span></span>, (S, O, K,) and <span class=\"ar\"> <span class=\"ar\">ضَلٌّ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضُلٌّ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضِلَّةٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضَلَلٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضَلْضَلَةٌ</span></span>, (K,) and <span class=\"ar\"> <span class=\"ar\">ضُلَضِلَةٌ</span></span>, (O, TA,) and <span class=\"ar\"> <span class=\"ar\">أُضْلُولَةٌ</span></span>, (K,) of which last the pl. is <span class=\"ar\">أَضَالِيلُ</span>, (Lth, O, TA,) as in the saying <span class=\"ar\">تَمَادَى فِى أَضَالِيلِ الهَوَى</span> [<i>He persevered in the errors of love</i>], (TA,) or <span class=\"ar\">أَضَالِيلُ</span>, as some say, has no sing., or its sing. is supposed, or has been heard, and is <span class=\"ar\">أُضْلُولَةٌ</span> or <span class=\"ar\">أُضْلُولٌ</span> or <span class=\"ar\">إِضْلِيلٌ</span> or some other form: (MF, TA:) the primary signification of <span class=\"ar\">الضَّلَالُ</span> is <i>the going away from the right course,</i> or <i>direction:</i> (Ham p. 357:) or it signifies, accord. to Ibn-El-Kemál, <i>the loss,</i> or <i>missing, of that which brings,</i> or <i>conducts, to the object sought:</i> or, as some say, <i>the pursuing a way that will not bring,</i> or <i>conduct, to that object:</i> or, accord. to Er-Rághib, <i>the deviating from the right way:</i> and it is said to be <i>any deviation from that which is right, intentional</i> or <i>unintentional, little</i> or <i>much;</i> because the right and approved way is very difficult; wherefore it may be used of him who commits any mistake whatever, and is imputed to prophets and to unbelievers, though between the <span class=\"ar\">ضلال</span> of the former and that of the latter is a wide difference: and in another point of view, it is of two sorts; one is in the speculative departments of knowledge, as in acquaintance with the unity of God, and with the prophetic function or office, and the like, indicated in the Kur iv. 135; or it is in the practical departments of knowledge, as in acquaintance with the ordinances of the law, that is, religious services. (TA.) -b2- Also <i>A state of perdition:</i> so in the Kur liv. 24: (S, O:) [and in like manner <span class=\"ar\"> <span class=\"ar\">ضَلَالَةٌ</span></span>; for] <span class=\"ar\">ضَلَالَةُ العَمَلِ</span> signifies <i>The annulled and lost state of work.</i> (TA.) -b3- And <i>Absence,</i> or <i>a state of concealment.</i> (Msb. [This is there said to be the primary signification.]) -b4- <span class=\"ar\">هُوَ الضَّلَالُ بْنُ التَّلَالِ</span> see expl. voce <span class=\"ar\">ضُلٌّ</span>.</p><p><b class=\"ar\">ضَلُولٌ</b> : see <span class=\"ar\">ضَالٌّ</span>.</p><p><b class=\"ar\">ضَلَالَةٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>, in the beginning, and near the end, of the paragraph. One says, <span class=\"ar\">هِىَ الضَّلَالَةُ</span> <span class=\"ar\">وَالتَّلَالَةُ</span>; (S, O;) in which the latter noun is an imitative sequent. (S and K in art. <span class=\"ar\">تل</span>.)</p><p><b class=\"ar\">ضِلِّيلٌ</b> A man (S, O) <i>who errs, strays, goes astray,</i> or <i>deviates from the right way</i> or <i>course, much,</i> or <i>often:</i> (S, O, K:) or (tropical:) <i>who errs,</i> &amp;c., <i>much,</i> or <i>often, in religion:</i> (TA:) and <span class=\"ar\"> <span class=\"ar\">مُضَلَّلٌ</span></span>, (S, TA,) which in some of the copies of the S is written thus and also <span class=\"ar\">مُضَلِّل</span>, (TA,) signifies the same; (S, TA;) or one <i>who is not disposed,</i> or <i>directed, to good;</i> in the K, <span class=\"ar\">الّذى لا يُوَفِّى بِخَيْرٍ</span>, [or <span class=\"ar\">يُوفِى بخير</span>, as in the CK,] but correctly <span class=\"ar\">الّذى</span> <span class=\"ar\">لا يُوَفَّقُ لِخَيْرٍ</span>; or, as some say, <i>a committer of errors,</i> and <i>of false, wrong,</i> or <i>vain, actions:</i> and <span class=\"ar\">ضِلِّيلٌ</span> is also expl. as signifying one <i>who will not desist from error.</i> (TA.) Imra-el-Keys was called <span class=\"ar\">المَلِكُ الضِّلِّيلُ</span> [<i>The much-erring king</i>], (S, O, K, TA, [in the CK, erroneously, <span class=\"ar\">الضَّلِيلُ</span>,]) and <span class=\"ar\">الملك <span class=\"ar\">المُضَلَّلُ</span></span>. (K.)</p><p><b class=\"ar\">ضَالٌّ</b> <i>Erring, straying,</i> or <i>going astray; deviating from the right way</i> or <i>course,</i> or <i>from that which is right; missing,</i> or <i>losing, the right way;</i> or <i>losing his way;</i> (S, * Msb, TA;) and <span class=\"ar\"> <span class=\"ar\">ضَلُولٌ</span></span> is syn. therewith; (K;) [or rather with <span class=\"ar\">ضِلِّيلٌ</span>, accord. to a general rule:] pl. of the former <span class=\"ar\">ضُلَّالٌ</span>, [of which see an ex. in a verse cited voce <span class=\"ar\">رِسْلٌ</span>,] and <span class=\"ar\">ضُالُّونَ</span>: [in the Kur i. last verse,] some read <span class=\"ar\">وَلَا ٱلضَّأَلِّينَ</span>, to avoid the concurrence of two quiescent letters. (TA.) You say <span class=\"ar\">ضَالٌّ</span> <span class=\"ar\">تَالٌّ</span>; (S, O;) in which the latter epithet is an imitative sequent. (S and K in art. <span class=\"ar\">تل</span>.) -b2- [Also <i>Becoming lost;</i> &amp;c. -b3- And <i>Forgetting.</i> It is said that] <span class=\"ar\">وَأَنَا مِنَ ٱلضَّالِّينَ</span> [in the Kur xxvi. 19] means (assumed tropical:) <i>I being of those that forgot.</i> (K, TA.) And <span class=\"ar\">اِمرَأَةٌ ضَالَّةٌ</span> means (assumed tropical:) <i>A woman forgetting the days of her menstruation.</i> (Mgh.)</p><p><b class=\"ar\">ضَالَّةٌ</b> an epithet in which the quality of a subst. is predominant, (IAth, TA,) <i>A stray;</i> i. e. <i>a beast that has strayed:</i> (S, O, TA:) or <i>a camel remaining in a place where it is lost, without an owner</i> (K, TA) <i>that is known:</i> (TA:) or <i>a lost animal</i> (IAth, Msb, TA) or <i>other thing, whatever it be:</i> (IAth, TA:) applied to the male and to the female, (S, O, Msb, K,) and to two and to a pl. number: (TA;) and it has for its pl. <span class=\"ar\">ضَوَالُّ</span>, (Msb, TA,) like <span class=\"ar\">دَوَابُّ</span> pl. of <span class=\"ar\">دَابَّةٌ</span>. (Msb.) It is said in a trad., <span class=\"ar\">ضَالَّةُ المُؤْمِنِ حَرَقُ النَّارِ</span> [expl. in art. <span class=\"ar\">حرق</span>]. (TA.) And one says, <span class=\"ar\">الحِكْمَةُ ضَالَّةُ</span> <span class=\"ar\">المُؤْمِنِ</span> (assumed tropical:) [<i>Wisdom is the object of persevering quest of the believer</i>]; meaning that the believer ceases not to seek wisdom like as a man seeks his stray. (TA.)</p><p><b class=\"ar\">ضَلَضِلٌ</b> and <span class=\"ar\"> <span class=\"ar\">ضَلَضِلَةٌ</span></span>, (As, S,) as though contracted from <span class=\"ar\">ضَلَاضِلٌ</span> [and <span class=\"ar\">ضَلَاضِلَةٌ</span>], (S,) or <span class=\"ar\"> <span class=\"ar\">ضَلَضِلَةٌ</span>أَرْضٌ</span> and <span class=\"ar\">ضَلَضِلٌ</span> [in the CK <span class=\"ar\">ضَلَضَلَةٌ</span> and <span class=\"ar\">صَلَضَلٌ</span>] and <span class=\"ar\"> <span class=\"ar\">ضُلَضِلَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضُلَضِلٌ</span></span> (K) and <span class=\"ar\"> <span class=\"ar\">ضُلَاضِلٌ</span></span> (Lh, K) and <span class=\"ar\">ضُلْضُلَةٌ</span>, (IDrd, K,) <i>Rugged land</i> or <i>ground.</i> (As, S, K.) And <span class=\"ar\">مَكَانٌ</span> <span class=\"ar\">ضَلَضِلٌ</span>, originally <span class=\"ar\">ضَلَاضِيلُ</span>, <i>A hard, stony place.</i> (Fr, TA.) -b2- Also, (so in the K,) i. e. (TA) <span class=\"ar\">ضَلَضِلٌ</span> and <span class=\"ar\"> <span class=\"ar\">ضَلَضِلَةٌ</span></span>, accord. to As, (O, TA,) or <span class=\"ar\"> <span class=\"ar\">ضُلَضِلَةٌ</span></span>, (S, O, TA,) [said to be] the only instance of its kind among reduplicate words, (S, O, TA, [in which last the same assertion is quoted from the T, app. in relation to the last, or last but one, of these words,]) and, as in the Jm, <span class=\"ar\"> <span class=\"ar\">ضُلْضُلَةٌ</span></span>, (O, TA,) <i>A stone,</i> (As, S, O,) or <i>stones,</i> (K,) <i>such as a man can lift from the ground and carry:</i> (As, S, O, K:) or, accord. to the T, <span class=\"ar\">ضلضلة</span> [thus in the TA, app. <span class=\"ar\"> <span class=\"ar\">ضَلَضِلَةٌ</span></span> or <span class=\"ar\"> <span class=\"ar\">ضُلَضِلَةٌ</span></span>,] signifies <i>any stone such as a man can lift from the ground and carry,</i> or <i>above that, smooth, found in the interiors of valleys.</i> (TA.)</p><p><b class=\"ar\">ضُلَضِلٌ</b> : see the next preceding paragraph. -A2- Also, (IAar, O, TA,) in the K, erroneously, <span class=\"ar\">صُلَضِلَةٌ</span>, (TA.) and <span class=\"ar\"> <span class=\"ar\">ضُلَاضِلٌ</span></span>, <i>A skilful guide of the way.</i> (IAar, O, K, TA.)</p><p><b class=\"ar\">ضَلْظَلَةٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>.</p><p><b class=\"ar\">ضُلْضُلَةٌ</b> : see <span class=\"ar\">ضَلَضِلٌ</span>, in two places. -b2- <span class=\"ar\">ضَلَاضِلُ</span> <span class=\"ar\">المَآءِ</span>, (O, K,) and <span class=\"ar\">صَلَاصِلُهُ</span>, (O,) [said in the O, in this art., to be pls. of which the sings. are <span class=\"ar\">ضُلَضِلَةٌ</span> and <span class=\"ar\">صُلَصِلَةٌ</span>, but the sings. are correctly <span class=\"ar\">ضُلْضُلَةٌ</span> and <span class=\"ar\">صُلْصُلَةٌ</span>, (see the latter of these two in its proper art.,)] <i>The remains of water:</i> (O, K:) so says Lh. (O.)</p><p><b class=\"ar\">ضَلَضِلَةٌ</b> : see <span class=\"ar\">ضَلَضِلٌ</span>, in four places.</p><p><b class=\"ar\">ضُلَضِلَةٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>: -b2- and <span class=\"ar\">مَضَلَّةٌ</span>: -b3- and <span class=\"ar\">ضَلَضِلٌ</span>, in three places.</p><p><b class=\"ar\">ضُلَاضِلٌ</b> : see <span class=\"ar\">ضَلَضِلٌ</span>: -A2- and <span class=\"ar\">ضُلَضِلٌ</span>.</p><p><b class=\"ar\">أُضْلُولَةٌ</b> : see <span class=\"ar\">ضَلَالٌ</span>.</p><p><b class=\"ar\">وَقَعَ فِى وَادِى تُضُلِّلَ</b> , (Ks, S, O, K, *) like <span class=\"ar\">تُخُيِّبَ</span> and <span class=\"ar\">تُهُلِّكَ</span>, all imperfectly decl., (S, O,) and <span class=\"ar\">تُضَلِّلَ</span>, (Ibn-'Abbád, O, K,) and <span class=\"ar\">تَضَلِّلَ</span>, with two fet-hahs, and <span class=\"ar\">تِضِلِّلِ</span>, with two kesrehs, (Ibn- 'Abbád, O, TA,) meaning <span class=\"ar\">البَاطِل</span> [i. e. (assumed tropical:) <i>He fell into that which was vain, unreal, nought, futile,</i> or <i>the like,</i> and consequently, <i>into disappointment</i>]: (Ibn-'Abbád, S, O, K, TA:) or, accord. to the A, <span class=\"ar\">وَقَعُوا فى وادى تضلّل</span> means (tropical:) <i>They perished.</i> (TA.)</p><p><b class=\"ar\">طَرِيقٌ مُضِلٌّ</b> <i>A road that causes to go astray,</i> or <i>to deviate from the right course.</i> (TA.) And, accord. to As, <span class=\"ar\">مُضِلٌّ</span> signifies A land (<span class=\"ar\">أَرْضٌ</span>) <i>in which one loses his way.</i> (TA. [See also the next paragraph.]) [Hence,] <span class=\"ar\">فِتْنَةٌ مُضِلَّةٌ</span> means [<i>A trial,</i> or <i>sedition,</i> or <i>discord,</i> &amp;c.,] <i>that causes men to go astray,</i> or <i>to deviate from that which is right.</i> (TA.) And [hence also,] <span class=\"ar\">المُضِلُّ</span> means <i>The</i> <span class=\"ar\">سَرَاب</span> [or <i>mirage</i>]. (TA.)</p><p><b class=\"ar\">مَضَلَّةٌ</b> a subst. like <span class=\"ar\">مَجْبَنَةٌ</span> and <span class=\"ar\">مَبْخَلَةٌ</span> [i. e., as such, signifying <i>A cause of erring, straying, going astray,</i> or <i>deviating from the right way</i> or <i>course</i> or <i>from that which is right,</i> &amp;c.]: (TA:) [and used in the manner of an epithet:] one says <span class=\"ar\">أَرْضٌ مَضَلَّةٌ</span> <i>A land that causes one to err,</i> &amp;c.: (TA:) or, as also <span class=\"ar\"> <span class=\"ar\">مَضِلَّةٌ</span></span>, (S, O, Msb, K, TA, [in the CK <span class=\"ar\">مِضَلَّةٌ</span>,]) and <span class=\"ar\"> <span class=\"ar\">ضُلَضِلَةٌ</span></span>, (O, K,) <i>a land in which one errs,</i> or <i>strays, from the</i> [<i>right</i>] <i>way;</i> (S, O, Msb, K; *) <i>in which one does not find the right way:</i> and <span class=\"ar\">خَرْقٌ مضلّةٌ</span> [<i>A desert,</i> or <i>farextending desert,</i> &amp;c., <i>in which one errs,</i> &amp;c.]: it is used alike as masc. and fem. and pl.: but one says also <span class=\"ar\">أَرَضُونَ مضلّاتٌ</span>. (TA.)</p><p><b class=\"ar\">مَضِلَّةٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">مُضَلَّلٌ</b> : see <span class=\"ar\">ضِلِّيلٌ</span>, in two places.</p><p><b class=\"ar\">مُتَضَالٌّ</b> [part. n. of 6, q. v.]. One says, <span class=\"ar\">إِنَّكَ</span> <span class=\"ar\">تَهْدِى الضَّالَّ وَلَا تَهْدِى المُتَضَالَّ</span> [<i>Verily thou wilt direct aright the erring,</i> &amp;c., <i>but thou wilt not direct aright him who feigns himself to be erring,</i> &amp;c.]. (S, O.)</p>"},"ضرب":{"mf":"الضَّرْبُ: إيقاعُ شيءٍ على شيء، ولتصوّر اختلاف الضّرب خولف بين تفاسيرها، كَضَرْبِ الشيءِ باليد، والعصا، والسّيف ونحوها، قال:<br>فَاضْرِبُوا فَوْقَ الْأَعْناقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنانٍ<br>[الأنفال/ ١٢]، فَضَرْبَ الرِّقابِ<br>[محمد/ ٤]، فَقُلْنا اضْرِبُوهُ بِبَعْضِها<br>[البقرة/ ٧٣]، أَنِ اضْرِبْ بِعَصاكَ الْحَجَرَ<br>[الأعراف/ ١٦٠]، فَراغَ عَلَيْهِمْ ضَرْباً بِالْيَمِينِ<br>[الصافات/ ٩٣]، يَضْرِبُونَ وُجُوهَهُمْ<br>[محمد/ ٢٧]، وضَرْبُ الأرضِ بالمطر، وضَرْبُ الدّراهمِ، اعتبارا بِضَرْبِ المطرقةِ، وقيل له: الطّبع، اعتبارا بتأثير السّمة فيه، وبذلك شبّه السّجيّة، وقيل لها: الضَّرِيبَةُ والطَّبِيعَةُ. والضَّرْبُ في الأَرْضِ: الذّهاب فيها وضَرْبُهَا بالأرجلِ.<br>قال تعالى: وَإِذا ضَرَبْتُمْ فِي الْأَرْضِ<br>[النساء/ ١٠١]، وَقالُوا لِإِخْوانِهِمْ إِذا ضَرَبُوا فِي الْأَرْضِ<br>[آل عمران/ ١٥٦]، وقال: لا يَسْتَطِيعُونَ ضَرْباً فِي الْأَرْضِ<br>[البقرة/ ٢٧٣]، ومنه: فَاضْرِبْ لَهُمْ طَرِيقاً فِي الْبَحْرِ<br>[طه/ ٧٧]، وضَرَبَ الفحلُ الناقةَ تشبيها بالضَّرْبِ بالمطرقة، كقولك: طَرَقَهَا، تشبيها بالطّرق بالمطرقة، وضَرَبَ الخيمةَ بضرب أوتادها بالمطرقة، وتشبيها بالخيمة قال: ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ<br><strong>[آل عمران/ ١١٢]، أي:</strong><br>التحفتهم الذّلّة التحاف الخيمة بمن ضُرِبَتْ عليه، وعلى هذا: وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ [آل عمران/ ١١٢]، ومنه استعير: فَضَرَبْنا عَلَى آذانِهِمْ فِي الْكَهْفِ سِنِينَ عَدَداً<br>[الكهف/ ١١]، وقوله: فَضُرِبَ بَيْنَهُمْ بِسُورٍ<br>[الحديد/ ١٣]، وضَرْبُ العودِ، والناي، والبوق يكون بالأنفاس، وضَرْبُ اللَّبِنِ بعضِهِ على بعض بالخلط، وضَرْبُ المَثلِ هو من ضَرْبِ الدّراهمِ، وهو ذكر شيء أثره يظهر في غيره. قال تعالى: ضَرَبَ اللَّهُ مَثَلًا [الزمر/ ٢٩]، وَاضْرِبْ لَهُمْ مَثَلًا<br>[الكهف/ ٣٢]، ضَرَبَ لَكُمْ مَثَلًا مِنْ أَنْفُسِكُمْ<br>[الروم/ ٢٨]، وَلَقَدْ ضَرَبْنا لِلنَّاسِ<br>[الروم/ ٥٨]، وَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلًا<br>[الزخرف/ ٥٧]، ما ضَرَبُوهُ لَكَ إِلَّا جَدَلًا<br>[الزخرف/ ٥٨]، وَاضْرِبْ لَهُمْ مَثَلَ الْحَياةِ الدُّنْيا<br>[الكهف/ ٤٥]، أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحاً<br>[الزخرف/ ٥].<br>والمُضَارَبَةُ: ضَرْبٌ من الشَّرِكَةِ. والمُضَرَّبَةُ:<br>ما أُكْثِرَ ضربُهُ بالخياطة. والتَّضْرِيبُ: التّحريضُ، كأنه حثّ على الضَّرْبِ الذي هو بعد في الأرض، والاضْطِرَابُ: كثرةُ الذّهاب في الجهات من الضّرب في الأرض، واسْتِضَرابُ الناقةِ: استدعاء ضرب الفحل إيّاها.","mq":[[],"الضاد والراء والباء أصل واحد، ثم يستعار ويحمل عليه.<br>من ذلك ضَربت ضرباً، إذا أوقعت بغيرك ضرباً. ويستعار منه ويشبَّه به الضَّرب فى الأرض تجارةً وغيرها من السّفر. قال اللّه تعالى: ﴿وَإِذا ضَرَبْتُمْ فِي اَلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُناحٌ أَنْ تَقْصُرُوا مِنَ اَلصَّلاةِ﴾. ويقولونَّ إن الإسراع إلى الس"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَرَبَهُ</b> , aor. <b class=\"ar\">ضَرِبَ</b> , (S, O, K, &amp;c.,) inf. n. <span class=\"ar\">ضَرْبٌ</span>, (S, O, &amp;c.,) [<i>He beat, struck, smote,</i> or <i>hit, him,</i> or <i>it;</i>] and <span class=\"ar\"> <span class=\"ar\">ضرّبهُ</span></span> [signifies the same in an intensive sense, i. e. <i>he beat,</i> &amp;c., <i>him,</i> or <i>it, much,</i> or <i>violently;</i> or in a frequentative sense, i. e. <i>several,</i> or <i>many, times:</i> or rather <span class=\"ar\">ضرّب</span> is used in relation to several, or many, objects, as will be shown in what follows]: (K:) accord. to Er-Rághib, <span class=\"ar\">الضَّرْبُ</span> signifies <i>the making a thing to fall upon another thing;</i> and, as some say, <i>the making it to fall with violence,</i> or <i>vehemence.</i> (TA.) You say, <span class=\"ar\">ضَرَبَهُ بِهِ</span> [<i>He struck him,</i> or <i>it, with it</i>], i. e. with a sword, (A, Mgh, Msb), &amp;c. (A, Msb.) And <span class=\"ar\">تَضْرِبُ فِى حَدِيدٍ بَارِدٍ</span> [<i>Thou beatest upon cold iron</i>]: a prov. [expl. in art. <span class=\"ar\">حد</span>]. (Har p. 633.) And <span class=\"ar\">ضَرَبْتُ زَيْدًا سَوْطًا</span>, meaning <span class=\"ar\">بِسَوْطٍ</span> [i. e. <i>I struck Zeyd with a whip</i>], or <span class=\"ar\">ضَرْبَةَ سَوْطٍ</span> [<i>a stroke of a whip</i>]: (M in art. <span class=\"ar\">سوط</span>, q. v.:) and <span class=\"ar\">ضَرَبَهُ مِائَةَ سَوْطٍ</span> [<i>He struck him a hundred strokes of the whip</i>]. (S and K in art. <span class=\"ar\">سحل</span>, &amp;c.) And <span class=\"ar\">ضَرَبْتُ عُنُقَهُ</span> [<i>I smote his neck,</i> meaning <i>I beheaded him</i>]; and <span class=\"ar\"> <span class=\"ar\">ضَرَّبْتُ</span>الأَعْنَاقَ</span> [<i>I smote the necks,</i> meaning <i>I struck off the heads</i>]; the teshdeed denoting muchness [of the action] or multiplicity [of the objects]: AZ says that, when the object is one, the Arabs use only the former verb, without teshdeed; but when there is a plurality of objects, either of the verbs; (Msb;) [so that] one says, <span class=\"ar\">ضَرَبُوا أَعْنَاقَهُمْ</span> [<i>They smote their necks,</i> or <i>beheaded them</i>], and <span class=\"ar\">أَمَرَ <span class=\"ar\">بِتَضْرِيبِ</span> الرِّقَابِ</span> [<i>He gave the order to smite the necks,</i> or <i>to strike off the heads</i>]: (A:) <span class=\"ar\">فَضَرْبَ</span> <span class=\"ar\">الرِّقَابِ</span> in the Kur xlvii. 4 is originally <span class=\"ar\">فَٱضْرِبُوا</span> <span class=\"ar\">الرِّقَابَ ضَرْبًا</span> [meaning <i>Then do ye smite the necks,</i> i. e. <i>strike off the heads</i>]; (Bd;) the inf. n. being here put for its verb. (Jel.) [Respecting the phrase <span class=\"ar\">هُوَ ٱلْيَضْرِبُكَ</span>, see 1 in art. <span class=\"ar\">جدع</span>.] -b2- [Hence a variety of meanings and phrases here following.] -b3- <span class=\"ar\">ضَرَبَ كَلْبَهُ عَلَى الصَّيْدِ</span> (assumed tropical:) [<i>He beat,</i> or <i>disciplined,</i> or <i>trained, his dog for the purpose of the chase</i>]: whence the phrases <span class=\"ar\">ضَرَبَ عَلَيْهِ جِرْوَتَهُ</span> and <span class=\"ar\">ضَرَبَ جِرْوَةَ نَفْسِهِ</span> and <span class=\"ar\">ضَرَبْتُ جِرْوَتِى عَنْهُ</span> [expl. voce <span class=\"ar\">جِرْوَةٌ</span>]. (Z, and TA in art. <span class=\"ar\">جرو</span>.) -b4- <span class=\"ar\">لَا تُضْرَبُ</span> <span class=\"ar\">أَكْبَادُ الإِبِلِ إِلَّا ثَلَاثَةِ مَسَاجِدَ</span> (assumed tropical:) <i>Camels shall not be ridden, save to three mosques:</i> [namely, that of Mekkeh, that of El-Medeeneh, and that of El-Aksà at Jerusalem:] a trad. (TA. [See also 4 in art. <span class=\"ar\">عمل</span>.]) -b5- [<span class=\"ar\">ضَرَبَ بِهِ الأَرْضَ</span>, lit. <i>He smote with him,</i> or <i>it, the ground;</i> meaning (assumed tropical:) <i>he cast, threw,</i> or <i>flung, him,</i> or <i>it, upon the ground.</i> And <span class=\"ar\">ضَرَبَ بِسَلْحِهِ الأَرْضَ</span> (assumed tropical:) <i>He cast forth his excrement,</i> or <i>ordure, upon the ground.</i>] And [hence] <span class=\"ar\">ضَرَبَ الأَرْضَ</span> and <span class=\"ar\">الغَائِطَ</span> (tropical:) <i>He voided excrement,</i> or <i>ordure;</i> (A, TA;) and so <span class=\"ar\">الخَلَآءَ</span>. (TA.) [<span class=\"ar\">ضَرَبَ بِنَفْسِهِ الأَرْضَ</span> see expl. in the latter half of this paragraph.] -b6- <span class=\"ar\">ضَرَبْتُ القَوْسَ بِالمِضْرَبِ</span> <i>I struck the string of the bow with the wooden implement</i> [or <i>mallet</i>] <i>used in separating cotton.</i> (Msb.) -b7- <span class=\"ar\">ضَرَبَ العُودَ</span> [<i>He struck the chords of the lute;</i> meaning <i>he played upon the lute;</i> and so <span class=\"ar\">ضَرَبَ بِالعُودِ</span>]. (S.) -b8- <span class=\"ar\">ضَرَبَ الوَتِدَ</span>, aor. and inf. n. as above, <i>He beat</i> [or <i>knocked</i> or <i>struck</i>] <i>the tent-peg,</i> or <i>stake, so that it became firm in the ground.</i> (Lh, TA.) And [hence] <span class=\"ar\">ضَرَبَ الخَيْمَةَ</span> (tropical:) <i>He pitched the tent, by knocking in its pegs with a mallet:</i> (Kull p. 231:) or <i>he set up the tent.</i> (Msb.) -b9- <span class=\"ar\">ضَرَبَ الدِّرْهَمَ</span>, aor. and inf. n. as above, (tropical:) <i>He struck, coined,</i> or <i>minted, the dirhem,</i> or <i>piece of money.</i> (TA.) And <span class=\"ar\">ضَرَبَ عَلَى ٱسمِهِ</span> (assumed tropical:) [<i>He struck, coined,</i> or <i>minted,</i> money <i>in his name</i>]. (ISd, TA in art. <span class=\"ar\">جوز</span>.) -b10- <span class=\"ar\">ضَرَبَ عَلَى</span> <span class=\"ar\">المَكْتُوبِ</span> (tropical:) <i>He sealed,</i> or <i>stamped, the writing.</i> (A, * TA.) [And <span class=\"ar\">ضَرَبَ عَلَيْهِ</span> (assumed tropical:) <i>He erased it;</i> namely, anything written.] -b11- <span class=\"ar\">ضَرَبَ الطِّينَ عَلَى</span> <span class=\"ar\">الجِدَارِ</span> (assumed tropical:) [<i>He stuck,</i> or <i>applied, the mud upon the wall,</i> as a plaster]. (TA.) -b12- Hence, accord. to some, the phrase <span class=\"ar\">ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ</span>, in the Kur ii. 58, considered as meaning (assumed tropical:) <i>Vileness was made to cleave to them:</i> or the meaning is, (assumed tropical:) <i>encompassed them,</i> like as the tent encompasses him over whom it is pitched. (Ksh, Bd.) And [in like manner] one says, <span class=\"ar\">ضُرِبَتْ عَلَيْهِمُ ضَرِيبَةٌ</span> (tropical:) <i>An impost,</i> of the tax called <span class=\"ar\">جِزْيَة</span>, &amp;c., <i>was imposed upon them.</i> (A, * Mgh, Msb. *) And <span class=\"ar\">ضَرَبَ عَلَى</span> <span class=\"ar\">العَبْدِ الأِتَاوَةَ</span> (tropical:) <i>He imposed upon the slave the tax according to a fixed time.</i> (TA. [See <span class=\"ar\">ضِريبَةٌ</span>.]) And <span class=\"ar\">ضُربَ عَلَيْهِمُ البَعْثُ</span> (assumed tropical:) <i>The being sent to the war was appointed them and imposed upon them as an obligation.</i> (Mgh in art. <span class=\"ar\">بعث</span>.) -b13- <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">الشَّبَكَةَ عَلَى الطَّائِرِ</span> (assumed tropical:) <i>He cast the net over the bird:</i> (Mgh:) and <span class=\"ar\">ضُرِبَ الفَخُّ عَلَى الطَّائِرِ</span> (tropical:) [<i>The snare was cast over the bird</i>]. (A, TA.) -b14- <span class=\"ar\">ضَرَبَ اللَّيْلُ</span> <span class=\"ar\">بِأَرُوَاقِهِ</span> (assumed tropical:) [<i>The night cast its folds of darkness;</i>] meaning <i>the night came.</i> (TA.) [And (assumed tropical:) <i>The night became dark,</i> or <i>was dark;</i> as appears from the following verse.] Homeyd says, <span class=\"ar\">سَرَى مِثْلَ نَبْضِ العِرْقِ وَاللَّيْلُ ضَارِبٌ</span> <span class=\"ar\">بِأرْوَاقِهِ وَالصُّبْحُ قَدْ كَادَ يَسْطَعُ</span> (assumed tropical:) [<i>He went on in his night-journey, like the pulsing of the vein, while the night was casting its folds of darkness</i> over the earth, <i>and the dawn had almost risen</i>]. (TA. [See also <span class=\"ar\">ضَارِبٌ</span>.]) You say also, <span class=\"ar\">ضَرَبَ عَلَيْهِ حِجَابًا</span> (assumed tropical:) [<i>He put,</i> or <i>let down, a veil,</i> or <i>curtain,</i> or <i>covering, over him,</i> or <i>it</i>]. (TA.) And <span class=\"ar\">ضُرِبَ بَيْنَهُمَا سَدٌّ</span> (assumed tropical:) [<i>A barrier was set between them two</i>]. (A in art. <span class=\"ar\">سد</span>.) <span class=\"ar\">ضَرَبْنَا عَلَى</span> <span class=\"ar\">آذَانِهِمْ</span> [in the Kur xviii. 10] means (tropical:) <i>We prevented their sleeping;</i> (K, TA;) as though by putting a covering over their ears; a metonymical [and elliptical] mode of saying <i>we made them to sleep</i> by preventing any sound from penetrating into their ears, in consequence of which they would have awoke: (Zj, L, TA:) or <span class=\"ar\">ضَرَبَ عَلَى آذَانِهِمْ</span> means (assumed tropical:) <i>he poured upon them sleep so that they slept and did not awake:</i> and one says also, <span class=\"ar\">ضَرَبْتُ النَّوْمَ عَلَى أُذُنِهِ</span> [meaning (assumed tropical:) <i>I poured sleep upon him by closing his ear</i>]. (Msb.) -b15- <span class=\"ar\">ضَرَبَتِ</span>, <span class=\"ar\">العَقْرَبُ</span>, (A, K, * TA,) aor. and inf. n. as above, (TA,) (tropical:) <i>The scorpion stung.</i> (A, K, * TA.) -b16- [<span class=\"ar\">ضَرَبَتْهُ الرِّيحُ</span> (assumed tropical:) <i>The wind beat it,</i> or <i>blew upon it;</i> namely, herbage, and water, &amp;c.] And <span class=\"ar\">ضَرَبَهُ</span> <span class=\"ar\">البَرْدُ</span> (IKtt, K, TA) (assumed tropical:) <i>The cold smote it so as to injure it;</i> namely, herbage; and in like manner one says of the wind: (IKtt, TA:) and <span class=\"ar\"> <span class=\"ar\">اضربهُ</span> البَرْدُ</span> (A, TA) (tropical:) <i>The cold smote it by its vehemence, so that it dried up;</i> and in like manner one says of the wind: (TA:) and <span class=\"ar\"> <span class=\"ar\">اضرب</span>الضَّرِيبُ الأَرْضَ</span> (assumed tropical:) <i>The hoar-frost,</i> or <i>rime, fell upon the land, so that its herbage became nipped,</i> or <i>blasted.</i> (AZ, TA. [See also <span class=\"ar\">ضَرِبَ</span>.]) And <span class=\"ar\">ضُرِبَ بِبَلِيَّةٍ</span> (assumed tropical:) <i>He was smitten with a trial,</i> or <i>an affliction.</i> (L, TA.) -b17- <span class=\"ar\">طَرِيقُ مَكَّةَ مَا ضَرَبَهَا العَامَ قَطْرَةٌ</span> (tropical:) [<i>The road to Mekkeh, not a drop</i> of rain <i>has fallen upon it this year</i>]. (A, TA.) -b18- <span class=\"ar\">ضَرَبَ الفَحْلُ</span> <span class=\"ar\">النَّاقَةَ</span>, (S, A, * Msb, K, * TA,) aor. <b class=\"ar\">ضَرِبَ</b> , (TA,) inf. n. <span class=\"ar\">ضِرَابٌ</span> (S, A, Msb, K) and <span class=\"ar\">ضَرْبٌ</span> also, accord. to Fr, but this latter, though agreeable with analogy, is disallowed by Sb and Akh, (TA,) (tropical:) <i>The stallion leaped the she-camel;</i> (Msb, TA;) i. e. (TA,) <i>compressed</i> (A, K, TA) <i>her.</i> (TA.) <span class=\"ar\">ضِرَابُ</span> <span class=\"ar\">الجَمَلِ</span> is used elliptically for <span class=\"ar\">ثَمَنُ ضِرَابِ الجَمَلِ</span> (tropical:) <i>The hire of the camel's leaping the female:</i> the taking of which, as also the taking of the hire of any stallion for covering, is forbidden in a trad. (TA.) -b19- <span class=\"ar\">ضَرَبَ الشَّىْءَ بِالشَّىْءِ</span> (tropical:) <i>He mixed the</i> [one] <i>thing with the</i> [other] <i>thing;</i> (A, K;) as also <span class=\"ar\"> <span class=\"ar\">ضرّبهُ</span></span>, (K,) inf. n. <span class=\"ar\">تَضْرِيبٌ</span>: (TA:) accord. to some, said peculiarly in relation to milk; (MF, TA;) but [SM says,] this I have not found in any lexicon. (TA.) <span class=\"ar\">ضَرَبَ اللَّبَنَ فِى السِّقَآءِ</span> means (tropical:) <span class=\"ar\">حَقَنَهُ</span> [i. e. <i>He collected the milk in the skin, and poured fresh milk upon that which was curdled,</i> or <i>thick,</i> or <i>upon that which was churned;</i> or <i>he poured the milk into the skin, and kept it therein that its butter might come forth</i>]. (A.) In the L and other lexicons it is said that <span class=\"ar\">ضَرَبْتُ بَيْنَهُمْ فِى الشَّرِّ</span> means <i>I caused them to become confused</i> [or <i>I involved them</i>] <i>in evil</i> or <i>mischief.</i> (TA. [And <span class=\"ar\">ضرّبت بَيْنَهُمْ</span> has a similar meaning: see 2.]) And <span class=\"ar\">ضُربَتِ الشَّاةُ بِلَوْنِ كَذَا</span> means <i>The sheep,</i> or <i>goat, was intermixed with such a colour.</i> (L, TA.) -b20- <span class=\"ar\">ضَرَبَ الشَّجَرُ بِعُرُوقِهِ</span> <span class=\"ar\">فِى الأَرْضِ</span> [<i>The trees struck their roots into the earth</i>]. (A and TA in art. <span class=\"ar\">عرق</span>.) -b21- [Hence, the saying,] <span class=\"ar\">ضَرَبَتْ فِيهِ فُلَانَةُ بِعِرْقٍ ذِى أَشَبٍ</span> i. e. <span class=\"ar\">اِلْتِبَاس</span>; (S and TA in the present art., and in like manner, in both, in art. <span class=\"ar\">اشب</span>, with the addition of <span class=\"ar\">ذِى</span> before <span class=\"ar\">اِلْتِبَاسٍ</span>;) (tropical:) [app. meaning <i>Such a woman implanted,</i> or <i>engendered, in him a strain,</i> i. e. <i>a radical,</i> or <i>hereditary, quality, of a dubious kind:</i> or the pronoun in <span class=\"ar\">فيه</span> relates to a family, or people; for it is said that] the meaning is, <i>such a woman corrupted their race by her bringing forth among them:</i> or, as some say, <span class=\"ar\">عرقت</span> <span class=\"ar\">فِيهِمْ عِرْقَ سَوْءٍ</span> [i. e. <span class=\"ar\">عَرَّقَتْ</span>, or, accord. to more common usage, <span class=\"ar\">أَعْرَقَتْ</span>, i. e., <i>implanted,</i> or <i>engendered, among them,</i> or <i>in them, an evil strain,</i> or <i>radical</i> or <i>hereditary disposition</i>]. (TA. [This saying is also mentioned in the A, as tropical, but is not expl. therein.]) -b22- <span class=\"ar\">ضَرَبَ بِالقِدَاحِ</span>, (S, Mgh, K,) and <span class=\"ar\">ضَرَبَ القِدَاحَ</span>, (A, TA,) (tropical:) <i>He turned about,</i> or <i>shuffled,</i> (<span class=\"ar\">أَجَالَ</span>,) <i>the arrows,</i> [<i>in the</i> <span class=\"ar\">رِبَابَة</span> (q. v.), <i>in the game called</i> <span class=\"ar\">المُيْسِر</span>,] <span class=\"ar\">عَلَى</span> <span class=\"ar\">الجَزورِ</span> [<i>for the slaughtered camel</i>]. (Mgh. [See <span class=\"ar\">حُرْضَةٌ</span>.]) [And (assumed tropical:) <i>He played with the gamingarrows; practised sortilege with arrows,</i> or <i>with the arrows.</i>] You say, <span class=\"ar\">ضَرَبْتُ مَعَ القَوْمِ بِسَهْمٍ</span> (assumed tropical:) <i>I practised sortilege with the people,</i> or <i>party, with an arrow;</i> syn. <span class=\"ar\">سَاهَمْتُهُمْ</span>. (Msb.) And <span class=\"ar\">ضَرَبَ بِالقِدْحَيْنِ</span> (assumed tropical:) <i>He practised sortilege with the two arrows;</i> one of which was inscribed with the sentence “ My Lord hath commanded me, ” and the other with “ My Lord hath forbidden me: ” a person between hope and despair is likened to one practising this mode of sortilege, which was used by the people of the Time of Ignorance when they doubted whether they should undertake an affair or abstain from it. (Har pp. 465 and 553.) One says also, <span class=\"ar\">ضَرَبَ فِى الجَزُورِبِسَهْمٍ</span> meaning (assumed tropical:) <i>He obtained a share,</i> or <i>portion, of the slaughtered camel.</i> (Mgh.) And hence the saying of El-Hareeree, <span class=\"ar\">وَضَرَبْتُ فِى مَرْعَاهَا بِنَصِيبٍ</span> (assumed tropical:) [<i>And I obtained a share of its pasture</i>]. (Mgh.) And the lawyers say, <span class=\"ar\">يَضْرِبُ فِيهِ بِالثُّلُثِ</span> i. e. (assumed tropical:) <i>He shall take thereof somewhat, according to what is due to him, of the third part.</i> (Mgh.) They say also, <span class=\"ar\">ضَرَبَ فِى مَالِهِ سَهْمًا</span> i. e. (assumed tropical:) <i>He assigned</i> [<i>a share,</i> or <i>portion, of his property</i>]: and thus is expl. the saying of Aboo-Haneefeh, <span class=\"ar\">لَا يَضْرِبُ لِلْمُوصَى لَهُ</span> <span class=\"ar\">فِيمَا زَادَ عَلَى الثُّلُثِ</span> (assumed tropical:) <i>He shall not assign,</i> or <i>give, to the legatee,</i> aught <i>of more than the third part;</i> the true objective complement being suppressed. (Mgh.) -b23- <span class=\"ar\">ضَرَبَ بِيَدَيْهِ</span> [lit. <i>He beat with his arms;</i> meaning (assumed tropical:) <i>he moved his arms about,</i> or <i>to and fro; brandished, tossed,</i> or <i>swung them</i>]: you say, <span class=\"ar\">ضَرَبَ بِيَدَيْهِ وَحَرَّكَهُمَا فِى مِشْيَتِهِ</span> (assumed tropical:) [<i>He swung his arms, and moved them about, in his manner of walking</i>]. (TA in art. <span class=\"ar\">جدف</span>. [See <span class=\"ar\">جَدَفَ</span>.]) And <span class=\"ar\">ضَرَبَ فِى المَآءِ</span> [<span class=\"ar\">بِيَدَيْهِ</span> being understood after the verb] (assumed tropical:) <i>He swam.</i> (K.) -b24- <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">بِيَدِهِ إِلَى شَىْءٍ</span> (assumed tropical:) <i>He made a sign,</i> or <i>pointed, with his hand, towards a thing.</i> (TA.) And <span class=\"ar\">ضَرَبَ</span> [alone] (assumed tropical:) <i>He made a sign,</i> or <i>pointed.</i> (K.) And <span class=\"ar\">ضَرَبَ بِيَدِهِ إِلَى كَذَا</span> (assumed tropical:) <i>He put forth his hand towards such a thing, to take it,</i> or <i>to point,</i> or <i>make a sign.</i> (TA.) And <span class=\"ar\">ضَرَبَ يَدَهُ إِلَى عَمَلِ كَذَا</span> (assumed tropical:) [<i>He applied his hand to the doing of such a thing</i>]. (Lth, TA.) [And <span class=\"ar\">ضَرَبَ يَدَيْهِ فِى المَالِ</span> a phrase expl. to me by IbrD as meaning (assumed tropical:) <i>He busied his hands with the property,</i> in the giving, or dispensing of it.] -b25- <span class=\"ar\">ضَرَبَ عَلَى يَدِهِ</span> (assumed tropical:) [<i>He struck his</i> (i. e. another man's) <i>hand;</i> meaning] <i>he struck,</i> or <i>made, the bargain with him;</i> or <i>ratified the sale with him:</i> for it is a custom, when two persons are bargaining together, for one of them to put his hand upon the other's in ratifying the bargain. (TA, from a trad.) -b26- And (tropical:) <i>He prohibited,</i> or <i>prevented,</i> or <i>hindered, him, from doing a thing,</i> or <i>from doing a thing that he had begun:</i> (TA:) and [in like manner] <span class=\"ar\">ضَرَبَ عَلَى يَدَيْهِ</span> (tropical:) <i>he withheld,</i> or <i>restrained, him,</i> or <i>it.</i> (K, TA.) And (i. e. the former phrase) (tropical:) <i>He</i> (the judge, A, Mgh, TA) <i>prohibited,</i> or <i>interdicted, him from the using,</i> or <i>disposing of, his property according to his own free will.</i> (S, A, Mgh, Msb, TA.) -b27- Also (tropical:) <i>He corrupted, vitiated, marred,</i> or <i>disordered, his affair,</i> or <i>case,</i> or <i>state.</i> (A, Msb, TA.) -b28- <span class=\"ar\">ضَرَبَ عَنْهُ</span> (assumed tropical:) <i>He turned away</i> a person or thing <i>from him</i> [or <i>it</i>]; as also <span class=\"ar\"> <span class=\"ar\">اضرب</span></span>: (TA:) [or] <span class=\"ar\"> <span class=\"ar\">اضرب</span>عنه</span> signifies, (S, Msb,) or signifies also, (TA,) and (Msb, TA) so does <span class=\"ar\">ضَرَبَ عنه</span>, (Msb, K, TA,) [the latter app. for <span class=\"ar\">ضَرَبَ نَفْسَهُ عَنْهُ</span>,] (assumed tropical:) <i>He turned away from, avoided, shunned,</i> or <i>left, him,</i> or <i>it;</i> (S * Msb, K * TA; *) namely, a person, (TA,) or a thing. (Msb.) <span class=\"ar\">أَفَنَضْرِبُ عَنْكُمُ ٱلذِّكْرَ صَفْحًا</span>, in the Kur [xliii. 4], is said to mean (assumed tropical:) <i>Shall we then neglect you, and not teach you what is incumbent on you?</i> the phrase being taken from a rider's striking his beast with his stick when he desires to turn him from the course that he is pursuing: or the meaning is, (assumed tropical:) <i>shall we then turn away the Kur-án from you,</i> and not invite you thereby to the faith, <i>turning away ourselves</i> from you? (TA.) One says also, <span class=\"ar\">ضَرَبْتُ عَنْهُ صَفْحًا</span> meaning (assumed tropical:) <i>I turned away from him and left him.</i> (S and TA in art. <span class=\"ar\">صفح</span>: see 1 in that art.) See also the saying <span class=\"ar\">ضَرَبَ أَخْمَاسَهُ فِى أَسْدَاسِهِ</span> voce <span class=\"ar\">خُمُسٌ</span>. -b29- And <span class=\"ar\">فُلَانٌ يَضْرِبُ أَخْمَاسًا لِأَسْدَاسٍ</span>: see voce <span class=\"ar\">خِمْسٌ</span>. -b30- <span class=\"ar\">ضَرَبَ بِنَفْسِهِ الأَرْضَ</span>, (K,) inf. n. <span class=\"ar\">ضَرْبٌ</span>, (TA,) [lit. <i>He smote with himself the ground;</i> and hence, (assumed tropical:) <i>he cast, threw,</i> or <i>flung, himself upon the ground;</i> app. often used in this sense; (a phrase similar to <span class=\"ar\">ضَرَبَ بِهِ الأَرْضَ</span> expl. before;) and hence,] (assumed tropical:) <i>he remained, stayed,</i> or <i>abode;</i> (K;) and so <span class=\"ar\"> <span class=\"ar\">اضرب</span></span> (AZ, ISk, S, K, TA) as used in the phrase <span class=\"ar\">اضرب</span> <span class=\"ar\">الرَّجُلُ فِى البَيْتِ</span> (tropical:) <i>The man remained, stayed,</i> or <i>abode, in the tent,</i> or <i>house,</i> (AZ, ISk, S, A, TA,) <i>not quitting it:</i> (ISk, A, TA:) and [in like manner] <span class=\"ar\">ضَرَبَ بذَنَبِهِ</span>, [<span class=\"ar\">الأَرْضَ</span> being understood,] (assumed tropical:) <i>He stayed,</i> or <i>abode, and remained fixed.</i> (K in art. <span class=\"ar\">ذنب</span>. [See also other explanations of this last phrase in a later part of this paragraph.]) And <span class=\"ar\">ضَرَبَ الوَتِدَ بِمَحَلِّ كَذَا</span> (tropical:) <i>He remained, stayed,</i> or <i>abode,</i> [lit., <i>struck the tent-peg,</i>] <i>in such a place of alighting.</i> (A.) And <span class=\"ar\">ضَرَبَتِ الإِبِلُ</span> <span class=\"ar\">بِعَطَنٍ</span>, [<span class=\"ar\">الأَرْضَ</span> being understood after <span class=\"ar\">الابل</span>,] (assumed tropical:) <i>The camels lay down</i> [<i>in a place by the water</i>]: (S in art. <span class=\"ar\">عطن</span>:) or <i>satisfied themselves with drinking and then lay down around the water</i> or <i>by the watering-troughs, to be brought again to drink another time:</i> (IAth, TA in that art.:) and [hence,] <span class=\"ar\">ضَرَبَ النَّاسُ بِعَطَنٍ</span>, occurring in a trad., (assumed tropical:) <i>The people's camels satisfied themselves with drinking until they lay down and remained in their place</i> [<i>at the water</i>]: (TA in the present art.:) or <i>the people satisfied their thirst and then abode at the water.</i> (K in art. <span class=\"ar\">عطن</span>.) -b31- <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">بِذَقَنِهِ الأَرْضَ</span> (tropical:) <i>He was cowardly; and feared;</i> (A, O,* K, TA;) <i>and clave to the ground:</i> (O, TA:) or <i>he was,</i> or <i>became, affected with shame, shyness,</i> or <i>bashfulness.</i> (A, TA.) -b32- <span class=\"ar\">يَضْرِبُ لَهُ</span> <span class=\"ar\">الأَرْضَ كُلَّهَا</span> [lit. <i>He beats for it the whole land,</i> i. e. in journeying,] means (assumed tropical:) <i>he seeks it through the whole land:</i> so says AZ in explanation of the phrase here following. (O, TA.) <span class=\"ar\">يَضْرِبُ</span> <span class=\"ar\">المَجْدَ</span> (assumed tropical:) <i>He seeks to gain,</i> or <i>obtain, glory:</i> (O, K:) or <i>he applies himself with art and diligence to gain glory,</i> (<span class=\"ar\">يَكْتَسِبُهُ</span>,) <i>and seeks it through the whole land.</i> (AZ, TA. [See also 8.]) -b34- <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">اللَّبِنَ</span>, (A,) or <span class=\"ar\">اللِّبْنَ</span>, (tropical:) <i>He made</i> [or <i>moulded</i>] <i>bricks.</i> (MA.) And <span class=\"ar\">ضَرَبَ الخَاتَمَ</span> (tropical:) <i>He made, fashioned,</i> or <i>moulded, the signet-ring.</i> (TA.) [Hence one says,] <span class=\"ar\">اِضْرِبْهُ عَلَى طَبْعِ هٰذَا</span> i. e. (assumed tropical:) [<i>Make thou it, fashion it,</i> or <i>mould it,</i>] <i>according to the model, make, fashion,</i> or <i>mould, of this.</i> (IAar, O and K in art. <span class=\"ar\">طبع</span>.) And <span class=\"ar\">هٰذِهِ</span> <span class=\"ar\">ضَرِيبَتُهُ الَّتِى ضُرِبَ عَلَيْهَا</span>, and <span class=\"ar\">ضُرِبَهَا</span>, and <span class=\"ar\">ضُرِبَ</span> alone, [for <span class=\"ar\">ضُرِبَ عَلَيْهَا</span>,] meaning <span class=\"ar\">طُبِعَ</span> [i. e. (assumed tropical:) <i>This is his nature, with an adaptation,</i> or <i>a disposition, to which he was moulded,</i> or <i>created;</i> or <i>to which he was adapted,</i> or <i>disposed, by creation</i>]. (Lh, TA.) And <span class=\"ar\">ضُرِبَ فُلَانٌ عَلَى الكَرَمِ</span> (tropical:) [<i>Such a one was moulded,</i> or <i>created, with an adaptation</i> or <i>a disposition, to generosity;</i> or <i>was adapted,</i> or <i>disposed, by creation,</i> or <i>nature, to generosity</i>]. (A.) -b35- <span class=\"ar\">ضَرَبَ مَثَلًا</span> (S, A, O, &amp;c.) (tropical:) <i>He rehearsed, propounded,</i> or <i>declared, a parable, a similitude, an example,</i> or <i>a proverb;</i> said of God [and of a man]: (S, * O, * Msb, TA:) or <i>he mentioned,</i> or <i>set forth, a parable,</i> &amp;c.: or <i>he framed a parable:</i> thus expl., the verb has but one objective complement: or the phrase signifies <i>he made</i> [such a thing] <i>an example,</i> or <i>the subject of a parable</i> or <i>similitude</i> &amp;c.; and so has two objective complements: in the saying in the Kur [xxxvi. 12] <span class=\"ar\">وَٱضْرِبْ لَهُمْ مَثَلًا أَصْحَابَ ٱلْقَرْيَةِ</span> (assumed tropical:) [<i>And propound thou to them a parable, the people of the town</i>] i. e., the story of the people of the town, [or <i>make thou to them a parable,</i> or <i>similitude,</i> or <i>an example, the people of the town;</i>] <span class=\"ar\">مثلا</span> may be in the accus. case as an objective complement, <span class=\"ar\">اضحاب القرية</span> being a substitute for <span class=\"ar\">مثلا</span>; or <span class=\"ar\">اصحاب القرية</span> may be regarded as a second objective complement [i. e. second in the order of the words, but first in the order of the sense]: the phrase is differently expl. on account of the different meanings of the verb <span class=\"ar\">ضَرَبَ</span>; which signifies <i>he described,</i> or <i>rehearsed;</i> and <i>he declared, propounded,</i> or <i>explained;</i> and <i>he made, caused to be,</i> or <i>constituted;</i> &amp;c.; accord. to some, it is taken from the phrase <span class=\"ar\">ضَرَبَ الدِرْهَمَ</span> [q. v.]; because of the impression which a parable or the like makes upon the mind: accord. to some, from <span class=\"ar\">ضَرِيبٌ</span> signifying “ a like; ” because the first thing is made like the second: accord. to some, from <span class=\"ar\">ضَرَبَ الطِّينَ عَلَى الجِدَارِ</span> [q. v.; because the mud, applied as a plaster, conforms to the shape of the wall]: and accord. to some, from <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">الخَاتَمَ</span> [q. v.]; because of the correspondence between a parable or the like and the object to which it is applied, and the correspondence between the signet and its impression. (TA, from the M and L &amp;c.) <span class=\"ar\">يَضْرِبُ ٱللّٰهُ ٱلْحَقَّ وَٱلْباطِلَ</span>, in the Kur [xiii. 18], means (assumed tropical:) <i>God likeneth,</i> or <i>compareth, truth and falsity.</i> (TA.) One says also, <span class=\"ar\">ضَرَبَ بِهِ مَثَلًا</span> (assumed tropical:) [<i>He made him,</i> or <i>it, a subject of a parable, a similitude, an example,</i> or <i>a proverb; he propounded,</i> or <i>framed, a parable,</i> &amp;c., <i>respecting him,</i> or <i>it</i>]. (TA.) And <span class=\"ar\">يُضْرَبُ المَثَلُ لِكَذَا</span> [<i>The proverb,</i> &amp;c., <i>is applied to, in relation to,</i> or <i>to the case of, such a thing</i>]. (Meyd &amp;c., passim.) -b36- <span class=\"ar\">ضَرَبَ لَهُ أَجَلًا</span> (assumed tropical:) <i>He specified,</i> or <i>notified, to,</i> or <i>for, him,</i> or <i>it, a term,</i> or <i>period.</i> (Mgh, Msb. *) -b37- <span class=\"ar\">ضَرَبَ لَهُمْ طَرِيقًا</span> (assumed tropical:) <i>He assigned to them,</i> or <i>made for them, a way;</i> syn. <span class=\"ar\">جَعَلَ</span>. (MA. [App. from a phrase in the Kur xx. 79, q. v.]) -b38- <span class=\"ar\">الضَّرْبُ</span> as a conventional term of the accountants, or arithmeticians, means The <i>multiplying</i> a number by another number; (Mgh, Msb;) as when you say, [<span class=\"ar\">ضَرَبَ خَمْسةً فِى سِتَّةٍ</span> <i>He multiplied five by six;</i> and] <span class=\"ar\">خَمْسَةٌ فِى سِتَّةٍ بِثَلَاثِينَ</span> [<i>Five</i> multiplied <i>by six is thirty</i>]. (Msb.) -b39- <span class=\"ar\">ضَرَبَ</span> [is often intrans., and thus] signifies also <span class=\"ar\">تَحَرَّكَ</span> [i. e. (assumed tropical:) <i>It was,</i> or <i>became, in a state of commotion,</i> &amp;c.]: (K:) [see also 8, which is more commonly used in this sense:] or, <i>so with strength,</i> or <i>force.</i> (TA.) [And hence several phrases here following.] -b40- <span class=\"ar\">ضَرَبَ العِرْقُ</span> (A, TA,) inf. n. <span class=\"ar\">ضَرْبٌ</span> and <span class=\"ar\">ضَرَبَانٌ</span>, (TA,) (tropical:) <i>The vein pulsed,</i> or <i>beat,</i> (A, TA,) and <i>throbbed:</i> (TA:) and <span class=\"ar\">ضَرَبَ</span>, inf. n. <span class=\"ar\">ضَرَبَانٌ</span>, (tropical:) <i>it</i> (the vein) <i>pained, and was,</i> or <i>became, in a state of strong commotion.</i> (TA.) And <span class=\"ar\">ضَرَبَ الجُرْحُ</span>, inf. n. <span class=\"ar\">ضَرَبَانٌ</span>, (S, A, Msb,) (tropical:) <i>The wound</i> [<i>throbbed;</i> or] <i>pained violently:</i> (A, Msb:) and so <span class=\"ar\">الضِرْسُ</span> (tropical:) [<i>the tooth</i>]. (A, TA.) -b41- <span class=\"ar\">ضَرَبَتِ</span> <span class=\"ar\">النَّاقَةُ</span>, (A, K,) or, as in some lexicons, <span class=\"ar\">المَخَاضُ</span>, (TA,) (tropical:) <i>The she-camel,</i> (A, K,) or <i>the pregnant</i> <i>camel,</i> (TA,) <i>raised her tail, and smote her vulva with it,</i> (A, K, TA,) <i>and then went along.</i> (K, TA.) -b42- <span class=\"ar\">ضَرَبَ فِى جَهَازِهِ</span> (tropical:) <i>He</i> (a camel) <i>took fright, and ran away at random,</i> (S, A, L, TA,) <i>and ceased not to gallop and leap until he had thrown off all his furniture,</i> or <i>load.</i> (L, TA.) -b43- <span class=\"ar\">جَآءَ يَضْرِبُ بِشَرٍّ</span> (tropical:) <i>He came hastening</i> [<i>with mischief,</i> or] <i>in an evil affair.</i> (A.) It is said in a trad. of 'Alee, When such and such things shall happen, (mentioning faction, or sedition, or the like,) <span class=\"ar\">ضَرَبَ يَعْسُوبُ الدِّينِ بِذَنَبِهِ</span>, meaning, accord. to AM, (assumed tropical:) <i>The leader of the religion shall hasten to go away through the land,</i> fleeing from the faction, or sedition: or, as some say, <i>shall go away hastily through the land, with his followers.</i> (O, TA. [But see <span class=\"ar\">يَعْسُوبٌ</span>: and see also <span class=\"ar\">ذَنَبٌ</span>.]) And you say also, <span class=\"ar\">ضَرَبْتُ فِىالسَّيْرِ</span>, (Msb,) inf. n. <span class=\"ar\">ضَرْبٌ</span>, (S,) (assumed tropical:) <i>I hastened in journeying.</i> (S, * Msb.) And <span class=\"ar\">ضَرَبَ فِى الأَرْضِ</span>, (S, A, Mgh, Msb, K,) aor. <b class=\"ar\">ضَرِبَ</b> , (TA,) inf. n. <span class=\"ar\">ضَرْبٌ</span> (S, K, TA) and <span class=\"ar\">مَضْرَبٌ</span> (S, TA) and <span class=\"ar\">ضَرَبَانٌ</span>, (K, TA,) (assumed tropical:) <i>He journeyed in the land</i> (S, Mgh, Msb) <i>seeking sustenance,</i> (S,) and <i>for the purpose of traffic:</i> (Mgh:) [and <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">الأَرْضَ</span>, as shown above, has a similar meaning:] or (tropical:) <i>he went forth in the land as a merchant;</i> (A, K;) or <i>warring and plundering,</i> (K,) or so <span class=\"ar\">ضَرَبَ فِى سَبِيلِ ٱللّٰهِ</span> [meaning <i>in the cause of God</i>]: (A:) or <i>he hastened through the land:</i> (A, K:) or <i>he arose, and hastened in his journey through the land:</i> (TA:) or <i>he went,</i> or <i>went away, in the land:</i> (A, K:) or <i>he traversed,</i> or <i>journeyed through, the land.</i> (TA.) The verb is [similarly] used in relation to almost all employments: you say, <span class=\"ar\">ضَرَبَ فِى التِّجَارَةِ</span> (assumed tropical:) [<i>He travelled for the purpose of traffic</i>]: (TA:) and <span class=\"ar\">إِنَّ لِىفِى</span> <span class=\"ar\">أَلْفِ دِرْهَمٍ لَمَضْرَبًا</span> i. e. <span class=\"ar\">ضَرْبًا</span> [<i>Verily I have to make a journey for the sake of,</i> or <i>on account of, a thousand dirhems</i>]. (S, TA: but in my copies of the S, <span class=\"ar\">لى</span> is omitted.) And <span class=\"ar\">ضَرَبَتِ الطَّيْرُ</span>, aor. as above, (tropical:) <i>The birds went,</i> or <i>went away,</i> [or <i>migrated,</i>] <i>seeking sustenance.</i> (K, TA.) -b44- <span class=\"ar\">ضَرَبَ</span> said of time, (assumed tropical:) <i>It went, passed,</i> or <i>passed away.</i> (K.) And <span class=\"ar\">ضَرَبَ الدَّهْرُ مِنْ ضَرَبَانِهِ</span>, or, accord. to one reading, <span class=\"ar\">مِنْ ضَرْبِهِ</span>, occurring in a trad., (tropical:) <i>The time in part passed;</i> [<i>the time pursued a part of its course;</i>] or <i>a part of the time passed.</i> (TA.) And <span class=\"ar\">ضَرَبَ الدَّهْرُ ضَرَبَانَهُ</span> (assumed tropical:) <i>Fortune,</i> or <i>time, produced,</i> or <i>brought to pass, its events:</i> (IKtt, TA:) a phrase like <span class=\"ar\">قُضِىَ مِنَ القَضَآءِ</span>. (S, L, TA.) And <span class=\"ar\">ضَرَبَ الدَّهْرُ مِنْ ضَرَبَانِهِ أَنْ كَانَ كَذَا وَكَذَا</span> (tropical:) [<i>Fortune,</i> or <i>time, brought to pass, among its events, that such and such things happened</i>]. (A, L, TA.) And <span class=\"ar\">ضَرَبَ الدَّهْرُ بَيْنَنَا</span> (tropical:) <i>Fortune,</i> or <i>time, separated us:</i> (AO, A, TA:) or <i>made a wide separation between us;</i> syn. <span class=\"ar\">بَعَّدَ</span>. (K.) -b45- Also (assumed tropical:) <i>It was,</i> or <i>became, long:</i> (K, TA:) so in the saying, <span class=\"ar\">ضَرَبَ اللَّيْلُ عَلَيْهِمْ</span> (assumed tropical:) [<i>The night was,</i> or <i>became, long to them</i>]. (TA.) -b46- And <span class=\"ar\">ضَرَبَ</span> <span class=\"ar\">إِلَيْهِ</span> (assumed tropical:) <i>It inclined to it.</i> (TA.) [One says, <span class=\"ar\">يَضْرِبُ</span> <span class=\"ar\">إِلَى السَّوَادِ</span> (assumed tropical:) <i>It inclines to blackness,</i> and <span class=\"ar\">إِلَى</span> <span class=\"ar\">الحُمْرَةِ</span> <i>to redness,</i> &amp;c.: often occurring in the lexicons.] -A2- <span class=\"ar\">ضَارَبَهُ فَضَرَبَهُ</span>, aor. of the latter <b class=\"ar\">ضَرُبَ</b> : see 3. -A3- <span class=\"ar\">ضَرُبَتْ يَدُهُ</span> <i>i. q.</i> <span class=\"ar\">جَادَ ضَرْبُهَا</span> [meaning <i>Excellent,</i> or <i>how excellent, is his hand,</i> or <i>arm, in beating, striking, smiting,</i> or <i>hitting!</i> a phrase similar to <span class=\"ar\">رَمُوتْ يَدُهُ</span>]. (K.) -A4- <span class=\"ar\">ضَرِبَ</span>, (IKtt, A, K,) aor. <b class=\"ar\">ضَرَبَ</b> , (K,) inf. n. <span class=\"ar\">ضَرَبٌ</span>, said of herbage, (tropical:) <i>It was marred,</i> or <i>spoilt, by the cold:</i> (A:) or <i>it was smitten by the cold,</i> (IKtt, K, TA,) <i>and injured thereby,</i> and <i>by the wind.</i> (IKtt, TA.) And <span class=\"ar\">ضَرِبَتِ الأَرْضُ</span>, inf. n. <span class=\"ar\">ضَرَبٌ</span>, (assumed tropical:) <i>The land was smitten by hoar-frost,</i> or <i>rime, and its herbage was nipped,</i> or <i>blasted, thereby:</i> (AZ, TA:) and <span class=\"ar\">ضُرِبَت</span> [in like manner] (tropical:) <i>it</i> (i. e. land) <i>was smitten by hoar-frost,</i> or <i>rime;</i> or <i>had hoar-frost,</i> or <i>rime, fallen upon it.</i> (S, A, TA.)</p><p><b>2.</b> <b class=\"ar\">ضَرَّبَ</b> see 1, first sentence; and in two places in a sentence shortly after that. -b2- <span class=\"ar\">ضرّب الشَّىْءَ بِالشَّىْءِ</span>: see 1, in the second quarter of the paragraph. -b3- [Hence,] <span class=\"ar\">التَّضْرِيبُ بَيْنُ القَوْمِ</span> (assumed tropical:) <i>The exciting discord,</i> or <i>strife,</i> or <i>animosity, between,</i> or <i>among, the people,</i> or <i>party.</i> (S, TA.) -b4- And <span class=\"ar\">ضرّب</span>, inf. n. <span class=\"ar\">تَضْرِيبٌ</span>, signifies also (assumed tropical:) <i>He excited, incited, urged,</i> or <i>instigated, and roused to ardour,</i> a courageous man, in war, or battle. (TA.) -b5- <span class=\"ar\">ضرّب المُضَرَّبَةَ</span>, (S, Mgh, Msb,) inf. n. as above, (TA,) <i>He sewed</i> (S, Mgh, Msb) [meaning <i>quilted</i>] <i>with cotton</i> (Mgh, Msb) <i>the</i> <span class=\"ar\">مُضَرَّبَة</span> [q. v.]. (S, Mgh, Msb.) -A2- <span class=\"ar\">ضرّبت عَيْنُهُ</span> <i>His eye became depressed in his head.</i> (K.) -A3- <span class=\"ar\">ضرّب</span>, inf. n. as above, also signifies (assumed tropical:) <i>He exposed himself,</i> or <i>became exposed,</i> (<span class=\"ar\">تَعَرَّضَ</span>,) <i>to the snow,</i> (K, TA,) i. e. <i>the</i> <span class=\"ar\">ضَرِيب</span> [which signifies also, and more commonly, <i>hoar-frost,</i> or <i>rime</i>]. (TA.) -A4- And <i>He drank what is termed</i> <span class=\"ar\">ضَرِيب</span>, (O, K, TA,) i. e. <i>the milk thus called,</i> (O,) or <span class=\"ar\">شَهْد</span> [meaning <i>honey,</i> or <i>honey in its comb,</i> or <i>honey not expressed from its comb</i>]. (TA.)</p><p><b>3.</b> <b class=\"ar\">ضاربهُ</b> , (S, A, Mgh, Msb, K,) inf. n. <span class=\"ar\">مُضَارَبَةٌ</span> (Msb, TA) and <span class=\"ar\">ضَرَابٌ</span>, <i>He contended with him in beating, striking, smiting,</i> or <i>hitting; he beat him,</i> &amp;c., <i>being beaten,</i> &amp;c., <i>by him;</i> (TA;) [<i>he returned him beating for beating, blow for blow,</i> or <i>blows for blows; he bandied,</i> or <i>exchanged, blows with him:</i> and] <i>he contended with him in fight.</i> (S, TA.) One says, <span class=\"ar\">ضاربهُ <span class=\"ar\">فَضَرَبَهُ</span></span>, aor. of the latter verb <b class=\"ar\">ضَرُبَ</b> , (K, TA,) agreeably with the general rule respecting verbs signifying the surpassing, or overcoming, in a contest, (MF, TA,) <i>He contended with him in beating,</i> &amp;c., <i>and he surpassed him,</i> or <i>overcame him, therein.</i> (K, * TA.) See also 6. -b2- [Golius says, as on the authority of the KL, that <span class=\"ar\">ضارب</span> signifies also “ <i>Coivit</i> camelus; ” and Freytag, as on the authority of the K, that it signifies “ <i>inivit</i> camelus camelam: ” but in the KL it is only said that <span class=\"ar\">ضَرَابٌ</span> is an inf. n. of a verb having this meaning; and its verb in this sense, as is said in the S and A and Msb and K, is <span class=\"ar\">ضَرَبَ</span>, which has been thus expl. in the first paragraph.] -b3- <span class=\"ar\">ضارب فِى المَالِ</span> and <span class=\"ar\">بِالمَالِ</span>, inf. n. <span class=\"ar\">مُضَارَبَةٌ</span>, means (tropical:) <i>He trafficked with the property.</i> (A.) And <span class=\"ar\">ضارب لَهُ</span> (A, Mgh, K) <span class=\"ar\">فِى مَالِهِ</span>, (A, Mgh,) or <span class=\"ar\">ضاربهُ فى المَالِ</span>, (S,) inf. n. as above, (S, A, Mgh,) means (tropical:) <i>He trafficked for him with his property</i> [or <i>with the property</i>]; (A, Mgh;) because he who does so generally journeys in the land seeking gain; (Mgh;) app. from <span class=\"ar\">الضَّرْبُ فِى</span> <span class=\"ar\">الأَرْضِ</span> [the journeying in the land] for the purpose of seeking sustenance: (TA:) and is syn. with <span class=\"ar\">قَارَضَهُ</span>, (S, * Mgh, K, * TA, *) <i>he gave him of his property for the purpose of his trafficking therewith on the condition that the gain should be between them two</i> or <i>that the latter should have a certain share of the gain:</i> and accord. to En-Nadr, <span class=\"ar\">ضاربهُ</span> is said of him who does thus and also of the person thus employed. (TA.)</p><p><b>4.</b> <b class=\"ar\">اضرب الفَحْلَ النَّاقَةَ</b> , (S,) and <span class=\"ar\">اضرب النَّاقَةَ</span> <span class=\"ar\">الفَحْلَ</span>, (A, TA,) inf. n. <span class=\"ar\">إِضْرَابٌ</span>, (TA,) (tropical:) <i>He made the stallion to leap the she-camel.</i> (S, * A, * TA.) -b2- <span class=\"ar\">اضرب جَأْشًا لِأَمْرِ كَذَا</span> (tropical:) <i>He disposed,</i> or <i>accommodated, and subjected, himself to such a thing,</i> or <i>such an affair.</i> (A, TA.) -b3- <span class=\"ar\">اضرب</span> <span class=\"ar\">السَّمُومُ المَآءَ</span> (assumed tropical:) <i>The</i> <span class=\"ar\">سموم</span> [or <i>hot wind</i>] <i>caused the earth to imbibe the water</i> (<span class=\"ar\">أَنْشَفَهُ الأَرْضَ</span>). (K.) -b4- <span class=\"ar\">اضرب لِنَفْسِهِ خَاتَمًا</span> (tropical:) [<i>He caused a signet-ring to be made, fashioned,</i> or <i>moulded, for himself</i>]. (A, TA. [See also 8.]) -b5- <span class=\"ar\">اضربهُ البَرْدُ</span>: and <span class=\"ar\">اضرب</span> <span class=\"ar\">الضَّرِيبُ الأَرْضَ</span>: see 1, in the former half of the paragraph. -b6- [Accord. to the TA, <span class=\"ar\">أُضْرِبْنَا</span> (there written <span class=\"ar\">اضرِبنا</span>) seems to signify (assumed tropical:) <i>We were smitten by hoar-frost,</i> or <i>rime:</i> or <i>our land,</i> or <i>herbage, was smitten thereby:</i> thus resembling <span class=\"ar\">أُجْلِدْنَا</span> and <span class=\"ar\">أُصْقِعْنَا</span>: but perhaps the right reading is <span class=\"ar\">أَضْرَبْنَا</span>: for] -A2- <span class=\"ar\">أَضْرَبَ القَوْمُ</span>, (K, TA,) inf. n. <span class=\"ar\">إِضْرَابٌ</span>, (TA,) signifies (assumed tropical:) <i>The people,</i> or <i>party, had hoar-frost,</i> or <i>rime, fallen upon them.</i> (K, TA.) -b2- <span class=\"ar\">اضرب الخُبْزُ</span> (assumed tropical:) <i>The bread</i> (K, TA) i. e. the bread baked in hot ashes (TA) <i>became thoroughly baked,</i> (K, TA,) <i>and in a fit state to be beaten with a stick and to have its ashes and dust shaken off.</i> (TA.) -b3- <span class=\"ar\">اضرب عَنْهُ</span>: see 1, near the middle of the paragraph, in two places. [<span class=\"ar\">اضرب عَنِ الأَمْرِ</span> is expl. in a copy of the A as meaning <span class=\"ar\">عَرَّفَ عَنْهُ</span>, and in the TA, (probably from that copy of the A, as I have reason to believe that it was used by the author of the TA,) is expl. by <span class=\"ar\">عرف عنه</span>; but the right reading is indubitably <span class=\"ar\">عَزَفَ عَنْهُ</span>, with the dotted <span class=\"ar\">ز</span>; meaning (tropical:) <i>He turned away from the thing,</i> or <i>affair;</i> a signification given in the first paragraph: it is said in the A to be tropical. And <span class=\"ar\">اضرب عَنْهُ</span> also signifies (assumed tropical:) <i>He digressed from it; made a digression,</i> or <i>transition, from it;</i> namely, a subject of speech or discourse: and particularly (assumed tropical:) <i>he turned from it and retracted it.</i>] -b4- <span class=\"ar\">اضرب الرَّجُلُ فِى البَيْتِ</span>: see 1, in the latter half of the paragraph. -b5- <span class=\"ar\">اضرب</span> signifies also (tropical:) <i>He was silent; he spoke not:</i> or <i>he lowered his eyes, looking towards the ground:</i> syn. <span class=\"ar\">أَطْرَقَ</span>. (S, TA.)</p><p><b>5.</b> <b class=\"ar\">تضرّب</b> [<i>He beat, struck, smote,</i> or <i>hit, himself much,</i> or <i>violently;</i> or <i>several,</i> or <i>many, times</i>]. One says, <span class=\"ar\">تضرّب بِالحَصَى</span> [<i>He smote himself much with pebbles</i>], (K in art. <span class=\"ar\">كثح</span>,) and <span class=\"ar\">بِالتُّرَابِ</span> [<i>with earth,</i> or <i>dust,</i> as a man sometimes does in vexation]. (L ibid.) -b2- See also 8, in two places.</p><p><b>6.</b> <b class=\"ar\">تضاربوا</b> , (A, MA, Mgh, Msb, K, in the S <span class=\"ar\">تضاربا</span>,) and <span class=\"ar\"> <span class=\"ar\">اضطربوا</span></span>, (A, Mgh, Msb, K, in the S <span class=\"ar\">اضطربا</span>,) and <span class=\"ar\"> <span class=\"ar\">ضاربوا</span></span>, (K,) [<i>They contended in beating, striking, smiting,</i> or <i>hitting, one another;</i> and particularly, <i>in fight;</i>] <i>they smote one another with the sword.</i> (MA.) One says, <span class=\"ar\"> <span class=\"ar\">اضطرب</span>العَبْدَانِ بِالعَصَوَيْنِ</span>, meaning <i>The two slaves beat each other with the two sticks,</i> or <i>staves.</i> (Mgh.)</p><p><b>8.</b> <b class=\"ar\">اضطرب</b> : see 6, in two places. The inf. n. is <span class=\"ar\">اِضْطِرَابٌ</span>, of which the dim. is <span class=\"ar\"> <span class=\"ar\">ضُتَيْرِيبٌ</span></span>, the <span class=\"ar\">ط</span> being changed [back] into <span class=\"ar\">ت</span> because the <span class=\"ar\">ض</span> becomes movent. (S and O in art. <span class=\"ar\">طلق</span>.) -b2- [Hence, said of a thing, <i>Its several parts collided;</i> or <i>were,</i> or <i>became, in a state of collision:</i> and hence,] <i>i. q.</i> <span class=\"ar\">تَحَرَّكَ</span> (S, Msb, K) and <span class=\"ar\">مَاجَ</span>; (K;) [but more significant than either of these; meaning <i>he,</i> or more generally <i>it, was,</i> or <i>became, in a state of commotion, agitation, convulsion, tumult, disturbance,</i> or <i>disorder; was,</i> or <i>became, agitated, convulsed,</i> or <i>unsteady; struggled; floundered; tossed,</i> or <i>shook, about,</i> or <i>to and fro; moved,</i> or <i>went, about,</i> or <i>to and fro,</i> or <i>from side to side; wabbled; wagged; quivered, quaked, trembled,</i> or <i>shivered; fluttered; flickered;</i> and <i>the like;</i>] and <span class=\"ar\"> <span class=\"ar\">تضرّب</span></span> signifies the same. (K. [<span class=\"ar\">ضَرَبَ</span>, also, is sometimes used in the sense of <span class=\"ar\">تَحَرَّكَ</span>, as mentioned before.]) One says, <span class=\"ar\">المَوْجُ يَضْطَرِبُ</span> <i>The waves</i> [<i>dash together, are tumultuous,</i> or] <i>beat one another.</i> (S.) And <span class=\"ar\">اضطرب الوَلَدُ بِالبَطْنِ</span> [<i>The child was,</i> or <i>became, in a state of commotion in the belly</i>]; (A;) And <span class=\"ar\"> <span class=\"ar\">تضرّب</span>فِى البَطْنِ</span> [which means the same]. (TA.) And <span class=\"ar\">اضطرب البَرْقُ فِى السَّحَابِ</span> <i>The lightning was,</i> or <i>became, in a state of commotion in the clouds;</i> [or <i>it flickered therein;</i>] syn. <span class=\"ar\">تَحَرَّكَ</span>. (TA.) And <span class=\"ar\">اضطرب فِى أُمُورِهِ</span> <i>He went to and fro occupied in his affairs for the means of subsistence:</i> (Mgh:) and <span class=\"ar\">اضطرب</span>, alone, signifies <i>he sought to gain;</i> or <i>applied himself with art and diligence to gain;</i> syn. <span class=\"ar\">اِكْتَسَبَ</span>; (K, TA;) and is used by ElKumeyt with <span class=\"ar\">المَجْدَ</span> as its objective complement. (TA. [See also <span class=\"ar\">يَضْرِبُ المَجْدَ</span>, in the latter half of the first paragraph.]) And <span class=\"ar\">اضطرب الرَّجُلُ</span> (assumed tropical:) <i>The man was tall, and therewithal loose, lax, flabby, uncompact, slack,</i> or <i>shaky, in make,</i> or <i>frame.</i> (K, * TA.) And <span class=\"ar\">اضطرب حَبْلُهُمْ</span> [properly, <i>Their rope was shaky, loose,</i> or <i>slack;</i> meaning] (assumed tropical:) <i>their word,</i> or <i>sentence,</i> or <i>saying, varied,</i> or <i>was discordant:</i> (K:) or <i>their words,</i> or <i>sayings,</i> [<i>conflicted,</i> or] <i>varied,</i> or <i>were discordant:</i> and so <span class=\"ar\">أَقْوَالُهُمْ</span> [<i>their sayings</i>]. (Kull p. 56.) And <span class=\"ar\">اضطرب رَأْيُهُ</span> (assumed tropical:) [<i>His opinion was,</i> or <i>became, confused, weak,</i> or <i>unsound</i>]. (TA in art. <span class=\"ar\">رخ</span>.) And <span class=\"ar\">اضطرب عَقْلُهُ</span> (assumed tropical:) [<i>His mind,</i> or <i>intellect, was,</i> or <i>became, disordered, confused,</i> or <i>unsound</i>]. (K, in art. <span class=\"ar\">توه</span>.) And <span class=\"ar\">اضطرب أَمْرُهُ</span> (assumed tropical:) <i>His affair,</i> or <i>state, was,</i> or <i>became, disordered, unsound,</i> or <i>corrupt;</i> (S, K; *) syn. <span class=\"ar\">اِخْتَلَّ</span>; (S, K;) [<i>it was,</i> or <i>became unsound,</i> or <i>unsettled;</i> as is indicated in the TA in art. <span class=\"ar\">زل</span>:] and <span class=\"ar\">اضطربت الأُمُورُ</span> (assumed tropical:) <i>The affairs were,</i> or <i>became, complicated, intricate, confused, discordant,</i> or <i>incongruous;</i> syn. <span class=\"ar\">اِخْتَلَفَت</span>: (Msb:) and <span class=\"ar\">اضطرب الأَمْرُ بَيْنَهُمْ</span> (assumed tropical:) [<i>The affair,</i> or <i>case, was,</i> or <i>became, complicated, intricate,</i> or <i>confused, so as to be a subject of disagreement,</i> or <i>difference, between them</i>]. (Msb voce <span class=\"ar\">شَجَرَ</span>, q. v.) -A2- <span class=\"ar\">اضطرب خَاتَمًا</span> (assumed tropical:) <i>He asked,</i> or <i>ordered, that a signet-ring should be made, fashioned,</i> or <i>moulded, for him:</i> (K, * TA: [see also 4:]) occurring in a trad. (TA.) -b2- <span class=\"ar\">اضطرب بِنَآءً فِى المَسْجِدِ</span> occurs in a trad. as meaning (assumed tropical:) <i>He set up a structure upon stakes driven into the ground in the mosque.</i> (TA.)</p><p><b>10.</b> <b class=\"ar\">استضربت</b> (assumed tropical:) <i>She</i> (a camel) <i>desired the stallion.</i> (K.) -b2- And <span class=\"ar\">استضربهُ فَحْلًا</span> <i>He desired,</i> or <i>demanded, of him a stallion to cover his she-camels;</i> like <span class=\"ar\">اسطرقه فحلا</span>. (TA. in art. <span class=\"ar\">طرق</span>.) -A2- <span class=\"ar\">استضرب العَسَلُ</span> <i>The honey became</i> <span class=\"ar\">ضَرَبَ</span>; (S;) i. e., <i>became thick;</i> (A;) or <i>became white and thick:</i> (S, K:) the verb in this sense is similar to <span class=\"ar\">اِسْتَنْوَقَ</span> in relation to a he-camel, and <span class=\"ar\">اِسْتَتْيَسَت</span> in relation to a she-goat. (S.)</p><p><b class=\"ar\">ضَرْبٌ</b> an inf. n. used in the sense of a pass. part. n.; (TA;) <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَضْرُوبٌ</span></span> [<i>Beaten, struck,</i> &amp;c.]: (K, TA:) in some of the copies of the K, it is made the same as <span class=\"ar\">ضَرْبٌ</span> signifying “ a species ” &amp;c.: but this is a mistake. (TA.) One says <span class=\"ar\">دِرْهَمٌ ضَرْبٌ</span> (tropical:) [<i>A coined dirhem</i>]; using the inf. n. as an epithet, as in the phrases <span class=\"ar\">مَآءٌ غَوْرٌ</span> and <span class=\"ar\">مَآءٌ سَكْبٌ</span>. (S.) And <span class=\"ar\">هٰذَا دِرْهَمٌ ضَرْبَ الأَمِيرِ</span>, in which <span class=\"ar\">ضرب</span> may be thus put in the accus. case as an inf. n., [the meaning being <span class=\"ar\">هٰذَا دِرْهَمٌ</span> <span class=\"ar\">مَضْرُوبٌ ضَرْبَ الأَمِيرِ</span> (tropical:) <i>This is a dirhem coined with the coining of the prince,</i>] which is the most common way. (L, TA.) -b2- (tropical:) <i>A light rain;</i> (S, K, TA;) or so <span class=\"ar\">مَطَرٌ ضَرْبٌ</span>: (A:) <span class=\"ar\">دِيمَةٌ</span> signifies “ a lasting, or continuous, and still, rain; ” and <span class=\"ar\">ضَرْبٌ</span>, <i>a little more than</i> <span class=\"ar\">دِيمَةٌ</span>, or <i>a little above this:</i> and <span class=\"ar\"> <span class=\"ar\">ضَرْبَةٌ</span></span> [as the n. un.] signifies <i>a fall,</i> or <i>shower, of light rain.</i> (As, TA.) -b3- (assumed tropical:) <i>A make, form, fashion, mould,</i> or <i>cast;</i> syn. <span class=\"ar\">صِيغَةٌ</span>. (S, TA.) -b4- (assumed tropical:) <i>A sort,</i> or <i>species;</i> (S, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَرِيبٌ</span></span>; (K;) and accord. to some copies of the K <span class=\"ar\">مَضْرُوبٌ</span>, but this is a mistake: the pl. of the first is <span class=\"ar\">ضُرُوبٌ</span>. (TA.) -b5- Also (tropical:) <i>A like</i> [of a thing and of a person]; (ISd, A, K, TA;) and so <span class=\"ar\"> <span class=\"ar\">ضِرْبٌ</span></span>, as related on the authority of Z; (TA;) and <span class=\"ar\"> <span class=\"ar\">ضَرِيبٌ</span></span>; (IAar, S, A, TA;) as in the phrase <span class=\"ar\">ضَرِيبُ الشَّىْءِ</span> <i>the like of the thing,</i> (S, TA,) and <span class=\"ar\">فُلَانٌ ضَرِيبُ فُلَانٍ</span> <i>such a one is the like of such a one:</i> (IAar, TA:) or <span class=\"ar\">ضَرْبٌ</span> signifies <i>a like in stature and make:</i> (IAar, TA:) its pl. is <span class=\"ar\">ضُرُوبٌ</span>; (TA;) and the pl. of <span class=\"ar\"> <span class=\"ar\">ضَرِيبٌ</span></span> is <span class=\"ar\">ضَرَائِبُ</span> (S) and <span class=\"ar\">ضُرَبَآءُ</span>, this latter occurring in a trad., in the phrase, <span class=\"ar\">ذَهَبَ هٰذَا وَضُرَبَاؤُهُ</span> <i>This went away, and the likes of him.</i> (TA.) One says also <span class=\"ar\">ضَرْبَ قَوْلِهِ</span> [meaning (assumed tropical:) <i>In the like of his saying;</i> referring to a saying in the Kur-án, &amp;c.; a phrase similar to <span class=\"ar\">نَحْوَ قَوْلِهِ</span>]. (AZ, T voce <span class=\"ar\">إِنْ</span> in several places.) -A2- A man <i>penetrating,</i> or <i>vigorous and effective; light,</i> or <i>active, in the accomplishment of an affair</i> or <i>of a want;</i> (K, TA;) <i>not flaccid,</i> or <i>flabby, in flesh.</i> (TA.) And (K) a man (S, TA) <i>light of flesh,</i> (S, A, K, TA,) <i>lean and slender.</i> (TA.) The pl. is <span class=\"ar\">ضُرُبٌ</span>; or, accord. to IJ, this may be pl. of <span class=\"ar\"> <span class=\"ar\">ضَرُوبٌ</span></span>. (L, TA.) -A3- The <i>last foot</i> of a verse: (K, * TA:) pl. [of pauc.] <span class=\"ar\">أَضْرُبٌ</span> and [of mult.] <span class=\"ar\">ضُرُوبٌ</span>. (TA.) -A4- See also <span class=\"ar\">ضَرَبٌ</span>. -b2- [Reiske, as mentioned by Freytag, explains it also as meaning <i>Sour milk:</i> but this is app. a mistake for <span class=\"ar\">صَرْبٌ</span>, with the unpointed <span class=\"ar\">ص</span>.]</p><p><b class=\"ar\">ضِرْبٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ضَرَبٌ</b> (S, A, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ضَرْبٌ</span></span>, but the former is the better known, (K,) <i>Thick honey:</i> (A:) or <i>white honey:</i> (Msb, K:) or <i>thick white honey:</i> (S:) or, as some say, <i>wild honey:</i> and <span class=\"ar\"> <span class=\"ar\">ضَرَبَةٌ</span></span> signifies the same: or a portion thereof: (TA:) <span class=\"ar\">ضَرَبٌ</span> is masc. and fem.: (S:) [for] it is said to be pl. of <span class=\"ar\"> <span class=\"ar\">ضَرَبَةٌ</span></span>, or a coll. gen. n., which is in most cases masc. [but is also fem.]. (Msb.)</p><p><b class=\"ar\">ضَرِبٌ</b> : see <span class=\"ar\">مِضْرَبٌ</span>. -b2- Also (tropical:) Herbage <i>smitten and injured by the cold,</i> and <i>by the wind.</i> (TA.) And (tropical:) Herbage <i>smitten by hoar-frost,</i> or <i>rime.</i> (TA.) And <span class=\"ar\">أَرْضٌ ضَرِبَةٌ</span> (tropical:) <i>Land smitten by hoarfrost,</i> or <i>rime, so that its herbage is nipped,</i> or <i>blasted, thereby.</i> (AZ, TA.)</p><p><b class=\"ar\">ضَرْبَةٌ</b> [inf. n. un. of <span class=\"ar\">ضَرَبَ</span>; <i>A single act of beating, striking,</i> &amp;c.: <i>a blow, stroke,</i> &amp;c.]. -b2- See also <span class=\"ar\">ضَرْبٌ</span>, fourth sentence. -b3- <span class=\"ar\">ضَرْبَةً وَاحِدَةً</span> means (assumed tropical:) <i>At one time; once.</i> (Mgh, Msb.) So in the saying, <span class=\"ar\">لَا آخُذُ مَالِى عَلَيْكَ إِلَّا ضَرْبَةً وَاحِدَةً</span> (assumed tropical:) [<i>I will not take what is due to me on thy part save at one time,</i> or <i>once</i>]. (Mgh.) -b4- <span class=\"ar\">ضَرْبَةُ الغَائِصِ</span>, which is forbidden, is (assumed tropical:) <i>The saying of the diver for pearls, to the merchant, I will dive for thee once, and what I shall bring up shall be thine for such a price.</i> (T, Mgh, TA.)</p><p><b class=\"ar\">ضَرَبَةٌ</b> : see <span class=\"ar\">ضَرَبٌ</span>, in two places.</p><p><b class=\"ar\">ضَرُوبٌ</b> : see <span class=\"ar\">مِضْرَبٌ</span>: and see <span class=\"ar\">ضَرْبٌ</span>, near the end.</p><p><b class=\"ar\">ضَرِيبٌ</b> <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَضْرُوبٌ</span></span> [<i>Beaten, struck,</i> &amp;c.]. (K, TA.) -b2- A tent-peg, or stake, <i>struck so as to be firm in the ground;</i> as also <span class=\"ar\"> <span class=\"ar\">مَضْرُوبٌ</span></span>. (Lh, TA.) -b3- See also <span class=\"ar\">ضَرْبٌ</span>, in three places. -b4- Also, (As, ISd, K, TA,) or <span class=\"ar\">ضَرِيبُ الشَّوْلِ</span>, accord. to Aboo-Nasr, (assumed tropical:) <i>Milk of which some is milked upon other:</i> or, accord. to some of the Arabs of the desert, <i>milk from a number of camels, some of it being thin, and some of it thick:</i> (S:) or <i>milk of which some is poured upon other:</i> (As, TA:) or <i>such as is milked from a number of camels</i> (ISd, K, TA) <i>into one vessel, and mixed together, not consisting of less than the milk of three camels:</i> (ISd, TA:) or <i>milk upon which other has been milked at night, and other on the morrow, and which has been mixed together.</i> (TA.) [See also <span class=\"ar\">صَرِيبٌ</span>.] -b5- And What is <i>bad,</i> of the kind of plants called <span class=\"ar\">حَمْض</span>: or what is <i>broken in pieces,</i> thereof. (K.) -A2- See also <span class=\"ar\">مِضْرَبٌ</span>. -b2- [Hence,] (tropical:) The <i>person who is intrusted, as deputy, with</i> [<i>the disposal of</i>] <i>the gaming-arrows</i> [<i>in the game called</i> <span class=\"ar\">المَيْسِر</span>]: or the <i>person who shuffles those arrows,</i> or <i>who plays with them;</i> (<span class=\"ar\">اَلَّذِى يَضْرِبُ</span> <span class=\"ar\">بِالقِدَاحِ</span>;) as also <span class=\"ar\"> <span class=\"ar\">ضَارِبٌ</span></span>: (K:) or both of these epithets signify the <i>person who shuffles those arrows</i> (<span class=\"ar\">اَلَّذِى يَضْرِبُ بِالقِدَاحِ</span>); and he is the <i>person who is intrusted, as deputy, with</i> [<i>the disposal of</i>] <i>them:</i> (S:) the former is of the measure <span class=\"ar\">فَعِيلٌ</span> in the sense of the measure <span class=\"ar\">فَاعِلٌ</span>: (Sb, TA:) and the pl. is <span class=\"ar\">ضُرَبَآءُ</span>. (S, A.) You say, <span class=\"ar\">هُوَضَرِيبِى</span>, meaning (tropical:) <i>He is my playfellow with the gamingarrows</i> (<span class=\"ar\">مِنْ يَضْرِبُ القِدَاحَ مَعِى</span>). (A, TA.) -b3- And <span class=\"ar\">الضَّرِيبُ</span> is a name of (assumed tropical:) <i>The third arrow of those used in the game called</i> <span class=\"ar\">المَيْسِر</span>: (K, * TA:) that arrow is thus called by some: by others <span class=\"ar\">الرَّقِيبُ</span> [q. v.]: it has three notches; and three portions are assigned to it if successful, and three fines if unsuccessful. (Lh, L, TA.) -b4- [Hence, app.,] <span class=\"ar\">ضَرِيبٌ</span> signifies also (assumed tropical:) <i>A share,</i> or <i>portion.</i> (K.) -b5- Also (assumed tropical:) <i>Hoar-frost,</i> or <i>rime;</i> (S, K;) like <span class=\"ar\">جَلِيدٌ</span> and <span class=\"ar\">سَقِيطٌ</span>: (S in art. <span class=\"ar\">جلد</span>:) and (assumed tropical:) <i>snow.</i> (K.) -b6- And (assumed tropical:) The <i>head:</i> (K:) so called because often in a state of agitation. (TA.) -A3- And <i>i. q.</i> <span class=\"ar\">شَهْدٌ</span> [i. e. <i>honey,</i> or <i>honey in its comb,</i> or <i>honey not expressed from its comb</i>]: and <span class=\"ar\">عَسَلٌ ضَرِيبٌ</span> <i>honey becoming,</i> or <i>become, white and thick.</i> (TA. [See also <span class=\"ar\">ضَرَبٌ</span>.]) -A4- Also <i>Big-bellied,</i> (<span class=\"ar\">بَطِينٌ</span>, [in some copies of the K <span class=\"ar\">بَطْن</span>,]) [as an epithet] of men, (K, TA,) and of others. (TA.)</p><p><b class=\"ar\">ضَرِيبَةٌ</b> <i>A man,</i> (K,) or <i>anything,</i> (T, S, * TA,) <i>living</i> or <i>dead,</i> (T, TA,) <i>struck,</i> or <i>smitten, with the sword:</i> (T, S, K, TA:) the <span class=\"ar\">ة</span> is affixed, though the word has the meaning of a pass. part. n., because it becomes numbered with substs., like <span class=\"ar\">نَطِيحَةٌ</span> and <span class=\"ar\">أَكِيلَةٌ</span>. (S.) -b2- [And also] The <i>place</i> [or <i>part</i>] <i>upon which the blow,</i> or <i>stroke, falls, of the body that is beaten,</i> or <i>struck.</i> (Ham p. 129.) -b3- And <i>Wool,</i> or [<i>goats'</i>] <i>hair, separated,</i> or <i>plucked asunder, with the fingers, and then folded together, and bound with a thread, and spun:</i> (S: [more fully expl. voce <span class=\"ar\">سَلِيلَةٌ</span>:]) and <i>wool that is beaten with a mallet:</i> (TA:) or <i>a portion of wool:</i> (K:) or <i>a portion of cotton,</i> and <i>of wool:</i> (TA:) pl. <span class=\"ar\">ضَرَائِبُ</span>. (S.) -b4- Also (tropical:) <i>An impost that is levied, of the poll-tax</i> or <i>land-tax</i> and <i>the like,</i> (S, A, Mgh, O, Msb, K, TA,) and <i>of</i> [<i>the tolls,</i> or <i>similar exactions, termed</i>] <span class=\"ar\">أَرْصَاد</span>: (S, O, TA:) pl. as above. (S, A, Mgh, &amp;c.) And (hence, TA) (tropical:) The <span class=\"ar\">غَلَّة</span> [as meaning the <i>income,</i> or <i>revenue, arising from the service</i>] of a slave; (S, K, TA;) i. e. <span class=\"ar\">ضَرِيبَةُ العَبْدِ</span> means <i>what the slave pays to his master, of the impost that is laid upon him:</i> <span class=\"ar\">ضَرِيبَةٌ</span> being of the measure <span class=\"ar\">فَعِيلَةٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُولَةٌ</span>. (TA.) -b5- And (tropical:) <i>A nature;</i> or <i>a natural, a native,</i> or <i>an innate, disposition</i> or <i>temper</i> or <i>the like:</i> [as though signifying <i>a particular cast of constitution, moulded by the Creator:</i>] syn. <span class=\"ar\">طَبِيعَةٌ</span>, (S, A, K,) and <span class=\"ar\">سَجِيَّةٌ</span>: (S:) pl. as above. (A, TA.) You say, <span class=\"ar\">فُلَانٌ كَرِيمُ الضَّرِيبَةِ</span> [(tropical:) <i>Such a one is generous in respect of nature</i>]; and <span class=\"ar\">لَئِيمُ الضَّرِيبَةِ</span> [(tropical:) <i>mean</i> &amp;c.]; (S;) and <span class=\"ar\">إِنَّهُ لَكَرِيمُ الضَّرَائِبِ</span> [(tropical:) <i>Verily he is generous in respect of natural dispositions</i>]: and <span class=\"ar\">خُلِقَ النَّاسُ عَلَى ضَرَائِبَ شَتَّى</span> [<i>Men are created of diverse natures</i> &amp;c.]. (TA.) -b6- See also <span class=\"ar\">مَضْرِبٌ</span>.</p><p><b class=\"ar\">ضَرَّابٌ</b> : see <span class=\"ar\">مِضْرَبٌ</span>.</p><p><b class=\"ar\">ضَارِبٌ</b> [<i>Beating, striking, smiting,</i> or <i>hitting:</i> &amp;c.:] act. part. n. of <span class=\"ar\">ضَرَبَ</span> [in all its senses]. (K, TA.) -b2- A she-camel <i>that strikes her milker:</i> (S, K:). or one <i>which, having been submissive,</i> or <i>tractable, before conceiving, afterwards strikes her milker away from before her:</i> or [the pl.] <span class=\"ar\">ضَوَارِبُ</span> signifies she-camels <i>that resist after conceiving, and become repugnant, so that one cannot milk them.</i> (TA.) -b3- Also, and <span class=\"ar\">ضَارِبَةٌ</span>, (K, TA,) the former a possessive epithet [i. e. denoting the possession of a quality], and the latter a verbal epithet [i. e. an act. part. n.], (TA,) (tropical:) A she-camel <i>that raises her tail, and smites with it her vulva,</i> (K, A, in which latter only the pl. is mentioned,) <i>and then goes:</i> (K:) pl. <span class=\"ar\">ضَوَارِبُ</span>. (A, TA.) And the former is like <span class=\"ar\">تضراب</span>, [i. e. <span class=\"ar\"> <span class=\"ar\">تِضْرَابٌ</span></span>, as appears from what follows,] expl. by Lh as meaning (assumed tropical:) A she-camel <i>that has been covered by the stallion,</i> [<i>and</i> app. <i>that raises her tail in consequence thereof,</i>] <i>but respecting which one knows not whether she be pregnant</i> or <i>not:</i> (TA:) or <span class=\"ar\"> <span class=\"ar\">تِضْرَابٌ</span></span> signifies a she-camel <i>recently covered by the stallion</i> [<i>and therefore often raising her tail</i>]. (Mz, 40th <span class=\"ar\">نوع</span>.) -b4- The former (<span class=\"ar\">ضَارِبٌ</span>) signifies also (assumed tropical:) <i>Swimming,</i> (S, TA,) in water. (TA.) Dhu-r-Rummeh says, <span class=\"ar\">لَيَالِىَ اللَّهْوِ يَطْبِينِى فَأَتْبَعُهُ</span> <span class=\"ar\">كَأَنَّنِى ضَارِبٌ فِى غَمْرَةٍ لَعِبُ</span> [<i>In the nights of diversion he calls me and I follow him as though I were swimming in a deep water, sporting</i> therein]. (S, TA.) -b5- <span class=\"ar\">طَيْرٌ ضَوَارِبُ</span> (tropical:) <i>Birds seeking sustenance:</i> (S, A, TA:) or <i>birds traversing the land,</i> [or <i>migrating,</i>] <i>in search of sustenance.</i> (L, TA.) -b6- See also <span class=\"ar\">ضَرِيبٌ</span>. -b7- <span class=\"ar\">ضَارِبٌ</span> also signifies (assumed tropical:) A <i>dark</i> night: (K:) or a night <i>of which the darkness extends to the right and left, and fills the world.</i> (S, O. [So in my copies of the S and in the O and TA: but accord. to Golius, as from the S, “ yet not filling the air. ”]) See the verse of Homeyd cited in the first paragraph. [J cites as an ex. of the last of the meanings expl. above, and so does Sgh in the O, the verse in the sentence here next following.] -b8- (assumed tropical:) Anything <i>long:</i> applied in this sense to a night: thus in the following verse: <span class=\"ar\">وَرَابَعَتْنِى تَحْتَ لَيْلٍ ضَارِبِ</span> <span class=\"ar\">بِسَاعِدٍ فَعْمٍ وَكَفٍّ خَاضِبِ</span> (assumed tropical:) [<i>And that she helped me in lifting and putting on the loads, beneath</i> the darkness of <i>a long night, with a plump fore arm and a hand dyed with hinnà</i>]. (TA.) -b9- (assumed tropical:) <i>A place,</i> (S,) or <i>a depressed place,</i> (K, TA,) and <i>a valley,</i> (TA,) <i>in which are trees.</i> (S, K, TA.) And (assumed tropical:) <i>A piece of rugged ground extending in an oblong form in a plain,</i> or <i>soft, tract.</i> (K, TA.) And (assumed tropical:) The <i>like of a</i> <span class=\"ar\">رَحْبَة</span> <i>in a valley</i> [app. meaning <i>where the water flows into it from its two sides:</i> see art. <span class=\"ar\">رحب</span>]: pl. <span class=\"ar\">ضَوَارِبُ</span>. (K.)</p><p><b class=\"ar\">ضَارُوبٌ</b> [an irregular instrumental noun, like <span class=\"ar\">طَاحُونٌ</span> and some other words of the same measure,] (tropical:) <i>A snare for catching birds.</i> (A, TA.)</p><p><b class=\"ar\">ضُتَيْرِيبٌ</b> dim. of <span class=\"ar\">اِضْطِرَابٌ</span>, inf. n. of 8, q. v.</p><p><b class=\"ar\">تِضْرَابٌ</b> : see <span class=\"ar\">ضَارِبٌ</span>, former half, in two places.</p><p><b class=\"ar\">مَضْرَبٌ</b> is an inf. n. (Ham p. 129.) [See the sentence explaining the phrase <span class=\"ar\">ضَرَبَ فِى الأَرْضِ</span>; and also the sentence next following it, towards the close of the first paragraph.] -b2- And it is also a noun of place [and of time, like <span class=\"ar\">مَضْرِبٌ</span>, which is the regular form]. (Ham ibid.) See the next paragraph, in five places.</p><p><b class=\"ar\">مَضْرِبٌ</b> [and <span class=\"ar\"> <span class=\"ar\">مَضْرَبٌ</span></span>, q. v.,] <i>A place,</i> or <i>time,</i> [the latter, as is said in the explanation of a phrase mentioned in what follows,] <i>of beating, striking, smiting,</i> or <i>hitting:</i> -b2- and also, (assumed tropical:) <i>a place,</i> or <i>time, of journeying.</i> (KL.) -b3- <span class=\"ar\">مَضْرِبُ</span> <span class=\"ar\">الظَّرِبَانِ</span> means (assumed tropical:) <i>The line,</i> or <i>long mark, upon the face of the animal called</i> <span class=\"ar\">ظربان</span> [as though it were a place upon which it had been struck]. (TA in art. <span class=\"ar\">ظرب</span>, q. v.) -b4- And <span class=\"ar\">مَضْرِبٌ</span>, (assumed tropical:) <i>A place where a tent is pitched,</i> or <i>set up.</i> (Msb.) -b5- See also <span class=\"ar\">مِضْرَبٌ</span>. -b6- Also, (thus in the TA in art. <span class=\"ar\">سوف</span>, as from the A,) or <span class=\"ar\"> <span class=\"ar\">مَضْرَبٌ</span></span>, (thus in a copy of the A in the present art.,) (tropical:) <i>i. q.</i> <span class=\"ar\">مَسَافَةٌ</span> [meaning <i>A space,</i> or <i>tract,</i> or <i>an extent, over which one journeys;</i> as being a place of beating the ground]: so in the saying, <span class=\"ar\">بَيْنَهُمْ <span class=\"ar\">مَضْرَبٌ</span>بَعِيدٌ</span> [or <span class=\"ar\">مَضْرِبٌ</span>, i. e. (tropical:) <i>Between them is a far-extending space to be traversed</i>]. (A.) -b7- [<span class=\"ar\">مَضْرِبُ عَسَلَةٍ</span> is a euphemism for (assumed tropical:) <i>The place of injection of sperma:</i> and hence it means (assumed tropical:) <i>the source from which one springs; origin, ancestry,</i> or <i>parentage;</i> &amp;c.] One says, <span class=\"ar\">مَا أَعْرِفُ لَهُ مَضْرِبَ عَسَلَةٍ</span> (S, A) meaning <span class=\"ar\">أَعْرَاقَهُ</span> [i. e. (tropical:) <i>I know not the sources</i> (or <i>the source</i>) <i>from which he has sprung;</i> or <i>his ancestry,</i> or <i>parentage</i>]: (S:) or <span class=\"ar\">مَا يُعْرَفُ لَهُ مَضْرِبُ عَسَلَةٍ</span> (tropical:) <i>No source</i> or <i>origin</i> [or <i>parentage</i>], <i>nor people, nor ancestor</i> or <i>father, nor nobility, pertaining to him, is know.</i> (M, K, TA.) And <span class=\"ar\">مَا لِفُلَانٍ</span> <span class=\"ar\">مَضْرِبُ عَسَلَةٍ</span> (S, A, in the latter <span class=\"ar\">لِزَيْدٍ</span>,) i. e. (tropical:) [<i>Such a one has no source</i>] <i>of kindred</i> (<span class=\"ar\">نَسَب</span>), <i>nor of cattle</i> or <i>property</i> (<span class=\"ar\">مَال</span>). (S.) And <span class=\"ar\">إِنَّهُ لَكَرِيمُ</span> <span class=\"ar\">المَضْرِبِ</span> (tropical:) [<i>Verily he is generous in respect of origin</i>]. (A, TA.) [See also <span class=\"ar\">ضَرِيبَةٌ</span>.] -b8- One says also, <span class=\"ar\">أَتَتِ النَّاقَةُ عَلَى مَضْرِبِهَا</span>, meaning (assumed tropical:) <i>The she-camel arrived at the time</i> [<i>of year</i>] <i>of her being leaped by the stallion;</i> making the time to be like the place. (S.) -b9- <span class=\"ar\">مَضْرِبٌ</span>, (S, A, O, and so in the M in art. <span class=\"ar\">رم</span>,) or <span class=\"ar\"> <span class=\"ar\">مَضْرَبٌ</span></span>, (K, * TA,) with fet-h to the <span class=\"ar\">م</span>, (K, TA,) and to the <span class=\"ar\">ر</span> also, (TA,) [but this is app. a mistake, as the weight of authority is in favour of the former,] (assumed tropical:) <i>A bone in which is marrow:</i> (S, O, K:) or <i>a bone that is broken and from which marrow is extracted</i> [or <i>sought to be extracted</i>]. (M in art. <span class=\"ar\">رم</span>.) One says, of a sheep or goat, (S, A,) that is emaciated, (S,) <span class=\"ar\">مَا يُرِمُّ مِنْهَا مَضْرِبٌ</span> (tropical:) [<i>Not a bone of her that is broken for its marrow contains any marrow</i>]; i. e. when a bone of her is broken, no marrow will be found in it. (S, A.) -b10- And <span class=\"ar\">مَضْرِبٌ</span> (S, Msb, K) and <span class=\"ar\"> <span class=\"ar\">مَضْرَبٌ</span></span> (Msb, K) and <span class=\"ar\"> <span class=\"ar\">مَضْرِبَةٌ</span></span> (S, Msb, K) and <span class=\"ar\"> <span class=\"ar\">مَضْرَبَةٌ</span></span> (Msb, K) and <span class=\"ar\"> <span class=\"ar\">مَضْرُبَةٌ</span></span> (Sb, TA) signify The <i>part</i> of a sword, <i>with which one strikes:</i> (Msb, and Ham p. 129:) or [the <i>part</i>] <i>about a span from the extremity:</i> (S, TA:) or the <i>part exclusive of,</i> or <i>below, the</i> <span class=\"ar\">ظُبَة</span> [q. v.] (<span class=\"ar\">دُونَ الطُّبَةِ</span>): (TA:) or the <i>edge</i> (<span class=\"ar\">حَدّ</span>) thereof; (K, TA;) thus expl. by several of the leading lexicologists: (TA:) and so <span class=\"ar\"> <span class=\"ar\">ضَرِيبَةٌ</span></span>: which last also signifies <i>a sword:</i> (K:) [i. e.] a sword itself is sometimes thus called, as ISd says: (TA:) the pl. of <span class=\"ar\">مَضْرِبٌ</span> is <span class=\"ar\">مَضَارِبُ</span>. (Ham ubi suprà.) -b11- [<span class=\"ar\">مَضْرِبُ مَثَلٍ</span> means (assumed tropical:) <i>The secondary idea,</i> or <i>thing, signified by a parable</i> or <i>proverb, and compared to the primary idea,</i> or <i>thing; the thing,</i> or <i>case, to which a parable</i> or <i>proverb is applied:</i> correlative of <span class=\"ar\">مَوْرِدُ مَثَلٍ</span>: pl. <span class=\"ar\">مَضَارِبُ</span>.] -b12- And [the pl.] <span class=\"ar\">مَضَارِبُ</span> signifies (assumed tropical:) <i>Stratagems in war.</i> (IAar, TA.)</p><p><b class=\"ar\">مُضْرِبٌ</b> [part. n. of <span class=\"ar\">أَضْرَبَ</span>, q. v.]. You say, <span class=\"ar\">رَأَيْتُ حَيَّةً مُضْرِبًا</span> (S, TA) and <span class=\"ar\">مُضْرِبَةً</span> (TA) (tropical:) <i>I saw a serpent still, not moving.</i> (S, TA.)</p><p><b class=\"ar\">مِضْرَبٌ</b> [<i>A thing with which one beats, strikes, smites,</i> or <i>hits;</i>] <i>a thing with which the action termed</i> <span class=\"ar\">الضَّرْب</span> <i>is performed;</i> as also <span class=\"ar\"> <span class=\"ar\">مِضْرَابٌ</span></span>. (K.) <i>A wooden instrument</i> [<i>a kind of mallet</i>] <i>with which the bow-string is struck in the operation of separating cotton.</i> (Msb.) -b2- And, (S, A, K,) as an epithet applied to a man, (S, A,) it signifies <span class=\"ar\">شَدِيدُ</span> <span class=\"ar\">الضَّرْبِ</span> [One <i>who beats, strikes, smites,</i> or <i>hits, vehemently</i>]; (S, O;) or <span class=\"ar\">كَثِيرُ الضَّرْبِ</span> [one <i>who beats,</i> &amp;c., <i>much</i>]; as also <span class=\"ar\"> <span class=\"ar\">ضَرُوبٌ</span></span> (A, K) and <span class=\"ar\"> <span class=\"ar\">ضَرَّابٌ</span></span> (A) and <span class=\"ar\"> <span class=\"ar\">ضَرِيبٌ</span></span> (K, TA) and <span class=\"ar\"> <span class=\"ar\">ضَرِبٌ</span></span>. (O, K, TA. [But in none of these lexicons is this signification mentioned in such a manner as to show that it necessarily relates to any but the first of these words, namely, <span class=\"ar\">مِضْرَبٌ</span>: that it does so, however, is indicated by the measures of all of them.]) -b3- Also, (O, K, TA,) or <span class=\"ar\"> <span class=\"ar\">مَضْرِبٌ</span></span>, with fet-h to the <span class=\"ar\">م</span> and kesr to the <span class=\"ar\">ر</span>, (Mgh,) [thus] written like <span class=\"ar\">مَجْلِسٌ</span> by MF, and pronounced by the vulgar <span class=\"ar\">مَضْرَب</span>, but both of these are [said to be] incorrect, (TA,) <i>A</i> [<i>tent such as is called</i>] <span class=\"ar\">قُبَّة</span>: (Mgh:) or <i>a great</i> [<i>tent of the kind called</i>] <span class=\"ar\">فُسْطَاط</span>; (O, K, TA;) the <span class=\"ar\">فسطاط</span> <i>of a king:</i> (TA:) pl. <span class=\"ar\">مَضَارِبُ</span>. (Mgh, TA.)</p><p><b class=\"ar\">مَضْرِبَةٌ</b> and <span class=\"ar\">مَضْرَبَةٌ</span> and <span class=\"ar\">مَضْرُبَةٌ</span>: see <span class=\"ar\">مَضْرِبٌ</span>.</p><p><b class=\"ar\">مُضَرَّبٌ</b> <i>Sewed</i> [meaning <i>quilted</i>] <i>with cotton:</i> applied in this sense to a <span class=\"ar\">بِسَاط</span> [or thing that is spread like a carpet, &amp;c.]. (Mgh, Msb.)</p><p><b class=\"ar\">مُضَرَّبَةٌ</b> [a subst. signifying <i>A quilt; a quilted garment</i> and <i>the like:</i> see 2]. (S, Mgh, Msb.)</p><p><b class=\"ar\">مِضْرَابٌ</b> The <i>thing</i> [i. e. <i>plectrum</i>] <i>with which a lute</i> (<span class=\"ar\">عُود</span>) <i>is struck</i> [or <i>played</i>]: (S:) pl. <span class=\"ar\">مَضَارِيبُ</span>. (TA in art. <span class=\"ar\">طرب</span>.) [See an ex. voce <span class=\"ar\">طَروب</span>. The plectrum commonly used for this purpose in the present day is a slip of a vulture's feather, and is termed <span class=\"ar\">رِيشَةٌ</span>: see the chap. on music in my “ Modern Egyptians. ”] -b2- See also <span class=\"ar\">مِضْرَبٌ</span>.</p><p><b class=\"ar\">مَضْرُوبٌ</b> : see <span class=\"ar\">ضَرْبٌ</span> and <span class=\"ar\">ضَرِيبٌ</span>, the latter in two places. Dhu-r-Rummeh says, speaking of a cake of bread (<span class=\"ar\">خُبْزَة</span>), <span class=\"ar\">وَمَضْرُوبَةٍ فِى غَيْرِ ذَنْبٍ بَرِيئَةِ</span> <span class=\"ar\">كَسَرْتُ لِأْصْحَابِى عَلَى عَجَلٍ كَسْرَا</span> [<i>Many a thing</i> (meaning many a cake of bread) <i>beaten for no offence, free from blame, I have broken for my companions in haste, with a</i> vigorous <i>breaking</i>]. (TA, after explaining the phrase <span class=\"ar\">أَضْرَبَ الخُبْزُ</span> [q. v.].) -b2- Also (assumed tropical:) <i>Staying, abiding,</i> or <i>remaining,</i> [<i>fixed,</i> or <i>settled,</i>] <i>in a tent,</i> or <i>house.</i> (TA.)</p><p><b class=\"ar\">مُضَارِبٌ</b> <i>One who is employed by another to traffic for him with his</i> (<i>the latter's</i>) <i>property, on the condition of their sharing the gain together:</i> and also <i>one who employs another to traffic for him with his</i> (<i>the former's</i>) <i>property, on that condition:</i> thus expl. by En-Nadr; and Az also allows the use of the word in these two senses. (TA.)</p><p><b class=\"ar\">مُضْطَرَبٌ</b> may mean <span class=\"ar\">اِضْطَرَابٌ</span> [i. e. it may be used as an inf. n. of <span class=\"ar\">اِضْطَرَبَ</span> (q. v.), agreeably with a general rule]: -b2- and it may mean <i>A place of</i> <span class=\"ar\">اِضْطِرَاب</span>: (Ham p. 142:) [thus used it often means <i>a place in which one goes to and fro seeking the means of subsistence:</i> and simply <i>a place in which one seeks gain:</i> see <span class=\"ar\">اِضْطَرَبَ فِى</span> <span class=\"ar\">أُمُورِهِ</span>: and see also the syns. <span class=\"ar\">مُرَاغَمٌ</span> (in two places) and <span class=\"ar\">مُنْتَفَدٌ</span>.] -b3- [It is also a pass. part. n.: and hence the phrase <span class=\"ar\">مُضْطَرَبَاتٌ لِلْمَعَاشِ</span>, meaning <i>The things that are desired to be gained for subsistence,</i> or <i>sustenance:</i> see <span class=\"ar\">مَرَاغِبُ</span>.]</p><p><b class=\"ar\">مُضْطَرِبٌ</b> [A thing <i>having its several parts in a state of collision:</i> and hence, a thing, and a man, <i>in a state of commotion, agitation, convulsion,</i> &amp;c.: see its verb, 8]. -b2- One says, <span class=\"ar\">جَآءَ مُضْطَرِبَ</span> <span class=\"ar\">العِنَانِ</span> [lit. <i>He came with quivering rein</i>]; meaning <i>he came discomfited,</i> or <i>put to flight, and alone.</i> (K.) -b3- And <span class=\"ar\">رَجُلٌ مُضْطَرِبُ الخَلْقِ</span> (tropical:) <i>A man incongruous, unsound, faulty,</i> or <i>weak, in respect of make:</i> (A, TA:) <i>tall, and</i> [<i>loose, lax, flabby, uncompact, slack, shaky,</i> or] <i>not strong of make.</i> (TA.) -b4- And <span class=\"ar\">حَدِيثٌ مُضْطَرِبُ السَّنَدِ</span> (assumed tropical:) <i>A tradition unsound, faulty,</i> or <i>weak, in respect of the authority upon which it rests,</i> or <i>to which it is traced up</i> or <i>ascribed;</i> syn. <span class=\"ar\">مُخْتَلٌّ</span>. (S, TA.)</p>"},"ضرر":{"mf":"الضُّرُّ: سوءُ الحال، إمّا في نفسه لقلّة العلم والفضل والعفّة، وإمّا في بدنه لعدم جارحة ونقص، وإمّا في حالة ظاهرة من قلّة مال وجاه، وقوله: فَكَشَفْنا ما بِهِ مِنْ ضُرٍّ<br>[الأنبياء/ ٨٤]، فهو محتمل لثلاثتها، وقوله:<br><br>وَإِذا مَسَّ الْإِنْسانَ الضُّرُّ [يونس/ ١٢]، وقوله: فَلَمَّا كَشَفْنا عَنْهُ ضُرَّهُ مَرَّ كَأَنْ لَمْ يَدْعُنا إِلى ضُرٍّ مَسَّهُ<br>[يونس/ ١٢]، يقال: ضَرَّهُ ضُرّاً: جلب إليه ضُرّاً، وقوله: لَنْ يَضُرُّوكُمْ إِلَّا أَذىً<br>[آل عمران/ ١١١]، ينبّههم على قلّة ما ينالهم من جهتهم، ويؤمّنهم من ضَرَرٍ يلحقهم نحو: لا يَضُرُّكُمْ كَيْدُهُمْ شَيْئاً<br>[آل عمران/ ١٢٠]، وَلَيْسَ بِضارِّهِمْ شَيْئاً<br>[المجادلة/ ١٠]، وَما هُمْ بِضارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ<br>[البقرة/ ١٠٢]، وقال تعالى: وَيَتَعَلَّمُونَ ما يَضُرُّهُمْ وَلا يَنْفَعُهُمْ<br><strong>[البقرة/ ١٠٢]، وقال:</strong><br>يَدْعُوا مِنْ دُونِ اللَّهِ ما لا يَضُرُّهُ وَما لا يَنْفَعُهُ<br>[الحج/ ١٢]، وقوله: يَدْعُوا لَمَنْ ضَرُّهُ أَقْرَبُ مِنْ نَفْعِهِ<br>[الحج/ ١٣]. فالأوّل يعنى به الضُّرُّ والنّفع، اللّذان بالقصد والإرادة، تنبيها أنه لا يقصد في ذلك ضَرّاً ولا نفعا لكونه جمادا. وفي الثاني يريد ما يتولّد من الاستعانة به ومن عبادته، لا ما يكون منه بقصده، والضَّرَّاءُ يقابل بالسَّرَّاء والنّعماء، والضرّ بالنّفع. قال تعالى: وَلَئِنْ أَذَقْناهُ نَعْماءَ بَعْدَ ضَرَّاءَ<br>[هود/ ١٠]، وَلا يَمْلِكُونَ لِأَنْفُسِهِمْ ضَرًّا وَلا نَفْعاً [الفرقان/ ٣]، ورجلٌ ضَرِيرٌ: كناية عن فقد بصره، وضَرِيرُ الوادي: شاطئه الذي ضَرَّهُ الماءُ، والضَّرِيرُ:<br>المَضَارُّ، وقد ضَارَرْتُهُ. قال تعالى: وَلا تُضآرُّوهُنَ<br>[الطلاق/ ٦]، وقال: وَلا يُضَارَّ كاتِبٌ وَلا شَهِيدٌ<br>[البقرة/ ٢٨٢]، يجوز أن يكون مسندا إلى الفاعل، كأنه قال: لا يُضَارِرْ، وأن يكون مفعولا، أي: لا يُضَارَرْ، بأن يشعل عن صنعته ومعاشه باستدعاء شهادته، وقال:<br>لا تُضَارَّ والِدَةٌ بِوَلَدِها<br>[البقرة/ ٢٣٣]، فإذا قرئ بالرّفع فلفظه خبر ومعناه أمر، وإذا فتح فأمر <strong>«١»</strong>. قال تعالى: ضِراراً لِتَعْتَدُوا<br>[البقرة/ ٢٣١]، والضَّرَّةُ أصلُها الفَعْلة التي تَضُرُّ، وسمّي المرأتان تحت رجل واحد كلّ واحدة منهما ضَرَّةٌ، لاعتقادهم أنّها تَضُرُّ بالمرأة الأخرى، ولأجل هذا النّظر منهم قال النبيّ صلّى الله عليه وسلم:<br><strong>«لا تسأل المرأة طلاق أختها لتكفئ ما في صحفتها»</strong> <strong>«٢»</strong> والضَّرَّاءُ: التّزويج بِضَرَّةٍ، ورجلٌ مُضِرٌّ: ذو زوجين فصاعدا. وامرأةٌ مُضِرٌّ: لها ضَرَّةٌ. والاضْطِرَارُ: حمل الإنسان على ما يَضُرُّهُ، وهو في التّعارف حمله على أمر يكرهه، وذلك على ضربين:<br><br>أحدهما: اضطرار بسبب خارج كمن يضرب، أو يهدّد، حتى يفعل منقادا، ويؤخذ قهرا، فيحمل على ذلك كما قال: ثُمَّ أَضْطَرُّهُ إِلى عَذابِ النَّارِ<br>[البقرة/ ١٢٦]، ثُمَّ نَضْطَرُّهُمْ إِلى عَذابٍ غَلِيظٍ<br>[لقمان/ ٢٤].<br>والثاني: بسبب داخل وذلك إمّا بقهر قوّة له لا يناله بدفعها هلاك، كمن غلب عليه شهوة خمر أو قمار، وإمّا بقهر قوّة يناله بدفعها الهلاك، كمن اشتدّ به الجوع فَاضْطُرَّ إلى أكل ميتة، وعلى هذا قوله: فَمَنِ اضْطُرَّ غَيْرَ باغٍ وَلا عادٍ<br>[البقرة/ ١٧٣]، فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ [المائدة/ ٣]، وقال: أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذا دَعاهُ<br>[النمل/ ٦٢]، فهو عامّ في كلّ ذلك، والضَّرُورِيُّ يقال على ثلاثة أضرب:<br>أحدها: إما يكون على طريق القهر والقسر، لا على الاختيار كالشّجر إذا حرّكته الرّيح الشّديدة.<br>والثاني: ما لا يحصل وجوده إلّا به نحو الغذاء الضَّرُورِيِّ للإنسان في حفظ البدن.<br>والثالث: يقال فيما لا يمكن أن يكون على خلافه، نحو أن يقال: الجسم الواحد لا يصحّ حصوله في مكانين في حالة واحدة بالضَّرُورَةِ.<br>وقيل: الضَّرَّةُ أصلُ الأنملة، وأصلُ الضّرع، والشّحمةُ المتدلّيةُ من الألية.","mq":[["خلاف النفع","اجتماع الشي"],"الضاد والراء ثلاثة أصول: الأوّل خلاف النَّفع، والثانى اجتماعُ الشَّئ، والثالث القوّة.<br>فالأوَّل الضَّرّ: ضدُّ النَّفْع. ويقال ضَرَّه يضُرُّه ضَرًّا. ثمَّ يحمل على هذا كلُّ ما جانَسَه أو قارَبه. فالضُّرُّ: الهُزال. والضِّرّ: تزوُّج المرأة على ضَرَّة. يقال نكحَتْ فلانةُ على ضِرّ، أى على امرأةٍ كانت قَب"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَرَّهُ</b> , (S, A, Msb, K,) and <span class=\"ar\">ضَرَّ بِهِ</span>, (K,) aor. <b class=\"ar\">ضَرُرَ</b> , (Msb,) inf. n. <span class=\"ar\">ضَرٌّ</span>; (S, Msb, K;) and <span class=\"ar\"> <span class=\"ar\">ضارّهُ</span></span>, [which see also below,] (S, A, Msb, K,) inf. n. <span class=\"ar\">مُضَارَّةٌ</span> (Msb, K) and <span class=\"ar\">ضِرَارٌ</span>; (A, Msb, K;) and <span class=\"ar\"> <span class=\"ar\">اضرّهُ</span></span>, (K,) or <span class=\"ar\"> <span class=\"ar\">اضرّ</span>بِهِ</span>, (Msb,) or both, inf. n. <span class=\"ar\">إِضْرَارٌ</span>; (TA;) <i>He,</i> or <i>it, harmed, injured, hurt, marred, mischiefed,</i> or <i>damaged, him,</i> or <i>it; contr. of</i> <span class=\"ar\">نَفَعَهُ</span>; (S, A, K;) <i>did to him,</i> or <i>it, an act that was evil,</i> or <i>disliked,</i> or <i>hated.</i> (Msb.) -b2- <span class=\"ar\">ضَرَّهُ إِلَيْهِ</span>: see 8. -b3- <span class=\"ar\">لَا يَضُرَّكَ عَلَيْهِ جَمَلٌ</span> (tropical:) <i>No camel will be more sufficient for thee than he;</i> syn. <span class=\"ar\">لَا يَزِيدُكَ</span>: and <span class=\"ar\">لَا يَضُرُّكَ عَلَيْهِ رَجُلٌ</span> (tropical:) [<i>No man will be more sufficient for thee than he;</i> or] <i>thou wilt not find a man who will be more sufficient for thee than he;</i> i. e. <span class=\"ar\">لَا تَجِدُ رَجُلًا يَزِيدُكَ عَلَى مَا عِنْدَ هٰذَا</span> <span class=\"ar\">الرَّجُلِ مِنَ الكِفَايَةِ</span>: (ISk, S:) and <span class=\"ar\">مَا يَضُرُّكَ عَلَى</span> <span class=\"ar\">الضَّبِّ صَيْدٌ</span> (tropical:) <i>No animal that is hunted is more sufficient for thee than the</i> <span class=\"ar\">ضَبّ</span>; and so <span class=\"ar\">مَا يَضِيرُكَ</span>: and <span class=\"ar\">مَا تَضُرُّكَ عَلَيْهَا جَارِيَةٌ</span> (tropical:) <i>No girl,</i> or <i>young woman, is more sufficient for thee than she;</i> syn. <span class=\"ar\">مَا تَزِيدُكَ</span>: (A:) and <span class=\"ar\">مَا يَضُرُّكَ عَلَيْهِ شَيْئًا</span> (tropical:) <i>He,</i> or <i>it, is not at all more sufficient for thee than he,</i> or <i>it;</i> syn. <span class=\"ar\">مَا يَزِيدُكَ</span>. (IAar, TA.) -A2- <span class=\"ar\">ضَرَّ</span>, [sec. pers. app. <span class=\"ar\">ضَرُرْتَ</span>, and aor. <span class=\"ar\">يَضُرُّ</span>,] inf. n. <span class=\"ar\">ضَرَارَةٌ</span>, (assumed tropical:) <i>He was,</i> or <i>became, blind:</i> part. n. <span class=\"ar\">ضَرِيرٌ</span> [q. v.]. (MA.)</p><p><b>3.</b> <b class=\"ar\">ضارّهُ</b> , inf. n. <span class=\"ar\">مُضَارَّةٌ</span> and <span class=\"ar\">ضَرَارٌ</span>, <i>He harmed him, injured him,</i> or <i>hurt him, in return,</i> or <i>in requital:</i> whence the saying in a trad., <span class=\"ar\">لا ضَرَرَ</span> <span class=\"ar\">وَلَا ضِرَارَ فِى الإِسْلَامِ</span> <i>There shall be no harming, injuring,</i> or <i>hurting,</i> of one man by another, <i>in the first instance, nor in return,</i> or <i>requital, in El-Islám:</i> (Mgh, TA: *) <span class=\"ar\">ضِرَارٌ</span> is <i>syn. with</i> <span class=\"ar\">مُضَارَّةٌ</span>: (S:) or, accord. to some, it is <i>syn. with</i> <span class=\"ar\">ضَرَرٌ</span>; and in the phrase in a trad. mentioned above, is added as a corroborative. (TA.) See also 1. <span class=\"ar\">مُضَارَّةٌ</span> in the case of a testament is the not executing it; or the violating it in part; or the bequeathing to any unfit person or persons; and the like; contrary to the <span class=\"ar\">سُنَّة</span>. (TA.) -b2- <i>He disagreed with,</i> or <i>differed from, him; dissented from him; was contrary, opposed,</i> or <i>repugnant, to him;</i> or <i>he acted contrarily, contrariously, adversely,</i> or <i>in opposition, to him;</i> syn. <span class=\"ar\">خالَفَهُ</span>. (K.) And hence, accord. to some, the saying in a trad., (O, K,) relating to the seeing God on the day of resurrection, (O,) <span class=\"ar\">لَا تُضَارُّونَ فِى رُؤْيَتِهِ</span>, (O, K,) i. e. <i>Ye will not differ, one from another, nor dispute together, respecting</i> the truth of <i>the seeing Him;</i> (Zj, O, * TA;) because of his manifest appearance: (Zj, TA:) or the meaning is, <span class=\"ar\">لَا تُضَامُّونَ</span>, (S, K,) and thus some relate it, (TA,) meaning <i>ye will not draw yourselves together,</i> (K, TA,) and <i>straiten one another;</i> one saying to another “ Show me Him, ” like as people do in looking at the new moon, but each will by himself have the sight of Him: (TA:) or, as some say, it is <span class=\"ar\">لَا <span class=\"ar\">تَضَارُّونَ</span></span> [originally <span class=\"ar\">تَتَضَارُّونَ</span>], meaning <span class=\"ar\">لَا تَضَامُّونَ</span>, [which is the same in signification as <span class=\"ar\">لَا تُضَامُّونَ</span>], i. e. with fet-h to the <span class=\"ar\">ت</span>: (TA, and so in one of my copies of the S:) and some say, <span class=\"ar\">لا تُضَارُونَ</span>, from <span class=\"ar\">الضَّيْرُ</span>; (Mgh, TA;) [i. e. <i>ye will not be hurt;</i>] meaning <i>ye will not hurt one another:</i> (M in art. <span class=\"ar\">ضير</span>:) and some, <span class=\"ar\">لَا تُضَامُون</span>, from <span class=\"ar\">الضَّيْمُ</span>. (Mgh, TA.) -b3- See also 4; and the phrase <span class=\"ar\">تَزَوَّجَ عَلَى</span> <span class=\"ar\">مُضَارَّةٍ</span>, voce <span class=\"ar\">ضِرٌّ</span>.</p><p><b>4.</b> <b class=\"ar\">اضرّهُ</b> and <b class=\"ar\">اضرّبِهِ</b> : see 1, first sentence. -b2- <span class=\"ar\">اضرّهُ عَلَى الأَمْرِ</span> <i>He compelled him against his will to do the thing.</i> (Sgh, K.) [See also 8.] -A2- <span class=\"ar\">اضرّ</span>, intrans., (tropical:) <i>It</i> (anything) <i>approached so near as to harm, injure,</i> or <i>hurt;</i> (TA;) or <i>so near as to straighten,</i> or <i>incommode.</i> (L.) You say, <span class=\"ar\">اضرّ بِهِ</span>, meaning (tropical:) <i>It approached very near to him, so as to annoy him:</i> (TA, from a trad.:) or (tropical:) <i>he drew very near to him:</i> (S, A:) or (tropical:) <i>he clave,</i> or <i>stuck, to him.</i> (A.) And <span class=\"ar\">اضرّ بِالطَّرِيق</span> (tropical:) <i>He approached the road, but was not upon it.</i> (TA.) And <span class=\"ar\">بَنُو فُلَانٍ يُضِرُّ الطَّرِيقُ</span> (tropical:) <i>The sons of such a one are one the travelled track.</i> (A.) And <span class=\"ar\">اضرّ</span> <span class=\"ar\">السَّيْلُ مِنَ الحَائِطِ</span> (assumed tropical:) <i>The torrent drew near to the wall:</i> and <span class=\"ar\">السَّحَابُ إِلَى الأَرْضِ</span> <i>the clouds to the earth.</i> (K.) -b2- <span class=\"ar\">اضرّ عَلَيْهِ</span> (tropical:) <i>He importuned him; plied him; plied him hard; pressed him; pressed him hard; was urgent with him; persecuted him,</i> or <i>harassed him.</i> (A.) -b3- <span class=\"ar\">اضرّ الفَرَسُ عَلَى فَأْسِ اللِّجَامِ</span> (tropical:) <i>The horse champed the</i> <span class=\"ar\">فأس</span> [q. v.] <i>of the bit;</i> (A 'Obeyd, S, A;) and so <span class=\"ar\">اضزّ</span>. (S.) -b4- <span class=\"ar\">اضرّ فُلَانٌ</span> <span class=\"ar\">عَلَى السَّيْرِ الشَّدِيدِ</span> (assumed tropical:) <i>Such a one bore patiently hard journeying.</i> (TA.) -A3- Also, (Msb,) inf. n. <span class=\"ar\">إِضْرَارٌ</span>, (S,) <i>He took to himself a wife while having another wife:</i> (As, S, Msb, TA:) [and so, app., <span class=\"ar\"> <span class=\"ar\">ضارّ</span></span>: (see <span class=\"ar\">ضِرٌّ</span>:)] or <i>he gave</i> [a woman] <i>in marriage to a man having at the time another wife.</i> (TA.) -A4- <span class=\"ar\">اضرّ يَعْدُو</span> (S, K, * TA) signifies <i>He hastened</i> (S, K, TA) <i>somewhat in running,</i> accord. to A 'Obeyd; (S, TA;) but Et-Toosee says that this is a mistake, and that it is correctly <span class=\"ar\">اصرّ</span>. (TA.)</p><p><b>5.</b> <b class=\"ar\">تضرّر</b> <i>He was</i> [<i>harmed, injured,</i> or <i>hurt;</i> or] <i>afflicted, grieved,</i> or <i>sick:</i> and <i>he experienced straitness, pressure,</i> or <i>inconvenience.</i> (KL.)</p><p><b>6.</b> <b class=\"ar\">لَا تَضَارُّونَ</b> [originally <span class=\"ar\">تَتَضَارُّونَ</span>]: see 3.</p><p><b>8.</b> <b class=\"ar\">اضطرّهُ إِلَى كَذَا</b> <i>It,</i> (a thing, or an affair, TA,) or <i>he,</i> [a man, or God,] <i>necessitated, constrained, compelled, forced,</i> or <i>drove, him to have recourse to,</i> or <i>to do, such a thing;</i> or <i>impelled,</i> or <i>drove, him, against his will, to it,</i> or <i>to do it;</i> (Msb, K;) <i>so that he had no means of avoiding it;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَرَّهُ</span>إِلَيْهِ</span>: (Msb:) <i>it made him to want,</i> or <i>be in need of, such a thing:</i> (K, TA:) from <span class=\"ar\">ضَرَرٌ</span> signifying “ narrowness, ” or “ straitness. ” (TA.) [See also 4. Hence the phrase, <span class=\"ar\">لَأَضْطَرَّنَّكَ إِلَى أَصْلِكَ</span>, expl. in art. <span class=\"ar\">اصل</span>. See also the Kur ii. 120, and xxxi. 23.] -b2- <span class=\"ar\">اُضْطُرَّ إِلَى كَذَا</span> <i>He was,</i> or <i>became, necessitated, constrained, compelled, forced,</i> or <i>driven, to have recourse to,</i> or <i>to do, such a thing;</i> or <i>was impelled,</i> or <i>driven, against his will, to it,</i> or <i>to do it:</i> (S, K:) <i>he wanted,</i> or <i>was</i> or <i>became in need of, such a thing.</i> (K.)</p><p><b class=\"ar\">ضَرٌّ</b> : see the next paragraph, in two places.</p><p><b class=\"ar\">ضُرٌّ</b> <i>Harm, injury, hurt, mischief,</i> or <i>damage; contr. of</i> <span class=\"ar\">نَفْعٌ</span>; as also <span class=\"ar\"> <span class=\"ar\">ضَرٌّ</span></span>, (A, K,) or this is an inf. n., (S, Msb, K,) and the former is a simple subst.; (ADk, Msb, K;) and <span class=\"ar\"> <span class=\"ar\">ضَرَرٌ</span></span> [which is now the most common]: (S, Mgh, Msb, TA:) or <i>an evil state</i> or <i>condition;</i> (ADk, T, S, L, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَرَرٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">تَضِرَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">تَضُرَّةٌ</span></span>; (K; for the right reading in the K is <span class=\"ar\">والضَّرَرُ سُوْءُ</span> <span class=\"ar\">الحَالِ</span>, as in the L, &amp;c.; not <span class=\"ar\">والضرر وسوء الحال</span>; TA; [but in some of the copies of the K, and in the TA, this signification is assigned to <span class=\"ar\">ضَرٌّ</span> instead of <span class=\"ar\">ضُرٌّ</span>; and in the latter, its pl. is said to be <span class=\"ar\">أَضُرٌّ</span>;]) and <i>poverty;</i> and <i>bodily affliction:</i> but the contr. of <span class=\"ar\">نَفْعٌ</span> is termed <span class=\"ar\"> <span class=\"ar\">ضَرٌّ</span></span>, with fet-h: (ADk, T, Msb, TA: *) [see also <span class=\"ar\">ضَرَّةٌ</span> and <span class=\"ar\">ضَرَرٌ</span> and <span class=\"ar\">ضَرَّآءُ</span> and <span class=\"ar\">ضَرُورَةٌ</span> and <span class=\"ar\">ضَارُورَآءُ</span>, all of which have similar meanings:] and <i>disease;</i> (A, Msb;) thus in the Kur xxi. 83: (Msb:) or <i>leanness:</i> (S, A, TA:) the <i>state,</i> or <i>condition, of him who is termed</i> <span class=\"ar\">ضَرِير</span> [q. v.]. (TA.) -A2- See also the next paragraph, in two places.</p><p><b class=\"ar\">ضَرٌّ</b> The <i>taking a wife in addition to another wife;</i> (S;) a subst. from <span class=\"ar\">ضَرَّةٌ</span>. (K.) You say, <span class=\"ar\">نُكِحَتِ المَرْأَةُ عَلَى ضِرٍّ</span> <i>The woman was taken to wife in addition to a former wife.</i> (S.) And, accord. to Aboo-'Abd-Allah Et-Tuwál, <span class=\"ar\">تَزَوَّجْتُ</span> <span class=\"ar\">المَرْأَةَ عَلَى ضِرٍّ</span> and <span class=\"ar\"> <span class=\"ar\">ضُرٍّ</span></span> [<i>I took the woman to wife in addition to another wife</i>]. (S.) And <span class=\"ar\">تَزَوَّجَ</span> <span class=\"ar\">عَلَى ضِرٍّ</span> and <span class=\"ar\"> <span class=\"ar\">ضُرٍّ</span></span> i. e. <span class=\"ar\"> <span class=\"ar\">مُضَارَّةٍ</span></span>, meaning <i>He married so as to have two</i> or <i>three wives together.</i> (K.) And Kr mentions the phrase, <span class=\"ar\">تَزَوَّجْتُ المَرْأَةَ عَلَى</span> <span class=\"ar\">ضِرٍّ كُنَّ لَهَا</span> [<i>I took to wife the woman in addition to others who were her fellow-wives</i>]: and if it be so, <span class=\"ar\">ضِرّ</span> is an inf. n. [used in this instance as an epithet, and therefore applicable to a pl. number as well as to a single person], formed by the rejection of the augmentative letter [in its verb, i. e. <span class=\"ar\">أَضَرَّ</span>], or it is a pl. that has no sing. (TA.) -A2- One says also <span class=\"ar\">رَجُلٌ ضِرُّ أَضْرَارٍ</span> (K, TA) i. e. <i>A man</i> [who is] <i>a strong one of strong ones;</i> like as one says <span class=\"ar\">صِلُّ أَصْلَالٍ</span> and <span class=\"ar\">ضِلُّ أَضْلَالٍ</span>: (TA:) or <i>very cunning</i> (<span class=\"ar\">دَاهِيَةٌ</span>) <i>in his judgment,</i> or <i>opinion.</i> (K, TA.)</p><p><b class=\"ar\">ضَرَّةٌ</b> [<i>Necessity,</i> or <i>need;</i>] a subst. from 8: (K, TA:) <i>hardness, distressfulness,</i> or <i>afflictiveness, of state</i> or <i>condition:</i> and <i>annoyance, molestation, harm,</i> or <i>hurt.</i> (Sgh, K.) See also [<span class=\"ar\">ضُرٌّ</span>, and] <span class=\"ar\">ضَرَرٌ</span>, and <span class=\"ar\">ضَرَّآءُ</span>, and <span class=\"ar\">ضَرُورَةٌ</span>. -A2- A woman's <i>husband's wife;</i> her <i>fellow-wife:</i> (S, Msb, K:) an appellation disliked by the Muslim; <span class=\"ar\">جَارَةٌ</span> being used in preference to it; accord. to a trad.: (TA:) pl. <span class=\"ar\">ضَرَائِرُ</span> (Msb, K) and <span class=\"ar\">ضَرَّاتٌ</span>; (Msb;) the former extr. [with respect to rule]; (TA;) the latter regular. (Msb.) [See also <span class=\"ar\">عَلَّةٌ</span>.] -b2- Hence, sing. of <span class=\"ar\">ضَرَائِرُ</span> signifying (tropical:) <i>Discordant things</i> or <i>affairs;</i> likened to fellow-wives, who will not agree. (TA.) -b3- And [hence also, app.,] <span class=\"ar\">الضَّرَّتَانِ</span> is a term applied to (assumed tropical:) <i>The two stones of a mill.</i> (S, M.) -A3- The <i>flesh of the</i> <span class=\"ar\">ضَرْع</span> [or <i>udder</i>]: (S:) or the <i>udder</i> (<span class=\"ar\">ضرع</span>) <i>altogether,</i> (K, TA,) <i>except the</i> <span class=\"ar\">أَطْبَآء</span> [or <i>teats</i>], <i>when containing milk,</i> but not otherwise: (TA:) or the <i>base of the</i> <span class=\"ar\">ضرع</span>, <i>which is never,</i> or <i>scarcely ever, without milk in it:</i> (TA:) or the <i>base of the</i> <span class=\"ar\">ثَدْى</span> [or <i>breast</i>]: and <i>i. q.</i> <span class=\"ar\">خِلْفٌ</span> [q. v.]. (K.) One says <span class=\"ar\">ضَرَّةٌ شَكْرَى</span>, meaning <i>A full</i> <span class=\"ar\">ضرّة</span>: (S in this art.:) or <i>a</i> <span class=\"ar\">ضرّة</span> <i>having much milk.</i> (S in art. <span class=\"ar\">شكر</span>.) -b2- <span class=\"ar\">ضَرَّةُ الإِبْهَامِ</span> <i>The portion of flesh that is beneath the thumb, which is what corresponds to the</i> <span class=\"ar\">أَلْيَه</span> <i>in the hand:</i> (S:) or <span class=\"ar\">الضَّرَّةُ</span> signifies <i>the portion of the palm of the hand extending from beneath the little finger to the wrist:</i> (Zj, in his “ Khalk el-Insán: ”) or <i>the inner side of the hand,</i> (K, TA,) <i>over against the little finger, corresponding to the</i> <span class=\"ar\">الية</span> <i>in the hand:</i> (TA:) or <i>the portion of flesh beneath the thumb:</i> (K:) or <i>the root thereof</i> [i. e. of the thumb]: (TA:) and <i>that part of the flesh of the sole of the foot upon which one treads, next the great toe.</i> (K.) [See <span class=\"ar\">أَلْيَةٌ</span>.] -b3- The pl. of <span class=\"ar\">ضَرَّةٌ</span> (in all the senses expl. above, TA) is <span class=\"ar\">ضَرَائِرُ</span>, (K, TA,) which [as said above] is extr. (TA.) -b4- And <span class=\"ar\">الضَّرَّتَانِ</span> signifies <i>The buttocks, on each side of the bone thereof:</i> (K:) or <i>the two flabby portions of flesh, on each side.</i> (M, TA.) -A4- Also <i>Much property,</i> (S,) or <i>many cattle,</i> (S, * TA,) <i>exclusive of money:</i> (TA:) or <i>property,</i> or <i>cattle,</i> (<span class=\"ar\">مال</span>,) <i>upon which one relies</i> [<i>for his maintenance</i>], <i>but belonging to another,</i> or <i>others,</i> (K, TA,) <i>of his relations:</i> (TA:) and <i>a detached number of cattle, of camels,</i> and <i>of sheep</i> or <i>goats.</i> (K, TA.)</p><p><b class=\"ar\">ضُرَّةٌ</b> : see <span class=\"ar\">ضَرَّآءُ</span>.</p><p><b class=\"ar\">ضَرَرٌ</b> : see <span class=\"ar\">ضُرٌّ</span>, in two places. -b2- Also <i>Defect, deficiency, detriment,</i> or <i>loss,</i> (Msb, K,) and so <span class=\"ar\"> <span class=\"ar\">ضَرَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَرَارَةٌ</span></span>, (TA,) <i>that happens to a thing,</i> (K,) or <i>to articles of property.</i> (Msb.) You say, <span class=\"ar\">دَخَلَ عَلَيْهِ ضَرَرٌ فِى مَالِهِ</span> [<i>Defect, deficiency, detriment,</i> or <i>loss, came upon him in his property,</i> or <i>cattle</i>]. (TA.) And <span class=\"ar\">هُوَ فِى ضَرَرِ خَيْرٍ</span> [<i>He is in a state of defective,</i> or <i>little, prosperity</i>]. (TA.) See also <span class=\"ar\">ضَرَّآءُ</span>. -b3- Also <i>Narrowness,</i> or <i>straitness.</i> (A 'Obeyd, S, K.) You say <span class=\"ar\">مَكَانٌ ذُو</span> <span class=\"ar\">ضَرَرٍ</span> <i>A narrow place.</i> (A 'Obeyd, S.) And <span class=\"ar\">لَا</span> <span class=\"ar\">ضَرَرَ عَلَيْكَ</span> and <span class=\"ar\">لا <span class=\"ar\">ضَارُورَةَ</span></span> and <span class=\"ar\">لا <span class=\"ar\">تَضِرَّةَ</span></span> [app. <i>No straitness shall befall thee:</i> or <i>no evil:</i> or <i>no adversity:</i> or <i>no want</i>]. (S.) -b4- And <i>Narrow.</i> (K.) You say <span class=\"ar\">مَكَانٌ ضَرَرٌ</span> <i>A narrow place.</i> (TA.) And <span class=\"ar\">مَآءٌ ضَرَرٌ</span> <i>Water in a narrow place.</i> (IAar.) -b5- And The <i>brink,</i> or <i>edge, of a cave,</i> or <i>cavern.</i> (AA, O, K.) One says, <span class=\"ar\">لَا تَمْشِ عَلَى هٰذَا الضَّرَرِ</span> [<i>Walk not thou on this brink,</i> or <i>edge, of a cave</i>]. (AA, O.)</p><p><b class=\"ar\">ضَرِيرٌ</b> <i>i. q.</i> <span class=\"ar\">مُضَارَّةٌ</span> [i. e. <i>Injurious conduct,</i> either <i>in the first instance</i> or <i>in return</i> or <i>requital:</i> &amp;c.: see 3]: (S, A, K:) a subst. in this sense: (TA:) but it is mostly used in the sense here next following. (S, TA.) -b2- (tropical:) <i>Jealousy.</i> (S, A, K.) One says, <span class=\"ar\">ما أَشَدَّ ضَرِيرَهُ عَلَيْهَا</span> (tropical:) <i>How great is his jealousy on her account!</i> (S, A.) And <span class=\"ar\">إِنَّهُ لَذُو</span> <span class=\"ar\">ضَرِيرٍ عَلَى ٱمْرَأَتِهِ</span> (tropical:) <i>Verily he is jealous on account of his wife.</i> (TA.) -b3- Also <i>Spirit</i> (<span class=\"ar\">نَفْسٌ</span>), and <i>remains of stoutness of body</i> (<span class=\"ar\">بَقِيَّةُ جِسْمٍ</span>): (S, K:) or, as some say, <i>remains of spirit</i> (<span class=\"ar\">بَقِيَّةُ نَفْسٍ</span>). (TA.) One says <span class=\"ar\">نَاقَةٌ ذَاتُ ضَرِيرٍ</span> <i>A she-camel strong in spirit, slow in becoming fatigued:</i> (S, TA:) also expl. as meaning <i>that injures the</i> [<i>other</i>] <i>camels by the vehemence of her pace,</i> or <i>the hardness of her journeying.</i> (TA.) And <span class=\"ar\">بَاقٍ ضَرِيرُهَا</span>, referring to camels, is expl. by As as meaning <i>Whose strength is lasting.</i> (TA.) -b4- Also <i>Patience,</i> (S, K,) and <i>endurance.</i> (S.) One says, <span class=\"ar\">إِنَّهُ لَذُو ضَرِيرٍ</span> <i>Verily he has patient endurance of evil:</i> (TA:) and <span class=\"ar\">إِنَّهُ لَذُو ضَرِيرٍ عَلَى</span> <span class=\"ar\">الشَّرِّ وَالشِّدَةِ</span> <i>Verily he has patient endurance of evil and hardship;</i> (As, S, * TA;) a phrase used in relation to a man and to a beast. (TA.) -A2- Also [an epithet] signifying Anything <i>intermixed,</i> or <i>mingled, with</i> <span class=\"ar\">ضُرّ</span> [i. e. <i>harm, injury,</i> &amp;c.]; and so <span class=\"ar\"> <span class=\"ar\">مَضْرُورٌ</span></span>. (K.) -b2- (assumed tropical:) <i>Blind;</i> (S, K;) [a more respectful epithet than <span class=\"ar\">أَعْمَى</span>]; pl. <span class=\"ar\">أَضِرَّآءُ</span>: (K:) (assumed tropical:) <i>harmed by the loss of an eye,</i> or <i>by a constant and severe disease:</i> (Msb:) (tropical:) <i>diseased:</i> (A, K:) and (assumed tropical:) <i>lean,</i> or <i>emaciated:</i> (K:) <i>affected with a malady of long continuance;</i> or <i>crippled,</i> or <i>deprived of the power to move</i> or <i>to stand</i> or <i>to walk, by disease,</i> or <i>by a protracted disease:</i> (TA:) fem. with <span class=\"ar\">ة</span>: (A, K:) and pl. as above. (TA.) -b3- And <i>Persevering,</i> and <i>strong.</i> (TA.) [Thus having contr. meanings.] -b4- And <i>Very patient</i> (AA, S, K) <i>in endurance of everything;</i> applied to a beast, (AA, S,) and also to a man. (TA.) -A3- Also The <i>brink</i> of a valley; (S, K;) the <i>side</i> thereof: one says, <span class=\"ar\">نَزَلَ فُلَانٌ عَلَى أَحَدِ</span> <span class=\"ar\">ضَرِيرَى الوَادِى</span>, meaning [<i>Such a one alighted</i>] <i>upon one of the two sides of the valley:</i> (S:) pl. <span class=\"ar\">أَضِرَّةٌ</span>. (TA.) -b2- [Freytag has explained it also, from the Deewán of the Hudhalees, as meaning The <i>last part of a journey.</i>]</p><p><b class=\"ar\">ضَرَائِرُ</b> Persons <i>in want, needy,</i> or <i>poor.</i> (S.) -b2- Also pl. of <span class=\"ar\">ضَرَّةٌ</span>, [q. v.,] (Msb, K, TA,) in various senses. (TA.)</p><p><b class=\"ar\">ضَرَارَةٌ</b> : see <span class=\"ar\">ضَرَرٌ</span>: and <span class=\"ar\">ضَرَّآءُ</span>, in two places. -b2- Also (assumed tropical:) <i>Blindness.</i> (S, K, TA.) [See 1, last sentence, where it is mentioned as an inf. n.]</p><p><b class=\"ar\">ضَرُورَةٌ</b> <i>Necessity, necessitude, need,</i> or <i>want;</i> (Lth, S, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَارُورَةٌ</span></span> (S, K) and <span class=\"ar\"> <span class=\"ar\">ضَارُورٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَارُورَآءُ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَرَّةٌ</span></span>: (K, TA:) pl. <span class=\"ar\">ضَرُورَاتٌ</span>. (TA.) You say, <span class=\"ar\">حَمَلَنِى الضَّرُورَةُ عَلَى</span> <span class=\"ar\">كَذَا وَكَذَا</span> [<i>Necessity urged me to do such and such things</i>]. (Lth.) And <span class=\"ar\">رَجُلٌ ذُو <span class=\"ar\">ضَارُورَةِ</span></span> and <span class=\"ar\">ضَرُورَةٍ</span> <i>A man in want.</i> (S.) [And hence <span class=\"ar\">فِى</span> <span class=\"ar\">الضَّرُورَةِ</span> as meaning <i>In the case of necessity</i> in poetry or verse: and <span class=\"ar\">ضَرُورَةً</span> <i>by necessity;</i> meaning by poetic license. See also <span class=\"ar\">ضَرُورِيَّةٌ</span>.] -b2- And <i>Difficulty, distress, affliction, trouble, inconvenience, fatigue,</i> or <i>weariness.</i> (Msb.) [See also <span class=\"ar\">ضُرٌّ</span>, and <span class=\"ar\">ضَرَّةٌ</span>, and <span class=\"ar\">ضَرَّآءُ</span>.]</p><p><b class=\"ar\">ضَرُورِىٌّ</b> [<i>Necessary</i> knowledge]; as opposed to <span class=\"ar\">اِكْتِسَابِىٌّ</span>, [<i>natural, bestowed by nature, instinctive,</i> or] <i>such as the creature has by</i> [<i>divine</i>] <i>appointment;</i> and, as opposed to <span class=\"ar\">اِسْتِدْلَالِىٌّ</span>, [<i>intuitive, immediate, axiomatic,</i> or] <i>such as originates without thought,</i> or <i>reflection, and intellectual examination of an evidence</i> or <i>a proof.</i> (Kull.) [See also <span class=\"ar\">بَدِيهِىٌّ</span>.] -b2- [<span class=\"ar\">ضَرُورِيَّةٌ</span> as an epithet applied to a proposition means <i>Qualified by the expression</i> <span class=\"ar\">بِالضَّرُورَةِ</span> (<i>by necessity</i>). -b3- And the pl. <span class=\"ar\">ضَرُورِيَّاتٌ</span> means <i>Necessary,</i> or <i>indispensable, things.</i>]</p><p>[ <b class=\"ar\">ضَرُورِيَّةٌ</b> <i>Necessity.</i> (See also <span class=\"ar\">ضَرُورَةٌ</span>.) -b2- As fem. of the epithet <span class=\"ar\">ضَرُورِىٌّ</span>, see this latter word.]</p><p><b class=\"ar\">ضَرَّآءُ</b> <i>A hurtful state</i> or <i>condition;</i> (IAth;) <i>contr. of</i> <span class=\"ar\">سَرَّآءُ</span>: (IAth, Msb:) or <i>hardship, distress,</i> or <i>straitness of condition</i> [or <i>of the means of subsistence,</i> or <i>of the conveniences of life</i>]; (AHeyth;) <i>i. q.</i> <span class=\"ar\">شِدَّةٌ</span>; (S, A, K;) as also <span class=\"ar\">بَأْسَآءُ</span>, like which it is a fem. n. without a mase.; and accord. to Fr, <span class=\"ar\">أَضُرٌّ</span> and <span class=\"ar\">أَبْؤُسٌ</span> may be used as pls. of these two ns.: (S:) or, accord. to Az, (assumed tropical:) <i>that</i> [<i>evil</i>] <i>which relates to the person;</i> as <i>disease:</i> whereas <span class=\"ar\">بأسآء</span> is that which relates to property; as poverty: (Bd in ii. 172:) or <i>detriment,</i> or <i>loss, with respect to property</i> and <i>with respect to persons;</i> (A, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَرَّةٌ</span></span>, or <span class=\"ar\"> <span class=\"ar\">ضُرَّةٌ</span></span>, (accord. to different copies of the K,) and <span class=\"ar\"> <span class=\"ar\">ضَرَارَةٌ</span></span>: (K:) and [hence] <i>poverty:</i> and <i>punishment:</i> and <i>drought,</i> or <i>barrenness;</i> or <i>vehement,</i> or <i>intense, drought;</i> (TA: [see also <span class=\"ar\">ضَارُورَآءُ</span>:]) and (assumed tropical:) <i>disease of long continuance;</i> or <i>such as cripples,</i> or <i>deprives of the power to move</i> or <i>to stand</i> or <i>to walk;</i> (A, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَرَرٌ</span></span>, as used in the Kur iv. 97: or, accord. to Ibn-'Arafeh, the latter there means (assumed tropical:) <i>a hurtful malady that cuts one off from serving in war against unbelievers and the like;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَرَارَةٌ</span></span>; <i>relating to sight,</i> &amp;c. (TA.) -A2- [Also, accord. to Freytag, <i>Tangled trees, in a valley:</i> but the word having this meaning is correctly <span class=\"ar\">ضَرَآءٌ</span>, belonging to art. <span class=\"ar\">ضرو</span> and <span class=\"ar\">ضرى</span>, q. v. And be explains it also as meaning <i>a bare,</i> or <i>an open, place;</i> and the <i>contr.</i> i. e. <i>a place covered with trees;</i> referring to the “ Kitáb el-Addád. ”]</p><p><b class=\"ar\">ضَرَّارٌ</b> [<i>That harms, injures, hurts,</i> &amp;c., <i>much</i>]. (TA in art. <span class=\"ar\">خلو</span>.)</p><p><b class=\"ar\">ضَارٌّ</b> [act. part. n. of 1; <i>Harming, injuring, hurting,</i> &amp;c.; or <i>that harms,</i> &amp;c.; <i>noxious, injurious,</i> &amp;c.]. <span class=\"ar\">النَّافِعُ الضَّارُّ</span>, an appellation of God, means <i>He who benefiteth and who harmeth</i> whomsoever He will, of his creatures. (TA.)</p><p><b class=\"ar\">ضَارُورٌ</b> : see <span class=\"ar\">ضَرُورَةٌ</span>.</p><p><b class=\"ar\">ضَارُورَةٌ</b> : see <span class=\"ar\">ضَرَرٌ</span>; and <span class=\"ar\">ضَرُورَةٌ</span>, in two places.</p><p><b class=\"ar\">ضَارُورَآءُ</b> <i>Drought:</i> and <i>hardship, distress,</i> or <i>adversity.</i> (K.) See also <span class=\"ar\">ضَرُورَةٌ</span>. [And see <span class=\"ar\">ضُرٌّ</span>, and <span class=\"ar\">ضَرَّآءُ</span>.]</p><p>[ <b class=\"ar\">صِفَةٌ ٱضْطِرَارِيَّةٌ</b> <i>i. q.</i> <span class=\"ar\">صِفَةٌ خِلْقِيَّةٌ</span> i. e. <i>A natural quality;</i> opposed to <span class=\"ar\">ٱخْتِيَارِيَّةٌ</span>.]</p><p><b class=\"ar\">تَضِرَّةٌ</b> and <span class=\"ar\">تَضُرَّةٌ</span>: see <span class=\"ar\">ضُرٌّ</span>: and for the former see also <span class=\"ar\">ضَرَرٌ</span>.</p><p><b class=\"ar\">مُضِرٌّ</b> <i>Approaching</i> (K, TA) to a thing: and <i>approaching so near as to harm, injure,</i> or <i>hurt.</i> (TA.) <span class=\"ar\">سَحَابٌ مُضِرٌّ</span> means <i>Clouds approaching the earth.</i> (S, A.) -A2- Also A man <i>having two wives,</i> (S, K, *) or <i>having</i> [<i>several</i>] <i>wives at the same time.</i> (Msb.) And a woman <i>having a fellow-wife,</i> (TA,) or <i>having fellow-wives;</i> (S, Msb;) <i>having a fellow-wife,</i> or <i>two fellow-wives;</i> as also <span class=\"ar\">مُضِرَّةٌ</span>. (K.) -A3- And A man <i>having a</i> <span class=\"ar\">ضَرَّة</span> [q. v.] <i>of cattle:</i> (TA:) or <i>who has a</i> <span class=\"ar\">ضَرَّة</span> <i>of cattle that return to him in the afternoon,</i> or <i>evening, from the place of pasture.</i> (S, TA.)</p><p><b class=\"ar\">مَضَرَّةٌ</b> <i>A cause,</i> or <i>means, of harm, injury, hurt, mischief,</i> or <i>damage; contr. of</i> <span class=\"ar\">مَنْفَعَةٌ</span>: (S, TA:) [and simply] <i>harm, injury, hurt,</i> &amp;c.; syn. <span class=\"ar\">ضَرَرٌ</span>: pl. <span class=\"ar\">مَضَارُّ</span>. (Msb.)</p><p><b class=\"ar\">مِضْرَارٌ</b> A woman, and a she-camel, and a mare, <i>that takes fright, and runs away, and goes at random,</i> (<span class=\"ar\">تَنِدُّ وَتَرْكَبُ شِدْقَهَا</span>,) <i>by reason of briskness, liveliness,</i> or <i>sprightliness.</i> (IAar, K.)</p><p><b class=\"ar\">مَضْرُورٌ</b> : see <span class=\"ar\">ضَرِيرٌ</span>.</p><p><b class=\"ar\">بَيْعُ المُضْطَرِّ</b> , which is forbidden in a trad., is of two kinds: one is <i>The sale that one is compelled to contract against his will;</i> and this is null: the other is <i>the sale to which one is necessitated to consent in consequence of a debt that he has incurred or of a burden that has come upon him, so that he sells at a loss that which is in his possession;</i> and this kind of sale is valid, though disapproved by the people of knowledge. (IAth, TA.)</p>"},"ضعف":{"mf":"الضَّعْفُ: خلافُ القوّة، وقد ضَعُفَ فهو<br><br>ضَعِيفٌ. قال عزّ وجلّ: ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ [الحج/ ٧٣]، والضَّعْفُ قد يكون في النّفس، وفي البدن، وفي الحال، وقيل:<br>الضَّعْفُ والضُّعْفُ لغتان <strong>«١»</strong>. قال تعالى: وَعَلِمَ أَنَّ فِيكُمْ ضَعْفاً<br>[الأنفال/ ٦٦]، قال: وَنُرِيدُ أَنْ نَمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا<br>[القصص/ ٥]، قال الخليل رحمه الله: الضُّعْفُ بالضم في البدن، والضَّعْفُ في العقل والرّأي <strong>«٢»</strong>، ومنه قوله تعالى: فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً أَوْ ضَعِيفاً<br><strong>[البقرة/ ٢٨٢]، وجمع الضَّعِيفِ:</strong><br>ضِعَافٌ، وضُعَفَاءُ. قال تعالى: لَيْسَ عَلَى الضُّعَفاءِ<br>[التوبة/ ٩١]، واسْتَضْعَفْتُهُ: وجدتُهُ ضَعِيفاً، قال وَالْمُسْتَضْعَفِينَ مِنَ الرِّجالِ وَالنِّساءِ وَالْوِلْدانِ<br>[النساء/ ٧٥]، قالُوا فِيمَ كُنْتُمْ قالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ<br>[النساء/ ٩٧]، إِنَّ الْقَوْمَ اسْتَضْعَفُونِي<br>[الأعراف/ ١٥٠]، وقوبل بالاستكبار في قوله:<br>قالَ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا<br>[سبأ/ ٣٣]، وقوله: اللَّهُ الَّذِي خَلَقَكُمْ مِنْ ضَعْفٍ<br><strong>«٣»</strong> ثُمَّ جَعَلَ مِنْ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنْ بَعْدِ قُوَّةٍ ضَعْفاً<br>[الروم/ ٥٤]. والثاني غير الأوّل، وكذا الثالث فإن قوله: خَلَقَكُمْ مِنْ ضَعْفٍ<br>[الروم/ ٥٤]، أي: من نطفة، أو من تراب، والثاني هو الضَّعْفُ الموجودُ في الجنين والطّفل. الثالث: الذي بعد الشّيخوخة، وهو المشار إليه بأرذل العمر. والقوّتان الأولى هي التي تجعل للطّفل من التّحرّك، وهدايته واستدعاء اللّبن، ودفع الأذى عن نفسه بالبكاء، والقوّة الثانية هي التي بعد البلوغ، ويدلّ على أنّ كلّ واحد من قوله: (ضَعْفٍ) إشارةٌ إلى حالة غير الحالة الأولى ذكره منكّرا، والمنكّر متى أعيد ذكره وأريد به ما تقدّم عرّف <strong>«٤»</strong>، كقولك: رأيت رجلا، فقال لي الرّجل: كذا. ومتى ذكر ثانيا منكّرا أريد به غير الأوّل، ولذلك قال ابن عباس في قوله:<br>فَإِنَّ مَعَ الْعُسْرِ يُسْراً إِنَّ مَعَ الْعُسْرِ يُسْراً [الشرح/ ٥- ٦]، لن يغلب عسر يسرين <strong>«٥»</strong>، <br><br>وقوله: وَخُلِقَ الْإِنْسانُ ضَعِيفاً<br>[النساء/ ٢٨]، فَضَعْفُهُ: كثرةُ حاجاته التي يستغني عنها الملأ الأعلى، وقوله: إِنَّ كَيْدَ الشَّيْطانِ كانَ ضَعِيفاً [النساء/ ٧٦]، فَضَعْفُ كيدِهِ إنما هو مع من صار من عباد الله المذكورين في قوله:<br>إِنَّ عِبادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطانٌ [الإسراء/ ٦٥]، والضِّعْفُ هو من الألفاظ المتضايفة التي يقتضي وجود أحدهما وجود الآخر، كالنّصف والزّوج، وهو تركّب قدرين متساويين، ويختصّ بالعدد، فإذا قيل: أَضْعَفْتُ الشيءَ، وضَعَّفْتُهُ، وضَاعَفْتُهُ: ضممت إليه مثله فصاعدا. قال بعضهم: ضَاعَفْتُ أبلغ من ضَعَّفْتُ <strong>«١»</strong>، ولهذا قرأ أكثرهم: يُضاعَفْ لَهَا الْعَذابُ ضِعْفَيْنِ<br>[الأحزاب/ ٣٠]، وَإِنْ تَكُ حَسَنَةً يُضاعِفْها<br>[النساء/ ٤٠]، وقال: مَنْ جاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثالِها [الأنعام/ ١٦٠]، والمُضَاعَفَةُ على قضيّة هذا القول تقتضي أن يكون عشر أمثالها، وقيل: ضَعَفْتُهُ بالتّخفيف ضَعْفاً، فهو مَضْعُوفٌ، فَالضَّعْفُ مصدرٌ، والضِّعْفُ اسمٌ، كالثَّنْيِ والثِّنْيِ <strong>«٢»</strong>، فَضِعْفُ الشيءِ هو الّذي يُثَنِّيهِ، ومتى أضيف إلى عدد اقتضى ذلك العدد ومثله، نحو أن يقال: ضِعْفُ العشرةِ، وضِعْفُ المائةِ، فذلك عشرون ومائتان بلا خلاف، وعلى هذا قول الشاعر:<br><span class=\"num\">٢٩٣-</span><table class=\"poem\"><tr><td>جزيتك ضِعْفَ الوِدِّ لمّا اشتكيته </td><td> وما إن جزاك الضِّعف من أحد قبلي</td></tr></table><strong>«٣»</strong> وإذا قيل: أعطه ضِعْفَيْ واحدٍ، فإنّ ذلك اقتضى الواحد ومثليه، وذلك ثلاثة، لأن معناه الواحد واللّذان يزاوجانه وذلك ثلاثة، هذا إذا كان الضِّعْفُ مضافا، فأمّا إذا لم يكن مضافا فقلت: الضِّعْفَيْنِ فإنّ ذلك يجري مجرى الزّوجين في أنّ كلّ واحد منهما يزاوج الآخر،<br><br>فيقتضي ذلك اثنين، لأنّ كلّ واحد منهما يُضَاعِفُ الآخرَ، فلا يخرجان عن الاثنين بخلاف ما إذا أضيف الضِّعْفَانِ إلى واحد فيثلّثهما، نحو:<br>ضِعْفَيِ الواحدِ، وقوله: فَأُولئِكَ لَهُمْ جَزاءُ الضِّعْفِ [سبأ/ ٣٧]، وقوله: لا تَأْكُلُوا الرِّبَوا أَضْعافاً مُضاعَفَةً<br><strong>[آل عمران/ ١٣٠]، فقد قيل:</strong><br>أتى باللّفظين على التأكيد، وقيل: بل المُضَاعَفَةُ من الضَّعْفِ لا من الضِّعْفِ، والمعنى: ما يعدّونه ضِعْفاً فهو ضَعْفٌ، أي: نقص، كقوله: وَما آتَيْتُمْ مِنْ رِباً لِيَرْبُوَا فِي أَمْوالِ النَّاسِ فَلا يَرْبُوا عِنْدَ اللَّهِ [الروم/ ٣٩]، وكقوله: يَمْحَقُ اللَّهُ الرِّبا وَيُرْبِي الصَّدَقاتِ [البقرة/ ٢٧٦]، وهذا المعنى أخذه الشاعر فقال:<br><span class=\"num\">٢٩٤-</span><br>زيادة شيب وهي نقص زيادتي<br><strong>«١»</strong> وقوله: فَآتِهِمْ عَذاباً ضِعْفاً مِنَ النَّارِ<br>[الأعراف/ ٣٨]، فإنهم سألوه أن يعذّبهم عذابا بضلالهم، وعذابا بإضلالهم كما أشار إليه بقوله:<br>لِيَحْمِلُوا أَوْزارَهُمْ كامِلَةً يَوْمَ الْقِيامَةِ وَمِنْ أَوْزارِ الَّذِينَ يُضِلُّونَهُمْ [النحل/ ٢٥]، وقوله:<br>لِكُلٍّ ضِعْفٌ وَلكِنْ لا تَعْلَمُونَ<br>[الأعراف/ ٣٨]، أي: لكلّ منهم ضِعْفُ ما لكم من العذاب، وقيل: أي: لكلّ منهم ومنكم ضِعْفُ ما يرى الآخر، فإنّ من العذاب ظاهرا وباطنا، وكلّ يدرك من الآخر الظاهر دون الباطن فيقدّر أن ليس له العذاب الباطن.","mq":[["يدل احدهما علي خلاف القوة"],"الضاد والعين والفاء أصلانِ متباينان، يدل أحدُهما على خلاف القُوَّة، ويدلُّ الآخَر على أن يزاد الشَّئُ مِثلَه.<br>فالأوَّل: الضَّعف والضُّعف، وهو خلاف القُوَّة. يقال ضَعُفَ يضعُف، ورجلٌ ضعيف وقوم ضُعفاءُ وضِعافٌ.<br>وأمَّا الأصل الآخَر فقال الخليل: أضعفت الشّئَ إضعافاً، وضعَّفتُه تضعيفاً، وضاعفْتُه مُضاعَف"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَعُفَ</b> , (S, O, Msb, K,) and <span class=\"ar\">ضَعَفَ</span>, (O, Msb, K,) the latter on the authority of Yoo, (O,) or of Lh, (L,) aor. of each <b class=\"ar\">ضَعُفَ</b> , (Msb, K,) inf. n. <span class=\"ar\">ضُعْفٌ</span> and <span class=\"ar\">ضَعْفٌ</span> (S, * O, * Msb, K) [and app. <span class=\"ar\">ضَعَفٌ</span> (q. v. infrà) or this is a simple subst.] and <span class=\"ar\">ضَعَافَةٌ</span> and <span class=\"ar\">ضَعَافِيَةٌ</span>, (K,) all of which are inf. ns. of the former verb, (TA,) or the first, which is of the dial. of Kureysh, is of the former verb, and the second, which is of the dial. of Temeem, is of the latter verb, (Msb,) <i>He,</i> or <i>it, was,</i> or <i>became, weak, feeble, faint, frail, infirm,</i> or <i>unsound;</i> <span class=\"ar\">ضُعْفٌ</span> and <span class=\"ar\">ضَعْفٌ</span> being the <i>contr. of</i> <span class=\"ar\">قُوَّةٌ</span>, (S, O, Msb, K,) and <i>of</i> <span class=\"ar\">صِحَّةٌ</span>; (Msb;) and both of them may be used alike, in every relation; or, accord. to the people of El-Basrah, both are so used; so says Az; (TA;) but some say that the former is used in relation to the body, and the latter in relation to the judgment or opinion. (O, Msb, K: but this is omitted in my copy of the TA.) -b2- <span class=\"ar\">ضَعُفَ عَنِ الشَّىْءِ</span> means <i>He lacked strength,</i> or <i>power,</i> or <i>ability, to do</i> or <i>accomplish,</i> or <i>to bear, the thing;</i> [<i>he was weak so as to be disabled,</i> or <i>incapacitated, from doing,</i> or <i>accomplishing,</i> or <i>from bearing, the thing;</i>] syn. <span class=\"ar\">عَجَزَ عَنْهُ</span>, (Msb in art. <span class=\"ar\">عجز</span>,) or <span class=\"ar\">عَجَزَ عَنِ ٱحْتِمَالِهِ</span>. (Msb in the present art.) -b3- [See also <span class=\"ar\">ضَعْفٌ</span> below.] -A2- <span class=\"ar\">ضَعُفَ</span> also signifies <i>It</i> (a thing) <i>exceeded;</i> syn. <span class=\"ar\">زَادَ</span>. (L, TA.) -b2- And you say, <span class=\"ar\">ضَعَفْتُ القَوْمَ</span> (Lth, O, K, *) aor. <b class=\"ar\">ضَعُفَ</b> , (O,) or <b class=\"ar\">ضَعَفَ</b> , (K, TA,) inf. n. <span class=\"ar\">ضَعْفٌ</span>; (O;) [and app. <span class=\"ar\">ضَعُفْتُ عَلَيْهِمْ</span>, like as you say <span class=\"ar\">زِدْتُ</span> <span class=\"ar\">عَلَيْهِمْ</span>;] <i>I exceeded the people,</i> or <i>party, in number, so that I and my companions had double,</i> or <i>several-fold, the number that they had.</i> (Lth, O, K. *) -b3- See also 3.</p><p><b>2.</b> <b class=\"ar\">ضعّفهُ</b> , inf. n. <span class=\"ar\">تَضْعِيفٌ</span>: see 4: and see also <span class=\"ar\">المُضَعَّفُ</span>. -b2- Also <i>He reckoned,</i> or <i>esteemed, him</i> <span class=\"ar\">ضَعِيف</span> [i. e. <i>weak,</i> &amp;c.]; (O, K;) and so <span class=\"ar\"> <span class=\"ar\">استضعفهُ</span></span>, (S, O, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">تضعّفهُ</span></span>: (O, K:) or <span class=\"ar\"> <span class=\"ar\">استضعفهُ</span></span> signifies <i>he found him to be so;</i> (TA;) or <i>he asserted him to be</i> (<span class=\"ar\">جَعَلَهُ</span>) <i>so;</i> (Msb;) or, as also <span class=\"ar\"> <span class=\"ar\">تضعّفهُ</span></span>, <i>he</i> [<i>esteemed him to be so, and therefore</i>] <i>behaved proudly, haughtily,</i> or <i>insolently, towards him, in respect of worldly things, because of</i> [<i>his</i>] <i>poverty, and meanness of condition.</i> (IAth, TA.) <span class=\"ar\">غَلَبَنِى أَهْلُ الكُوفَةِ أَسْتَعْمِلُ عَلَيْهِمُ المُؤْمِنَ فَيُضَعَّفُ</span> <span class=\"ar\">وَأَسْتَعْمِلُ عَلَيْهِمُ القَوِىَّ فَيُفَجَّرُ</span>, [<i>The people of El-Koofeh have overcome me: I employ as governor over them the believer, and he is esteemed weak; and I employ as governor over them the strong, and he is charged with unrighteousness:</i>] is a saying mentioned in a trad. of 'Omar. (TA.) -b3- And <i>He attributed,</i> or <i>ascribed,</i> (O, K,) <i>to him,</i> i. e. a man, (O,) or (tropical:) <i>to it,</i> i. e. a tradition, [&amp;c.,] <span class=\"ar\">ضَعْف</span> [meaning <i>weakness,</i> app., in the case of a man, <i>of judgment,</i> and in the case of a tradition &amp;c., <i>of authority</i>]. (O, K, TA.) -A2- And <i>He doubled it,</i> or <i>made it double, covering one part of it with another part.</i> (TA.) -b2- See also the next paragraph, in two places.</p><p><b>3.</b> <b class=\"ar\">ضاعفهُ</b> , (S, O, K,) inf. n. <span class=\"ar\">مُضَاعَفَةٌ</span>; (S, Msb;) and <span class=\"ar\"> <span class=\"ar\">ضعّفهُ</span></span>, (S K,) inf. n. <span class=\"ar\">تَضْعِيفٌ</span>; (S, O, Msb;) and <span class=\"ar\"> <span class=\"ar\">اضعفهُ</span></span>, (S, O, K,) inf. n. <span class=\"ar\">إِضْعَافٌ</span>; (S, Msb;) all signify the same; (S, K;) i. e. <i>He doubled it,</i> or <i>made it double,</i> or <i>two-fold;</i> (O, K;) [and <i>trebled it,</i> or <i>made it treble,</i> or <i>three-fold;</i> and <i>redoubled it,</i> or <i>made it several-fold,</i> or <i>manyfold;</i> i. e. <i>multiplied it;</i> for] Kh says, <span class=\"ar\">التَّضْعِيفُ</span> signifies <i>the adding to</i> a thing <i>so as to make</i> it <i>double,</i> or <i>two-fold;</i> or <i>more</i> [i. e. <i>treble,</i> or <i>threefold;</i> and <i>several-fold,</i> or <i>many-fold</i>]; (S, O, Msb;) and so <span class=\"ar\">الإِضْعَافُ</span>, and <span class=\"ar\">المُضَاعَفَةُ</span>; (S, Msb;) and <span class=\"ar\"> <span class=\"ar\">ضَعَفَهُ</span></span>, without teshdeed, signifies the same as <span class=\"ar\">ضاعفهُ</span>. (Ham p. 257.) The saying, in the Kur [xxxiii. 30], <span class=\"ar\">يُضَاعَفْ لَهَا العَذَابُ ضِعْفَيْنِ</span>, (Mgh, O, K,) in which AA read <span class=\"ar\"> <span class=\"ar\">يُضَعَّفْ</span></span>, (TA,) accord. to AO, (Mgh, O,) means, <i>The punishment shall be made to her three punishments;</i> (Mgh, O, K;) for, he says, she is to be punished once; and when the punishment is doubled twofold, [or is repeated twice,] the one becomes three: (TA:) he adds, (O,) and the tropical meaning of <span class=\"ar\">يُضَاعَفْ</span> (<span class=\"ar\">مَجَازُ يُضَاعَفْ</span> [for which <span class=\"ar\">مَجازٌ يُضَاعَفُ</span> is erroneously put in the CK]) is two things' being added to a thing so that it becomes three: (O, K:) but Az disapproves this, saying that it is peculiar to the tropical and the common conventional speech, whereas the skilled grammarians state the meaning to be, <i>she shall be punished with twice the like of the punishment of another;</i> (Mgh;) [so that it may be rendered <i>the punishment shall be doubled to her,</i> made <i>two-fold;</i> and in like manner] Ibn-'Arafeh explains it as meaning <i>she shall have two shares of punishment.</i> (O.) <span class=\"ar\">فَيُضَاعِفُهُ لَهُ أَضْعَافًا كَثِيرَةً</span> [<i>And He will multiply it to him many-fold,</i> or, as some read, <span class=\"ar\">فَيُضَاعِفَهُ</span> <i>that He may multiply it,</i>] is another phrase occurring in the Kur [ii. 246]. (O, TA.) And one says, <span class=\"ar\"> <span class=\"ar\">أَضْعَفْتُ</span>الثَّوَابَ لِلْقَوْمِ</span> [<i>I doubled,</i> or <i>multiplied, the recompense to the people,</i> or <i>party</i>]. (Msb.) And <span class=\"ar\"> <span class=\"ar\">أُضْعِفَ</span>القَوْمُ</span> <i>The people,</i> or <i>party, had a doubling,</i> or <i>multiplying,</i> [of their recompense, &amp;c.,] <i>made to them;</i> (Msb;) [and so, app., <span class=\"ar\">أَضْعَفُوا</span>; (see <span class=\"ar\">مُضْعِفٌ</span>;)] <i>i. q.</i> <span class=\"ar\">ضُوعِفَ لَهُمْ</span>. (S, O, K.)</p><p><b>4.</b> <b class=\"ar\">اضعفهُ</b> <i>He,</i> (God, Msb, or another, S,) or <i>it,</i> (disease, TA,) <i>rendered him</i> <span class=\"ar\">ضَعِيف</span> [i. e. <i>weak,</i> &amp;c.]; (S, O, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ضعّفهُ</span></span>. (L, TA.) -A2- And <span class=\"ar\">أَضْعَفَ</span>, said of a man, <i>He became one whose beast was weak.</i> (S, O, K.) -A3- See also 3, first sentence, and last two sentences.</p><p><b>5.</b> <b class=\"ar\">تَضَعَّفَ</b> see 2, in two places. -A2- [<span class=\"ar\">تضعّف</span> app. signifies also <i>He manifested weakness:</i> see <span class=\"ar\">تضوّر</span>.]</p><p><b>6.</b> <b class=\"ar\">تضاعف</b> signifies <span class=\"ar\">صَارَ ضِعْفَ مَا كَانَ</span> [i. e. <i>It became double,</i> or <i>two-fold;</i> and <i>treble,</i> or <i>threefold;</i> and <i>several-fold,</i> or <i>many-fold</i>]. (O, K.)</p><p><b>10.</b> <b class=\"ar\">إِسْتَضْعَفَ</b> see 2, in two places.</p><p><b class=\"ar\">ضَعْفٌ</b> an inf. n. of 1, like <span class=\"ar\"> <span class=\"ar\">ضُعْفٌ</span></span>, (S, * O, * Msb, K,) [both, when used as simple substs., signifying <i>Weakness, feebleness,</i> &amp;c.,] but some say that the former is in the judgment or opinion, and the latter in the body; (O, Msb, K;) and <span class=\"ar\"> <span class=\"ar\">ضَعَفٌ</span></span> signifies the same, (IAar, K, TA,) and is in the body and also in the judgment or opinion and the intellect. (TA.) -b2- <span class=\"ar\">ضَعْفُ التَّأْلِيفِ</span> [<i>Weakness of construction, in language,</i>] is <i>such a construction of the members of a sentence as is contrary to the</i> [<i>generally approved</i>] <i>rules of syntax;</i> as when a pronoun is introduced before its noun with respect to the actual order of the words and the order of the sense [in a case in which the pronoun is affixed to the agent in a verbal proposition]; for instance, in the phrase, <span class=\"ar\">ضَرَبَ غُلَامُهُ</span> <span class=\"ar\">زَيْدًا</span> [“ His, ” i. e. Zeyd's, “ young man beat Zeyd ”]. (KT.) When the pronoun is affixed to the objective complement, as in <span class=\"ar\">خَافَ رَبَّهُ عُمَرُ</span> [“ 'Omar feared his Lord ”] such introduction of it is common: (I'Ak p. 128:) and it is [universally] allowable when the pronoun is of the kind called <span class=\"ar\">ضَمِيرُ الشَّأْنِ</span>, as in <span class=\"ar\">إِنَّهُ زَيْدٌ قَائِمٌ</span>; or <span class=\"ar\">ضَمِيرُ رُبَّ</span>, as in <span class=\"ar\">رُبَّهُ رَجُلًا لَقِيتُهُ</span>; or <span class=\"ar\">ضَمِيرُ نِعْمَ</span>, as in <span class=\"ar\">نِعْمَهُ رَجُلًا زَيْدٌ</span>. (Kull p. 56.) -b3- [In the CK, a signification belonging to <span class=\"ar\">ضُعْف</span> is assigned to <span class=\"ar\">ضَعْف</span>.]</p><p><b class=\"ar\">ضُعْفٌ</b> : see <span class=\"ar\">ضَعْفٌ</span>. -b2- <span class=\"ar\">مِنْ ضُعْفٍ</span> in the Kur xxx. 53 means <i>Of sperm.</i> (O, K, TA.) AA, reciting before the Prophet, said <span class=\"ar\">مِنْ ضَعْفٍ</span>; and was told by the latter to say <span class=\"ar\">من ضُعْفٍ</span>, [i. e.] with damm. (TA.)</p><p><b class=\"ar\">ضِعْفُ الشَّىْءِ</b> signifies <i>The like of the thing,</i> (AO, Zj, S, O, Msb, K, TA,) <i>that doubles it</i> (<span class=\"ar\">يُضْعِفُهُ</span>); (Zj, TA;) and <span class=\"ar\">ضِعْفَاهُ</span>, <i>twice the like of it;</i> (AO, S, O, Msb, K;) and <span class=\"ar\">أَضْعَافُهُ</span>, <i>the likes of it:</i> (S, Msb:) <span class=\"ar\">الضِّعْفُ</span> in the [proper] language of the Arabs means <i>the like:</i> this is the original signification: (Az, Msb:) and (K, TA, but in CK “ or, ”) then, by a later [and conventional] usage, (Az, Msb,) <i>the like and more, the addition being unlimited:</i> (Az, Msb, K:) one says, <span class=\"ar\">هٰذَا</span> <span class=\"ar\">ضِعْفُ هٰذَا</span> i. e. <i>This is the like of this:</i> and <span class=\"ar\">هٰذَانِ</span> <span class=\"ar\">ضِعْفَاهُ</span> i. e. <i>These two are twice the like of it:</i> and it is allowable in the language of the Arabs to say, <span class=\"ar\">هٰذَا ضِعْفُهُ</span> meaning <i>This is twice the like</i> [i. e. <i>the double</i>] <i>of it,</i> and <i>thrice the like</i> [i. e. <i>the treble</i>] <i>of it,</i> [and <i>more,</i>] because the <span class=\"ar\">ضِعْف</span> is an unlimited addition: (Az, Msb: [and the like is said in the O, on the authority of Az:]) and one says, <span class=\"ar\">لَكَ ضِعْفُهُ</span> meaning <i>Thou shalt have twice the like of it,</i> (Zj, O, K,) using the sing. form, though the dual form is better, (Zj, O,) and meaning also <i>thrice the like of it,</i> and <i>more without limit:</i> (K:) and <span class=\"ar\">الاِثْنَانِ ضِعْفُ الوَاحِدِ</span> [i. e. <span class=\"ar\">الاثنان</span> <i>is the double of</i> <span class=\"ar\">الواحد</span>]: (M and K in art. <span class=\"ar\">ثنى</span>:) and if one say in his will, <span class=\"ar\">أَعْطُوهُ ضِعْفَ نَصِيبِ وَلَدِى</span>, twice the like of the share of his child is given to him; and if he say <span class=\"ar\">ضِعْفَيْهِ</span>, thrice the like thereof is given to him; so that if the share of the son be a hundred, he [the legatee] is given two hundred in the former case, and three hundred in the latter case; for the will is made to accord with the common conventional language, not with the niceties of the [proper] language: (Az, Msb: [and the like is said, but less fully, in the Mgh:]) the pl. is <span class=\"ar\">أَضْعَافٌ</span> only. (TA.) <span class=\"ar\">إِذًا لَأَذَقْنَاكَ ضِعْفَ</span> <span class=\"ar\">الحَيَاةِ وَضِعْفَ المَمَاتِ</span>, in the Kur [xvii. 77], means <span class=\"ar\">ضِعْفَ العَذَابِ حَيًّا وَمَيِّتًا</span>, (S,) or <span class=\"ar\">ضِعْفَ عَذَابِ</span> <span class=\"ar\">الحَيَاةِ وَضِعْفَ عَذَابِ المُمَاتِ</span>, (O, Jel,) i. e. [<i>In that case we would assuredly have made thee to taste</i>] <i>the like</i> [or, as some explain it, <i>the double</i>] <i>of the punishment</i> of others <i>in the present world and</i> [<i>the like</i> or <i>the double thereof</i>] <i>in the world to come:</i> (Jel:) [Sgh adds, app. on the authority of Ibn-'Arafeh,] the meaning is, the punishment of others should be made two-fold, or more, (<span class=\"ar\">يُضَاعَف</span>,) to thee, because thou art a prophet. (O.) In the saying, <span class=\"ar\">فَأُولَائِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ</span> <span class=\"ar\">بِمَا عَمِلُوا</span>, in the Kur [xxxiv. 36], by <span class=\"ar\">الضِّعْفِ</span> is meant <span class=\"ar\">الأضْعَافِ</span> [i. e. <i>For these shall be the recompense of the likes for what they have done</i>]; and it is most properly held to denote ten of the likes thereof, because of the saying in the Kur [vi. 161], “ Whoso doth that which is good, for him shall be ten of the likes thereof. ” (O.) In the saying, <span class=\"ar\">فَآتِهِمْ عَذَابًا ضِعْفًا</span>, in the Kur [vii. 36], by <span class=\"ar\">ضِعْفًا</span> is meant <span class=\"ar\">مُضَاعَفًا</span> [i. e. <i>Therefore do Thou recompense them with a doubled,</i> or <i>a double, punishment</i>]: <span class=\"ar\">عَذَابٌ ضِعْفٌ</span> meaning <i>a punishment as though doubled, one part of it upon another.</i> (TA.) -b2- <span class=\"ar\">أَضْعَافُ الكِتَابِ</span> means (tropical:) <i>The interspaces of the lines,</i> (S, O, K, TA,) or <i>of the margin,</i> (S, O,) or and <i>of the margins,</i> (K, TA,) <i>of the writing,</i> or <i>book:</i> (S, O, K, TA:) so in the saying, <span class=\"ar\">وَقَّعَ</span> <span class=\"ar\">فُلَانٌ فِى أَضْعَافِ كِتَابِهِ</span> (tropical:) [<i>Such a one made an entry of a note</i> or <i>postil</i> or <i>the like,</i> or <i>entries of notes</i> &amp;c., <i>in the interspaces of the lines,</i> &amp;c., <i>of his writing,</i> or <i>book</i>]: (S, O, TA:) and <span class=\"ar\"> <span class=\"ar\">تَضَاعِيفُ</span> الكِتَابِ</span> signifies the same as <span class=\"ar\">أَضْعَافُهُ</span>. (TA.) -b3- And <span class=\"ar\">أَضْعَافُ الجَسَدِ</span> (assumed tropical:) <i>The limbs, members,</i> or <i>organs,</i> (<span class=\"ar\">أَعْضَآء</span>,) <i>of the body:</i> (O, K:) or <i>the bones thereof:</i> (AA, K:) or <i>the bones thereof having flesh upon them:</i> (TA:) sing. <span class=\"ar\">ضِعْفٌ</span>. (K.) Hence the saying of Ru-beh, <span class=\"ar\">وَٱللّٰهُ بَيْنَ القَلْبِ وَالأَضْعَافِ</span> (assumed tropical:) [<i>And God is between the heart and the limbs,</i> &amp;c.]. (TA.) And it is said of Yoonus, [the prophet Jonah,] <span class=\"ar\">كَانَ فِى أَضْعَافِ الحُوتِ</span> (tropical:) [<i>He was amid the members of the fish</i>]. (TA.)</p><p><b class=\"ar\">ضَعَفٌ</b> : see <span class=\"ar\">ضَعْفٌ</span>. -A2- Also <i>Garments,</i> or <i>pieces of cloth, made double</i> ( <span class=\"ar\"><span class=\"ar\">مُضَعًّفَةٌ</span> </span>). (Ibn-'Abbád, O, K.)</p><p><b class=\"ar\">ضَعْفَةٌ</b> <i>Weakness of heart,</i> and <i>littleness of intel-ligence.</i> (TA.)</p><p><b class=\"ar\">ضَعَفَةٌ</b> <i>A party,</i> or <i>company,</i> or <i>small company,</i> (<span class=\"ar\">شِرْذِمَةٌ</span>,) <i>of the Arabs.</i> (TA.) -b2- Also a pl. of <span class=\"ar\">ضَعِيفٌ</span> [q. v.]. (S &amp;c.)</p><p><b class=\"ar\">ضَعْفَانُ</b> : see <span class=\"ar\">ضَعِيفٌ</span>.</p><p><b class=\"ar\">ضَعُوفٌ</b> : see the next paragraph, in two places.</p><p><b class=\"ar\">ضَعِيفٌ</b> (S, O, Msb, K) and [in an intensive sense] <span class=\"ar\"> <span class=\"ar\">ضَعُوفٌ</span></span> (Ibn-Buzurj, O, K) and <span class=\"ar\"> <span class=\"ar\">ضَعْفَانُ</span></span> (K) <i>Weak, feeble, faint, frail, infirm,</i> or <i>unsound:</i> (S, * O, * Msb, K: *) pl. (of the first, S, O, Msb) <span class=\"ar\">ضِعَافٌ</span> and <span class=\"ar\">ضُعَفَآءُ</span> and <span class=\"ar\">ضَعَفَةٌ</span>, (S, O, Msb, K,) which last is [said to be] the only instance of its kind except <span class=\"ar\">خَبَثَةٌ</span> pl. of <span class=\"ar\">خَبِيثٌ</span> [q. v.], (TA,) and <span class=\"ar\">ضَعْفَى</span>, like <span class=\"ar\">جَرْحَى</span> pl. of <span class=\"ar\">جَرِيحٌ</span>: (Msb:) fem. <span class=\"ar\"> <span class=\"ar\">ضَعُوفٌ</span></span> (Ibn-Burzurj, O, K) and <span class=\"ar\">ضَعِيفَةٌ</span>; pl., applied to women, <span class=\"ar\">ضَعِيفَاتٌ</span> (K) and <span class=\"ar\">ضَعَائِفُ</span> and <span class=\"ar\">ضِعَافٌ</span>. (TA.) <span class=\"ar\">وَخُلِقَ ٱلْإِنْسَانُ ضَعِيفًا</span> (in the Kur [iv. 32], O) means [<i>For man was created weak,</i> or] <i>subject to be inclined by his desire.</i> (O, L, K.) And <span class=\"ar\">الضَّعِيفَانِ</span> [<i>The two weak ones</i>] means <i>the woman and the slave:</i> hence the trad., <span class=\"ar\">اِتَّقُوا ٱللّٰهَ فِى</span> <span class=\"ar\">الضَّعِيفَيْنِ</span> [<i>Fear ye God in respect of the woman and the slave</i>]. (TA.) -b2- In the dial. of Himyer, <i>Blind:</i> and [it is said that] thus it signifies in the phrase <span class=\"ar\">لَنَرَاكَ فِينَا ضَعِيفًا</span> [<i>Verily we see thee to be, among us, blind</i>], (O, K,) in the Kur [xi. 93]: (O:) but Esh-Shiháb rejects this, in the 'Inayeh. (TA.) -b3- [As a conventional term] in lexicology, applied to a word, [<i>Of weak authority;</i>] <i>inferior to what is termed</i> <span class=\"ar\">فَصِيحٌ</span>, <i>but superior to what is termed</i> <span class=\"ar\">مُنْكَرٌ</span>. (Mz, 10th <span class=\"ar\">نوع</span>.) -b4- Applied to verse, or poetry, [<i>Weak;</i>] <i>unsound,</i> or <i>infirm;</i> syn. <span class=\"ar\">عَلِيلٌ</span>: thus used by Kh. (TA.) -b5- The saying of a man who had found a thing dropped on the ground (<span class=\"ar\">وَجَدَ لُقَطَةً</span>), <span class=\"ar\">فَعَرَّفْتُهَا ضَعِيفًا</span>, means <i>And I made it known in a suppressed,</i> or <i>low,</i> [or <i>weak,</i>] <i>voice.</i> (Mgh in art. <span class=\"ar\">نفر</span>.)</p><p><b class=\"ar\">ضَاعِفٌ</b> A cow <i>having a young one in her belly;</i> (IDrd, O;) as though she were made double thereby: (TA:) but IDrd says that this is not of high authority. (O.)</p><p><b class=\"ar\">تَضْعِيفٌ</b> inf. n. of 2. (S &amp;c.) -b2- <span class=\"ar\">تَضَاعِيفُ الشَّىْءِ</span> means <i>The doubles,</i> or <i>trebles,</i> or <i>multiples, of the thing;</i> (<span class=\"ar\">مَا ضُعِّفَ مِنْهُ</span>;) in this sense, <span class=\"ar\">تضاعيف</span> has no sing., like <span class=\"ar\">تَبَاشِيرُ</span> &amp;c. (TA.) -b3- <span class=\"ar\">تَضَاعِيفُ الكِتَابِ</span>: see <span class=\"ar\">ضِعْف</span>, near the end. -b4- As expl. by Lth, (O,) <span class=\"ar\">التَّضْعِيفُ</span> signifies <span class=\"ar\">حُمْلَانُ الكِيمِيَآءِ</span> [i. e. <i>What is used as an alloy in chemistry</i> or <i>alchymy</i>]. (O, K.)</p><p><b class=\"ar\">مُضْعِفٌ</b> A man <i>whose beast,</i> (S, K, and Mgh in art. <span class=\"ar\">كفأ</span>,) or <i>whose camel,</i> (O,) <i>is weak,</i> (S, Mgh, O, K,) or <i>untractable.</i> (O.) Hence the saying of ' Omar, <span class=\"ar\">المُضْعِفُ أَمِيرٌ عَلَى أَصْحَابِهِ</span> [<i>He whose beast is weak,</i> or <i>untractable, is ruler over his companions</i>]; (O, K;) i. e. in journeying; (O;) because they go his pace. (O, K.) And the saying, in a trad., <span class=\"ar\">يَرُدُّ مُشِدُّهُمْ عَلَى مُضْعِفِهِمْ</span> [expl. in art. <span class=\"ar\">شد</span>]. (Mgh in art. <span class=\"ar\">كفأ</span>.) -A2- <span class=\"ar\">فَأُولَائِكَ هُمُ ٱلْمُضْعِفُونَ</span>, in the Kur [xxx. 38], means <i>These are they who shall have their recompense doubled,</i> or <i>multiplied:</i> (Az, Bd, TA:) or <i>those who double,</i> or <i>multiply, their recompense</i> (Bd, Jel) and <i>their possessions,</i> (Bd,) by the blessing of their almsgiving: (Bd, Jel: *) but some read <span class=\"ar\">المُضْعَفُونَ</span>. (Bd.) -b2- <span class=\"ar\">المُضْعِفُ</span> also signifies <span class=\"ar\">مَنْ فَشَتْ ضَيْعَتُهُ وَكَثُرَتْ</span> [<i>He whose property has become wide-spread and abundant</i>]. (Ibn-' Abbád, O, L, K.)</p><p><b class=\"ar\">أَرْضٌ مُضَعَّفَةٌ</b> <i>Land upon which a weak rain has fallen:</i> (Ibn-'Abbád, O, K:) and [in like manner] <span class=\"ar\"> <span class=\"ar\">مَضْعُوفٌ</span></span> signifies a place <i>upon which has fallen only a little,</i> or <i>weak, rain.</i> (O in art. <span class=\"ar\">رك</span>.) -b2- <span class=\"ar\">المُضَعَّفُ</span> <i>One of the arrows used in the game of</i> <span class=\"ar\">المُيْسِر</span>, <i>that has no share,</i> or <i>portion, allotted to it;</i> as though it were disabled from having a share (<span class=\"ar\">كَأَنَّهُ <span class=\"ar\">ضُعِّفَ</span>عَنْ أَنْ يَكُونَ لَهُ نَصِيبٌ</span>): (TA:) <i>the second of the arrows termed</i> <span class=\"ar\">الغُفْلُ</span>, <i>that have no notches, and to which is assigned</i> [<i>no portion and</i>] <i>no fine:</i> these being added only to give additional weight to the collection of arrows from fear of occasioning suspicion [of foul play]. (Lh, M.) [See <span class=\"ar\">السَّفِيحُ</span>.] -A2- See also <span class=\"ar\">ضَعَفٌ</span>.</p><p><b class=\"ar\">مُضَعِّفٌ</b> A man <i>having manifold good deeds.</i> (TA.)</p><p><b class=\"ar\">مَضْعُوفٌ</b> , applied to a thing, (S,) or to a man, (O,) <i>Rendered</i> <span class=\"ar\">ضَعِيف</span> [i. e. <i>weak,</i> &amp;c.]: (AA, S, O, K:) by rule it should be <span class=\"ar\">مُضْعَفٌ</span>. (O, K.) A man <i>weak in intellect:</i> (IAar, TA:) or <i>weakhearted and having little intellect.</i> (TA.) -b2- See also <span class=\"ar\">أَرْضٌ مُضَعَّفَةٌ</span>, above.</p><p><b class=\"ar\">دِرْعٌ مُضَاعَفَةٌ</b> <i>A coat of mail composed of double rings.</i> (S, O, K.) -b2- <span class=\"ar\">مُضَاعَفٌ</span> as a conventional term used by those who treat of inflection, <i>Having a</i> [<i>radical</i>] <i>letter doubled.</i> (TA.)</p><p><b class=\"ar\">أَهْلُ الجَنَّةِ كُلُّ ضَعِيفٍ مُتَضَعَّفٍ</b> [<i>The meet for Paradise is every weak person who is esteemed weak</i>]. (K, * TA. [In the CK, erroneously, <span class=\"ar\">مُتَضَعِّفٌ</span>: and in the K, <span class=\"ar\">اهل الجنّة</span> is omitted.])</p>"},"ضيع":{"mf":"ضَاعَ الشيءُ يَضِيعُ ضَيَاعاً، وأَضَعْتُهُ وضَيَّعْتُهُ.<br>قال تعالى: لا أُضِيعُ عَمَلَ عامِلٍ مِنْكُمْ<br>[آل عمران/ ١٩٥]، إِنَّا لا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا<br>[الكهف/ ٣٠]، وَما كانَ اللَّهُ لِيُضِيعَ إِيمانَكُمْ<br>[البقرة/ ١٤٣]، لا يُضِيعُ أَجْرَ الْمُحْسِنِينَ<br>[التوبة/ ١٢٠]، وضَيْعَةُ الرّجلِ: عقاره الذي يَضِيعُ ما لم يفتقد، وجمعه: ضِيَاعٌ، وتَضَيَّعَ الرّيحُ: إذا هبّت هبوبا يُضَيِّعُ ما هبّت عليه.","mq":[["فوت الشي وذهابه وهلاكه"],"الضاد والياء والعين أصلٌ صحيح يدلُّ على فَوت الشّئ وذَهابه وهلاكه. يقال ضاع الشَّئُ يَضيع ضَياعاً وضَيْعةً، وأضعته أنا إضاعة.<br>فأمّا تسميتُهم العَقَار ضيعة فما أحسَبُها من اللُّغة الأَصِيلة (٢)<br>، وأظنّه من مُحْدَث الكلام. وسمعت من يقول: إنّما سمِّيت بذلك لأنّها إذا تُرِك تعهُّدِها ضاعت.<br>فإن كان كذا ف"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَاعَ</b> , aor. <span class=\"ar\">يَضِيعُ</span>, inf. n. <span class=\"ar\">ضَيَاعٌ</span> and <span class=\"ar\">ضَيْعَةٌ</span> (S, Mgh, O, Msb, K) and <span class=\"ar\">ضَيْعٌ</span> and <span class=\"ar\">ضِيعٌ</span>, (K,) <i>It</i> (a thing, S, Mgh, O, Msb) <i>perished, came to nought, passed away,</i> or <i>became lost.</i> (S, O, Msb, K.) It is said in a trad. of Saad, <span class=\"ar\">إِنِّى أَخَافُ عَلَى</span> <span class=\"ar\">الأَعْنَابِ الضَّيْعُةَ</span> i. e. [<i>Verily I fear, for the grapes,</i>] <i>their</i> [lit. <i>the</i>] <i>perishing,</i> or <i>becoming lost.</i> (TA.) -b2- And <span class=\"ar\">ضاع</span>, (K, TA,) inf. n. <span class=\"ar\">ضَيَاعٌ</span> and <span class=\"ar\">ضَيْعَةٌ</span>, (TA,) <i>It</i> (a thing) <i>was left; left,</i> or <i>let, alone;</i> or <i>neglected.</i> (K, TA.) Hence, <span class=\"ar\">ضاعت</span> <span class=\"ar\">الإِبِلُ</span>, and <span class=\"ar\">ضاع العِيَالُ</span>, <i>The camels,</i> and <i>the family,</i> or <i>household, were left untended,</i> and <i>unminded;</i> and <i>were left alone,</i> or <i>neglected.</i> (TA.) -A2- <span class=\"ar\">ضاع</span>, aor. <span class=\"ar\">يَضِيعُ</span>, said of perfume, or sweet odour, <i>i. q.</i> <span class=\"ar\">ضاع</span> having for its aor. <span class=\"ar\">يَضُوعُ</span>. (Har p. 670.) [See 5 in art. <span class=\"ar\">ضوع</span>: and see also 5 in the present art.]</p><p><b>2.</b> <b class=\"ar\">ضيّع الشَّىْءَ</b> , (O, Msb, K,) inf. n. <span class=\"ar\">تَضْيِيعٌ</span>; (S;) and <span class=\"ar\"> <span class=\"ar\">اضاعهُ</span></span>, (O, Msb, K,) inf. n. <span class=\"ar\">إِضَاعَةٌ</span>; (S;) both signify the same; (S, O, Msb, K;) <i>He made,</i> or <i>caused, the thing to perish,</i> or <i>become lost; he destroyed it, wasted it,</i> or <i>lost it.</i> (Msb, K, TA.) Hence, <span class=\"ar\">ضَيَّعُوا فُلَانًا</span> is used by the vulgar as meaning <i>They beheaded such a one with the sword.</i> (TA.) It is said in a prov., <span class=\"ar\">الصَّيْفَ ضَيَّعْتِ اللَّبَنَ</span> [<i>In the spring,</i> or <i>in the summer, thou losedst the milk</i>], in which the <span class=\"ar\">ت</span> is with kesr when the words are addressed to a male, or to a female, or to a pl. number, because originally addressed to a woman, the wife of a wealthy man, whom she disliked because of his being aged, wherefore he divorced her, and a poor man married her, and she sent to her first husband requesting a gift, and he answered her thus; (S, O, K; *) <span class=\"ar\">الصيف</span> being in the accus. case as an adv. n.: so says Yaakoob: (S, O:) or El-Aswad Ibn-Hurmuz divorced his wife El- ' Anood Esh-Shenneeyeh, (O, K,) of the BenooShenn, (TA,) preferring to her a beautiful and wealthy woman of his people; (O, K; *) then there occurred between them what led to their separation, and he sought to obtain [again] El- ' Anood, and sent a message to her; but in replying to him she said, <span class=\"ar\">أَنْشَأْتَ تَطْلُبُ وَصْلَنَا</span> <span class=\"ar\">فِى الصَّيْفِ ضَيَّعْتَ اللَّبَنْ</span> [<i>Thou hast begun to seek our union: in the spring,</i> or <i>in the summer, thou losedst the milk</i>]: (O, * K:) the <span class=\"ar\">ت</span> in this case being with fet-h. (K. [See more in Freytag's Arab. Prov. ii. 197-8, or in Har p. 577; in both of which, however, and in the O, <span class=\"ar\">ضيّعت</span> is with kesr in the latter case, as in the former.]) [One says also, <span class=\"ar\">ضيّع عَهْدَهُ</span>, meaning <i>He broke his compact, contract,</i> or <i>covenant</i>]. The phrase, in a trad., <span class=\"ar\">نَهَى عَنْ <span class=\"ar\">إِضَاعَةِ</span> المَالِ</span> means <i>He forbade the expending of wealth otherwise than in obedience to God, and the squandering thereof, and extravagance.</i> (TA.) -b2- See also the next paragraph.</p><p><b>4.</b> <b class=\"ar\">اضاع الشَّىْءَ</b> : see 2, first sentence, and last but one. -b2- Also, [and app. <span class=\"ar\"> <span class=\"ar\">ضيّعهُ</span></span> likewise, accord. to the K,] <i>He left the thing; left it,</i> or <i>let it, alone;</i> or <i>neglected it.</i> (K, TA.) You say, <span class=\"ar\">اضاع عِيَالَهُ</span> <i>He neglected his family,</i> or <i>household; omitted taking good care of them,</i> or <i>being mindful of them.</i> (TA.) <span class=\"ar\">وَمَا كَانَ ٱللّٰهُ لِيُضِعَ</span> <span class=\"ar\">إِيمَانَكُمْ</span>, in the Kur [ii. 138], means <i>And God will not neglect</i> [or <i>make to be lost</i>] <i>your prayer.</i> (TA.) <span class=\"ar\">أَضَاعُوا الصَّلَاةَ</span>, in the same, [xix. 60,] means <i>Who neglected,</i> or <i>omitted, prayer,</i> (Bd, TA,) <i>altogether:</i> (TA:) or <i>deferred it:</i> (Bd:) or <i>who performed it in other than its right time:</i> but the first explanation is more suitable, for the unbelievers are meant thereby. (TA.) -A2- <span class=\"ar\">اضاع</span> [is also intrans., and] may signify <i>He found his affair to be coming to nought.</i> (Ham p. 33.) -b2- And <i>His estates</i> (<span class=\"ar\">ضِيَاعُهُ</span>) <i>became wide-spread,</i> (S, O, K,) and <i>many,</i> or <i>numerous.</i> (S, O, Msb, K.)</p><p><b>5.</b> <b class=\"ar\">تضيّع</b> , said of the wind, <i>It blew:</i> because it [often] destroys that upon which it blows: so says Er-Rághib. (TA. [But it may be from what here follows.]) -b2- Said of musk, <i>It diffused its odour,</i> or <i>fragrance:</i> (S, O, K;) a dial. var. of <span class=\"ar\">تضوّع</span>: (S:) or an instance of substitution [of <span class=\"ar\">ى</span> for <span class=\"ar\">و</span>]. (O.) [See also 1, last explanation.]</p><p><b class=\"ar\">مَاتَ ضِيْعًا</b> and <span class=\"ar\">ضِيَعًا</span>: see <span class=\"ar\">ضَيَاعٌ</span>.</p><p><b class=\"ar\">ضَيْعَةٌ</b> an inf. n. of 1. (S, &amp;c.) -b2- See <span class=\"ar\">ضَيَاعٌ</span>, below, last sentence but one. -b3- Also <i>A single case,</i> or <i>occasion, of perishing, coming to nought, passing away,</i> or <i>becoming lost;</i> or <i>of being left, left</i> or <i>let alone,</i> or <i>neglected.</i> (TA.) -b4- <span class=\"ar\">تَرَكْتُهُ</span> <span class=\"ar\">بِضَيْعَةٍ</span> means <i>I left him unsought-after,</i> or <i>unminded,</i> or <i>unmissed.</i> (TA. [See also a similar phrase voce <span class=\"ar\">ضَيَاعٌ</span>.]) -A2- Also <i>i. q.</i> <span class=\"ar\">عَقَارٌ</span> [meaning <i>An estate consisting of land,</i> or <i>of land and a house,</i> or <i>of a house</i> or <i>land yielding a revenue,</i> or <i>of a house and palm-trees,</i> or <i>the like</i>]; (S, O, Msb, K;) and [particularly] <i>land yielding a revenue;</i> (K;) or with the people of the towns and villages and cultivated lands it signifies the <i>property,</i> of a man, <i>consisting of palm-trees and grape-vines and land:</i> but the Arabs [of the desert] know not the word in this sense: (Az, TA:) IF says, I do not reckon the application of this word as a name for the <span class=\"ar\">عَقَار</span> to be of the original language, but think it to be an innovation in speech; and I have heard it said that this is termed a <span class=\"ar\">ضيعة</span> because, when frequent attention to it is neglected, it perishes; and if it be so, this is an evidence of what we have said, that it is of the innovated speech: (O, TA:) the dim. is <span class=\"ar\"> <span class=\"ar\">ضُيَيْعَةٌ</span></span>, for which one should not say <span class=\"ar\">ضُوَيْعَةٌ</span>: (S, O, K:) the pl. is <span class=\"ar\">ضِيَاعٌ</span> and <span class=\"ar\">ضِيَعٌ</span>, (S, O, Msb, K,) as though the latter were a contraction of the former, (Msb,) and <span class=\"ar\">ضَيْعَاتٌ</span>: (K:) accord. to Lth, the first of these pls. signifies <i>places of alighting</i> or <i>abode</i> or <i>settlement;</i> which are thus called because, when the paying frequent attention to them, or taking good care of them, and the keeping them, or putting them, in a good state, or state of repair, is neglected, they come to nought: and <span class=\"ar\">ضَيْعَاتٌ</span> occurs in a trad. as meaning the <i>means of subsistence.</i> (TA.) And, (T, O, Msb, K,) as used by the Arabs [of the desert], who know not the word in any other sense than this, (T, O,) <i>A craft,</i> or <i>handicraft, by which one gains his subsistence; a mode,</i> or <i>manner, of gain;</i> or <i>any</i> <i>habitual work</i> or <i>occupation</i> of a man; (T, O, Msb, K) as the <i>sewing of skins</i> or <i>boots</i> and <i>the like;</i> and the <i>twisting of ropes;</i> and the <i>weaving,</i> or <i>plaiting, of palm-leaves;</i> and the <i>culture of palm-trees</i> (<span class=\"ar\">عَمَلُ النَّخْلِ</span>); and the <i>pasturing of camels;</i> and <i>the like thereof;</i> (T, O;) including the <i>sowing,</i> or <i>tilling, of land:</i> (TA:) or the <span class=\"ar\">ضَيْعَة</span> of the Arabs was the <i>management,</i> or <i>tending, of camels</i> and <i>of sheep and goats:</i> and the term includes a man's <i>craft,</i> or <i>handicraft,</i> or <i>means of gain:</i> (Sh, O:) and his <i>traffic:</i> (Sh, O, K:) one says to a man, <span class=\"ar\">قُمْ إِلَى ضَيْعَتِكَ</span> [<i>Arise to thy craft,</i> &amp;c.]: (Sh, O:) and <span class=\"ar\">كُلُّ رَجُلٍ</span> <span class=\"ar\">وَضَيْعَتَهُ</span>, [<i>Every man</i> should occupy himself <i>with his</i> proper <i>craft,</i> &amp;c.] (Msb.) <span class=\"ar\">أَفْشَى ٱللّٰهُ</span>, <span class=\"ar\">ضَيْعَتَهُ</span>, occurring in a trad., means <i>God made</i> or <i>may God make, his means of subsistence to be abundant.</i> (TA.) And one says, <span class=\"ar\">فَشَتْ ضَيْعَتُهُ</span>, [or, more commonly, <span class=\"ar\">فَشَتْ عَلَيْهِ ضَيْعَتُهُ</span>, as in the TA in art. <span class=\"ar\">فشو</span>, &amp;c.,] which is said to mean <i>His property was,</i> or <i>became, large,</i> or <i>abundant,</i> [or <i>wide-spread,</i>] <i>so that he was unable to collect it together:</i> and [hence] <i>his means of attaining his object</i> [or <i>his affairs</i> (as in the TA in art. <span class=\"ar\">فشو</span>)] <i>became disordered so that he knew not with which of them to begin:</i> (TA:) or <i>he took to doing an affair that did not concern him:</i> (TA, and Ham p. 33:) it is nearly like the saying <span class=\"ar\">اِتَّسَعَ الخَرْقُ</span> <span class=\"ar\">عَلَى الرَّاقِعِ</span> [expl. in art. <span class=\"ar\">خرق</span>]. (Ham ibid.) And <span class=\"ar\">إِنِّى لَأَرَى ضَيْعَةً لَا يُصْلِحُهَا إِلَّا ضَجْعَةٌ</span> [<i>Verily I see property that nothing but a sleep will restore to a right state</i>] a prov.; said by a pastor whose camels had dispersed themselves, and who, desiring to collect them together, and being unable to do so, sought aid of sleep. (O.)</p><p><b class=\"ar\">مَاتَ ضِيعَةً</b> : see the next paragraph.</p><p><b class=\"ar\">ضَيَاعٌ</b> an inf. n. of 1 [q. v.]. (S, &amp;c.) [Hence] one says, <span class=\"ar\">مَاتَ ضَيَاعًا</span>, as also <span class=\"ar\"> <span class=\"ar\">ضِيَعًا</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضِيْعًا</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضِيعَةٌ</span></span>, <i>He</i> (a man, TA) <i>died unsought-after,</i> or <i>unminded,</i> or <i>unmissed.</i> (K, TA. [See also a similar phrase voce <span class=\"ar\">ضَيْعَةٌ</span>.]) -b2- Also <i>A family,</i> or <i>household:</i> (ISh, O, K:) or the meaning is <span class=\"ar\">عِيَالٌ ضُيَّعٌ</span>, (Mgh, O, K, *) i. e. <i>a family,</i> or <i>household, neglected, untended, and unminded;</i> (TA;) or <i>such as are exposed,</i> or <i>liable, to perish,</i> (<span class=\"ar\">بِعَرَضِ أَنْ يَضِيعَ</span>,) <i>as young children, and those who are crippled,</i> or <i>deprived of the power of motion, who cannot manage their own affairs:</i> (Mgh:) occurring in a trad., in which it is said that when a man died leaving such as are thus termed, (<span class=\"ar\">تَرَكَ ضَيَاعًا</span>,) they were to be brought to the Prophet, (Mgh, O,) to be maintained by means of the government-treasury: (Mgh:) a prefixed noun is to be understood [i. e. it is for <span class=\"ar\">عِيَالَ ضَيَاعٍ</span> or the like]: (Mgh:) or it is an inf. n. used as a subst. [properly thus termed]: (Mgh, O:) or, accord. to one relation of the trad., the word is <span class=\"ar\"> <span class=\"ar\">ضَيْعَةً</span></span> [which is likewise an inf. n., and in this case to be expl. in the same manner]: (Mgh:) if read <span class=\"ar\">ضِيَاعًا</span>, it would be pl. of <span class=\"ar\">ضَائِعٌ</span>. (Mgh, O.) -A2- Also <i>A sort of perfume,</i> or <i>odoriferous substance.</i> (K.)</p><p><b class=\"ar\">ضُيَيْعَةٌ</b> dim. of <span class=\"ar\">ضَيْعَةٌ</span>, q. v. (S, O, K.)</p><p><b class=\"ar\">ضَائعٌ</b> <i>Perishing, coming to nought, passing away,</i> or <i>becoming lost:</i> (Mgh, * Msb:) [and <i>being left; left,</i> or <i>let, alone;</i> or <i>neglected:</i>] part. n. of 1: (Mgh, Msb:) pl. <span class=\"ar\">ضِيَاعٌ</span> (Mgh, O, Msb, K) and <span class=\"ar\">ضُيَّعٌ</span>. (Mgh, O, * Msb, K. *) [See an ex. of the latter pl. in a verse cited voce <span class=\"ar\">دَانَ</span>, in art. <span class=\"ar\">دين</span>. See also <span class=\"ar\">سَائِعٌ</span>, in art. <span class=\"ar\">سوع</span>.] -b2- And A man <i>in a state of poverty:</i> or <i>having a family,</i> or <i>household, to sustain:</i> or <i>in a state of circumstances by means of which he is unable to subsist.</i> (TA.) -b3- <span class=\"ar\">فُلَانٌ يَأْكُلُ فِى مِعًى ضَائِعٍ</span> means <span class=\"ar\">جَائِعٍ</span> [i. e. <i>Such a one eats into a hungry,</i> or <i>an empty, gut</i>]: and it was said to the daughters of ElKhuss, “ What is the sharpest thing? (<span class=\"ar\">مَا أَحَدُّ</span> <span class=\"ar\">شَىْء</span>;) and she answered, <span class=\"ar\">نَابٌ جَائِعٌ يُلْقِى فِى</span> <span class=\"ar\">مِعًى ضَائِعٍ</span> [<i>A hungry canine tooth that throws</i> the food <i>into an empty gut</i>]. (S.)</p><p><b class=\"ar\">أَضْيَعُ</b> means <span class=\"ar\">أَكْثَرُ ضَيَاعًا</span>: so in the saying, <span class=\"ar\">فُلَانٌ أَضْيَعُ مِنْ فُلَانٍ</span> [<i>Such a one is in a more perishing state than such a one</i>]. (TA.)</p><p><b class=\"ar\">مُضِيعٌ</b> act. part. n. of the trans. v. <span class=\"ar\">اضاع</span>. (TA.) [See <span class=\"ar\">مِسْيَاعٌ</span>, in art. <span class=\"ar\">سوع</span>.] -A2- And part. n. of the intrans. v. <span class=\"ar\">اضاع</span>; as such signifying One <i>whose estates</i> (<span class=\"ar\">ضِيَاعُهُ</span>) <i>are becoming wide-spread,</i> and <i>many,</i> or <i>numerous.</i> (S, TA.)</p><p><b class=\"ar\">مَضِيعَةٌ</b> and <span class=\"ar\">مَضْيَعَةٌ</span> <i>i. q.</i> <span class=\"ar\">ضَيَاعٌ</span> [an inf. n. of 1, q. v.]. (Mgh, O, Msb, K.) So in the saying, <span class=\"ar\">تَرَكَ عِيَالَهُ بِمَضِيعَةٍ</span> or <span class=\"ar\">بِمَضْيَعَةٍ</span> [<i>He left his family,</i> or <i>household, in a state of perishing,</i> &amp;c.]. (Mgh.) So too in the saying, <span class=\"ar\">السَّارِقُ لَا يُقْطَعُ فِى مَالٍ</span> <span class=\"ar\">بِمَضِيعَةٍ</span> [<i>The thief shall not suffer amputation</i> of his hand <i>in the case of</i> his stealing <i>property in a neglected state</i>]. (Mgh.) And so in the saying, <span class=\"ar\">هُوَ بِدَارِ مَضِيعَةٍ</span> (S, * O, K) and <span class=\"ar\">مَضْيَعَةٍ</span> (O, K) [<i>He is in a place</i> (lit. <i>an abode</i>) <i>of perdition,</i> &amp;c.]: or as meaning in this saying, <i>abandonment,</i> and <i>ignominy.</i> (TA.) And <span class=\"ar\">هُوَ مُقِيمٌ بِدَارِ مَضِيعَةٍ</span> or <span class=\"ar\">مَضْيَعَةٍ</span> means [<i>He is dwelling in the abode of indolence;</i> or] <i>his characteristic in his affairs is indolence.</i> (Msb.) -b2- Also, [or perhaps the latter only, as meaning <i>A cause of perishing</i> &amp;c., this latter being app. of the class of <span class=\"ar\">مَبْخَلَةٌ</span> and <span class=\"ar\">مَجْبَنَةٌ</span> &amp;c.,] <i>A desert,</i> or <i>waterless desert, that is cut off</i> [<i>from inhabited regions</i>]: or, as expl. by IJ, <i>a place in which a man perishes,</i> or <i>is lost.</i> (Msb.)</p><p><b class=\"ar\">مُضَيِّعٌ</b> : see what follows.</p><p><b class=\"ar\">رَجُلٌ مِضْيَاعٌ لِلْمَالِ</b> <i>i. q.</i><span class=\"ar\"> <span class=\"ar\">مُضَيِّعٌ</span>لَهُ</span> [i. e. <i>A man who wastes,</i> or <i>squanders, wealth,</i> or <i>property</i>]. (S, O, K.)</p>"},"ضيق":{"mf":"الضِّيقُ: ضدّ السّعة، ويقال: الضَّيْقُ أيضا، والضَّيْقَةُ يستعمل في الفقر والبخل والغمّ ونحو ذلك. قال تعالى: وَضاقَ بِهِمْ ذَرْعاً<br>[هود/ ٧٧]، أي: عجز عنهم، وقال: وَضائِقٌ بِهِ صَدْرُكَ<br>[هود/ ١٢]، وَيَضِيقُ صَدْرِي<br>[الشعراء/ ١٣]، ضَيِّقاً حَرَجاً<br>[الأنعام/ ١٢٥]، وَضاقَتْ عَلَيْكُمُ الْأَرْضُ بِما رَحُبَتْ<br>[التوبة/ ٢٥]، وَضاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ<br><br>[التوبة/ ١١٨]، وَلا تَكُ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ<br>[النحل/ ١٢٧]. كلّ ذلك عبارة عن الحزن، وقوله: وَلا تُضآرُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَ<br>[الطلاق/ ٦]، ينطوي على تَضْيِيقِ النفقة وتَضْيِيقِ الصّدر، ويقال في الفقر: ضَاقَ، وأَضَاقَ فهو مُضِيقٌ. واستعمال ذلك فيه كاستعمال الوسع في ضدّه.","mq":[["خلاف السعة"],"الضاد والياء والقاف كلمة واحدةٌ تدلُّ على خلافِ السَّعَة، وذلك هو الضِّيق والضَّيِقة: الفَقْر. يقال أضاق الرّجلُ: ذهب مالُه. وضاقَ، إذا بخل. وشئٌ ضَيْقٌ، أى ضيِّق. والباب كلُّه قياس واحد. فأمّا قول القائل:<br>بضِيقَةَ بينَ النَّجْمِ والدّ؟؟؟ انِ (٣)<br>فيقال إنّ الضِّيقة منزلٌ فى منازل القمرْ. قال أبو عمر"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَاقَ</b> , aor. <span class=\"ar\">يَضِيقُ</span>, inf. n. <span class=\"ar\">ضَيْقٌ</span> (S, O, Msb, K) and <span class=\"ar\">ضِيقٌ</span>, (S, O, K,) or this latter is a simple subst., (Msb,) <i>It was,</i> or <i>became, narrow,</i> or <i>strait; contr. of</i> <span class=\"ar\">اِتَّسَعَ</span>; (Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">تضيّق</span></span>, [or rather this signifies <i>it was,</i> or <i>became, rendered narrow,</i> or <i>strait,</i> being quasipass. of 2,] and <span class=\"ar\"> <span class=\"ar\">تضايق</span></span>: (K:) it is said of a thing, (S, O, Msb,) and of a place. (Msb.) [See also <span class=\"ar\">ضَيْقٌ</span> below.] <span class=\"ar\">ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ</span>, in the Kur ix. 119, means <i>The earth became strait to them.</i> (Bd, Jel.) And one says, <span class=\"ar\">ضَاقَتْ بِهِ الأَرْضُ</span> [meaning, in like manner, <i>The earth,</i> or <i>land, became narrow,</i> or <i>strait, with him</i>]: 'Amr Ibn-El-Ahtam says, <span class=\"ar\">لَعَمْرُكَ مَا ضَاقَتْ بِلَادٌ بِأَهْلِهَا</span> <span class=\"ar\">وَلٰكِنَّ أَخْلَاقَ الرِّجَالِ تَضِيقُ</span> [<i>By thy life,</i> or <i>by thy religion, countries have not become narrow with their inhabitants, but the dispositions of the men become narrow</i>]. (O, TA.) [<span class=\"ar\">ضاق بِهِ</span> often signifies, and so does <span class=\"ar\"> <span class=\"ar\">تضايق</span>به</span>, <i>It was,</i> or <i>became, choked, surcharged,</i> or <i>overfilled, with it;</i> for instance, a water-course with water, and a place with people.] And <span class=\"ar\"> <span class=\"ar\">تضايق</span> بِهِ الأَمْرُ</span> means <span class=\"ar\">ضاق عَلَيْهِ</span> (tropical:) [<i>The affair was,</i> or <i>became, strait to him</i>]. (O, TA. [See an ex. in art. <span class=\"ar\">رحب</span>, conj. 6.]) One says also, <span class=\"ar\">ضاق عَلَيْهِ</span> <span class=\"ar\">مَعَاشُهُ</span>: see 4. [And <span class=\"ar\">ضاق الوَقْتُ</span> (assumed tropical:) <i>The time became strait,</i> or <i>contracted.</i>] And <span class=\"ar\">ضاق صَدْرُهُ</span> (assumed tropical:) <i>His bosom,</i> or <i>mind, became strait,</i> or <i>contracted:</i> (Msb:) and <span class=\"ar\">ضاق عَنْهُ صَدْرُكَ</span> (assumed tropical:) [<i>Thy mind became so contracted as to be incapable of it:</i> or <i>thy mind shrank from it</i>]. (K.) [And <span class=\"ar\">يَضِيقُ العَقْلُ عَنْ تَقْدِيرِهِ</span> (assumed tropical:) <i>The intellect is incapable of determining its limit,</i> or <i>limits,</i> or <i>the like.</i>] And <span class=\"ar\">ضاق عَنِ الجَوَابِ</span> and <span class=\"ar\">بِالجَوَابِ</span> (assumed tropical:) [<i>He was straitened,</i> or <i>embarrassed, so as to be unable to reply,</i> or <i>to answer; he was incapable of replying,</i> or <i>answering</i>]: both signify the same. (TA in art. <span class=\"ar\">زند</span>.) And <span class=\"ar\">ضاق بالأَمْرِ ذَرْعًا</span>, (S, * O, * Msb,) meaning (assumed tropical:) <i>The thing,</i> or <i>affair, was difficult,</i> or <i>distressing, to him,</i> (Msb,) originally <span class=\"ar\">ضاق ذَرْعُهُ بِهِ</span>, (S, * O, * Msb,) i. e. <i>his ability</i> [<i>was straitened by it,</i> or <i>was inadequate to it</i>]; and <i>his power:</i> (Msb:) or <i>his art,</i> or <i>artifice,</i> or <i>cunning:</i> or <i>his way, course, mode,</i> or <i>manner, of acting</i> (<span class=\"ar\">مَذْهَبُهُ</span>) [<i>was straitened,</i> or <i>rendered difficult,</i> or <i>distressing, by it</i>]. (O. [See more voce <span class=\"ar\">ذَرْعٌ</span>: and see a similar phrase in the Kur xi. 79 and xxix. 32.]) And hence, app., the saying <span class=\"ar\">ضاق</span> <span class=\"ar\">المَالُ عَنِ الدُّيُونِ</span> (tropical:) <i>The property was inadequate to the debts.</i> (Msb.) And you say, <span class=\"ar\">ضاق عَنْكَ</span> <span class=\"ar\">الشَّىْءُ</span> [meaning <span class=\"ar\">لَمْ يَسَعْكَ</span> (assumed tropical:) <i>The thing was not allowable to thee</i>]: one says, <span class=\"ar\">لَا يَسَعُنِى شَىْءٌ وَيَضِيقَ</span> <span class=\"ar\">عَنْكَ</span>, (S, O, * TA, [in the O, erroneously, <span class=\"ar\">لا</span> <span class=\"ar\">يستغنى</span>,]) i. e. <span class=\"ar\">وَأَنْ يَضِيقَ عَنْكَ</span> (assumed tropical:) [<i>A thing will not be allowable to me conjointly with its being disallowable to thee,</i> <span class=\"ar\">وَأَنْ يَضِيقٌ</span> meaning <span class=\"ar\">مَعَ ضَيْقِهِ</span>]: <span class=\"ar\">بَلْ مَتَى وَسِعَنِى شَىْءٌ وَسِعَكَ</span> [<i>but when a thing is allowable to me, it is allowable to thee</i>]. (S in art. <span class=\"ar\">وسع</span>.) And <span class=\"ar\">ضاق</span>, (aor. <span class=\"ar\">يَضَِيقُ</span>, K, inf. n. <span class=\"ar\">ضِيقٌ</span>, TA,) (tropical:) <i>He was</i> or <i>became, niggardly,</i> or <i>avaricious.</i> (S, O, Msb, K, TA.)</p><p><b>2.</b> <b class=\"ar\">ضيّقهُ</b> , (Msb, K,) inf. n. <span class=\"ar\">تَضْيِيقٌ</span>, (Msb, TA,) <i>He made it strait,</i> or <i>narrow;</i> (Msb, K;) namely, a place [&amp;c.]; (Msb;) as also <span class=\"ar\"> <span class=\"ar\">اضاقهُ</span></span>, (K,) inf. n. <span class=\"ar\">إِضَاقَةٌ</span>. (TA.) You say, <span class=\"ar\">ضَيَّقْتُ عَلَيْهِ</span> <span class=\"ar\">المَكَانَ</span>, (S,) or <span class=\"ar\">الشَّىْءَ</span>, i. e. <i>I straitened,</i> or <i>made narrow, to him</i> [<i>the place,</i> or <i>the thing;</i> or <i>I scanted it,</i> or <i>made it scanty</i>]; <i>contr. of</i> <span class=\"ar\">وَسَّعْتُهُ</span> <span class=\"ar\">عَلَيْهِ</span>. (O.) And <span class=\"ar\">ضَيَّقْتُ عَلَيْهِ</span> [alone, used elliptically, <i>I straitened him,</i> properly speaking; and also, (assumed tropical:) his circumstances &amp;c.]. (Msb.) And <span class=\"ar\">ضُيِّقَ</span> <span class=\"ar\">عَلَى فُلَانٍ</span> (assumed tropical:) [<i>Such a one was straitened</i>]. (TA.) <span class=\"ar\">لِتُضَيِّقُوا عَلَيْهِنَّ</span>, in the Kur [lxv. 6, (assumed tropical:) <i>In order that ye may straiten them</i>], implies relation to expenses and to the bosom. (TA.) [See 3. <span class=\"ar\">التَّضْيِيقُ بَيْنَ شَيْئَيْنِ</span>, occurring in the S and K in art. <span class=\"ar\">حوص</span>, means <i>The making a coarctation between two things.</i>]</p><p><b>3.</b> <b class=\"ar\">ضايقهُ</b> <i>He straitened him:</i> (MA:) [see also 2: or, properly, <i>he straitened him, being in like manner straitened by him:</i> see 1 in art. <span class=\"ar\">زحم</span>: and] (tropical:) <i>he treated him,</i> or <i>behaved towards him, with hardness,</i> or <i>harshness;</i> (O, * K, * TA;) <span class=\"ar\">فِى كَذَا</span> [<i>in,</i> or <i>in respect of, such a thing</i>]. (TA.)</p><p><b>4.</b> <b class=\"ar\">اضاق</b> (tropical:) <i>His means of living became strait</i> (<span class=\"ar\"> <span class=\"ar\">ضَاقَ</span>عَلَيِْه مَعَاشُهُ</span>); (TA;) <i>his property went away;</i> (S, O, Msb, K;) and <i>he became poor.</i> (TA.) -A2- See also 2.</p><p><b>5.</b> <b class=\"ar\">تَضَيَّقَ</b> see 1, first sentence.</p><p><b>6.</b> <b class=\"ar\">تَضَاْيَقَ</b> see 1, in three places. <span class=\"ar\">تضايقوا</span> <i>They straitened one another; pushed,</i> or <i>pressed, one against another;</i> or <i>crowded one another;</i> in a place of assembly; syn. <span class=\"ar\">زَحَمَ بَعْضُهُمْ بَعْضًا</span>: (Msb in art. <span class=\"ar\">زحم</span>:) or <i>they became straitened</i> in a place, or (assumed tropical:) in disposition. (S, O.)</p><p><b>10.</b> <b class=\"ar\">استضاقت بِدُرْجَةٍ</b> [<i>She endeavoured to constrict her vagina by means of a pessary</i>], (O, K, TA,) or <span class=\"ar\">بِالأَدْوِيَةِ</span> [<i>by means of medicaments</i>]; (A, TA;) said of a woman. (A, O, K.)</p><p><b class=\"ar\">ضَيْقٌ</b> an inf. n. of 1, (S, O, Msb, K,) as also <span class=\"ar\"> <span class=\"ar\">ضِيقٌ</span></span>, (S, O, K,) or the latter is a simple subst.: (Msb:) [both, used as simple substs., signify <i>Narrowness,</i> or <i>straitness:</i>] accord. to Fr, [both seem to signify thus; but the latter, properly; and the former, tropically; for he says that] <span class=\"ar\">الضَّيْقُ</span> is in that which does not [really] become wide, like the mind (<span class=\"ar\">الصَّدْر</span>): (O:) or it is <span class=\"ar\">مَا ضَاقَ عَنْهُ صَدْرُكَ</span> [<i>that of which the mind by its being contracted is incapable,</i> or <i>from which the mind shrinks;</i> an explanation not given in the K as on the authority of Fr, and deviating from his words as given in the O; whence it appears that, for <span class=\"ar\">مَا</span>, we should perhaps read <span class=\"ar\">فِيمَا</span>]: (K:) but <span class=\"ar\"> <span class=\"ar\">الضِّيقُ</span></span> is in that which may be [really] wide, like the house and the garment: (O, K:) and the former [is also used as an epithet, being a contraction of <span class=\"ar\">ضَيِّقٌ</span> in this case, and as such] has a dual and a plural and a feminine; but the latter has not: (O:) or both are alike [in signification]: (K:) and <span class=\"ar\"> <span class=\"ar\">ضَيْقَةٌ</span></span> is syn. with <span class=\"ar\">ضِيقٌ</span>. (S.) -b2- Also, and <span class=\"ar\"> <span class=\"ar\">ضَيَقٌ</span></span>, accord. to AA, (O, [the latter there expressly said to be <span class=\"ar\">بِالتَّحْرِيكِ</span>,]) or the former and <span class=\"ar\"> <span class=\"ar\">ضِيقٌ</span></span>, (K, [said in the TA to be a mistake for <span class=\"ar\">ضَيَقٌ</span>, but see what follows,]) <i>Doubt</i> (AA, O, K) <i>in the heart:</i> (K) the first is more common than the second, in this sense; and occurs in the Kur in xvi. last verse and xxvii. 72: (O:) [but] Ibn-Ketheer read, in both of these instances, <span class=\"ar\"> <span class=\"ar\">ضِيق</span></span>; and this and <span class=\"ar\">ضَيْق</span> are dial. vars. signifying <i>straitness of mind.</i> (Bd.) -A2- See also <span class=\"ar\">ضَيِّقٌ</span>, in two places: -b2- and <span class=\"ar\">ضَيْقَةٌ</span>, second sentence, in two places.</p><p><b class=\"ar\">ضِيقٌ</b> : see the next preceding paragraph, in five places.</p><p><b class=\"ar\">ضَيَقٌ</b> : see <span class=\"ar\">ضَيْقٌ</span>, latter part.</p><p><b class=\"ar\">ضَيْقَةٌ</b> : see <span class=\"ar\">ضَيْقٌ</span>, latter part. -b2- Also (S) (tropical:) <i>Poverty;</i> and <i>an evil state</i> or <i>condition;</i> (S, O, K, TA;) and so <span class=\"ar\"> <span class=\"ar\">ضِيقَةٌ</span></span>: (K, TA:) and the pl. [or rather coll. gen. n.] (Fr, S, K, TA) of the former (Fr, S, TA) is <span class=\"ar\"> <span class=\"ar\">ضَيْقٌ</span></span>: (Fr, S, K, TA: [in the CK, erroneously, <span class=\"ar\">ضِيقٌ</span>:]) Fr says, when you see <span class=\"ar\"> <span class=\"ar\">الضَّيْق</span></span> to have occurred in the place of <span class=\"ar\">الضِّيق</span>, it is in [one of] two cases; either it is the pl. [or coll. gen. n.] of <span class=\"ar\">الضَّيْقَةُ</span>; or it means <i>the narrow,</i> or <i>strait, thing,</i> <span class=\"ar\">ضَيْقٌ</span> being a contraction of <span class=\"ar\">ضَيِّقٌ</span>. (TA.) -b3- And <span class=\"ar\">الضَّيْقَةُ</span>, (O,) or <span class=\"ar\">ضَيْقَةُ</span> [without the article], (JK, O, TA,) or <span class=\"ar\"> <span class=\"ar\">الضِّيقَةُ</span></span>, (K, [app. a mistake, for in the O, in every case, whether as a proper name or not, <span class=\"ar\">الضيقة</span> is written <span class=\"ar\">الضَّيْقَةُ</span>,]) is the name of <i>A certain mansion of the moon,</i> (JK, O, K, TA,) [not one of the Twentyeight Mansions,] <i>close by</i> <span class=\"ar\">الثُّرَيَّا</span> [or <i>the Pleiades</i>]: (JK, O, TA:) or, as IKt says, on the authority of Ibn-Ziyád El-Kilábee, sometimes the moon falls short of <span class=\"ar\">الدَّبَرَان</span> and alights in <span class=\"ar\">الضيقة</span>, i. e. <i>two small stars, near together, between</i> <span class=\"ar\">الثُّرَيَّا</span> <i>and</i> <span class=\"ar\">الدَّابَرَان</span>: (TA:) it is asserted by the Arabs to be an inauspicious place. (O, * TA.) Hence the saying of El-Akhtal, <span class=\"ar\">فَهَلَّا زَجَرْتَ الطَّيْرَ لَيْلَةَ جِئْتَهَا</span> <span class=\"ar\">بِضَيْقَةَ بَيْنَ النَّجْمِ وَالدَّبَرَانِ</span> [<i>And wherefore didst not thou draw an omen from the flight of birds on the night when thou camest to her,</i> when the moon was <i>in Deykah, between the Pleiades and Ed-Debarán?</i>]: he notifies that the moon, in the night of their coming together, was making its abode [in the neighbourhood of] <span class=\"ar\">الدبران</span>, which is inauspicious: (O, TA:) or [the latter hemistich, as J relates it, app. on the authority of A 'Obeyd, is thus,] <span class=\"ar\">بِضَيْقَةِ بَيْنَ النَّجْمِ وَالدَّبَرَانِ</span> from <span class=\"ar\">الضَّيْقَةُ</span> as syn. with <span class=\"ar\">الضَّيْقُ</span>; (S;) and as AA relates the verse, it is [thus] with kesr to the <span class=\"ar\">ة</span> in <span class=\"ar\">بضيقة</span>; the word not being made the [proper] name of a place, but the meaning being <span class=\"ar\">بضيقة مَا بَيْنَ النجم والدبران</span> [i. e. <i>in the narrow space between the Pleiades and Ed-Debarán</i>]. (TA.) -b4- <span class=\"ar\">ضَيْقَةٌ</span> is also the fem. of <span class=\"ar\">ضَيْقٌ</span> the contracted form of <span class=\"ar\">ضَيِّقٌ</span>. (S, O, TA.)</p><p><b class=\"ar\">ضِيقَةٌ</b> : see the next preceding paragraph, former half, in two places.</p><p><b class=\"ar\">ضُوقَى</b> and <span class=\"ar\">ضِيقَى</span> are fems. of <span class=\"ar\"> <span class=\"ar\">أَضْيَقُ</span></span>; (S, O, K;) the former [as well as the latter] is [originally] of the measure <span class=\"ar\">فُعْلَى</span>, (TA,) [each being originally <span class=\"ar\">ضُيْقَى</span>,] the <span class=\"ar\">ى</span> being changed in the former into <span class=\"ar\">و</span> because quiescent and preceded by dammeh: (S, O, TA:) the former occurs in the saying of a woman to her fellowwife, contending with her for superiority, <span class=\"ar\">مَا أَنْتِ بِالخُورَى وَلَا الضُّوقَى حِرًا</span> [<i>Thou art not the better nor the narrower</i> &amp;c.; <span class=\"ar\">خُورَى</span> being in like manner fem. of <span class=\"ar\">أَخْيَرُ</span>]. (TA.) Accord. to Kr, the former is pl. of <span class=\"ar\"> <span class=\"ar\">ضَيِّقَةٌ</span></span>; (TA;) and he says the same of <span class=\"ar\">ضِيقَى</span> also; (TA voce <span class=\"ar\">كَيِّسٌ</span>;) but ISd says, I know not how this may be, for <span class=\"ar\">فُعْلَى</span> is not of the measures of pls. except of the kind of pl. which differs not from its sing. otherwise than in the latter's having <span class=\"ar\">ة</span> [as an affix], like <span class=\"ar\">بُهْمَاةٌ</span> and <span class=\"ar\">بُهْمَى</span> [q. v.]. (TA in the present art.)</p><p><b class=\"ar\">ضِيَاقٌ</b> : see <span class=\"ar\">مِضْيَاقٌ</span>.</p><p><b class=\"ar\">ضَائِقٌ</b> : see the next paragraph, in four places.</p><p><b class=\"ar\">ضَيِّقٌ</b> and <span class=\"ar\"> <span class=\"ar\">ضَيْقٌ</span></span>, (S, O, K,) the latter a contraction of the former, (S,) the two being like <span class=\"ar\">هَيِّنٌ</span> and <span class=\"ar\">هَيْنٌ</span> [&amp;c.], (O,) and <span class=\"ar\"> <span class=\"ar\">ضَائِقٌ</span></span>, (K,) <i>Narrow,</i> or <i>strait:</i> (S, * O, * K:) or <span class=\"ar\">ضَيِّقٌ</span> is an epithet used in this sense when permanence [of the attribute] is meant [and so therefore is its contracted form]; and <span class=\"ar\"> <span class=\"ar\">ضَائِقٌ</span></span> as meaning [<i>being,</i> or <i>becoming, narrow</i> or <i>strait;</i> or] <i>temporarily narrow</i> or <i>strait:</i> (Msb:) the fem. of the first (TA) and of the second (S, O, TA) [as well as of the third] is with <span class=\"ar\">ة</span>: (S, O, TA:) see also <span class=\"ar\">ضُوقَى</span>: [the pls. of the first and second, applied to rational beings, is <span class=\"ar\">ضَيِّقُونَ</span> and <span class=\"ar\">ضَيْقُونَ</span>, like <span class=\"ar\">مَيِّتُونَ</span> and <span class=\"ar\">مَيْتُونَ</span>: and] the pl. of <span class=\"ar\"> <span class=\"ar\">ضَائِقٌ</span></span> is <span class=\"ar\">ضَاقَةً</span>. (TA.) You say <span class=\"ar\">شَىْءٌ ضَيِّقٌ</span> (O, Msb) and <span class=\"ar\"> <span class=\"ar\">ضَيْقٌ</span></span> (O) <i>A narrow,</i> or <i>strait, thing.</i> (O, * Msb.) And <span class=\"ar\">صَدْرٌ ضَيِّقٌ</span> (assumed tropical:) <i>A strait,</i> or <i>contracted, mind;</i> (Msb;) and <span class=\"ar\">نَفْسٌ ضَيِّقَةٌ</span> [meaning the same]. (TA.) And <span class=\"ar\"> <span class=\"ar\">وَضَائقٌ</span>بِهِ صَدْرُكَ</span>, in the Kur [xi. 15], means (assumed tropical:) <i>And thy mind is temporarily strait</i> or <i>contracted thereby.</i> (Msb.) <span class=\"ar\">ضَيِّقٌ</span> signifies also (assumed tropical:) <i>Niggardly,</i> or <i>avaricious.</i> (KL.) [And <span class=\"ar\">ضَيِّقُ الخُلُقِ</span> (assumed tropical:) <i>Narrow,</i> or <i>illiberal, in disposition.</i>]</p><p><b class=\"ar\">أَضْيَقُ</b> [<i>More,</i> and <i>most, narrow</i> or <i>strait</i> or <i>contracted</i>]: (S, O, K:) see its fems. <span class=\"ar\">ضُوقَى</span> and <span class=\"ar\">ضِيقَى</span>, above. [See also three exs. voce <span class=\"ar\">اِسْتٌ</span>, in art. <span class=\"ar\">سته</span>.]</p><p><b class=\"ar\">مَضِيقٌ</b> <i>A narrow,</i> or <i>strait, place:</i> (K:) [<i>a pass: a place of narrowness</i> or <i>straitness</i>] of land; and of the vulva; and (assumed tropical:) [<i>a place,</i> or <i>state, of straitness</i>] of life, or of the means of subsistence: (K in art. <span class=\"ar\">ازم</span>:) and (tropical:) <i>a narrow,</i> or <i>strait, affair</i> or <i>case:</i> (K, TA:) pl. <span class=\"ar\">مَضَايِقُ</span>. (TA.)</p><p><b class=\"ar\">أَمْرٌ مُضَيَّقٌ</b> (assumed tropical:) [<i>An affair rendered strait</i>]. (TA.)</p><p><b class=\"ar\">مِضْيَاقٌ</b> , (JK, and O on the authority of Ibn- 'Abbád, and TA,) or <span class=\"ar\"> <span class=\"ar\">ضِيَاقٌ</span></span>, like <span class=\"ar\">كِتَابٌ</span> [in measure], thus in all the copies of the K, (TA,) [but probably, I think, taken from a mistranscription,] <i>A pessary</i> (<span class=\"ar\">دُرْجَةٌ</span>) <i>of rag and perfume, with which a woman endeavours to constrict her vagina</i> (<span class=\"ar\">تَسْتَضِيقُ بِهَا</span>). (JK, Ibn-'Abbád, O, K.)</p>"},"ضحك":{"mf":"الضَّحِكُ: انبساطُ الوجه وتكشّر الأسنان من سرور النّفس، ولظهور الأسنان عنده سمّيت مقدّمات الأسنان الضَّوَاحِكِ. واستعير الضَّحِكُ للسّخرية، فقيل: ضَحِكْتُ منه، ورجلٌ ضُحَكَةٌ:<br>يَضْحَكُ من النّاس، وضُحْكةٌ: لمن يُضْحَكُ منه <strong>«٢»</strong>. قال تعالى: وَكُنْتُمْ مِنْهُمْ تَضْحَكُونَ<br>[المؤمنون/ ١١٠]، إِذا هُمْ مِنْها يَضْحَكُونَ<br>[الزخرف/ ٤٧]، تَعْجَبُونَ وَتَضْحَكُونَ [النجم/ ٥٩- ٦٠]، ويستعمل في السّرور المجرّد نحو: مُسْفِرَةٌ ضاحِكَةٌ<br>[عبس/ ٣٨- ٣٩]، فَلْيَضْحَكُوا قَلِيلًا<br>[التوبة/ ٨٢]، فَتَبَسَّمَ ضاحِكاً<br><strong>[النمل/ ١٩]، قال الشاعر:</strong><br><span class=\"num\">٢٩١-</span><br>يَضْحَكُ الضّبع لقتلى هذيل... وترى الذّئب لها يستهلّ<br><strong>«٣»</strong> واستعمل للتّعجّب المجرّد تارة، ومن هذا<br><br>المعنى قَصَدَ مَن قال: الضَّحِكُ يَختصُّ بالإنسان، وليس يوجد في غيره من الحيوان، قال: ولهذا المعنى قال تعالى: وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكى<br>[النجم/ ٤٣]، وَامْرَأَتُهُ قائِمَةٌ فَضَحِكَتْ<br>[هود/ ٧١]، وضَحِكُهَا كان للتّعجّب بدلالة قوله: أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ [هود/ ٧٣]، ويدلّ على ذلك أيضا قوله: أَأَلِدُ وَأَنَا عَجُوزٌ إلى قوله: عَجِيبٌ [هود/ ٧٢]، وقول من قال: حاضت، فليس ذلك تفسيرا لقوله: فَضَحِكَتْ كما تصوّره بعض المفسّرين <strong>«١»</strong>، فقال: ضَحِكَتْ بمعنى حاضت، وإنّما ذكر ذلك تنصيصا لحالها، وأنّ الله تعالى جعل ذلك أمارة لما بشّرت به، فحاضت في الوقت ليعلم أنّ حملها ليس بمنكر، إذ كانت المرأة ما دامت تحيض فإنها تحبل، وقول الشاعر في صفة روضة:<br><span class=\"num\">٢٩٢-</span><br>يُضَاحِكُ الشمسَ منها كوكب شرِقٌ<br><strong>«٢»</strong> فإنّه شبّه تلألؤها بِالضَّحِكِ، ولذلك سمّي البرق العارض ضَاحِكاً، والحجر يبرق ضَاحِكاً، وسمّي البلح حين يتفتَّقُ ضَاحِكاً، وطريقٌ ضَحُوكٌ: واضحٌ، وضَحِكَ الغديرُ: تلألأ من امتلائه، وقد أَضْحَكْتُهُ.","mq":[[],"الضاد والحاء والكاف قريبٌ من الباب الذى قبله، وهو دليل الانكشاف والبروز. من ذلك الضَّحِك ضَحِك الإنسان. ويقال أيضاً<br>حقا يقينا ولما يأتنا الصدر.<br>«فى شهور الصيف محراق».<br>الضَّحْك (١)<br>، والأوَّل أفصح. والضَّاحكة: كل سنٍّ تبدو من مُقَدَّم الأسنان والأضراس عند الضَّحِك.<br>قال ابنُ الأعرابىّ: الضّاحك من السّ"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَحِكَ</b> , (S, MA, O, Msb, K, &amp;c.,) and some say <span class=\"ar\">ضِحِكْتُ</span>, with kesr to the <span class=\"ar\">ض</span>, (TA, as from the K, [but not in the CK nor in my MS. copy of the K,]) to agree with the vowel of the <span class=\"ar\">ح</span> because the latter is a faucial letter, and this is a correct dial. var. of which similar instances are mentioned, and <span class=\"ar\">ضَحَكَ</span> also is said to be a well known dial. var. of <span class=\"ar\">ضَحِكَ</span>, (TA,) aor. <b class=\"ar\">ضَحَكَ</b> , (S. O,) inf. n. <span class=\"ar\">ضَحِكٌ</span> and <span class=\"ar\">ضِحْكٌ</span> (S, MA, O, Msb, K, KL) and <span class=\"ar\">ضَحْكٌ</span>, (S, MA, O, K, KL,) the first of which is the superior form, (IDrd, O,) [the second and third being contractions thereof,] and <span class=\"ar\">ضِحِكٌ</span>, (S, O, K, KL,) and if you said <span class=\"ar\">ضَحَكٌ</span> it would be agreeable with analogy, (Az, TA,) <i>He laughed;</i> (MA, KL, PS, TK;) <i>contr. of</i> <span class=\"ar\">بَكَى</span>: (TK:) [see also 6:] <span class=\"ar\">الضَّحِكُ</span> is well known, as meaning <i>the expanding of the face, and displaying of the teeth, by reason of happiness, joy,</i> or <i>gladness;</i> and <span class=\"ar\">التَّبَسُّمُ</span> is the beginning thereof: thus in the Towsheeh and other works: (MF, TA:) and in like manner in the Mufradát [of Er-Rághib]; in which it is added that it is also used as meaning simply <i>the being happy, joyful,</i> or <i>glad:</i> and sometimes as meaning simply <i>the wondering</i> [at a thing]; and this is the meaning intended by him who says that it is peculiar to man: (TA:) [i. e.] <span class=\"ar\">ضَحِكَ</span>, said of a man, signifies also <i>he wondered;</i> syn. <span class=\"ar\">عَجِبَ</span>; (O, K, TA;) with <span class=\"ar\">مِنْ</span> preposed to the object of wonder: (TA:) or <i>he was frightened;</i> or <i>he feared.</i> (K, TA.) You say, <span class=\"ar\">ضَحِكَ مِنْهُ</span> and <span class=\"ar\">بِهِ</span>, both meaning the same, (S, O, Msb,) i. e. <i>He laughed at him; derided him;</i> or <i>ridiculed him:</i> or <i>he wondered at him.</i> (Msb.) And <span class=\"ar\">ضَحِكَ إِلَيْهِ</span> [<i>He behaved laughingly,</i> or <i>cheerfully, towards him</i>]. (IDrd and K in art. <span class=\"ar\">بش</span> [See <span class=\"ar\">بَشَّ لَهُ</span>.]) -b2- Said of an ape, <i>He uttered a cry</i> or <i>cries:</i> (K:) or one says of the ape when he utters a cry or cries, <span class=\"ar\">يَضْحَكُ</span>, (S, TA,) meaning <i>he displays his teeth,</i> or <i>grins.</i> (TA.) -b3- And <span class=\"ar\">ضَحِكَ السَّحَابُ</span> (tropical:) <i>The clouds lightened.</i> (S, O, K, TA.) Hence the usage of the verb in a trad. cited voce <span class=\"ar\">تَحَدَّثَ</span>. (O, TA.) -b4- And <span class=\"ar\">ضَحِكَ الغَدِيرُ</span> i. e. (tropical:) [<i>The pool of water left by a torrent</i>] <i>glistened by reason of its fulness.</i> (TA.) -b5- [And <span class=\"ar\">ضَحِكَ ثَغْرُهُ</span> (assumed tropical:) <i>His front teeth,</i> or <i>his teeth, glistened</i> by reason of his laughing; meaning <i>he laughed so as to show his front teeth,</i> or <i>his teeth.</i>] -b6- And <span class=\"ar\">ضَحِكَ الزَّهْرُ</span> (tropical:) <i>The flowers</i> [<i>looked gay,</i> or] <i>were as though they were laughing.</i> (TA.) And <span class=\"ar\">ضَحِكَتِ الأَرْضُ</span> (tropical:) <i>The earth,</i> or <i>land, put forth its plants,</i> or <i>herbage, and its flowers.</i> (TA.) And <span class=\"ar\">ضَحِكَتِ الرِّيَاضُ عَنِ الأَزْهَارِ</span> (tropical:) <i>The meadows,</i> or <i>gardens, displayed the flowers.</i> (TA.) -b7- And <span class=\"ar\">ضَحِكَتِ النَّخْلَةُ</span> (tropical:) <i>The palm-tree put forth</i> [or <i>disclosed</i>] <i>its</i> <span class=\"ar\">ضَحْك</span>; as also <span class=\"ar\"> <span class=\"ar\">أَضْحَكَت</span></span>; (TA;) [i. e.] <i>the spathe of the palm-tree,</i> (Skr, O, TA,) <i>that covered the</i> <span class=\"ar\">طَلْع</span> [or <i>spadix</i>], (O,) <i>burst open.</i> (Skr, O, TA.) And <span class=\"ar\">ضَحِكَ الطَّلْعُ</span> (tropical:) <i>The</i> <span class=\"ar\">طلع</span> [here app. meaning the <i>spathe of the palm-tree</i>] <i>split,</i> or <i>clave, open;</i> and so <span class=\"ar\">تَبَسَّمَ</span>. (TA.) -b8- And, as some assert, (ISd, TA,) <span class=\"ar\">ضَحِكَتْ</span> signifies also (tropical:) <i>She menstruated;</i> said of a hare; (ISd, Z, O, Msb, TA;) accord. to some, from the <span class=\"ar\">ضَحَّاك</span> [meaning the interior] of the <span class=\"ar\">طَلْعَة</span> [of the palm-tree] when it bursts open; (ISd, TA;) and hence, (K, TA,) said also in this sense of a woman, (O, Msb, K, TA,) accord. to Mujáhid, (O, TA,) and some others, (TA,) in the Kur xi. 74, (O, K, TA,) where some read <span class=\"ar\">فَضَحَكَتْ</span>, which is said to be a well-known dial. var.; (TA;) and likewise, accord. to some, said in this sense of the hyena, (O, TA,) when she sees blood, or as IAar says, when she eats the flesh of men and drinks their blood: (TA:) [it is commonly asserted by the Arabs that] the hare menstruates like women: (Kzw:) but with respect to this meaning as assigned to the verb in the Kur xi. 74, Fr says that he had not heard it from any person deserving of confidence; (O, TA; *) and Zj says that it is nought: both say that the meaning there is, <i>she laughed by reason of happiness:</i> (TA:) and some say that there is an inversion in this case, what is meant being <span class=\"ar\">فَبَشَّرْنَاهَا بِإِسْحٰقَ</span> <span class=\"ar\">فَضَحِكَتْ</span>: (Fr, O, TA:) or the meaning is, <i>she wondered;</i> so says I'Ab; and so Er-Rághib, who adds that it is confirmed by her saying, “ shall I bring forth a child when I am an old woman, and this my husband is an old man? verily this is indeed a wonderful thing: ” and that <span class=\"ar\">فَحَاضَتْ</span> which is inserted by some of the expositors after <span class=\"ar\">فَضَحِكَتْ</span> is not an explanation of this expression, as some of them have imagined it to be, but is the mention of [a fact which was] a sign that the announcement was not that of an event improbable: or the meaning is, <i>she was frightened;</i> so says Fr.: (TA:) and with respect to the meaning of this verb when said of the hyena, mentioned above, it is rejected by AHát and others: (TA:) IDrd says, on the authority of AHát, respecting the following verse of TaäbbataSharrà, <span class=\"ar\">تَضْحَكُ الضَّبْعُ لِقَتْلَى هُذَيْلٍ</span> <span class=\"ar\">وَتَرَى الذِّئْبَ لَهَا يَسْتَهِلُّ</span> that the meaning is (assumed tropical:) <i>The hyena displays her teeth,</i> or <i>grins, on account of the slain</i> [<i>of Hudheyl</i>], when she sees them, like as they say of the ass when he plucks out the [plant called] <span class=\"ar\">صِلِّيَانَة</span>; (O, TA;) or, as others say, (assumed tropical:) <i>the hyena snarls, displaying her teeth; and sees the wolf raising his voice in calling</i> the [other] wolves <i>to them,</i> i. e. to the slain: (O, TA:*) Abu-l-' Abbás says that the meaning is, (assumed tropical:) <i>the hyena displays her teeth,</i> because the wolf contends with her over the slain: and some say that the poet means, (assumed tropical:) <i>the hyena rejoices because of the slain.</i> (TA.) -b9- One says also, <span class=\"ar\">ضَحِكَتِ</span> <span class=\"ar\">السَّمُرَةُ</span>, meaning (assumed tropical:) <i>The</i> <span class=\"ar\">سمرة</span> [or <i>gum-acacia-tree</i>] <i>flowed with its gum:</i> from <span class=\"ar\">ضحكت</span> meaning “ she menstruated. ” (Bd in xi. 74.)</p><p><b>3.</b> <b class=\"ar\">مُضَاحَكَةٌ</b> [inf. n. of <span class=\"ar\">ضاحكهُ</span>] signifies [The <i>contending,</i> or <i>vying, in laughing, with another;</i> or the <i>laughing with another;</i> or] the <i>laughing together.</i> (KL.) -b2- [Hence,] one says, <span class=\"ar\">النَّوْرُ</span> <span class=\"ar\">يُضَاحِكُ الشَّمْسَ</span> (assumed tropical:) [<i>The flowers vie in brightness with the sun</i>]. (TA.) -b3- And <span class=\"ar\">إِنَّ رَأْيَكَ لَيُضَاحِكُ</span> <span class=\"ar\">المُشْكِلَاتِ</span> (tropical:) [<i>Verily thy judgment makes sport with ambiguities</i>]; said to him to whom confused and dubious things are apparent and known. (TA.)</p><p><b>4.</b> <b class=\"ar\">اضحكهُ</b> , (S, O, K,) inf. n. <span class=\"ar\">إِضْحَاكٌ</span>, (KL,) said of God, (S, O,) or of a man, (K,) <i>He made him,</i> or <i>caused him, to laugh.</i> (S, * O, * K, * KL, PS.) -b2- [Hence,] <span class=\"ar\">اضحك الضَّبُعَ</span>, said of blood, (TA,) or of the sword, (O, TA,) (assumed tropical:) [<i>It made the hyena to display her teeth;</i> or <i>to snarl, displaying her teeth:</i> or <i>to rejoice:</i> (see 1, latter part:) but explained as meaning] (tropical:) <i>it made the hyena to menstruate.</i> (TA.) -b3- And <span class=\"ar\">اضحك الحَوْضَ</span> (tropical:) <i>He filled the wateringtrough so that it overflowed:</i> (O, TA:) its glistening being likened to laughing. (TA.) -b4- See also 1, near the middle of the paragraph.</p><p><b>5.</b> <b class=\"ar\">تَضَحَّكَ</b> see the next paragraph.</p><p><b>6.</b> <b class=\"ar\">تضاحك</b> and <span class=\"ar\"> <span class=\"ar\">تضحّك</span></span> [are both mentioned in the K and TA as though <i>syn. with each other and with</i> <span class=\"ar\">ضَحِكَ</span>: and accord. to the KL, the former signifies <i>He laughed:</i> but accord. to the TK, the latter signifies <i>he manifested laughing:</i> or] the former is <i>syn. with</i> <span class=\"ar\"> <span class=\"ar\">استضحك</span></span> [app. as meaning <i>he affected to laugh,</i> or <i>laughing:</i> or, more exactly, agreeably with analogy, like the contr. <span class=\"ar\">تَبَاكَى</span> and <span class=\"ar\">اِسْتَبْكَى</span>, the former signifies thus; and the latter, <i>he desired to laugh</i>]. (S.) -b2- And you say also, <span class=\"ar\">هُمْ يَتَضَاحَكُونَ</span> [meaning <i>They laugh together, one with another</i>]. (K.)</p><p><b>10.</b> <b class=\"ar\">إِسْتَضْحَكَ</b> see the next preceding paragraph.</p><p><b class=\"ar\">ضَحْكٌ</b> [originally an inf. n., a contraction of <span class=\"ar\">ضَحِكٌ</span>,] The <i>appearance,</i> or <i>appearing, of the central incisors</i> [or <i>of the front teeth</i>] <i>by reason of happiness, joy,</i> or <i>gladness.</i> (TA.) -b2- And hence, (TA,) <i>Wonder.</i> (K, TA.) -A2- [As an epithet,] A man <i>whose teeth are white.</i> (As, O, TA.) -A3- [And as a subst., properly so termed,] <i>White front teeth.</i> (As, O, K.) -b2- And (assumed tropical:) <i>Honey:</i> (K:) or <i>white honey;</i> (Ibn-Es-Seed, TA;) likened to the front teeth because of its intense whiteness: (AA, O, TA:) or <i>honey in its comb;</i> syn. <span class=\"ar\">شَهْدٌ</span>. (K.) -b3- And, (O, K,) some say, (O,) (assumed tropical:) <i>Fresh butter.</i> (O, K.) -b4- And (assumed tropical:) <i>Snow.</i> (O, K.) -b5- And (assumed tropical:) <i>Blossoms,</i> or <i>flowers,</i> or <i>white blossoms</i> or <i>flowers;</i> syn. <span class=\"ar\">نَوْرٌ</span>: (O, and so in copies of the K:) or <i>light;</i> syn. <span class=\"ar\">نُورٌ</span>. (So in a copy of the K.) -b6- And (assumed tropical:) The <span class=\"ar\">طَلْع</span> [or <i>spadix</i>] <i>of the palm-tree when its envelope bursts open from it;</i> (S, * O, * K;) in the dial. of Belhárith Ibn-Kaab: (O:) accord. to Th, <i>what is in the interior of the</i> <span class=\"ar\">طَلْعَة</span> [here meaning <i>spathe of the palm-tree</i>]: as AA says, the <span class=\"ar\">وَلِيعَة</span>, or <span class=\"ar\">وَلِيع</span> [thus differently written in two different places in the TA,] <i>of the</i> <span class=\"ar\">طَلْع</span> [or <i>spathe of the palm-tree</i>], <i>which is eaten;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَحَّاكٌ</span></span>. (TA.) -b7- And (assumed tropical:) The <i>middle of a road;</i> (K, TA;) and so, accord. to the K, <span class=\"ar\"> <span class=\"ar\">ضَحَّاكٌ</span></span>; but, correctly, this should have been there mentioned as syn. with <span class=\"ar\">ضَحْكٌ</span> in the sense next preceding. (TA.)</p><p><b class=\"ar\">ضَحْكَةٌ</b> <i>A single act of</i> <span class=\"ar\">ضَحِك</span> [or <i>laughing;</i> i. e. <i>a laugh</i>]. (S, O.) -A2- [The pl.] <span class=\"ar\">ضَحْكَاتٌ</span> signifies (tropical:) The <i>best</i> of everything: and <span class=\"ar\">ضَحْكَاتُ القُلُوبِ</span>, <i>the best</i> of possessions, or wealth, and of children: so says Aboo-Sa'eed. (TA.)</p><p><b class=\"ar\">ضُحْكَةٌ</b> A thing, (Lth, TA,) or a man, (S, O. TA,) <i>that is laughed at,</i> or <i>ridiculed;</i> i. e. <span class=\"ar\">يُضْحَكُ</span> <span class=\"ar\">مِنْهُ</span>: (S, O, K, TA:) an epithet importing more discommendation than <span class=\"ar\">ضُحَكَةٌ</span>. (K.) -b2- See also <span class=\"ar\">مَضْحَكٌ</span>.</p><p><b class=\"ar\">ضُحَكَةٌ</b> , (S, O, Msb, K,) an epithet importing discommendation, (K,) and <span class=\"ar\"> <span class=\"ar\">ضُحُكَّةٌ</span></span>, (Ibn-'Abbád, O, K,) and <span class=\"ar\"> <span class=\"ar\">ضَحَّاكٌ</span></span>, (Msb, K,) an epithet importing commendation, (TA, [but the contr. is implied, or rather plainly indicated, in the K,]) and <span class=\"ar\"> <span class=\"ar\">ضَحُوكٌ</span></span>, (K,) and <span class=\"ar\"> <span class=\"ar\">مِضْحَاكٌ</span></span>, (S, O, K,) which last is [also] applied to a woman, (S, O,) One <i>who laughs much</i> (<span class=\"ar\">كَثِيرُ الضَّحِكِ</span>). (S, O, Msb, K.)</p><p><b class=\"ar\">ضُحُكَّةٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ضَحُوكٌ</b> : see <span class=\"ar\">ضُحَكَةٌ</span>. -b2- [Also] A man <i>cheerful in countenance.</i> (O.) -b3- And (assumed tropical:) <i>A wide road:</i> (S, O:) or (tropical:) <i>a distinct, an apparent,</i> or <i>a conspicuous, road;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَحَّاكٌ</span></span>: pl. of the former (in this sense, TA) <span class=\"ar\">ضُحْكٌ</span>. (K, TA.)</p><p><b class=\"ar\">ضَحَّاكٌ</b> : see <span class=\"ar\">ضُحَكَةٌ</span>: -b2- and see <span class=\"ar\">ضَحْكٌ</span>, last two sentences: -b3- and <span class=\"ar\">ضَحُوكٌ</span>.</p><p><b class=\"ar\">ضَاحِكٌ</b> <i>Laughing;</i> [&amp;c.;] (KL;) act. part. n. of <span class=\"ar\">ضَحِكَ</span>. (Msb, K.) -b2- Also applied to clouds (<span class=\"ar\">سَحَاب</span>), meaning (tropical:) <i>Appearing,</i> or <i>extending sideways, in the horizon, and lightening.</i> (S, O, TA.) -b3- [And to the tooth (<span class=\"ar\">السِّنّ</span>, used as a gen. n.): thus in the phrase <span class=\"ar\">ضَاحِكَ السِّنِّ</span>, meaning (assumed tropical:) <i>Laughingly, so as to display the teeth.</i>] -b4- See also <span class=\"ar\">ضَاحِكَةٌ</span>. -b5- Also, [or perhaps <span class=\"ar\">حَجَرٌ ضَاحِكٌ</span>,] (tropical:) <i>Very white stone appearing in a mountain</i> (IDrd, O, TA.) <i>of any colour, as though laughing.</i> (IDrd, O, TA.) -b6- One says also <span class=\"ar\">رَأْىٌ ضَاحِكٌ</span>, meaning (tropical:) <i>Judgment that is plain,</i> or <i>perspicuous,</i> (TA,) <i>not confused</i> or <i>dubious.</i> (O, TA.) -b7- And, [using <span class=\"ar\">ضاحك</span> as a gen. n.,] <span class=\"ar\">مَا أَكْثَرَ ضَاحِكَ نَخْلِكُمْ</span> (tropical:) [<i>How numerous are the bursting spathes of your palm-trees!</i>]. (TA.) -b8- [And an instance of <span class=\"ar\">ضَاحِكٌ</span> applied to a woman, without <span class=\"ar\">ة</span>, meaning (assumed tropical:) <i>Menstruating,</i> is cited by Bd, in xi. 74.]</p><p><b class=\"ar\">ضَاحِكَةٌ</b> , (S, O, K,) or <span class=\"ar\"> <span class=\"ar\">ضَاحِكٌ</span></span>, (Msb,) or both, (Mgh,) (tropical:) The <i>tooth next behind the</i> <span class=\"ar\">نَاب</span> [or <i>canine tooth</i>]; (Mgh, Msb;) [i. e. the <i>anterior bicuspid;</i>] <i>any one of the four teeth that are between the</i> <span class=\"ar\">أَنْيَاب</span> <i>and the</i> <span class=\"ar\">أَضْرَاس</span>: (S, O, K:) or <i>any one of the teeth that are in front of the</i> <span class=\"ar\">أَضْرَاس</span> <i>that appear on the occasion of laughing:</i> (K:) pl. <span class=\"ar\">ضَوَاحِكُ</span>. (S, Mgh, O, Msb, K.) <span class=\"ar\">أَوضَحُوا بِضَاحِكَةٍ</span> (O, TA,) a phrase occurring in a trad., (O,) means (assumed tropical:) <i>They smiled.</i> (TA.)</p><p><b class=\"ar\">أُضْحُوكَةٌ</b> [<i>A laughable thing;</i>] <i>a thing at which one laughs:</i> (O, K, TA:) and <span class=\"ar\"> <span class=\"ar\">مَضْحَكَةٌ</span></span> signifies [in like manner <i>a cause of laughter;</i>] <i>a thing at which one laughs,</i> or <i>which one ridicules:</i> pl. of the former <span class=\"ar\">أَضَاحِيكُ</span>. (TA.) [See also <span class=\"ar\">مُضْحِكَاتٌ</span>.]</p><p>[ <b class=\"ar\">مَضْحَكٌ</b> lit. <i>A place of laughing:</i> the <i>front teeth;</i> because they appear in laughing; like <span class=\"ar\">مَبْسِمٌ</span>: pl. <span class=\"ar\">مَضَاحِكُ</span>.] One says, <span class=\"ar\">بَدَتْ مَضَاحِكُهُ</span> and <span class=\"ar\"> <span class=\"ar\">ضُحْكَتُهُ</span></span> and [in like manner] <span class=\"ar\">مَبَاسِمُهُ</span> (assumed tropical:) [<i>His front teeth appeared,</i> by his laughing]. (TA.)</p><p><b class=\"ar\">مَضْحَكَةٌ</b> : see <span class=\"ar\">أُضْحُوكَةٌ</span>.</p><p><b class=\"ar\">مُضْحِكَاتٌ</b> [pl. of <span class=\"ar\">مُضْحِكَةٌ</span>] <i>i. q.</i> <span class=\"ar\">نَوَادِرُ</span> [as meaning <i>Extraordinary things</i> or <i>sayings,</i> particularly <i>such as cause laughter:</i> see also <span class=\"ar\">أُضْحُوكَةٌ</span>]. (TA.)</p><p><b class=\"ar\">مِضْحَاكٌ</b> : see <span class=\"ar\">ضُحَكَةٌ</span>.</p>"},"ضحو":{"mf":"الضُّحَى: انبساطُ الشمس وامتداد النهار، وسمّي الوقت به. قال الله عزّ وجل: وَالشَّمْسِ وَضُحاها<br>[الشمس/ ١]، إِلَّا عَشِيَّةً أَوْ ضُحاها [النازعات/ ٤٦]، وَالضُّحى وَاللَّيْلِ [الضحى/ ١- ٢]، وَأَخْرَجَ ضُحاها [النازعات/ ٢٩]، وَأَنْ يُحْشَرَ النَّاسُ ضُحًى<br>[طه/ ٥٩]، وضَحَى يَضْحَى: تَعَرَّضَ للشمس.<br>قال: وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى<br>[طه/ ١١٩]، أي: لك أن تتصوّن من حرّ الشمس، وتَضَحَّى: أَكَلَ ضُحًى، كقولك: تغدّى، والضَّحَاءُ والغداءُ لطعامهما، وضَاحِيَةُ كلِّ شيءٍ:<br>ناحيتُهُ البارزةُ، وقيل للسماء: الضَّوَاحِي وليلة إِضْحِيَانَةٌ، وضَحْيَاءُ: مُضيئةٌ إضاءةَ الضُّحَى.<br>والأُضْحِيَّةُ جمعُها أَضَاحِي وقيل: ضَحِيَّةٌ<br><br>وضَحَايَا، وأَضْحَاةٌ وأَضْحًى، وتسميتها بذلك في الشّرع لقوله عليه السلام: <strong>«من ذبح قبل صلاتنا هذه فليُعِدْ»</strong> <strong>«١»</strong>.","mq":[["بروز الشي"],"الضاد والحاء والحرف المعتل أصلٌ صحيح واحد يدلُّ على بُروز الشئ. فالضَّحَاء: امتداد النَّهار، وذلك هو الوقت البارز المنكشف.<br>ثمَّ يقال للطعام الذى يُؤكل فى ذلك الوقت ضَحاء. قال:<br>وطال السنام على جبلة.<br>تَرَى الثَّوْرَ يمشى راجعاً مِنْ ضَحائه (١)<br>ويقال ضَحِى الرجل يَضْحَى، إذا تعرَّضَ للشَّمس، وضَحَى مثل"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَحَا الطَّرِيقُ</b> , (S, K,) aor. <span class=\"ar\">يَضْحُو</span>, (S,) inf. n. <span class=\"ar\">ضَحْوٌ</span>, (S, and so in the CK,) or <span class=\"ar\">ضُحُوٌّ</span>, (so in other copies of the K and in the TA,) like <span class=\"ar\">عُلُوٌّ</span>, thus accord. to ISd and IKtt, (TA,) and <span class=\"ar\">ضُحِىٌّ</span>, (TA as from the K, [but not in the CK nor in my MS. copy of the K,]) <i>The road appeared,</i> or <i>became apparent,</i> (S, K,) to a person: so says AZ: (S:) [and so, app., signifies <span class=\"ar\">ضَحِىَ</span>, aor. <span class=\"ar\">يَضْحَى</span>; for] As says, <span class=\"ar\">يُسْتَحَبُّ مِنَ الفَرَسِ أَنْ</span> <span class=\"ar\">يَضْحَى عِجَانُهُ</span> i. e. [<i>It is approved as a quality of the horse</i>] <i>that his</i> <span class=\"ar\">عجان</span> [q. v., a word variously expl.,] <i>appear.</i> (S, TA.) -b2- <span class=\"ar\">ضَحِيَتِ</span> <span class=\"ar\">اللّيْلَةُ</span> <i>The night was,</i> or <i>became, cloudless.</i> (TA.) -b3- <span class=\"ar\">ضَحِىَ الفَرَسَ</span> <i>The horse was,</i> or <i>became, white.</i> (TA.) -b4- <span class=\"ar\">ظِلُّهُ ضَحَا</span> (tropical:) <i>He died:</i> (K, TA:) it [properly] means <i>his shade,</i> or <i>shadow, became sun:</i> and when a man's shade, or shadow, becomes sun, he himself becomes nought. (IAmb, TA.) -b5- And <span class=\"ar\">ضَحَا</span> and <span class=\"ar\">ضَحِىَ</span>, aor. of each <span class=\"ar\">يَضْحَى</span>, inf. n. <span class=\"ar\">ضَحْوٌ</span>, (K, TA,) or, accord. to the M, <span class=\"ar\">ضُحُوٌّ</span>, (TA,) and <span class=\"ar\">ضُحِىٌّ</span>, <i>He,</i> or <i>it, was smitten by the sun;</i> or <i>the sun came,</i> or <i>fell, upon him,</i> or <i>it:</i> (K, TA:) or <span class=\"ar\">ضَحِىَ</span>, aor. <span class=\"ar\">يَضْحَى</span>, inf. n. <span class=\"ar\">ضَحًا</span>; and <span class=\"ar\">ضَحَا</span>, aor. <span class=\"ar\">يَضْحُو</span>, inf. n. <span class=\"ar\">ضَحْوٌ</span> and <span class=\"ar\">ضُحُوٌّ</span>, <i>he,</i> or <i>it, was smitten by the heat of the sun.</i> (Ham p. 625.) Hence, in the Kur [xx. 117], <span class=\"ar\">لَا تَظْمَأُ فِيهَا وَلَا تَضْحَى</span> [<i>Thou shalt not thirst. therein nor shalt thou be smitten by the sun</i>]; i. e., thou shalt be preserved from the heat of the sun. (TA.) -b6- And <span class=\"ar\">ضَحَا</span>, inf. n. <span class=\"ar\">ضَحْوٌ</span> and <span class=\"ar\">ضُحُوٌّ</span> and <span class=\"ar\">ضُحِىٌّ</span>, <i>He went forth to the sunshine;</i> (K;) as also <span class=\"ar\"> <span class=\"ar\">استضحى</span>لِلشَّمْسِ</span>; (TA;) [and app. <span class=\"ar\"> <span class=\"ar\">تضحّى</span></span> also; see Har p. 296, where, for <span class=\"ar\">النزول</span>, in <span class=\"ar\">النزول للشمس</span> as an explanation of <span class=\"ar\">التَّضَحِّى</span>, I think we should read <span class=\"ar\">البُرُوزُ</span>:] or <span class=\"ar\">ضَحِيتُ لِلشَّمْسِ</span>, inf. n. <span class=\"ar\">ضَحَآءٌ</span>; and <span class=\"ar\">ضَحَيْتُ</span> also; aor. of each <span class=\"ar\">أَضْحَى</span>; <i>I went forth to the sunshine.</i> (S.) <span class=\"ar\">أَضْحِ</span> [the imperative of <span class=\"ar\"> <span class=\"ar\">أَضْحَى</span></span>] occurs in a trad., accord. to the relaters thereof: but As says that it is [correctly] <span class=\"ar\">اِضْحَ</span>, with kesr to the <span class=\"ar\">ا</span> and fet-h to the <span class=\"ar\">ح</span>; from <span class=\"ar\">ضَحِيتُ</span>; being a command to go forth to the sunshine. (S.) -b7- And <span class=\"ar\">ضَحِىَ</span>, (S, K,) inf. n. <span class=\"ar\">ضَحًى</span> [or <span class=\"ar\">ضَحًا</span>], <i>He</i> (a man, S) <i>sweated.</i> (S, K.)</p><p><b>2.</b> <b class=\"ar\">ضَحَّيْنَاهُمْ</b> is like <span class=\"ar\">صَبَّحْنَاهُمْ</span> [i. e. it signifies <i>We came to them in the time of the morning called</i> <span class=\"ar\">الضُّحَى</span>]: (TA:) and <span class=\"ar\"> <span class=\"ar\">ضاحاهُ</span></span>, (K, TA,) inf. n. <span class=\"ar\">مُضَاحَاةٌ</span>, is similar to <span class=\"ar\">غَادَاهُ</span> and <span class=\"ar\">رَاوَحَهُ</span>, meaning, (TA,) <i>He came to him in the time called</i> <span class=\"ar\">الضُّحَى</span>. (K, TA.) -b2- <span class=\"ar\">ضحّى الغَنَمَ</span> <i>He pastured the sheep,</i> or <i>goats, in the time called</i> <span class=\"ar\">الضُّحَى</span>; (S, K, TA;) and in like manner, <span class=\"ar\">الإِبِلَ</span> <i>the camels.</i> (TA.) And <span class=\"ar\">ضَحَّيْتُ الإِبِلَ عَنِ الوِرْدِ</span> <i>I pastured the camels with the</i> [<i>morning-pasture called</i>] <span class=\"ar\"><span class=\"ar\">ضَحَآء</span> </span>, <i>so that they might come to the water having satisfied themselves with food:</i> and in like manner, <span class=\"ar\">عَشَّيْتُهَا عَنْهُ</span> “ I pastured them with the [evening-pasture called] <span class=\"ar\">عَشَآء</span>, ” &amp;c. (A, TA.) -b3- [Hence,] <span class=\"ar\">ضَحَّيْتُهُ</span>, inf. n. <span class=\"ar\">تَضْحِيَةٌ</span>, <i>I fed him in the time called</i> <span class=\"ar\">الضُّحَى</span>: (K, TA:) or <i>I fed him with the</i> [<i>morning-meal called</i>] <span class=\"ar\">غَدَآء</span>, <i>at any time</i> [<i>of the morning</i>]; but more commonly known as meaning, <i>in the time called</i> <span class=\"ar\">الضُّحَى</span>: and the verb primarily relates to camels [and sheep or goats]: or <span class=\"ar\">ضحّى قَوْمَهُ</span> means <i>he fed his people,</i> or <i>party, with the</i> [<i>morning-meal called</i>] <span class=\"ar\">غَدَآء</span>; or <i>he invited them</i> [<i>thereto,</i> i. e.] <i>to his</i> <span class=\"ar\">ضَحَآء</span>. (TA.) -b4- IAth says, when the Arabs, in their journeying, or migrating, passed by a piece of land in which was herbage, one of them said, <span class=\"ar\">أَلَا ضَحُّوا</span> <span class=\"ar\">رُوَيْدًا</span>, meaning [<i>Now</i>] <i>be ye gentle with the camels</i> <span class=\"ar\">حَتَّى <span class=\"ar\">نَتَضَحَّى</span></span> i. e. <i>in order that we may obtain of this herbage;</i> then <span class=\"ar\">التَّضْحِيَةُ</span> was applied to mean <i>the being gentle in order that the camels may reach the place of alighting</i> [app. <i>in the morning</i>] <i>having satisfied themselves with food:</i> and then <span class=\"ar\"> <span class=\"ar\">تَضَحَّى</span></span> was said of anyone as meaning <i>he ate in the time called</i> [<span class=\"ar\">الضُّحَى</span> or] <span class=\"ar\">الضَّحَآء</span>. (TA.) One says, <span class=\"ar\">ضَحَّيْتُ عَنِ الشَّىْءِ</span> (assumed tropical:) <i>I was gentle,</i> or <i>I acted gently, with the thing.</i> (S.) And <span class=\"ar\">ضحّى عَنِ الأَمْرِ</span> (tropical:) <i>He acted gently,</i> or <i>deliberately, in the affair:</i> and so <span class=\"ar\">عَشَّى عَنْهُ</span>. (A, TA.) And <span class=\"ar\">ضَحِّ رُوَيْدًا</span>, (S, A, TA,) a prov., (A, TA,) meaning (tropical:) <i>Hasten thou not;</i> (S, TA;) from <span class=\"ar\">تَضْحِيَةُ الإِبِلِ عَنِ الوِرْدِ</span>: [see the third sentence of this paragraph:] or meaning <i>be thou patient a little while:</i> (TA:) or the meaning is, <i>slaughter thou,</i> or <i>sacrifice thou,</i> [<i>deliberately, leisurely,</i> or] <i>without haste:</i> (Meyd:) [for] -b5- <span class=\"ar\">ضحّى</span>, inf. n. <span class=\"ar\">تَضْحيَةٌ</span>, signifies [also] <i>He slaughtered,</i> or <i>sacrificed, the</i> [<i>victim termed</i>] <span class=\"ar\">أُضْحِيَّة</span>, <i>in the time called</i> <span class=\"ar\">الضُّحَى</span>: and hence, by reason of frequency of usage, <i>he did so in any time of what are termed</i> <span class=\"ar\">أَيَّامُ التَّشْرِيقِ</span>: (Msb:) and <span class=\"ar\">ضحّى</span> <span class=\"ar\">بِشَاةٍ</span>, (S, Mgh, Msb, K,) or <span class=\"ar\">بِكَبْشٍ أَوْ غَيْرِهِ</span>, (Mgh,) <i>he slaughtered,</i> or <i>sacrificed, a sheep</i> or <i>goat,</i> (S, Msb, K,) or <i>a ram or other</i> [victim], (Mgh,) <i>in the time called</i> <span class=\"ar\">الضُّحَى</span> (Mgh, K) <i>of the day called</i> <span class=\"ar\">يَوْمُ الأَضْحَى</span>; and afterwards said of him who has done so [<i>at any time, even</i>] <i>in the last part of the</i> [<i>said</i>] <i>day.</i> (Mgh.) -A2- See also 4. -A3- And see 5.</p><p><b>3.</b> <b class=\"ar\">ضاحت البِلَدُ</b> <i>The countries,</i> or <i>lands, became exposed to the sun, and their herbage consequently dried up.</i> (TA.) -A2- <span class=\"ar\">ضاحاهُ</span>: see 2, first sentence.</p><p><b>4.</b> <b class=\"ar\">اضحى</b> <i>He</i> (a man, TA) <i>entered upon the time of morning called</i> <span class=\"ar\">الضُّحَى</span>, (K, * TA,) or <i>the time called</i> <span class=\"ar\">الضَّحْوَة</span>, (TA,) [or <i>the time called</i> <span class=\"ar\">الضَّحَآء</span>, for] you say, <span class=\"ar\">أَقَمْتُ بِالمَكَانِ حَتَّى أَضْحَيْتُ</span>, from <span class=\"ar\">الضَّحَآءُ</span> [and therefore meaning <i>I remained in the place until I entered upon the time called</i> <span class=\"ar\">الضَّحَآء</span>], like as you say <span class=\"ar\">أَصْبَحْتُ</span> from <span class=\"ar\">الصَّبَاحُ</span>. (S, TA.) Hence the saying of 'Omar, <span class=\"ar\">أَضْحُوا</span> <span class=\"ar\">لِصَلَاةِ الضُّحَى</span>, (S,) or <span class=\"ar\">بِصَلَاةِ الضُّحَى</span>, (TA,) i. e. <i>Perform ye the prayer of the time called</i> <span class=\"ar\">الضحى</span> <i>at its</i> [<i>proper</i>] <i>time:</i> do not delay it until the time called <span class=\"ar\">الضَّحَآء</span> has become advanced: (TA:) or do not perform that prayer when the time called <span class=\"ar\">الضُّحَى</span> has become advanced. (S.) -b2- And you say, <span class=\"ar\">اضحى فُلَانٌ يَفْعَلُ كَذَا</span>, (S, M, K,) like as you say <span class=\"ar\">ظَلَّ يفعل كذا</span>; (S;) meaning <i>Such a one became occupied,</i> or <i>engaged, in the time called</i> <span class=\"ar\">الضُّحَى</span> <i>in doing such a thing:</i> (M, K, TA:) or <i>did such a thing in the first part of the day,</i> (IKtt, TA.) -b3- [This phrase often means also <i>Such a one became occupied,</i> or <i>engaged, in doing such a thing; betook, set,</i> or <i>applied, himself to doing such a thing; set about,</i> or <i>commenced, doing such a thing;</i> or <i>began to do such a thing;</i> like <span class=\"ar\">أَصْبَحَ</span> and <span class=\"ar\">ظَلَّ</span> &amp;c. And, like these verbs, <span class=\"ar\">اضحى</span> followed by an aor., or by a part. n. in the accus. case, often requires to be rendered simply <i>He,</i> or <i>it, became:</i> see an ex. in a verse cited voce <span class=\"ar\">دَفِئٌ</span>.] -b4- <span class=\"ar\">اضحى</span> also signifies <i>He performed the supererogatory act of prayer</i> (<span class=\"ar\">النَّافِلَة</span>) <i>in the time called</i> <span class=\"ar\">الضُّحَى</span>. (TA.) -b5- See also 1, last sentence but one. -b6- One says also, <span class=\"ar\">اضحى عَنِ الأَمْرِ</span>, meaning (tropical:) <i>He withdrew himself far from the affair.</i> (TA. [See also another meaning of this phrase in what follows.]) And <span class=\"ar\">القَطا يُضْحِى عَنِ المَآءِ</span> (tropical:) <i>The birds called</i> <span class=\"ar\">قطا</span> <i>go far from water.</i> (TA.) -A2- <span class=\"ar\">اضحى الشَّىْءَ</span> <i>He made apparent, showed,</i> or <i>revealed, the thing.</i> (K, TA.) And <span class=\"ar\"> <span class=\"ar\">ضحّى</span>عَنِ الأَمْرِ</span> <i>He made the affair,</i> or <i>case, apparent,</i> or <i>manifest:</i> and [so <span class=\"ar\">اضحى عَنْهُ</span>, for] one says, <span class=\"ar\">أَضْحِ لِى عَنْ أَمْرِكَ</span>, with fet-h to the <span class=\"ar\">ء</span>, meaning <i>Make manifest to me thy affair,</i> or <i>case:</i> so in the M. (TA.) -b2- <span class=\"ar\">لَا أَضْحَى</span> <span class=\"ar\">ٱللّٰهُ لَنَا ظِلَّكَ</span> is a deprecatory phrase [lit. <i>May God not cause thy shadow to become sun to us:</i> meaning (assumed tropical:) <i>may God not deprive us of thee by death:</i> (see <span class=\"ar\">ضَحَا ظِلُّهُ</span>:) or it may be similar in meaning to the phrase here following]. (TA.) <span class=\"ar\">لَا تُضْحِنَا</span> <span class=\"ar\">عَنْ ظِلِّكَ</span> [lit. <i>Make us not to go forth into the sun from thy shadow</i>] means (assumed tropical:) <i>withdraw not from us the shadow of thy compassion:</i> the verb being made trans. by means of <span class=\"ar\">عن</span> because the phrase implies the meaning of <span class=\"ar\">لَا تُخْرِجْنَا مِنْهُ</span>: and <span class=\"ar\">ظلّ</span> being here used metaphorically. (Har p. 4.)</p><p><b>5.</b> <b class=\"ar\">تَضحّى</b> : see 1, latter half. -b2- And see 2, in two places. It [generally] means <i>He ate in the time of morning called</i> <span class=\"ar\">الضُّحَى</span>: (K:) or <i>he ate the</i> [<i>morning-meal called</i>] <span class=\"ar\">غَدَآء</span>; syn. <span class=\"ar\">تَغَدَّى</span>: (S, TA:) and <span class=\"ar\"> <span class=\"ar\">ضحّى</span></span> also has the former [or the latter] meaning. (ISd, TA.)</p><p><b>10.</b> <b class=\"ar\">إِسْتَضْحَوَ</b> see 1, latter half.</p><p><b class=\"ar\">ضَحْوٌ</b> : see the next paragraph.</p><p><b class=\"ar\">ضُحًى</b> , also written <span class=\"ar\">ضُحًا</span>, held by some to be of the measure <span class=\"ar\">فُعَلٌ</span>, and by others to be [originally <span class=\"ar\">ضُحْوًى</span> i. e.] of the measure <span class=\"ar\">فُعْلًى</span>, of the former measure accord. to Mbr, and of the latter accord. to Th, (MF, TA,) [The <i>early part of the forenoon, after sunrise:</i> accord. to some, <i>when the sun is yet low:</i> accord. to others, <i>when the sun is somewhat high:</i>] <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">ضَحْوَةٌ</span></span>, accord. to most authorities: (MF, TA, and so in one place in the K:) or this latter signifies the <i>period</i> of the day <i>after sunrise:</i> (S:) or this signifies the <i>advanced state of the day</i> (<span class=\"ar\">اِرْتِفَاعُ النَّهَارِ</span> [which is said by the doctors of the law in the present day to mean <i>when the sun has risen the measure of a</i> <span class=\"ar\">رُمْح</span>, q. v., or <i>more</i>]); as also <span class=\"ar\"> <span class=\"ar\">ضَحْوٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَحِيَّةٌ</span></span>: (K:) and the <span class=\"ar\">ضُحَى</span> is <i>after the</i> <span class=\"ar\">ضَحْوَة</span> (S, K) <i>a little,</i> (K,) <i>when the sun shines brightly:</i> (S:) or <i>from sunrise to the time when the day is advanced and very white:</i> thus in the M: (TA:) or it is the <i>spreading of the sun</i> [<i>upon the earth</i>], and the <i>extending of the day:</i> and the <i>time</i> [<i>thereof</i>] is thus named: (Er-Rághib, TA:) or <span class=\"ar\">ضُحًى</span> is pl. of <span class=\"ar\"> <span class=\"ar\">ضَحْوَةٌ</span></span>, like as <span class=\"ar\">قُرًى</span> is of <span class=\"ar\">قَرْيَةٌ</span>; and its sing. is like <span class=\"ar\"> <span class=\"ar\">ضَحَآءٌ</span></span>, which means the <i>extending of the day,</i> and is of the masc. gender, as though a name of the <i>time</i> [<i>thereof</i>]: then <span class=\"ar\">ضُحًى</span> became used as a sing., and the <i>time</i> was thus called: (Msb:) it is fem. and masc.: (S, K: *) he who makes it fem. holds it to be pl. of <span class=\"ar\"> <span class=\"ar\">ضَحْوَةٌ</span></span>; and he who makes it masc. holds it to be [a sing.] noun of the measure <span class=\"ar\">فُعَلٌ</span>, like <span class=\"ar\">صُرَدٌ</span> and <span class=\"ar\">نُغَرٌ</span>: (S:) its dim. is ↓<span class=\"ar\">ضُحَىٌّ</span>, without <span class=\"ar\">ة</span>; (Fr, Msb, K;) for they disapproved the affixing the <span class=\"ar\">ة</span> lest it should be confounded with the dim. of <span class=\"ar\">ضَحْوَةٌ</span>. (Fr, Msb.) Using it as an adv. noun, you say, <span class=\"ar\">لَقِيتُهُ ضُحَى</span>, when you mean [<i>I met him</i>] <i>in the</i> <span class=\"ar\">ضحى</span> <i>of this day;</i> without tenween. (S, TA.) See also <span class=\"ar\">ضَحْوَةٌ</span>. [See also De Sacy's Chrest. Ar., sec. ed., i. 162-167, respecting the prayer that is performed in the time thus called, i. e. the prayer termed <span class=\"ar\">صَلَاةُ الضُّحَى</span>, mentioned above, voce <span class=\"ar\">أَضْحَى</span>.] -b2- Also The <i>sun:</i> (M, Msb, K:) because of its appearing in the time thus called. (M, TA.) One says, <span class=\"ar\">اِرْتَفَعَتِ الضَّحَى</span>, meaning <i>The sun became high.</i> (Msb.) -b3- And <span class=\"ar\">ضُحَى الشَّمْسِ</span> <i>The light of the sun:</i> thus is expl. xci. 1. of the Kur. (TA.) -b4- <span class=\"ar\">مَا لِكَلَامِهِ</span> <span class=\"ar\">ضُحًى</span> means (assumed tropical:) <i>His speech,</i> or <i>language, has no perspicuity:</i> thus in the M and K: but in the A, <span class=\"ar\">أَنْشَدَنِى شَعْرًا لَيْسَ فِيهِ حَلَاوَةٌ وَلَا <span class=\"ar\">ضَحَآءٌ</span></span> i. e. [<i>He recited to me poetry</i>] <i>in which was no</i> [<i>sweetness nor</i>] <i>plainness of meaning.</i> (TA.)</p><p><b class=\"ar\">ضَحْوَةٌ</b> : see the next preceding paragraph, in three places. You say, <span class=\"ar\">أَتَيْتُكَ ضَحْوَةً</span>, meaning [<i>I came to thee</i>] <i>in a</i> [<i>time called</i>] <span class=\"ar\"><span class=\"ar\">ضُحًى</span> </span> [or rather <span class=\"ar\">ضَحْوَة</span>], (K, * TA,) with tenween, unless you mean <i>of this day</i> [in which case you say <span class=\"ar\">ضَحْوَةٌ</span>, without tenween, like as you say in the latter case <span class=\"ar\">ضُحَى</span>]. (TA.)</p><p><b class=\"ar\">ضَحْيَا</b> and <span class=\"ar\">ضَحْيَآءُ</span> fems. of <span class=\"ar\">أَضْحَى</span> [q. v.].</p><p><b class=\"ar\">ضَحْيَانٌ</b> , which should by rule be <span class=\"ar\">ضَحْوَانٌ</span>, Anything <i>exposing itself,</i> or <i>being exposed, to the sun.</i> (IJ, TA.) <span class=\"ar\">قُلَّةٌ ضَحْيَانَةٌ</span> means [<i>A mountain-top</i>] <i>exposed to the sun:</i> (S, K:) occurring in a saying of Taäbbata-sharrà. (S.) And <span class=\"ar\">عَصًا ضَحْيَانَةٌ</span> <i>A staff,</i> or <i>stick, growing in the sun so as to be matured thereby, and extremely hard.</i> (TA.) -b2- See also <span class=\"ar\">أَضْحَى</span>. -b3- Also A man <i>who eats in the time called</i> <span class=\"ar\">الضُّحَى</span>: fem. with <span class=\"ar\">ة</span>. (K.)</p><p><b class=\"ar\">ضَحَآءٌ</b> , with medd, (S, Hr, Msb, TA,) and fet-h, (Hr, Msb, TA, [erroneously written in copies of the K with damm,]) The <i>period</i> [<i>of the forenoon</i>] <i>next after that called</i> <span class=\"ar\">الضُّحَى</span>; i. e. <i>when the day is at the highest:</i> (S:) or the <i>period near midday:</i> (K:) or the <i>period of the day when the sun has risen to the fourth part of the sky:</i> (TA:) see also <span class=\"ar\">ضُحًى</span>, in two places. -b2- And hence, The [<i>morning-meal called</i>] <span class=\"ar\">غَدَآء</span>; because it is eaten in the time thus called. (S, TA.) [And also applied to <i>Pasture eaten in that time:</i>] see 2, third sentence.</p><p><b class=\"ar\">ضُحَىٌّ</b> dim. of <span class=\"ar\">ضُحًى</span>, q. v. (Fr, Msb, K.)</p><p><b class=\"ar\">ضَحِيَّةٌ</b> : see <span class=\"ar\">ضُحًى</span>: -A2- and see also <span class=\"ar\">أُضْحِيَّةٌ</span>.</p><p><b class=\"ar\">ضَاحٍ</b> [part. n. of 1, <i>Appearing, &amp;c.</i>] -b2- You say <span class=\"ar\">مَكَانٌ ضاحٍ</span> <i>An outer, exterior,</i> or <i>exposed, place:</i> (S:) and <span class=\"ar\">أَرْضٌ ضَاحِيَةٌ</span> <i>Land not surrounded by a wall.</i> (TA in art. <span class=\"ar\">حوط</span>.) [And particularly <i>A place exposed to the sun.</i>] -b3- [Hence,] <span class=\"ar\">مَفَازَةٌ ضَاحِيَةُ الظِّلِّ</span> [<i>A desert,</i> or <i>waterless desert,</i>] <i>having no shade</i> or <i>shadow;</i> and <span class=\"ar\">ضَاحِيَةُ</span> <span class=\"ar\">الظِّلَالِ</span> [<i>having no shades</i> or <i>shadows</i>]. (TA.) And <span class=\"ar\">شَجَرَةٌ ضَاحِيَةٌ بِالظِّلِّ</span> [if not a mistake for <span class=\"ar\">ضَاحِيَةُ الظِّلِّ</span>] <i>A tree having no shade.</i> (Har p. 4.] -b4- And <span class=\"ar\">بَدَا بِضَاحِى رَأْسِهِ</span> [<i>He appeared with,</i> or <i>he showed,</i>] <i>the side of his head.</i> (TA.) [See also the next paragraph.]</p><p><b class=\"ar\">ضَاحِيَةٌ</b> <i>An outer, exterior,</i> or <i>exposed, side</i> or <i>region</i> or <i>tract</i> of anything: [pl. <span class=\"ar\">ضَوَاحٍ</span>: whence] one says, <span class=\"ar\">هُمْ يَنْزِلُونَ الضَّوَاحِىَ</span> [<i>They alight,</i> or <i>abide, in the exterior tracts</i>]. (S.) [Hence also,] <span class=\"ar\">ضَوَاحِى الرُّومِ</span> <i>The exterior districts of the Greeks.</i> (K.) And <span class=\"ar\">الضَّاحِيَةُ مِنَ البَعْلِ</span> <i>What are in the open country, of the palm-trees that imbibe with their roots, without being watered:</i> opposed to <span class=\"ar\">الضَّامِنَةُ مِنَ النَّخْلِ</span>: (AO, S in this art. and in art. <span class=\"ar\">ضمن</span>, q. v.:) and <span class=\"ar\">الضَّوَاحِى مِنَ النَّخْلِ</span> <i>what are outside of the town-wall, of the palm-trees:</i> thus used, <span class=\"ar\">الضواحى</span> is an epithet in which the quality of a subst. is predominant. (TA.) And <span class=\"ar\">ضَوَاحِى</span> <span class=\"ar\">قُرَيْشٍ</span> <i>Those</i> [<i>of Kureysh</i>] <i>who abide outside of Mekkeh.</i> (TA.) And <span class=\"ar\">هُوَ مِنْ أَهْلِ الضَّاحِيَةِ</span> <i>He is of the people of the desert.</i> (TA.) <span class=\"ar\">الضَّوَاحِى</span> also signifies <i>The parts,</i> of a man, <i>that stand out,</i> or <i>are exposed,</i> (K, TA,) <i>to the sun,</i> (TA,) <i>such as the shoulder-blades,</i> and <i>the shoulders:</i> (K, TA:) pl. of <span class=\"ar\">ضَاحِيَةٌ</span>. (TA.) And <i>The sides</i> of a watering-trough. (K.) And <i>The heavens.</i> (S, K.) -b2- [Hence also,] <span class=\"ar\">فَعَلَهُ ضَاحِيَةً</span> <i>He did it openly.</i> (S, A, K.) -b3- <span class=\"ar\">ضَاحِيَةُ المَالِ</span> means <i>The cattle,</i> (K,) or <i>sheep</i> or <i>goats,</i> (TA,) <i>that drink in the time of morning called</i> <span class=\"ar\">ضُحًى</span>. (K, TA.)</p><p><b class=\"ar\">أَضْحَى</b> , applied to a horse, <i>i. q.</i> <span class=\"ar\">أَشْهَبُ</span> [<i>Of a colour in which whiteness predominates over blackness;</i> &amp;c.]: fem. <span class=\"ar\">ضَحْيَآءُ</span>: (S, K:) or <span class=\"ar\">الضَّحْيَآءُ</span> was, (K,) or was also, (S, and so afterwards in the K,) the name of a certain mare, belonging to 'Amr Ibn-'Ámir (S, K) Ibn-Rabee'ah. (S.) -b2- And <span class=\"ar\">لَيْلَةٌ ضَحْيَآءُ</span>, (S, K,) and <span class=\"ar\">ضَحْيَا</span> with the short <span class=\"ar\">ا</span>, both mentioned by ISd, (TA,) and <span class=\"ar\"> <span class=\"ar\">إِضْحِيَانَةٌ</span></span>, (S, K,) and <span class=\"ar\"> <span class=\"ar\">إِضْحِيَةٌ</span></span> accord. to the K, but [SM says] I have not found any mention of this last, [meaning except in the K,] and probably the right word is <span class=\"ar\"> <span class=\"ar\">إِضحِيَانٌ</span></span>, as in the books of strange words together with <span class=\"ar\">إِضْحِيَانَةٌ</span>, and accord. to the “ Irtisháf ed-Darab ” of AHei one says [also] <span class=\"ar\"> <span class=\"ar\">أَضْحِيَانٌ</span></span> with fet-h, (TA,) <i>A bright night,</i> (S, K, TA,) <i>in which are no clouds:</i> (S, TA:) and in like manner, <span class=\"ar\">يَوْمٌ <span class=\"ar\">إِضْحِيَانٌ</span></span>, in the K, erroneously, <span class=\"ar\">ضَحْيَاةٌ</span>, <i>a bright day, in which are no clouds,</i> as in the M; or <i>bright with the brightness of the</i> <span class=\"ar\">ضُحَى</span>, accord. to Er-Rághib; or [simply] <i>bright,</i> and so <span class=\"ar\"> <span class=\"ar\">ضَحْيَانٌ</span></span>, which is likewise applied in this sense to a moon, as also <span class=\"ar\"> <span class=\"ar\">إِضْحِيَانٌ</span></span>, and to a lamp, or its lighted wick. (TA.) -b3- And <span class=\"ar\">اِمْرَأَةٌ</span> <span class=\"ar\">ضَحْيَآءُ</span> <i>A woman whose hair of her</i> <span class=\"ar\">عَانَة</span> <i>will not grow forth;</i> (K, TA;) as though her <span class=\"ar\">عانة</span>, being bare of hair, had no shade upon it. (TA.) -A2- <span class=\"ar\">مَا أَدْرِى أَىُّ الضَّحْيَآءِ هُوَ</span> is a saying mentioned by Az in art. <span class=\"ar\">طهى</span> as meaning <i>I know not what one of mankind,</i> or <i>of the people, he is.</i> (TA.) -A3- <span class=\"ar\">أَضْحًى</span> [a coll. gen. n., of which the n. un. is <span class=\"ar\">أَضْحَاةٌ</span>]: see <span class=\"ar\">أُضْحِيَّةٌ</span>. Hence, <span class=\"ar\">يَوْمُ الأَضْحَى</span> [<i>The day of the victims;</i> which is the tenth of Dhu-l- Hijjeh]; (S, Mgh, K, * TA;) so says Yaakoob; (TA;) or <span class=\"ar\">عِيدُ الأَضْحَى</span> [<i>the festival of the victims</i>]: (Msb:) and by <span class=\"ar\">الأَضْحَى</span> when it is made masc. is meant that day. (Fr, S, Msb.)</p><p><b class=\"ar\">إِضْحِيَةٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">إِضْحِيَانٌ</b> and <span class=\"ar\">أَضْحِيَانٌ</span>, and the former with <span class=\"ar\">ة</span>: see <span class=\"ar\">أَضْحَى</span>, in five places. -b2- <span class=\"ar\">الإِضْحِيَانُ</span> is also the name of <i>A certain plant,</i> (K, TA,) <i>resembling the</i> <span class=\"ar\">أُقْحُوَان</span> [or <i>chamomile</i>] <i>in appearance.</i> (TA.)</p><p><b class=\"ar\">أُضْحِيَّةٌ</b> , (As, S, Mgh, Msb, K,) of the measure <span class=\"ar\">أُفْعُولَةٌ</span> [as though originally <span class=\"ar\">أُضْحُويَةٌ</span>], (Msb,) and <span class=\"ar\">إِضْحِيَّةٌ</span>, (As, S, Msb, K,) pl. [of each] <span class=\"ar\">أَضاحِىُّ</span>; and <span class=\"ar\"> <span class=\"ar\">ضَحِيَّةٌ</span></span>, of which the pl. is <span class=\"ar\">ضَحَايَا</span>; and <span class=\"ar\">أَضْحَاةٌ</span>, of which the pl. is <span class=\"ar\"> <span class=\"ar\">أَضْحًى</span></span>, (As, S, Mgh, Msb, K, [in copies of the K and in my copy of the Mgh written <span class=\"ar\">أَضْحَى</span>, but it is properly speaking a coll. gen. n. of which <span class=\"ar\">أَضْحَاةٌ</span> is the n. un., and is therefore with tenween,]) like <span class=\"ar\">أَرْطَاةٌ</span> and <span class=\"ar\">أَرْطًى</span>; (As, S, Mgh, Msb; *) <i>A sheep</i> or <i>goat</i> (S, K, KL) &amp;c. [i. e. meaning also <i>a camel</i> and <i>a bull</i> or <i>cow</i>] (KL) <i>that is slaughtered,</i> or <i>sacrificed,</i> (S, K, KL,) <i>in the time called</i> <span class=\"ar\">الضُّحَى</span>, (K,) <i>on the day called</i> <span class=\"ar\">يَوْمُ الأَضْحَى</span> [<i>the day of the victims,</i> which is the tenth of Dhu-l-Hijjeh]. (S, K, * KL.)</p><p><b class=\"ar\">أَرْضٌ مَضْحَاةٌ</b> <i>A land from which the sun is hardly,</i> or <i>never, absent;</i> (K, TA;) i. e. <i>an exposed land.</i> (TA.)</p><p><b class=\"ar\">مُضْطَحٍ</b> and <span class=\"ar\"> <span class=\"ar\">مُتَضَحٍّ</span></span> and <span class=\"ar\"> <span class=\"ar\">مُسْتَضْحٍ</span></span> A man <i>entering upon the time of morning called</i> <span class=\"ar\">الضُّحَى</span>. (K, * TA.)</p><p><b class=\"ar\">مُتَضَحٍّ</b> : see what next precedes.</p><p><b class=\"ar\">مُسْتَضْحٍ</b> : see what next precedes.</p>"},"ضيف":{"mf":"أصلُ الضَّيْفِ الميلُ. يقال: ضِفْتُ إلى كذا، وأَضَفْتُ كذا إلى كذا، وضَافَتِ الشّمسُ للغروب وتَضَيَّفَتْ، وضَافَ السّهمُ عن الهدف، وتَضَيَّفَ، والضَّيْفُ: من مال إليك نازلا بك، وصارت الضِّيَافَةُ متعارفة في القرى، وأصل الضَّيْفِ مصدرٌ، ولذلك استوى فيه الواحد والجمع في عامّة كلامهم، وقد يجمع فيقال:<br>أَضْيَافٌ، وضُيُوفٌ، وضِيفَانٌ. قال تعالى:<br>ضَيْفِ إِبْراهِيمَ<br>[الحجر/ ٥١]، وَلا تُخْزُونِ فِي ضَيْفِي<br>[هود/ ٧٨]، إِنَّ هؤُلاءِ ضَيْفِي [الحجر/ ٦٨]، ويقال: اسْتَضَفْتُ فلاناً فَأَضَافَنِي، وقد ضِفْتُهُ ضَيْفاً فأنا ضَائِفٌ وضَيْفٌ. وتستعمل الإِضَافَةُ في كلام النّحويّين في اسم مجرور يضمّ إليه اسم قبله، وفي كلام بعضهم في كلّ شيء يثبت بثبوته آخر، كالأب والابن، والأخ والصّديق، فإنّ كلّ ذلك يقتضي وجوده وجود آخر، فيقال لهذه: الأسماء المُتَضَايِفَةُ.","mq":[["ميل الشي الي الشي"],"الضاد والياء والفاء أصلٌ واحدٌ صحيح، يدلُّ على مَيل الشئ إلى الشئ. يقال أضَفْت الشّئَ إلى الشّئ: أمَلْته. وضافت الشمس<br>إن تنأ عنا ننتقصك وإن تقم.<br>أعائشُ ما لأهلكِ لا أراهم … يُضِيعون السوام مع المُضيعِ<br>وكيف يُضيعُ صاحبُ مدفآتِ … على أثباجهنَّ من الصَّقيعِ<br>ولعل بقية الكلام بعدهما عند ابن فارس: «فهذا م"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَافَ</b> , (M, K,) [aor. <span class=\"ar\">يَضِيفُ</span>,] inf. n. <span class=\"ar\">ضَيْفٌ</span>; (TK;) and <span class=\"ar\"> <span class=\"ar\">اضاف</span></span>, (M,) and <span class=\"ar\"> <span class=\"ar\">تضيّف</span></span>, and <span class=\"ar\"> <span class=\"ar\">ضيّف</span></span>; (K;) <i>He,</i> or <i>it, inclined,</i> (M, K,) and <i>approached,</i> or <i>drew near;</i> <span class=\"ar\">إِلَيْهِ</span> [<i>to him,</i> or <i>it</i>]. (M.) -b2- And <span class=\"ar\">ضافت الشَّمْسُ</span>, (S, M, Mgh,) or <span class=\"ar\">ضافت الشمس لِلْغُرُوبِ</span>, (O,) aor. <span class=\"ar\">تَضِيفُ</span>, inf. n. <span class=\"ar\">ضَيْفٌ</span>; (M;) and <span class=\"ar\"> <span class=\"ar\">تضيّفت</span></span>, (S, M, Mgh,) or <span class=\"ar\">تضيّفت للغروب</span>; (O;) and <span class=\"ar\"> <span class=\"ar\">ضيّفت</span></span>, (S, M, Mgh,) <span class=\"ar\">ضيّفت للغروب</span>; (O;) <i>The sun inclined,</i> (S, Mgh, O,) or <i>drew near,</i> (M,) <i>to setting.</i> (S, M, Mgh, O.) -b3- And <span class=\"ar\">ضافت</span> said of a woman, aor. as above, <i>She menstruated;</i> (O, K;) because she who does so inclines, or declines, from a state of pureness to menstruation. (O, TA.) -b4- And <span class=\"ar\">ضاف السَّهْمُ</span>, (M,) or <span class=\"ar\">ضاف السهم عَنِ الهَدَفِ</span>, (S, O,) <i>The arrow turned aside from the butt:</i> (S, M, O:) like <span class=\"ar\">صاف</span>. (S, O.) And <span class=\"ar\">ضاف عَنِ الشَّىْءِ</span>, inf. n. <span class=\"ar\">ضَوْفٌ</span> [and <span class=\"ar\">ضَيْفٌ</span>], <i>He,</i> or <i>it, turned away from the thing:</i> like <span class=\"ar\">صاف</span>, inf. n. <span class=\"ar\">صَوْفٌ</span> [and <span class=\"ar\">صَيْفٌ</span>]. (M in art. <span class=\"ar\">ضوف</span>.) -b5- And <span class=\"ar\">ضاف</span> said of a man, (assumed tropical:) <i>He feared;</i> as also <span class=\"ar\"> <span class=\"ar\">اضاف</span></span>. (M.) And <span class=\"ar\"> <span class=\"ar\">اضاف</span>مِنْهُ</span> (assumed tropical:) <i>He feared it,</i> or <i>was cautious of it;</i> namely, an event, or affair; (S, M, O, K, TA;) as also <span class=\"ar\">ضاف مِنْهُ</span>: (TA:) or (tropical:) <i>he was cautious of it with the caution of one encompassed,</i> or <i>beset, thereby.</i> (Z, TA.) -A2- <span class=\"ar\">ضِفْتُهُ</span>, (S, M, O, Msb, K,) aor. <span class=\"ar\">أَضِيفُهُ</span>, (O, K,) inf. n. <span class=\"ar\">ضِيَافَةٌ</span>, (S,) or <span class=\"ar\">ضَيْفٌ</span>, (Msb,) or both; (M, O, K;) and <span class=\"ar\"> <span class=\"ar\">تَضَيَّفْتُهُ</span></span>; (S, M, O, K;) <i>I alighted at his abode;</i> (M, Msb;) and <i>inclined to him:</i> (M:) or <i>I alighted at his abode</i> (S, M, O, Msb, K) <i>as a</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>], (S, O, K,) or <i>and became his</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>]. (M, O, Msb. [See also 3.]) And <span class=\"ar\">ضاف القَوْمَ</span>, and <span class=\"ar\"> <span class=\"ar\">تَضَيَّفَهُمْ</span></span>, <i>He alighted at the abode of the people,</i> or <i>party, as a</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>]. (Mgh.) And <span class=\"ar\"> <span class=\"ar\">تَضَيَّفْتُهُ</span></span> <i>I came to him as a</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>]. (L, TA.) -b2- [Hence,] <span class=\"ar\">ضافهُ الهَمُّ</span> (assumed tropical:) <i>Anxiety befell him.</i> (S, M, * O. [See, again, 3.]) -b3- And <span class=\"ar\">ضِفْتُهُ</span> signifies also <i>I sought,</i> or <i>desired, of him entertainment as a</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>]; and so <span class=\"ar\"> <span class=\"ar\">تَضَيَّفْتُهُ</span></span>; (M;) or this latter, (L, Msb,) and <span class=\"ar\"> <span class=\"ar\">اِسْتَضَفْتُهُ</span></span>, (M,) <i>I asked of him such entertainment.</i> (M, L, Msb.)</p><p><b>2.</b> <b class=\"ar\">ضيّف</b> , intrans.: see 1, first and second sentences. -A2- As trans.: see 4, last sentence, in four places. -b2- [Hence,] <span class=\"ar\">ضَيَّفْتُهُ</span> signifies also (assumed tropical:) <i>I protected him,</i> or <i>defended him, from him who sought,</i> or <i>pursued, him:</i> (Msb:) (tropical:) <i>I rendered him safe, secure,</i> or <i>free from fear;</i> and <i>became at peace with him;</i> thus used metaphorically. (TA.)</p><p><b>3.</b> <b class=\"ar\">ضايفهُ</b> [app. signifies <i>He straitened him:</i> (see 6:) or, perhaps, <i>he became his guest;</i> like <span class=\"ar\">ضَافَهُ</span>, &amp;c]. -b2- [Hence one says,] <span class=\"ar\">ضايفهُ الهَمُّ</span> (tropical:) [<i>Anxiety straitened him:</i> or, perhaps, <i>befell him;</i> like <span class=\"ar\">ضَافَهُ</span>]. (TA.) -b3- [And <span class=\"ar\">ضايفهُ</span>, inf. n. <span class=\"ar\">مُضَايَفَةٌ</span>, signifies also <i>It was,</i> or <i>became, correlative to it;</i> as, for instance, fathership to sonship. See also the next paragraph.]</p><p><b>4.</b> <b class=\"ar\">اضاف</b> , intrans.: see 1, in three places. -b2- Also, said of a man, <i>He ran,</i> and <i>hastened, made haste,</i> or <i>sped,</i> (Ibn-'Abbád, O, K,) and <i>fled,</i> or <i>turned away and fled:</i> (K:) and said of a dog as meaning <i>he ran away,</i> or <i>fled.</i> (TA in art. <span class=\"ar\">جبن</span>.) -b3- And <span class=\"ar\">اضاف عَلَى الشَّىْءِ</span> <i>i. q.</i> <span class=\"ar\">أَشْرَفَ عَلَيْهِ</span> [<i>He looked upon,</i> or <i>viewed, the thing from above:</i> or <i>he was,</i> or <i>became, on the brink,</i> or <i>verge,</i> or <i>at the point, of the thing:</i> &amp;c.]. (O, K, * TA.) -b4- <span class=\"ar\">تُضِيفُ إِلَى صَوْتِ الفَحْلِ</span>, said of a she-camel, means <i>She hears with desire of going to him the voice,</i> or <i>sound, of the stallion.</i> (M.) -b5- And <span class=\"ar\">الإِضَافَةُ</span> and <span class=\"ar\"> <span class=\"ar\">التَّضَايُفُ</span></span> signify <i>Correlation,</i> or <i>reciprocal relation, so that one of the two cannot be conceived in the mind without the other;</i> as in the case of <span class=\"ar\">الأُبُوَّةُ</span> and <span class=\"ar\">البُنُوَّةُ</span> [i. e. fathership and sonship]. (KT. [See also 3.]) -A2- <span class=\"ar\">اضافهُ إِلَيْهِ</span> <i>He made it to incline towards it;</i> (S, M, * O, Msb, K; *) namely, a thing (S, O) to a thing. (S, O, Msb.) <i>He made it to lean, rest,</i> or <i>stay itself, against it,</i> or <i>upon it.</i> (M, TA.) You say, <span class=\"ar\">اضاف ظَهْرَهُ إِلَى الحَائِطِ</span> <i>He leaned his back against the wall.</i> (MA.) And <span class=\"ar\">اضاف إِلَيْهِ أَمْرًا</span> (tropical:) <i>He rested,</i> or <i>stayed, upon him an affair, and desired him to do what would suffice.</i> (TA.) -b2- And <i>He made him to have recourse to it,</i> or <i>to betake himself to it for refuge.</i> (S, O, K.) -b3- And <i>He adjoined it to it.</i> (Msb.) -b4- And hence <span class=\"ar\">الإِضَافَةُ</span> as a conventional term of the grammarians; because the first [of two nouns in the case to which it applies] is adjoined to the second: (Msb:) [for] <span class=\"ar\">إِضَافَةُ الاِسْمِ إِلَى الاِسْمِ</span> is [<i>The prefixing the noun to the noun so that the former governs the latter in the gen. case</i>] as when you say <span class=\"ar\">غُلَامُ زَيْدٍ</span>; in which instance, <span class=\"ar\">غلام</span> is termed <span class=\"ar\"> <span class=\"ar\">مُضَافٌ</span></span>, and <span class=\"ar\">زيد</span> is termed <span class=\"ar\"> <span class=\"ar\">مُضَافٌ</span>إِلَيْهِ</span>: and this is done for the purpose of particularizing or appropriating, and of making known or definite: therefore the <span class=\"ar\">إِضَافَة</span> of a thing to itself [i. e. the prefixing a noun in this manner to one identical therewith in meaning] is not allowable, because a thing does not make known, or definite, itself; (S;) unless by an ellipsis, as when you say <span class=\"ar\">حَقُّ اليَقِينِ</span> for <span class=\"ar\">حَقُّ الشَّىْءِ اليَقِينِ</span>; or, accord. to Fr, the Arabs used to do so because of the difference of the two words themselves. (S voce <span class=\"ar\">جَامِعٌ</span>.) [<span class=\"ar\">الإِضَافَةُ</span> is also often used as meaning <i>The state of being prefixed in the manner explained above;</i> or <i>the connection of a noun so prefixed with its complement.</i> The various kinds of <span class=\"ar\">إِضَافَة</span> are sufficiently explained in the grammars of De Sacy and others: they are not proper subjects of a lexicon, though much is said respecting them in the O, and more in the Msb. -b5- Hence also, <span class=\"ar\">بِالإِضَافَةِ إِلَى كَذَا</span> meaning <i>In comparison with</i> (lit. <i>to</i>), or <i>in relation to,</i> (like <span class=\"ar\">بِالنِّسْبَةِ إِلَى</span>,) <i>such a thing;</i> as though <i>in juxtaposition to it:</i> a phrase of frequent occurrence: see an ex. in Bd ii. 6.] -b6- <span class=\"ar\">أَضَفْتُهُ</span> (inf. n. <span class=\"ar\">إِضَافَةٌ</span>, Msb) and <span class=\"ar\"> <span class=\"ar\">ضَيَّفْتُهُ</span></span> (inf. n. <span class=\"ar\">تَضْيِيفٌ</span>, O) both signify the same, (S, M, O, Msb, K,) from <span class=\"ar\">الضِّيَافَةُ</span>; (O;) i. e. both signify <i>I made him a guest,</i> or <i>lodged him,</i> or <i>gave him refuge</i> or <i>asylum,</i> syn. <span class=\"ar\">أَنْزَلْتُهُ</span>, (S, M, Msb,) <i>with me, as a</i> <span class=\"ar\">ضَيْف</span> [or <i>guest</i>], (S,) <i>and entertained him:</i> (S, M, Msb:) <span class=\"ar\">أَضَافُوهُ</span> and <span class=\"ar\"> <span class=\"ar\">ضَيَّفُوهُ</span></span> both signify <span class=\"ar\">أَنْزَلُوهُ</span>: (Mgh:) accord. to Th, <span class=\"ar\">أَضَفْتُهُ</span> signifies <i>I lodged him at my abode as a</i> <span class=\"ar\">ضَيْف</span>: and <i>I gave him</i> (i. e. one in fear) <i>protection,</i> or <i>refuge</i> or <i>asylum:</i> (Msb:) and <span class=\"ar\"> <span class=\"ar\">ضَيَّفْتُهُ</span></span> is also expl. as meaning <i>I fed him:</i> and <span class=\"ar\"> <span class=\"ar\">ضيّفهُ</span></span> as meaning <i>he made him to be in the condition of</i> <span class=\"ar\">أَضْيَاف</span> [or <i>guests</i>]. (TA.)</p><p><b>5.</b> <b class=\"ar\">تَضَيَّفَ</b> intrans.: see 1, first and second sentences. -b2- <span class=\"ar\">تَضَيُّفٌ</span> signifies also The <i>being collected together.</i> (KL, from the Mj.) -b3- And The <i>being a</i> <span class=\"ar\">تَابِع</span> [or <i>follower,</i> &amp;c.]. (Id.) -A2- As trans.: see 1, latter half, in four places.</p><p><b>6.</b> <b class=\"ar\">تَضَاْيَفَ</b> see 4. -A2- <span class=\"ar\">تضايف</span> as said of a valley, [from <span class=\"ar\">ضِيفٌ</span> “ a side, ”] <i>It became narrow;</i> syn. <span class=\"ar\">تَضَايَقَ</span>. (S, M, O.) <span class=\"ar\">تَضَايَفْنَ عَلَيْهِ</span>, a phrase used by a poet [describing camels following an old camel], <i>They became near to him,</i> (S, M, O,) <i>by his side.</i> (S, M.) And you say, <span class=\"ar\">تضايفهُ القَوْمُ</span> <i>The people,</i> or <i>party, became on both sides of him</i> (<span class=\"ar\">بِضِيفَيْهِ</span>). (TA.) And <span class=\"ar\">تَضَايفُه السَّبُعَانِ</span> <i>The two beasts of prey hemmed him in on both sides.</i> (TA.) And <span class=\"ar\">تَضَايَفَتِ الكِلَابُ الصَّيْدَ</span> and <span class=\"ar\">تَضَايَفَتْ عَلَيْهِ</span> [<i>The dogs hemmed in the object of the chase on both sides,</i> or <i>round about</i>]. (TA.) [In the TA, all these are said to be tropical; but why, I see not.]</p><p><b>7.</b> <b class=\"ar\">انضاف إِلَيْهِ</b> signifies <i>He,</i> or <i>it, became joined,</i> or <i>adjoined,</i> or <i>added, to him,</i> or <i>it:</i> and <i>he joined himself to him:</i> but is perhaps postclassical.]</p><p><b>10.</b> <b class=\"ar\">إِسْتَضْيَفَ</b> see 1, last sentence. -b2- You say also <span class=\"ar\">اِسْتَضَافَنِى</span>, meaning <i>He desired me,</i> or <i>asked me, to grant him protection,</i> or <i>refuge.</i> (Msb.) And <span class=\"ar\">استضاف فُلَانٌ إِلَى فُلَانٍ</span> <i>Such a one had recourse,</i> or <i>betook himself, to such a one for protection,</i> or <i>refuge.</i> (IAar, M.)</p><p><b class=\"ar\">ضَيْفٌ</b> <i>A guest:</i> and <i>guests:</i> (MA:) so called because adjoined to the family and fed with them: (Ham p. 124:) it is applied to one, and to a pl. number, (S, M, MA, O, Msb, K,) and to a male and to a female, (S, O, Msb, K,) because it is originally an inf. n.: (MA, Msb:) [as a sing.,] <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مُضَيَّفٌ</span></span>, (M,) which is <i>syn. with</i> <span class=\"ar\">نَزِيلٌ</span>: (TA:) and applied to a pl. number, it may be pl. [or rather a quasi-pl. n.] of <span class=\"ar\"> <span class=\"ar\">ضَائِفٌ</span></span>, which is syn. with <span class=\"ar\">نَازِلٌ</span>; thus being of the class of <span class=\"ar\">زَوْزٌ</span> and <span class=\"ar\">صَوْمٌ</span>: (M:) and it is also pluralized, having for its pls. <span class=\"ar\">أَضْيَافٌ</span> and <span class=\"ar\">ضِيفَانٌ</span> (S, M, MA, O, Msb, K) and <span class=\"ar\">ضُيُوفٌ</span> (S, M, MA, O, K) and <span class=\"ar\">ضِيَافٌ</span>, (MA, TA,) the first of which is properly a pl. of pauc., but is also used as a pl. of mult.: (M:) and a female is termed <span class=\"ar\">ضَيْفَةٌ</span> as well as <span class=\"ar\">ضَيْفٌ</span>: (S, M, O, Msb, K:) El-Ba'eeth says, <span class=\"ar\">لَقًى حَمَلَتْهُ أُمُّهُ وَهْىَ ضَيْفَةٌ</span> [<i>A castaway with whom his mother became pregnant while she was a guest</i>]: (S, M, O:) or, accord. to AHeyth, the meaning here is that which follows. (O.) -b2- <span class=\"ar\">ضَيْفَةٌ</span> applied to a woman signifies also <i>Menstruating:</i> (O, K:) so says AHeyth with reference to the citation above from El-Ba'eeth. (O.)</p><p><b class=\"ar\">ضِيفٌ</b> The <i>side</i> (T, S, M, O, K) of a valley (T, M) and of a mountain (M) [&amp;c.: see 6]: and, as metaphorically used by an anonymous poet, of the <span class=\"ar\">ذَكَر</span>: (M:) and <span class=\"ar\"> <span class=\"ar\">مَضَايِفُ</span></span> signifies the <i>sides</i> of a valley. (TA.) -b2- And one says, <span class=\"ar\">فُلَانٌ فِى ضِيفِ فُلَانٍ</span>, meaning <i>Such a one is in the vicinage,</i> or <i>quarter, of such a one.</i> (M.)</p><p><b class=\"ar\">ضَيْفَنٌ</b> <i>One who comes with a guest:</i> (S, O:) or <i>who so comes intruding without invitation:</i> (K:) or <i>one who follows a guest:</i> derived from <span class=\"ar\">ضَيْفٌ</span>, accord. to Sb; but said by AZ to belong to art. <span class=\"ar\">ضفن</span>: (M:) [accord. to J and Sgh] the <span class=\"ar\">ن</span> is augmentative: the pl. is <span class=\"ar\">ضَيَافِنُ</span>. (S, O.)</p><p><b class=\"ar\">ضِيَافَةٌ</b> an inf. n. of <span class=\"ar\">ضِفْتُهُ</span> in the first of the senses assigned to the latter above. (S, M, O, K.) -b2- [And] a subst. from <span class=\"ar\">أَضَفْتُهُ</span> and <span class=\"ar\">ضَيَّفْتُهُ</span> [as such signifying The <i>entertainment of a guest</i> or <i>guests;</i> i. e. the <i>act of entertaining:</i> and <i>an entertainment</i> as meaning <i>a repast, given to a guest</i> or <i>guests; a banquet,</i> or <i>feast</i>]. (Msb.) [Hence, <span class=\"ar\">دَارُ الضِّيَافَةِ</span> <i>The house of entertainment of guests.</i>]</p><p><b class=\"ar\">ضَائِفٌ</b> A man <i>alighting as a guest;</i> syn. <span class=\"ar\">نَازِلٌ</span>: (M, TA:) see <span class=\"ar\">ضَيْفٌ</span>: its [proper] pl. is <span class=\"ar\">ضُيَّفٌ</span>. (TA.)</p><p><b class=\"ar\">مُضَافٌ</b> ; and <span class=\"ar\">مُضَافٌ إِلَيْهِ</span>: see 4. -b2- The former signifies also (tropical:) One who is <i>made an adjunct,</i> or <i>adherent, to a people,</i> or <i>party,</i> (S, M, O, K, TA,) and <i>made to incline to them,</i> (M,) <i>not being of them.</i> (M, TA.) One says, <span class=\"ar\">مَا هُوَ إِلَّا مُضَافٌ</span> (tropical:) [<i>He is none other than an adjunct,</i> or <i>adherent</i>]. (TA.) -b3- And (tropical:) One <i>whose origin,</i> or <i>lineage,</i> or <i>parentage, is suspected;</i> or <i>who makes a claim to relationship not having it:</i> (O, K, TA:) and (K) <i>whose origin,</i> or <i>relationship, is referred to a people,</i> or <i>party, of whom he is not a member.</i> (O, K, TA.) -b4- And One <i>who is constrained to betake himself to a place of refuge,</i> (M, O, K, TA,) <i>to a narrow,</i> or <i>confined, place, and who is burdened with evil:</i> (TA:) El-Bureyk ElHudhalee says, <span class=\"ar\">وَيَحْمِى المُضَافَ إِذَا مَا دَعَا</span> [<i>And he protects him who is constrained to betake himself to a place of refuge, when he calls for aid</i>]. (M.) And <span class=\"ar\"> <span class=\"ar\">مُسْتَضَافٌ</span></span> signifies the same as <span class=\"ar\">مُضَافٌ</span> [app. in the last of the senses expl. above]: so says IB; and he cites the saying of Jowwás Ibn-Heiyán El-Azdee, <span class=\"ar\">وَلَقَدْ أَقْدَمُ فِى <span class=\"ar\">الرَّوٌ</span>عِ وَأَحْمِى المُسْتَضَافَا</span> [app. meaning <i>And verily I advance boldly in the case of fear, and I protect him who is constrained to betake himself to a place of refuge</i>]. (TA.) [See also <span class=\"ar\">مَضُوفٌ</span>.] -b5- Also One who is <i>beset, hemmed in,</i> or <i>encompassed,</i> in war, or battle: (S, O, K: said in the TA to be tropical:) or one <i>falling among the horsemen and men of valour, having in him no strength.</i> (M.) [See, again, <span class=\"ar\">مَضُوفٌ</span>.] -b6- And One <i>in a state of fear.</i> (TA.)</p><p><b class=\"ar\">مَضُوفٌ</b> <i>Beset by distress of mind:</i> (TA:) [accord. to Freytag, as from the Deewán of the Hudhalees, <i>constrained to seek refuge:</i> (see also <span class=\"ar\">مُضَافٌ</span>:)] it occurs in the saying of the Hudhalee, <span class=\"ar\">أَنْتَ تُجِيبُ دَعْوَةَ المَضُوفِ</span> [<i>Thou answerest the prayer,</i> or <i>call, of him who is beset</i> &amp;c.]; and is formed after the manner of <span class=\"ar\">بُوعَ</span> for <span class=\"ar\">بِيعَ</span>. (M, TA.)</p><p><b class=\"ar\">مَضِيفٌ</b> a dial. var. of <span class=\"ar\">مَصِيفٌ</span> [q. v.]. (TA.) [ISd says that] <span class=\"ar\">مَضِيفًا</span> occurring in a verse of Aboo-Dhu-eyb [as some relate it], cited voce <span class=\"ar\">كَرَبَةٌ</span>, [where the reading of <span class=\"ar\">مَصِيفًا</span> is given,] is for <span class=\"ar\">ضَائِفًا</span>, meaning <i>Turning aside; crooked.</i> (M.)</p><p><b class=\"ar\">مُضِيفٌ</b> <i>Fleeing;</i> or <i>turning away and fleeing.</i> (Ibn-'Abbád, O. [See also its verb.])</p><p><b class=\"ar\">مُضَافَةٌ</b> <i>Hardship,</i> or <i>difficulty,</i> or <i>distress.</i> (TA.) -b2- See also the next paragraph.</p><p><b class=\"ar\">مَضُوفَةٌ</b> , an anomalous word, by rule <span class=\"ar\">مَضِيفَةٌ</span>, (Kh, Sb, TA in art. <span class=\"ar\">ضوف</span>,) <i>Anxiety;</i> and <i>want,</i> or <i>a want;</i> (O and K in that art.;) and <span class=\"ar\"> <span class=\"ar\">مَضِيفَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مُضِيفَةٌ</span></span> signify the same; (O in that art. and in art. <span class=\"ar\">ضيف</span>;) or these two signify <i>anxiety,</i> and <i>grief:</i> (K in this art.:) or <span class=\"ar\">مَضُوفَةٌ</span> signifies <i>an affair,</i> or <i>event, that is feared,</i> or <i>of which one is cautious;</i> (S and M in this art.;) thus accord. to As; and <span class=\"ar\"> <span class=\"ar\">مَضِيفَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">مُضَافَةٌ</span></span> signify the same. (S, L, TA.)</p><p><b class=\"ar\">مَضِيفَةٌ</b> and <span class=\"ar\">مُضِيفَةٌ</span>: see both in the next preceding paragraph; the former in two places.</p><p><b class=\"ar\">مَضْيَفَةٌ</b> , of the measure <span class=\"ar\">مَفْعَلَةٌ</span>, <i>A place of</i> <span class=\"ar\">ضِيَافَة</span> [i. e. <i>entertainment of a guest</i> or <i>guests:</i> pl. <span class=\"ar\">مَضَايِفُ</span>]. (TA.)</p><p><b class=\"ar\">مُضَيَّفٌ</b> : see <span class=\"ar\">ضَيفٌ</span>.</p><p><b class=\"ar\">مُضَيِّفٌ</b> The <i>master of an abode in which guests are entertained;</i> as also <span class=\"ar\"> <span class=\"ar\">مَضَايِفِىٌّ</span></span>. (TA.)</p><p><b class=\"ar\">مِضْيَافٌ</b> [One <i>who often entertains guests</i>]. (Har p. 579.)</p><p><b class=\"ar\">مَضَايِفُ</b> [pl. of <span class=\"ar\">مَضْيَفَةٌ</span>: -b2- and also of a sing. not mentioned]: see <span class=\"ar\">ضِيفٌ</span>.</p><p><b class=\"ar\">مَضَايِفِىٌّ</b> [from <span class=\"ar\">مَضَايِفُ</span> pl. of <span class=\"ar\">مَضْيَفَةٌ</span>]: see <span class=\"ar\">مُضَيِّفٌ</span>.</p><p><b class=\"ar\">إِسْمَآءٌ مُتَضَايِفَةٌ</b> <i>Correlative nouns;</i> i. e. <i>nouns significant of the existence of persons,</i> or <i>things, whereof the existence of one necessarily indicates the existence of another;</i> as <span class=\"ar\">أَبٌ</span> and <span class=\"ar\">اِبْنٌ</span> [father and son]. (Er-Rághib, TA.)</p><p><b class=\"ar\">مُسْتَضَافٌ</b> : see <span class=\"ar\">مُضَافٌ</span>.</p><p><b class=\"ar\">مُسْتَضِيفٌ</b> [act. part. n. of 10, q. v.:] <i>Asking,</i> or <i>calling, for aid,</i> or <i>succour.</i> (Ibn-'Abbád, O, K.)</p>"},"ضوأ":{"mf":"الضَّوْءُ: ما انتشر من الأجسام النّيّرة، ويقال:<br>ضَاءَتِ النارُ، وأَضَاءَتْ، وأَضَاءَهَا غيرُها. قال تعالى: فَلَمَّا أَضاءَتْ ما حَوْلَهُ<br>[البقرة/ ١٧]، كُلَّما أَضاءَ لَهُمْ مَشَوْا فِيهِ<br>[البقرة/ ٢٠]، يَكادُ زَيْتُها يُضِيءُ<br>[النور/ ٣٥]، يَأْتِيكُمْ بِضِياءٍ<br>[القصص/ ٧١]، وسَمَّى كُتُبَهُ المُهْتَدَى بها ضِيَاءً في نحو قوله: وَلَقَدْ آتَيْنا مُوسى وَهارُونَ الْفُرْقانَ وَضِياءً وَذِكْراً لِلْمُتَّقِينَ<br>[الأنبياء/ ٤٨].<br>تمّ كتاب الضّاد<br>كتاب الطّاء","mq":[["نور"],"الضاد والواو والهمزة أصلٌ صحيح، يدلُّ على نورِ. من<br>ذلك الضَّوء والضُّوء بمعنًى، وهو الضِّياء والنُّور. قال اللّه تعالى: ﴿فَلَمّا أَضاءَتْ ما حَوْلَهُ﴾. قال أبو عبيد: أضاءت النّارُ وأضاءت غيرَها. وأنشد:<br>أضاءت لنا النّار وجهاً أغرَّ … ملتبِساً بالفؤاد التباسا (١)<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَوڤاَ</b> see 4, in two places.</p><p><b>2.</b> <b class=\"ar\">ضَوَّاَ</b> see the next paragraph, in two places. -b2- One says also, <span class=\"ar\">ضَوَّأْتُ عَنْهُ</span> [meaning <i>I brought to light, made visible, discovered,</i> or <i>revealed, him,</i> or <i>it</i>]. (M, TA.) A sheep, or goat, belonging to an Arab of the desert strayed; whereupon he said, <span class=\"ar\">اَللّٰهُمَّ ضَوِّئْ عَنْهُ</span> [<i>O God, bring it to light,</i> or <i>discover it</i>]. (A, TA.) -A2- Accord. to Lth, but he is the only authority for it known by AM, (TA,) <span class=\"ar\">ضَوَّأَ عَنِ الأَمْرِ</span>, inf. n. <span class=\"ar\">تَضْوِئَةٌ</span>, means <i>He declined,</i> or <i>turned away, from the affair.</i> (K, TA.)</p><p><b>4.</b> <b class=\"ar\">اضآء</b> , (M, Msb, K,) said of a thing, (M,) [as, for instance,] of the moon, (Msb,) or <span class=\"ar\">اضآءت</span>, said of fire (<span class=\"ar\">النَّار</span>,), (A 'Obeyd, S, O,) inf. n. <span class=\"ar\">إِضَآءٌ</span>; (Msb;) and <span class=\"ar\"> <span class=\"ar\">ضَآءَ</span></span>, (M, Msb, K,) or <span class=\"ar\">ضَآءَت</span>, (S, O,) aor. <span class=\"ar\">يَضُوْءُ</span>, (M,) or <span class=\"ar\">تَضُوْءُ</span>, (S,) inf. n. <span class=\"ar\">ضَوْءٌ</span> (S, M, O, Msb, K) and <span class=\"ar\">ضُوْءٌ</span>, (S, O, K,) or the latter is a simple subst.; (Msb;) but the former verb is preferred; (TA;) <i>It gave light, was light</i> or <i>bright, shone,</i> or <i>shone brightly.</i> (Msb, K, * TA.) [See also an ex. of ↓ the latter verb in a verse cited voce <span class=\"ar\">أُفُقٌ</span>; and cited here in the TA.] And <span class=\"ar\">أَضَأْتُ لَهُ</span> [<i>I gave light to him</i>]. (M.) -A2- The former verb is also trans.: you say, <span class=\"ar\">أَضَآءَتْهُ النَّارُ</span> [<i>The fire made it to be light</i> or <i>bright, to shine,</i> or <i>to shine brightly</i>]: (S, O:) and <span class=\"ar\">أَضَأْتُهُ</span> and <span class=\"ar\"> <span class=\"ar\">ضَوَّأْتُهُ</span></span> [<i>I made it to give light, to be light</i> or <i>bright, to shine,</i> or <i>to shine brightly</i>]: (M, Msb, * K:) and <span class=\"ar\">أَضَأْتُ بِهِ البَيْتَ</span> and <span class=\"ar\"> <span class=\"ar\">ضَوَّأْتُهُ</span>بِهِ</span> [<i>I lighted,</i> or <i>illumined, with it</i> (i. e. with a lamp or the like) <i>the house,</i> or <i>chamber,</i> or <i>tent</i>]. (M.) -b2- [Hence,] <span class=\"ar\">اضآء بِبَوْلِهِ</span> (tropical:) <i>He ejected his urine</i> [so as to make its drops to glisten]; or <i>emitted it and then stopped it;</i> syn. <span class=\"ar\">حَذَفَ بِهِ</span>; (K, TA;) or <span class=\"ar\">خَذَفَ بِهِ</span>; (so in a copy of the M, as on the authority of Kr;) or, as in the A, <span class=\"ar\">أَذْرَعَ بِهِ</span>. (TA.) -b3- And they said <span class=\"ar\">مَا أَضْوَأَهُ</span> [<i>How light,</i> or <i>bright, is it!</i>]. (S voce <span class=\"ar\">أَظْلَمَ</span> [q. v.].) -b4- And <span class=\"ar\">اضآء</span> signifies also <span class=\"ar\">أَصَابَ ضَوْءًا</span> [<i>He saw</i> (lit. <i>lighted on,</i> or <i>found,</i>) <i>light,</i> or <i>brightness</i>]. (T voce <span class=\"ar\">أَظْلَمَ</span> [q. v.])</p><p><b>5.</b> <b class=\"ar\">تضوّأ</b> <i>He stood in the dark to see people by the light of their fire,</i> (AZ, K, TA,) <i>without their seeing him.</i> (AZ, TA.) And <span class=\"ar\">تضوّا ٱمْرَأَةً</span> [<i>He stood in the dark to see a woman by the light of her fire, without her seeing him</i>]. (TA.)</p><p><b>10.</b> <b class=\"ar\">اِسْتَضَأُتُ بِهِ</b> [<i>I sought to obtain light by means of it; I made use of it for light</i>]. (M, K.) <span class=\"ar\">لَا تَسْتَضِيؤُوا بِنَارِ أَهْلِ الشِّرْكِ</span> [lit. <i>Seek not ye to obtain light by means of the fire of the people of belief in a plurality of gods</i>], (O, K,) a saying of the Prophet, (O,) means (tropical:) <i>seek not ye counsel,</i> or <i>advice, of the believers in a plurality of gods, in affairs:</i> (O, K:) because he whose affair is confused and dubious to him is as though he were in darkness. (O.)</p><p><b class=\"ar\">ضَوْءٌ</b> and <span class=\"ar\"> <span class=\"ar\">ضُوْءٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضِيَآءٌ</span></span> (S, M, O, K) and <span class=\"ar\"> <span class=\"ar\">ضِوَآءٌ</span></span>, (M, K,) the last of which is [erroneously] written in the L <span class=\"ar\">ضَوَآءٌ</span>, (TA,) signify the same, (S, M, O, K,) i. e. <i>Light,</i> syn. <span class=\"ar\">نُورٌ</span>, (K, TA,) accord. to the leading lexicologists; but see what follows: (TA:) and <span class=\"ar\">ضَوْءٌ</span> is an inf. n. of <span class=\"ar\">ضَآءَ</span>, (S, M, O, Msb, K,) and so is <span class=\"ar\"> <span class=\"ar\">ضُوْءٌ</span></span>, (S, O, K,) or this is a simple subst. from <span class=\"ar\">ضَآءَ</span>, and so is <span class=\"ar\"> <span class=\"ar\">ضِيَآءٌ</span></span>, which is also, sometimes, written <span class=\"ar\"> <span class=\"ar\">ضِئَآءٌ</span></span>, from <span class=\"ar\">أَضَآءَ</span> as syn. with <span class=\"ar\">ضَآءَ</span>: (Msb:) the pl. of <span class=\"ar\">ضَوْءٌ</span> (M, TA) and <span class=\"ar\"> <span class=\"ar\">ضُوْءٌ</span></span> (M) is <span class=\"ar\">أَضْوَآءٌ</span>; and <span class=\"ar\"> <span class=\"ar\">ضِيَآءٌ</span></span> is sometimes a pl., (M, TA,) as Zj states it to be: (TA:) some say that <span class=\"ar\">ضَوْءٌ</span> has a more intensive signification than <span class=\"ar\">نُورٌ</span>, and that hence God has likened his direction [the Kur-án] to <span class=\"ar\">النُّور</span> rather than to <span class=\"ar\">الضَّوْء</span>; because if it were otherwise, no one had erred: and that hence, also, [in the Kur x. 5,] the sun is termed <span class=\"ar\"> <span class=\"ar\">ضِيَآء</span></span>; and the moon, <span class=\"ar\">نُورٌ</span>: it is also said that <span class=\"ar\">ضَوْءٌ</span> signifies the <i>rays that are diffused by what is termed</i> <span class=\"ar\">نُورٌ</span>: the kádee Zekereeyà affirms that these two words are syn. by their original application, but that <span class=\"ar\">ضَوْءٌ</span> is more forcible accord. to usage: and some say that <span class=\"ar\">الضَّوْءُ</span> signifies <i>that</i> [<i>light</i>] <i>which subsists by itself,</i> as [that of] the sun, and fire; and <span class=\"ar\">النُّورُ</span>, to that which subsists by some other thing [as does the light of the moon]. (MF, TA.)</p><p><b class=\"ar\">ضُوْءٌ</b> : see the next preceding paragraph, in three places.</p><p><b class=\"ar\">ضِوَآءٌ</b> : see <span class=\"ar\">ضَوْءٌ</span>.</p><p><b class=\"ar\">ضِيَآءٌ</b> and <span class=\"ar\">ضِئَآءٌ</span>: see <span class=\"ar\">ضَوْءٌ</span>, in five places.</p>"},"ضجع":{"mq":[["لصوق بالارض علي جنب"],"الضاد والجيم والعين أصل واحد يدلُّ على لُصوقٍ بالأرض على جنْب، ثم يُحمَل على ذلك. يقال ضَجَع ضُجوعا. والمرَّة الواحدة الضَّجْعة.<br>ويقال اضطجع يضطجع اضطجاعاً. وضجيعُك: الذى يُضاجِعك، وهو حسن الضِّجْعة كالرِّكْبة.<br>ومن الباب: ضجَّع فى الأمر، إذا قصَّر، كأنه لم يقُم به واضطجع عنه.<br>ويقال رجل ضَجُوع، أى ضع"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَجَعَ</b> , aor. <b class=\"ar\">ضَجَعَ</b> , inf. n. <span class=\"ar\">ضَجْعٌ</span> and <span class=\"ar\">ضُجُوعٌ</span>, [<i>He lay upon his side;</i> or] <i>he laid his side upon the ground;</i> [and simply <i>he lay;</i> and <i>he slept;</i>] as also <span class=\"ar\"> <span class=\"ar\">اِضْطَجَعَ</span></span>, (S, Msb, K, TA,) which is also expl. as syn. with <span class=\"ar\">نَامَ</span>, [which has the second and third of the meanings mentioned above,] and with <span class=\"ar\">اِسْتَلْقَى</span>, [which has the third of those meanings,] (TA,) the <span class=\"ar\">ط</span> being substituted for the <span class=\"ar\">ت</span> of <span class=\"ar\">اِضْتَجَعَ</span>, (Lth, S, Msb,) and <span class=\"ar\"> <span class=\"ar\">اِضَّجَعَ</span></span>, (S, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">اِلْطَجَعَ</span></span>, (S, L, K, in the CK [erroneously] <span class=\"ar\">اطَّجَعَ</span>,) the <span class=\"ar\">ض</span> in <span class=\"ar\">اضطجع</span> being changed into <span class=\"ar\">ل</span>, which is the letter nearest in sound thereto, because the combination of two such letters as <span class=\"ar\">ض</span> and <span class=\"ar\">ط</span> is disliked, (S, L,) the same change occurring in <span class=\"ar\">اِلْطِرَادٌ</span> for <span class=\"ar\">اِضْطِرَادٌ</span>, (Az, TA,) though this change is anomalous; (L;) and <span class=\"ar\"> <span class=\"ar\">أَضْجَعَ</span></span> likewise signifies the same as <span class=\"ar\">ضَجَعَ</span>; (Msb;) [and] so does <span class=\"ar\"> <span class=\"ar\">انضجع</span></span>, (K, TA,) as quasi-pass. of the trans. verb <span class=\"ar\">اضجع</span>. (TA.) -b2- [And accord. to Freytag, it occurs in the Deewán of the Hudhalees as signifying <i>He declined from the way.</i>] -b3- <span class=\"ar\">ضَجَعَ</span> <span class=\"ar\">النَّجْمُ</span> means (tropical:) [<i>The star,</i> or <i>asterism,</i> or <i>the Pleiades,</i>] <i>inclined to setting;</i> as also <span class=\"ar\"> <span class=\"ar\">ضجّع</span></span>, (K, TA,) inf. n. <span class=\"ar\">تَضْجيعٌ</span>. (TA.) And <span class=\"ar\">ضَجَعَتِ الشَّمْسُ</span> is a dial. var. of <span class=\"ar\"> <span class=\"ar\">ضجّعت</span></span>, (TA,) which means (tropical:) <i>The sun approached the setting;</i> (S, K, TA;) like <span class=\"ar\">ضَرَّعَت</span>. (S, TA.) -b4- <span class=\"ar\">ضَجَعَ فِى أَمْرِهِ</span> (tropical:) <i>He was,</i> or <i>became, weak in his affair;</i> as also <span class=\"ar\"> <span class=\"ar\">اضجع</span></span>; and so <span class=\"ar\">ضَجِعَ</span>, like <span class=\"ar\">فَرِحَ</span> [in measure], on the authority of IKtt. (TA. [See also 2, and 5, and 6.]) And <span class=\"ar\">ضُجِعَ فِى رَأْيِهِ</span> [not a mistranscription for <span class=\"ar\">ضَجِعَ</span>, as is shown by its part. n., q. v.,] (tropical:) <i>He was,</i> or <i>became, weak in his judgment,</i> or <i>opinion.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">ضَجَّعَ</b> see above, in two places. -b2- <span class=\"ar\">ضجّع فِى الأَمْرِ</span>, (Mgh, K,) inf. n. <span class=\"ar\">تَضْجِيعٌ</span>, (S,) (tropical:) <i>He fell short of doing what was requisite,</i> or <i>due, in the affair;</i> (S, Mgh, K, TA;) and <i>was,</i> or <i>became, weak therein.</i> (Mgh.) [See also <span class=\"ar\">ضَجَعَ فِى أَمْرِهِ</span>, and see 5, and 6.] -b3- Hence, <span class=\"ar\">التَّضْجِيعُ فِى النِّيَّةِ</span> (assumed tropical:) <i>The wavering,</i> or <i>vacillating, in intention, and not making it to take effect.</i> (Mgh.)</p><p><b>3.</b> <b class=\"ar\">ضاجعهُ</b> , (S, TA,) inf. n. <span class=\"ar\">مُضَاجَعَةٌ</span>, <i>He lay upon his side,</i> or simply <i>he lay,</i> or <i>slept, with him.</i> (TA.) And <span class=\"ar\">ضَاجَعَهَا</span>, (Msb, TA,) inf. n. as above, (Msb,) <i>He lay,</i> or <i>slept, with her,</i> (Msb, TA,) namely, his girl, or young woman, (TA,) <i>in,</i> or <i>on, one bed,</i> (Msb,) or <i>in one innermost garment.</i> (TA.) -b2- And hence, <span class=\"ar\">ضاجعهُ الهَمُّ</span> (tropical:) <i>Anxiety clave to him.</i> (TA.)</p><p><b>4.</b> <b class=\"ar\">أَضْجَعْتُهُ</b> , (S, Msb, K,) inf. n. <span class=\"ar\">إِضْجَاعٌ</span>, (TA,) <i>I laid him upon his side;</i> (S, * Msb;) <i>I laid his side upon the ground.</i> (K.) -b2- And (tropical:) <i>I lowered it,</i> or <i>depressed it,</i> namely, a thing. (K, TA.) -b3- <span class=\"ar\">اضجع الرُّمْحُ الطَّعْنَ</span> (tropical:) [app. <i>The spear made the thrusting to be in a downward direction</i>]. (TA.) -b4- <span class=\"ar\">اضجع جُوَالِقَهُ</span> (assumed tropical:) <i>He emptied his sack, it being full.</i> (O, K.) -b5- <span class=\"ar\">الإِضْجَاعُ</span> in relation to the vowel-sounds is (tropical:) like <span class=\"ar\">الإِمَالَةُ</span> and <span class=\"ar\">الخَفْضُ</span>. (K, TA. [See arts. <span class=\"ar\">ميل</span> and <span class=\"ar\">خفض</span>.]) -A2- See also 1, in two places.</p><p><b>5.</b> <b class=\"ar\">تضجّع فِى الأَمْرِ</b> (tropical:) <i>He held back in the affair,</i> (S, K, TA,) <i>and did not undertake it.</i> (S, TA.) [See also 1, and 2, and 6.] -b2- And <span class=\"ar\">تضجّع السَّحَابُ</span> (tropical:) <i>The clouds continued raining</i> (<span class=\"ar\">أَرَبَّ</span>) <i>in the place.</i> (S, K, TA.)</p><p><b>6.</b> <b class=\"ar\">تضاجع عَنْ أَمْرِ كَذَا وَكَذَا</b> (tropical:) <i>He feigned himself unmindful,</i> or <i>heedless, of such and such an affair.</i> (Z, TA.) [See also 1, and 2, and 5.]</p><p><b>7.</b> <b class=\"ar\">إِنْضَجَعَ</b> see 1, first sentence.</p><p><b>8.</b> <b class=\"ar\">اِضْطَجَعَ</b> , and its vars. <span class=\"ar\">اِضَّجَعَ</span> and <span class=\"ar\">اِلْطَجَعَ</span>: see 1, first sentence. -b2- <span class=\"ar\">الاِضْطِجَاعُ فِى السُّجُودِ</span> is (tropical:) <i>The not drawing up the body from the ground in prostration</i> [in prayer]; (Mgh, TA;) <i>the contracting oneself, and making the breast to cleave to the ground, therein.</i> (K, TA.) [See also its part. n., below.]</p><p><b class=\"ar\">ضَجْعٌ</b> [The <i>species of glasswort,</i> or <i>kali, called</i>] <span class=\"ar\">غَاسُول</span>, <i>for</i> [<i>washing</i>] <i>clothes:</i> n. un. with <span class=\"ar\">ة</span>: (K:) accord. to IDrd, the <i>gum of a certain plant,</i> or <i>a certain plant</i> [<i>itself</i>], <i>with which clothes are washed:</i> (O:) of the dial. of El-Yemen: (TA:) and, (O, K,) accord. to Ed-Deenawaree, (O,) i. e. AHn, (TA,) <i>a certain plant,</i> (K,) <i>resembling small cucumbers,</i> (O, K, TA,) [or] <i>in shape like asparagus,</i> (TA,) <i>but thicker</i> (O, K, TA) <i>in a great degree,</i> (O, TA,) <i>four-sided in the stalks,</i> (O, K, TA,) <i>and having in it an acidity</i> (O, TA,) <i>and a bitterness</i> (<span class=\"ar\">مَرَارَة</span> O) or <i>a taste between sweet and sour</i> (<span class=\"ar\">مَزَازَة</span> TA): <i>it is crushed</i> (<span class=\"ar\">يُشْدَخُ</span> O) or <i>cut into slices</i> (<span class=\"ar\">يشرح</span> TA) <i>and its juice is expressed into milk such as is termed</i> <span class=\"ar\">رَائِب</span> [q. v.], <i>which in consequence becomes pleasant,</i> (O, K, TA,) <i>and somewhat biting to the tongue; and its leaves are put into sour milk, like as is done with the leaves of the mustard:</i> (O, TA:) <i>it is good as an aphrodisiac.</i> (O, K, TA.)</p><p><b class=\"ar\">ضِجْعٌ</b> (assumed tropical:) <i>Inclination:</i> (O, K:) so in the phrase <span class=\"ar\">ضِجْعُ فُلَانٍ إِلَى فُلَانٍ</span> (assumed tropical:) [<i>The inclination of such a one is towards such a one</i>], (O,) or <span class=\"ar\">إِلَىَّ</span> [<i>towards me</i>]. (K.)</p><p><b class=\"ar\">ضَجْعَةٌ</b> <i>A single act of lying, upon the side</i> or <i>otherwise,</i> or <i>of sleeping:</i> (IAth, O, * TA:) <i>a sleep.</i> (K, TA.) -b2- And (tropical:) <i>Weakness</i> in judgment; (O, K, TA;) as also <span class=\"ar\"> <span class=\"ar\">ضُجْعَةٌ</span></span>. (K.) One says, <span class=\"ar\">فِى رَأْيِهِ ضَجْعَةٌ</span> (tropical:) <i>In his judgment is weakness.</i> (O, TA.) -b3- And (tropical:) <i>Ease; repose; freedom from</i> <i>trouble</i> or <i>inconvenience, and toil</i> or <i>fatigue;</i> as also <span class=\"ar\"> <span class=\"ar\">ضُجْعَةٌ</span></span>. (TA.)</p><p><b class=\"ar\">ضُجْعَةٌ</b> <i>One whom people often lay upon his side</i> [or <i>throw down</i>]. (K, TA.) -b2- [And app., <i>One who lays others on the side,</i> or <i>prostrates them;</i> as is implied by what here follows.] -b3- (assumed tropical:) <i>A disease:</i> (K, TA:) because it lays the man upon his bed. (TA.) -b4- See also <span class=\"ar\">ضَجْعَةٌ</span>, in two places. -b5- And see <span class=\"ar\">ضُجَعَةٌ</span>.</p><p><b class=\"ar\">ضِجْعَةٌ</b> <i>A mode,</i> or <i>manner, of lying upon the side</i> [or <i>in any posture</i>], (S, O, Msb, K,) or <i>of sleeping.</i> (TA.) -b2- And (assumed tropical:) <i>Sluggishness, laziness,</i> or <i>indolence.</i> (K, TA.) -b3- Also, for <span class=\"ar\">ذَاتُ ضِجْعَةٍ</span>, (assumed tropical:) <i>A bed.</i> (JM. [See also <span class=\"ar\">مَضْجَعٌ</span>.]) It is said in a trad. that the <span class=\"ar\">ضِجْعَة</span> of the Apostle of God was of skins, (IAth, JM, TA,) stuffed with fibres of the palm-tree: (IAth, TA:) meaning his <i>bed.</i> (JM.)</p><p><b class=\"ar\">ضَجَعَةٌ</b> a gen. n. (O, K) in the sense of <span class=\"ar\">اِضْطِجَاعٌ</span> [i. e. The act of <i>lying upon the side,</i> or <i>in any manner;</i> and of <i>sleeping</i>]. (O.)</p><p><b class=\"ar\">ضُجَعَةٌ</b> , (S, O, K,) and, accord. to the K, <span class=\"ar\"> <span class=\"ar\">ضُجْعَةٌ</span></span>, but this [as an epithet] has the meaning first assigned to it above, (TA,) and <span class=\"ar\"> <span class=\"ar\">ضُجْعِيَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضِجْعِيَّةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضُجْعِىٌّ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضِجْعِىٌّ</span></span>, (O, K,) the last two [in the CK, erroneously, <span class=\"ar\">ضُِجْعَى</span>, but] like <span class=\"ar\">قُعْدِىٌّ</span> and <span class=\"ar\">قِعْدِىٌّ</span>, (O,) and <span class=\"ar\"> <span class=\"ar\">ضَاجعٌ</span></span>, (K,) [or this last is a simple part. n.,] (tropical:) A man <i>who lies upon his side</i> [or <i>in any manner,</i> or <i>sleeps,</i>] <i>much,</i> or <i>often:</i> (S, O, K, TA:) <i>sluggish, lazy,</i> or <i>indolent:</i> (S and O in explanation of the first, and K in explanation of all:) or <i>who keeps to the house</i> or <i>tent; seldom,</i> or <i>never, going forth; nor rising and speeding to do a generous deed:</i> or <i>impotent and stationary:</i> (K, TA:) [or,] accord. to IB, <span class=\"ar\"> <span class=\"ar\">ضَاجِعٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضُجْعِىٌّ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضِجْعِىٌّ</span></span> signify one <i>who is content with his poverty, and betakes himself to his house</i> or <i>tent.</i> (TA.)</p><p><b class=\"ar\">ضُجْعِىٌّ</b> and <span class=\"ar\">ضِجْعِىٌّ</span>: see each in two places in the next preceding paragraph.</p><p><b class=\"ar\">ضُجْعِيَّةٌ</b> and <span class=\"ar\">ضِجْعِيَّةٌ</span>: see <span class=\"ar\">ضُجَعَةٌ</span>.</p><p><b class=\"ar\">ضَجُوعٌ</b> A water-skin (<span class=\"ar\">قِرْبَةٌ</span>) <i>that makes the drawer of water to lean by reason of its heaviness.</i> (Ibn-'Abbád, O, K.) -b2- A <i>wide</i> <span class=\"ar\">دَلْو</span> [or leathern bucket]; (Ibn-'Abbád, O, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَاجِعَةٌ</span></span>. (Ibn-'Abbád, O.) -b3- (tropical:) A cloud (<span class=\"ar\">سَحَابَةٌ</span>) <i>slow by reason of the abundance of its water.</i> (IDrd, O, K, TA.) -b4- A well (<span class=\"ar\">بِئْرٌ</span>) <i>hollowed in the sides, the water having eaten its interior.</i> (AA, O, K. *) -b5- A she-camel <i>that pastures aside.</i> (A'Obeyd, O, K.) -b6- A wife <i>contrarious to the husband.</i> (Ibn-'Abbád, O, K. [See also <span class=\"ar\">أَضْجَعُ</span>.]) -b7- And (tropical:) A man <i>weak in judgment;</i> (IDrd, O, K;) as also <span class=\"ar\"> <span class=\"ar\">مَضْجُوعٌ</span></span>. (K.)</p><p><b class=\"ar\">ضَجِيعٌ</b> [<i>A bedfellow</i>]. <span class=\"ar\">ضَجِيعُكَ</span> means <i>He who lies,</i> or <i>sleeps, with thee;</i> (S, O, Msb;) <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مُضَاجِعُكَ</span></span>; (K;) which latter is likewise applied to a female; as also <span class=\"ar\">ضَجِيعَةٌ</span>: and you say, <span class=\"ar\">هُوَ ضَجِيعُهَا</span> meaning <i>He is he who lies,</i> or <i>sleeps, with her in one innermost garment;</i> and <span class=\"ar\">هِىَ</span> <span class=\"ar\">ضَجِيعَتُهُ</span> <i>She is she who so lies,</i> or <i>sleeps, with him.</i> (TA.) And [hence] one says, <span class=\"ar\">بِئْسَ الضَّجِيعُ الجُوعُ</span> (tropical:) [<i>Very evil is the bedfellow, hunger</i>]. (TA.)</p><p><b class=\"ar\">ضَاجِعٌ</b> <i>Lying upon his side</i> [or <i>in any manner;</i> and <i>sleeping;</i> see its verb]; (S, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">مُضْطَجِعٌ</span></span> (TA) and <span class=\"ar\"> <span class=\"ar\">مُضْجِعٌ</span></span>. (Msb.) See also <span class=\"ar\">ضُجَعَةٌ</span>, in two places. -b2- (tropical:) <i>Stupid, foolish,</i> or <i>unsound in intellect:</i> (IAar, O, K, TA:) because of his impotence, and his cleaving to his place. (TA.) -b3- <span class=\"ar\">دَلْوٌ ضَاجِعَةٌ</span> <i>A leathern bucket that is full,</i> (IAar, ISk, O, K,) <i>so that it leans in rising from the well by reason of its heaviness.</i> (ISk, O, K.) See also <span class=\"ar\">ضَجُوعٌ</span>. -b4- And <span class=\"ar\">ضَاجِعٌ</span> (tropical:) A star <i>inclining to setting:</i> pl. <span class=\"ar\">ضَوَاجِعُ</span>: (O, K, TA:) [or] <span class=\"ar\">الضَّوَاجِعُ</span> signifies [or signifies also] <i>the fixed stars.</i> (Ham p. 364.) -b5- And (tropical:) <i>Inclining</i> as in the saying <span class=\"ar\">أَرَاكَ ضَاجِعًا إِلَى فُلَانٍ</span> (tropical:) [<i>I see thee inclining towards such a one</i>]. (O, TA.) -b6- And (assumed tropical:) <i>A place of bending of a valley:</i> pl. <span class=\"ar\">ضَوَاجِعُ</span>. (O, K.) -b7- Also, applied to a beast, (assumed tropical:) <i>Worthless; in which is no good.</i> (TA.) [But] -b8- <span class=\"ar\">غَنَمٌ ضَاجِعَةٌ</span> means <i>Numerous sheep</i> or <i>goats;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَحْعَآءُ</span></span>. (Fr, S, O, K.) -b9- And <span class=\"ar\">إِبِلٌ</span> <span class=\"ar\">ضَاجِعَةٌ</span> and <span class=\"ar\">ضَوَاجِعُ</span> (assumed tropical:) <i>Camels keeping to the plants called</i> <span class=\"ar\">حَمْض</span>; <i>remaining among them.</i> (TA.)</p><p><b class=\"ar\">ضَاجِعَةٌ</b> as a subst. <i>i. q.</i> <span class=\"ar\">مَصَبُّ وَادٍ</span>; (AA, T, O, K, TA; [app. meaning The <i>place where the water flows into it, of a valley;</i> for] Az adds, in the T, as though it were a <span class=\"ar\">رَحَبَة</span>, [see <span class=\"ar\">رَحَبَةُ الوَادِى</span> in art. <span class=\"ar\">رحب</span>,] then, afterwards, it takes a straight direction, and becomes a valley (<span class=\"ar\">وَادٍ</span>): pl. <span class=\"ar\">ضَوَاجِعُ</span>. (TA.) -b2- <span class=\"ar\">ضَوَاجِعُ</span> [which is like wise pl. of <span class=\"ar\">ضَاجِعٌ</span>] also signifies [<i>Hills such as are called</i>] <span class=\"ar\">هِضَاب</span> [pl. of <span class=\"ar\">هَضْبَةٌ</span>]; (S, O, K;) and is said to have no sing. [in this sense]: occurring in a verse of En-Nábighah Edh-Dhubyánee: (S:) but ISk says that, in this instance, it is the name of a certain place. (O.)</p><p><b class=\"ar\">أَضْجَعُ الثَّنَايَا</b> (tropical:) <i>Having the central incisors inclining;</i> (O, K, TA;) applied to a man: (O:) pl. <span class=\"ar\">ضُجْعٌ</span>. (TA.) -b2- And <span class=\"ar\">أَضْجَعُ</span> signifies also <i>Contrarious to his wife.</i> (O, K. [See also <span class=\"ar\">ضَجُوعٌ</span>.]) -b3- For a meaning of its fem., <span class=\"ar\">ضَجْعَآءُ</span>, see <span class=\"ar\">ضَاجِعٌ</span>, last sentence but one.</p><p><b class=\"ar\">مَضْجَعٌ</b> <i>A place in which,</i> or <i>on which, one lies upon his side</i> [or <i>in any manner,</i> or <i>sleeps</i>]; (O, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">مُضْطَجَعٌ</span></span>: (O, K:) [<i>a bed;</i> and <i>the like:</i>] pl. <span class=\"ar\">مَضَاجِعُ</span>: (Msb, TA:) which means sometimes <i>places of sleep,</i> or <i>of passing the night:</i> (Bd in iv. 38:) and <i>beds;</i> or <i>other things spread upon the ground to lie upon.</i> (Jel ibid., and Bd in xxxii. 16.) -b2- [Hence] the pl. is used as meaning (assumed tropical:) <i>Wives,</i> or <i>women:</i> so in the saying, <span class=\"ar\">هُوَ طَيِّبُ المَضَاجِعِ</span> i. e. (assumed tropical:) <i>He has well-born wives</i> or <i>women;</i> like <span class=\"ar\">كَرِيمُ المَفَارِشِ</span>. (TA.) -b3- And <span class=\"ar\">مَضَاجِعُ الغَيْثِ</span> means (tropical:) <i>The places of falling of rain.</i> (O, K, TA.) One says, <span class=\"ar\">بَاتَتِ الرِّيَاضُ</span> <span class=\"ar\">مَضَاجِعَ لِلْغَيْثِ</span> (tropical:) [<i>The meadows were during the night places of the falling of rain</i>]. (A, TA.)</p><p><b class=\"ar\">مُضْجِعٌ</b> : see <span class=\"ar\">ضَاجِعٌ</span>, first sentence.</p><p><b class=\"ar\">مَضْجُوعٌ</b> : see <span class=\"ar\">ضَجُوعٌ</span>, last sentence. <span class=\"ar\">مُضَاجِعٌ</span>: see <span class=\"ar\">ضَجِيعٌ</span></p><p><b class=\"ar\">مُضْطَجَعٌ</b> : see <span class=\"ar\">مَضْجَعٌ</span>. -b2- It is also used as an inf. n. (Har p. 664.)</p><p><b class=\"ar\">مُضْطَجَعٌ</b> : see <span class=\"ar\">ضَاجِعٌ</span>, first sentence. -b2- [It is said that] <span class=\"ar\">صَلَّى مُضْطَجِعًا</span> means (tropical:) <i>He prayed lying upon his right side,</i> [or app., <i>inclining towards that side,</i>] <i>facing the Kibleh.</i> (TA. [But see 8.])</p>"},"ضرع":{"mf":"الضَّرْعُ: ضَرْعُ الناقةِ، والشاة، وغيرهما، وأَضْرَعَتِ الشاةُ: نزل اللّبن في ضَرْعِهَا لقرب نتاجها، وذلك نحو: أتمر، وألبن: إذا كثر تمره ولبنه، وشاةٌ ضَرِيعٌ: عظيمةُ الضَّرْعِ، وأما قوله:<br>لَيْسَ لَهُمْ طَعامٌ إِلَّا مِنْ ضَرِيعٍ<br>[الغاشية/ ٦]، فقيل: هو يَبِيسُ الشَّبْرَقِ <strong>«١»</strong>، وقيل: نباتٌ أحمرُ منتنُ الرّيحِ يرمي به البحر، وكيفما كان فإشارة إلى شيء منكر. وضَرَعَ إليهم: تناول ضَرْعَ أُمِّهِ، وقيل منه: ضَرَعَ الرّجلُ ضَرَاعَةً:<br>ضَعُفَ وذَلَّ، فهو ضَارِعٌ، وضَرِعٌ، وتَضَرّعَ:<br>أظهر الضَّرَاعَةَ. قال تعالى: تَضَرُّعاً وَخُفْيَةً<br>[الأنعام/ ٦٣]، لَعَلَّهُمْ يَتَضَرَّعُونَ<br>[الأنعام/ ٤٢]، لَعَلَّهُمْ يَضَّرَّعُونَ<br>[الأعراف/ ٩٤]، أي: يَتَضَرَّعُونَ فأدغم، فَلَوْلا إِذْ جاءَهُمْ بَأْسُنا تَضَرَّعُوا<br><strong>[الأنعام/ ٤٣]، والمُضَارَعَةُ أصلُها:</strong><br>التّشارك في الضَّرَاعَةِ، ثمّ جرّد للمشاركة، ومنه استعار النّحويّون لفظَ الفعلِ المُضَارِعِ.","mq":[["لين في الشي"],"الضاد والراء والعين أصل صحيح يدلُّ على لينٍ فى الشَّئ.<br>من ذلك ضَرَع الرجل ضَراعة، إذا ذلَّ. ورجل ضَرَعٌ: ضعيف. قال اُبن وَعْلة:<br>أناةٌ وحلما وانتظارا بهم غداً … فما أنا بالوانى ولا الضَّرَع الغُمْرِ (١)<br>ومن الباب ضَرْع الشّاة وغيرِه، سمى بذلك لما فيه من لِين. ويقال:<br>أضْرَعَت النّاقة، إذا نَزَل لبنُها"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَرَعَ</b> , said of a lamb or kid, <i>He took</i> [<i>with his mouth</i>] <i>the</i> <span class=\"ar\">ضَرْع</span> [meaning <i>dug</i>] <i>of his mother.</i> (TA.) [This seems to be regarded by some as the primary signification.] -b2- And (TA) the same, (S, Msb, K,) said of a man, (S,) aor. <b class=\"ar\">ضَرَعَ</b> ; (Msb, K;) and <span class=\"ar\">ضَرِعَ</span>, aor. <b class=\"ar\">ضَرَعَ</b> ; and <span class=\"ar\">ضَرُعَ</span>, aor. <b class=\"ar\">ضَرُعَ</b> ; (K;) inf. n. (S, Msb, K) of the first (S, Msb, TA) and of the third (TA) <span class=\"ar\">ضَرَاعَةٌ</span>, (S Msb, K,) and (K) of the second (TA) <span class=\"ar\">ضَرَعٌ</span>; (K;) <i>He was,</i> or <i>became, lowly, humble,</i> or <i>submissive;</i> (S, K;) and <i>low, abject,</i> or <i>abased;</i> (S, Msb, K;) <span class=\"ar\">إِلَيْهِ</span> (K) and <span class=\"ar\">لَهُ</span> [<i>to him</i>]: (TA:) or <span class=\"ar\">ضَرِعَ</span> and <span class=\"ar\">ضَرَعَ</span> signify <i>he lowered, humbled,</i> or <i>abased, himself,</i> (K, * TA,) [like <span class=\"ar\">تضرّع</span>, which is more commonly used in this sense,] <i>and made petition for a gift:</i> (TA:) and <span class=\"ar\">ضَرُعَ</span>, (Msb, K, TA,) inf. n. <span class=\"ar\">ضَرَعٌ</span>, (Msb,) or <span class=\"ar\">ضَرَاعَةٌ</span>, (TA,) <i>he was,</i> or <i>became, weak;</i> (K, TA;) and it is said that the verb in this last sense is from <span class=\"ar\">ضَرَعَ</span> in the sense expl. in the first sentence: so in the “ Mufradát ” [of Er-Rághib]: <span class=\"ar\">ضَرِعَ</span>, likewise, like <span class=\"ar\">فَرِحَ</span> [in measure], signifies <i>he was,</i> or <i>became, weak in body, slender, spare,</i> or <i>light of flesh:</i> and <span class=\"ar\">ضُرُوعٌ</span>, [app. as an inf. n. of which the verb is <span class=\"ar\">ضَرَعَ</span>,] the <i>being lean,</i> or <i>emaciated.</i> (TA.) For another explanation of <span class=\"ar\">ضَرَاعَةٌ</span>, see 5. -b3- [<span class=\"ar\">ضَرَعَ</span> is made trans. by means of <span class=\"ar\">ب</span>:] one says, <span class=\"ar\">ضَرَعَ بِهِ فَرَسُهُ</span> <i>His horse humbled him,</i> or <i>abased him:</i> (O, K, TA:) or, as in the L, <i>overcame him.</i> (TA.) -b4- <span class=\"ar\">ضَرَعَ مِنْهُ</span>, said of an animal of prey, (IKtt, K, TA,) inf. n. <span class=\"ar\">ضُرُوعٌ</span>, (K,) <i>He approached</i> (IKtt, K, TA) <i>him</i> i. e. a man, (IKtt, TA,) or <i>it</i> i. e. a thing. (K.) -b5- See also the next paragraph.</p><p><b>2.</b> <b class=\"ar\">تَضْرِيعٌ</b> signifies The <i>drawing near,</i> or <i>approaching, by little and little, in a deceitful,</i> or <i>guileful, manner, going this way and that,</i> or <i>to the right and left;</i> (Ibn-'Abbád, O, K;) as also <span class=\"ar\"> <span class=\"ar\">تَضَرُّعٌ</span></span>: (K:) you say <span class=\"ar\">ضَرَّعَ</span> and <span class=\"ar\">تَضَرَّعَ</span>. (O, TA.) -b2- And <span class=\"ar\">ضَرَّعَتِ الشَّمْسُ</span>, (K,) inf. n. as above, (S, O,) (tropical:) <i>The sun approached the setting;</i> (S, O, K;) [like <span class=\"ar\">ضجّعت</span>;] and <span class=\"ar\"> <span class=\"ar\">ضَرَعَت</span></span> signifies the same; [like <span class=\"ar\">ضَجَعَت</span>;] or <i>the sun set;</i> (K;) and <span class=\"ar\"> <span class=\"ar\">ضَارِعَتِ</span>الشَّمْسُ</span>, inf. n. <span class=\"ar\">مُضَارَعَةٌ</span>, signifies the same as <span class=\"ar\">ضَرَعَت</span> and <span class=\"ar\">ضرّعت</span>. (TA.) -b3- And <span class=\"ar\">ضَرَّعَتِ القِدْرُ</span> <i>i. q.</i> <span class=\"ar\">حَانَ أَنْ تُدْرِكَ</span> [i. e. <i>The cookingpot approached,</i> or <i>attained, to the time of the cooking of its contents;</i> and so, app., <span class=\"ar\"> <span class=\"ar\">ضارعت</span></span>, accord. to the TA, but the passage in which this is there indicated presents an obvious mistranscription]. (S, O, K, TA. [In the CK, <span class=\"ar\">تُدْرَكَ</span> is erroneously put for <span class=\"ar\">تُدْرِكَ</span>.]) -b4- And <span class=\"ar\">ضَرَّعَ الرُّبُّ</span> [app. means <i>The rob,</i> or <i>inspissated juice, became nearly mature;</i> or] <i>the expressed juice was cooked, but its cooking was not complete.</i> (O, K, * TA. [In the CK, <span class=\"ar\">الرُّبَّ</span> is erroneously put for <span class=\"ar\">الرُّبُّ</span>, and <span class=\"ar\">طَبَخ</span> for <span class=\"ar\">طُبِخَ</span>, and <span class=\"ar\">يُتِمَّ طَبْخَهُ</span> for <span class=\"ar\">يَتِمَّ طَبْخُهُ</span>.])</p><p><b>3.</b> <b class=\"ar\">مُضَارِعَةٌ</b> is <i>syn. with</i> <span class=\"ar\">مُشَابَهَةٌ</span>: (S, O, Msb:) accord. to Er-Rághib, its primary meaning is The <i>sharing</i> [in a thing, or particularly <i>in the</i> <span class=\"ar\">ضَرْع</span>, or <i>udder</i>], like <span class=\"ar\">مُرَاضَعَةٌ</span>, which is the “ sharing in sucking. ” (TA.) You say <span class=\"ar\">ضارعهُ</span> <i>He,</i> or <i>it, resembled him,</i> or <i>it; was,</i> or <i>became like him,</i> or <i>it.</i> (K, TA.) And <span class=\"ar\">بَيْنَهُمَا مُرَاضَعَةُ</span> <span class=\"ar\">الكَاسِ وَمُضَارَعَةُ الأَجْنَاسِ</span> [<i>Between them two are the sipping of the wine-cup, and the resemblance of kinds;</i> or <i>compotation and congeniality</i>]: said in the A to be from <span class=\"ar\">الضَّرْعُ</span>. (TA.) [See also an ex. voce <span class=\"ar\">تَحَلَّجَ</span>.] -b2- Also <i>i. q.</i> <span class=\"ar\">مُقَارَبَةٌ</span> [meaning The <i>approaching</i> a thing]. (TA.) See 2, in two places.</p><p><b>4.</b> <b class=\"ar\">اضرعت</b> , said of a ewe or she-goat, <i>Her milk descended</i> [<i>into her udder,</i> i. e. <i>she secreted milk in her udder,</i> as is shown in the lexicons in many places, (see for instance, <span class=\"ar\">أَرَدَّتْ</span>, and <span class=\"ar\">رِدَّةٌ</span>,)] <i>a little before her bringing forth:</i> (S, O, K:) and [in like manner] said of a she-camel, <i>her milk descended from</i> (<span class=\"ar\">مِنْ</span> [a mistranscription for <span class=\"ar\">فِى</span> i. e. <i>into</i>]) <i>her udder near the time of bringing forth;</i> and the epithet applied to her is <span class=\"ar\"> <span class=\"ar\">مُضْرِعٌ</span></span> [without <span class=\"ar\">ة</span>]: or, as in the A, said of a she-camel and of a cow, <i>her udder</i> (<span class=\"ar\">ضَرْعُهَا</span>) <i>became prominent before bringing forth:</i> (TA:) or, said of a ewe or she-goat, <i>she showed herself to be pregnant, and became large in her udder.</i> (T in art. <span class=\"ar\">رمد</span>.) And <span class=\"ar\">أَضْرَعَتْ عَلَى رَأْسِ الوَلَدِ</span> [<i>She secreted milk,</i> or <i>became large, in the udder, at the time of bringing forth,</i> or <i>when about to produce the young,</i> like as one says <span class=\"ar\">كَانَ ذٰلِكَ عَلَى رَأْسِ فُلَانٍ</span> expl. in art. <span class=\"ar\">رأس</span>], said of a ewe or goat. (S in arts. <span class=\"ar\">رمد</span> and <span class=\"ar\">ربق</span> [in both of which the meaning is clearly shown] and in art. <span class=\"ar\">دفع</span> [in which last see several sentences].) -b2- [Hence, app.,] <span class=\"ar\">أَضْرَعْتُ لَهُ مَالِى</span> (assumed tropical:) <i>I gave him liberally, unsparingly,</i> or <i>freely, my property.</i> (O, K. *) -b3- And <span class=\"ar\">اضرعهُ</span> signifies also <i>He,</i> or <i>it, lowered, humbled,</i> or <i>abased, him.</i> (S, O, K.) Thus, in a trad. of 'Alee, <span class=\"ar\">أَضْرَعَ ٱللّٰهُ</span> <span class=\"ar\">خُدُودَكُمْ</span> <i>May God lower,</i> or <i>humble,</i> or <i>abase, your cheeks.</i> (TA.) One says also, <span class=\"ar\">كَانَ مَزْهُوًّا</span> <span class=\"ar\">فَأَضْرَعَهُ الفَقْرُ</span> [<i>He was proud, haughty,</i> or <i>insolent, and poverty lowered,</i> or <i>humbled,</i> or <i>abased, him</i>]. (TA.) And it is said in a prov., <span class=\"ar\">الحُمَّى أَضْرَعَتْنِى</span> <span class=\"ar\">لَكَ</span>, (S, Meyd, A, O,) or <span class=\"ar\">لِلنَّوْمِ</span>, (Meyd, O, K,) accord. to different relations, (Meyd, O,) [meaning <i>The fever abased me to thee,</i> or <i>to sleep;</i>] asserted by El-Mufaddal to have been first said by a certain man named Mureyr, to a Jinnee by whom he was carried off while sleeping under the influence of fever, after he had been making a fruitless search after his two brothers, Murárah and Murrah, who had also been carried off by Jinn: [his story is related at length in the O and TA, as well as by Meyd.; and is given in Har p. 568, and in Freytag's Arab. Prov. i. pp. 364-5:] the prov. is applied to the case of abasement on the occasion of need. (Meyd, O, TA.) -b4- One says also, <span class=\"ar\">اضرعهُ إِلَيْهِ</span> <i>He,</i> or <i>it, constrained him to have recourse to him,</i> or <i>it.</i> (TA.) -b5- And <span class=\"ar\">اضرعهُ الحُبُّ</span> <i>Love rendered him lean,</i> or <i>emaciated.</i> (TA.)</p><p><b>5.</b> <b class=\"ar\">تضرّع</b> <i>He lowered, humbled,</i> or <i>abased, himself:</i> (O, K, TA:) or <i>he addressed himself with earnest,</i> or <i>energetic, supplication:</i> (TA:) syn. <span class=\"ar\">اِبْتَهَلَ</span>, to God (<span class=\"ar\">إِلَى ٱللّٰهِ</span>): (S, O, K:) or <i>he manifested</i> <span class=\"ar\"> <span class=\"ar\">ضَرَاعَة</span></span> i. e. <i>severe poverty,</i> (O, TA:) <i>and want,</i> (TA,) to God: (O, TA:) or <i>i. q.</i> <span class=\"ar\">تَعَرَّضَ بِطَلَبِ الحَاجَةِ</span>, (K, TA,) or <span class=\"ar\">يَطْلُبُ الحَاجَةَ</span>; (CK;) you say, <span class=\"ar\">جَآءَ فُلَانٌ يَتَضَرَّعُ</span> and <span class=\"ar\">يَتَعَرَّضُ</span> i. e. <i>Such a one came asking,</i> or <i>petitioning, to another for a thing that he wanted.</i> (Fr, S, O.) [See also <span class=\"ar\">تَصَرَّعَ</span>.] -b2- Also <i>He writhed; and asked,</i> or <i>called, for aid,</i> or <i>succour.</i> (TA.) -b3- And, said of the shade, (tropical:) <i>It contracted, shrank,</i> or <i>decreased;</i> or <i>it went away;</i> syn. <span class=\"ar\">قَلَصَ</span>: (Ibn-'Abbád, O, K, TA:) and <span class=\"ar\">تَصَرَّعَ</span> is a dial. var. thereof. -b4- See also 2.</p><p><b class=\"ar\">ضَرْعٌ</b> a word of well-known meaning; (TA;) [properly and generally, the <i>udder,</i> but sometimes applied to the <i>dug,</i> or <i>teat:</i>] the <span class=\"ar\">ضَرْع</span> is <i>of every female that has a cloven hoof,</i> or <i>of the she-camel:</i> (S, O:) [i. e.] <i>of each of these:</i> (K:) or [<i>of the former only;</i> i. e.] <i>of the sheep</i> or <i>goat and of the cow</i> and <i>the like;</i> that of the camel being termed <span class=\"ar\">خِلْفٌ</span>: (Lth, O, K:) it is, <i>to the clovenhoofed female, like the</i> <span class=\"ar\">ثَدْى</span> <i>to the woman:</i> (Msb:) or, <i>to cattle, like the</i> <span class=\"ar\">ثَدْى</span> <i>to the woman:</i> (Towsheeh, TA:) accord. to the IF, it is <i>of the sheep</i> or <i>goat</i> and <i>of other animals:</i> accord. to IDrd, <i>of the sheep</i> or <i>goat</i> [<i>only</i>]: AZ says, <i>it comprises the</i> <span class=\"ar\">أَطْبَآء</span>, <i>which are the</i> <span class=\"ar\">أَخْلَاف</span>, <i>and in which are the</i> <span class=\"ar\">أَحَالِيل</span>, <i>which are the orifices for the passing forth of the milk:</i> (O:) the pl. is <span class=\"ar\">ضُرُوعٌ</span>. (O, Msb, K.) <span class=\"ar\">مَا لَهُ زَرْعٌ وَلَا ضَرْعٌ</span> [lit. <i>He has not seed-produce nor an udder</i>] means (tropical:) <i>he has not anything:</i> (TA:) or it means <i>he has not land to sow, nor ewe</i> or <i>she-goat</i> or <i>she-camel</i> or <i>other animal having a</i> <span class=\"ar\">ضَرْع</span>. (O.) -A2- See also the next paragraph, in two places.</p><p><b class=\"ar\">ضِرْعٌ</b> <i>A like; a similar person</i> or <i>thing;</i> (IAar, O, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَرْعٌ</span></span>: (IAar, TA in art. <span class=\"ar\">صرع</span>:) and so <span class=\"ar\">صِرْعٌ</span> (O, TA) and <span class=\"ar\">صَرْعٌ</span>. (O and K and TA in art. <span class=\"ar\">صرع</span>.) -b2- And <i>A sort,</i> or <i>species:</i> and <i>a state, condition,</i> or <i>manner of being:</i> of a thing: as also <span class=\"ar\"> <span class=\"ar\">ضَرْعٌ</span></span>: and so <span class=\"ar\">صِرْعٌ</span> and <span class=\"ar\">صَرْعٌ</span>. (TA in art. <span class=\"ar\">صرع</span>.) -b3- And <i>A strand of a rope:</i> (O, K:) and so <span class=\"ar\">صِرْعٌ</span>: (O:) pl. <span class=\"ar\">ضُرُوعٌ</span>. (O, K: and the CK adds <span class=\"ar\">أَضْرُعٌ</span>.)</p><p><b class=\"ar\">ضَرَعٌ</b> <i>Lowly, humble, submissive,</i> or <i>in a state of abasement;</i> [originally an inf. n., and therefore, as an epithet,] applied to a single person and to a pl. number: (O:) and <span class=\"ar\"> <span class=\"ar\">ضَارِعٌ</span></span> signifies the same, applied to a single person; (O, Msb;) as also <span class=\"ar\"> <span class=\"ar\">مُسْتَضْرِعٌ</span></span>, (K, *TA:) accord. To Lth, one says, <span class=\"ar\">خَدُّكَ <span class=\"ar\">ضَارِعٌ</span></span>, (O,) and <span class=\"ar\"> <span class=\"ar\">أَضْرَعُ</span></span>, which signifies the same, (Ham p. 344,) and <span class=\"ar\">جَنْبُكَ <span class=\"ar\">ضَارِعٌ</span></span>, [meaning, as is implied in the O, <i>Thy cheek is lowly</i> &amp;c., and so <i>thy side,</i> and the like is said in the Ham p. 590,] and <span class=\"ar\">أَنْتَ <span class=\"ar\">ضَارِعٌ</span></span> [<i>Thou art lowly</i> &amp;c.]: (O:) and the pl. of <span class=\"ar\">ضَارِعٌ</span> is <span class=\"ar\">ضَرَعَةٌ</span> and <span class=\"ar\">ضُرُوعٌ</span>: (TA:) or <span class=\"ar\"> <span class=\"ar\">ضَارِعٌ</span></span> signifies, and so <span class=\"ar\"> <span class=\"ar\">ضَرِعٌ</span></span>, and [in an intensive sense] <span class=\"ar\"> <span class=\"ar\">ضَرُوعٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَرَعَةٌ</span></span>, <i>lowering, humbling,</i> or <i>abasing, himself:</i> (K:) or <i>thus, and making petition for a gift:</i> (TA:) and <span class=\"ar\">ضَرَعٌ</span> signifies <i>weak;</i> (S, Mgh, Msb, K:) as also <span class=\"ar\"> <span class=\"ar\">ضَرِعٌ</span></span>; (K;) the former (Msb, K) originally an inf. n. (Msb) [and therefore, as an epithet,] applied to a single person and to a pl. number: (K:) and <span class=\"ar\">ضَرَعٌ</span> and <span class=\"ar\"> <span class=\"ar\">ضَارِعٌ</span></span> <i>small;</i> applied to anything: or <i>small in age, weak,</i> (K, TA,) <i>and lean, spare,</i> or <i>light of flesh:</i> (TA:) and <span class=\"ar\"> <span class=\"ar\">ضَارِعُ</span>الجِسْمِ</span>, (S,) and <span class=\"ar\"> <span class=\"ar\">ضَرِعٌ</span></span>, (TA,) <i>lean, spare,</i> or <i>light of flesh, and weak, in the body;</i> (S, TA;) applied to a man: (S:) and <span class=\"ar\">ضَرَعٌ</span> applied to a colt, <i>not having strength to run,</i> (K, TA,) <i>by reason of the smallness of his age.</i> (TA.) Also (assumed tropical:) <i>Cowardly,</i> or <i>weak-hearted:</i> you say, <span class=\"ar\">هُوَ وَرَعٌ ضَرَعٌ</span> [both app. meaning the same]. (TA.) And, applied to a man, (tropical:) <i>Inexperienced in affairs; ignorant;</i> or <i>in whom is no profit nor judgment;</i> syn. <span class=\"ar\">غُمْرٌ</span>. (TA.)</p><p><b class=\"ar\">ضَرِعٌ</b> : see <span class=\"ar\">ضَرَعٌ</span>, in three places.</p><p><b class=\"ar\">ضَرَعَةٌ</b> : see <span class=\"ar\">ضَرَعٌ</span>. -b2- It is also a pl. of <span class=\"ar\">ضَارِعٌ</span> [as mentioned above, voce <span class=\"ar\">ضَرَعٌ</span>]. (TA.)</p><p><b class=\"ar\">سُبَبَةٌ ضُرَعَةٌ</b> occurs in a trad. as meaning <i>A reviler of men, who becomes like them</i> and <i>equal to them.</i> (TA.)</p><p><b class=\"ar\">ضَرُوعٌ</b> : see <span class=\"ar\">ضَرَعٌ</span>.</p><p><b class=\"ar\">ضُرُوعٌ</b> pl. of <span class=\"ar\">ضَرْعٌ</span> [q. v.]. (O, Msb, K.) -b2- Also <i>A species of grape,</i> (AHn, O, K.) <i>growing in the Saráh</i> (<span class=\"ar\">السَّرَاة</span>), (AHn, O,) <i>white, large in the berries,</i> (AHn, O, K,) <i>having little juice, great in the bunches, like the sort of raisins called</i> <span class=\"ar\">طَائِفِىّ</span>. (O.) -A2- It is also a pl. of <span class=\"ar\">ضَارِعٌ</span> [as mentioned above, voce <span class=\"ar\">ضَرَعٌ</span>]. (TA.)</p><p><b class=\"ar\">ضَرِيعٌ</b> and <span class=\"ar\">ضَرِيعَةٌ</span> (IF, S O, K) and <span class=\"ar\"> <span class=\"ar\">ضَرْعَآءُ</span></span>, (O, K,) applied to a ewe or she-goat, <i>Large in the</i> <span class=\"ar\">ضَرْع</span> [or <i>udder</i>]; (IF, S, O, K;) and in like manner applied to a woman: (K:) or ↓ the last is applied to a woman as meaning <i>large in the breasts,</i> and in like manner to a ewe or she-goat: (IDrd, TA:) or, accord. to the L, the second and ↓ third, as first expl. above, are applied to a ewe or she-goat, and to a camel; and the first is applied to a ewe or she-goat, as meaning <i>goodly in the</i> <span class=\"ar\">ضَرْع</span>. (TA.) -A2- Also, the first of these words, (O, K;) mentioned in the Kur lxxxviii. 6, (O,) <i>i. q.</i> <span class=\"ar\">شِبْرِقٌ</span>; (O, K;) which is <i>A bad sort of pasture, upon which the pasturing cattle do not make</i> (<span class=\"ar\">لَا تَعْقِدُ</span>) <i>fat nor flesh, and which renders them in a bad condition if they do not quit it and betake themselves to other pasture;</i> (AHn, O;) or, accord. to IAth, the <span class=\"ar\">شبرق</span> is <i>a certain plant in El-Hijáz, having large thorns:</i> (TA:) or, the <i>plant called</i> <span class=\"ar\">شِبْرِق</span> <i>that is dried up;</i> (Fr, S, O, K;) <span class=\"ar\">شبرق</span> being its appellation when it is in its fresh state; (Fr, K, TA;) the people of El-Hijáz call it <span class=\"ar\">ضريع</span> in its dry state; (Fr, TA;) and it is [said to be] a plant which the beast will not approach, because of its bad quality: (K:) and (K) <i>what is dry of any tree;</i> (Ibn-'Abbád, O, K;) accord. to some, peculiarly, of the <span class=\"ar\">عَرْفَج</span> and <span class=\"ar\">خُلَّة</span>; (TA;) or [<i>any</i>] <i>dry herbage:</i> (TA in art. <span class=\"ar\">بحت</span>:) and, (K,) accord. to Lth, (O,) <i>a certain plant in water that has become altered for the worse by long standing or the like, having roots that reach not to the ground:</i> (O, K:) or <i>a certain thing in Hell, more bitter than aloes, and more stinking than the carcass, and hotter than fire;</i> (K, TA;) <i>the food of the inmates of Hell;</i> but this was unknown to the [pagan] Arabs: (TA:) and, (K,) as some say, (O,) <i>a certain plant,</i> (K, O,) <i>green,</i> (O,) thus in the L, but in the “ Mufradát ” <i>red,</i> (TA,) <i>of fetid odour, cast up by the sea,</i> (O, K,) <i>light, and hollow:</i> (TA:) and, (K,) accord. to Abu-l-Jowzà, (O,) the <i>prickles of the palm-tree:</i> (O, K:) and, (K,) accord. to IAar, (O,) the [<i>thorny tree called</i>] <span class=\"ar\">عَوْسَج</span>, <i>in its fresh state.</i> (O, K.) -b2- Also <i>Wine:</i> or <i>thin wine:</i> (K:) or <i>thin beverage.</i> (Ibn-'Abbád, O, K.) -b3- And the <i>skin that is upon the bone, beneath the flesh</i> (Lth, O, K) <i>of the rib:</i> (Lth, O:) or the <i>integument upon it.</i> (TA.)</p><p><b class=\"ar\">ضَارِعٌ</b> : see <span class=\"ar\">ضَرَعٌ</span>, in seven places. -b2- <span class=\"ar\">نُجُومٌ</span> <span class=\"ar\">ضَوَارِعُ</span> mean (tropical:) <i>Stars inclining to setting,</i> or <i>to the places of setting.</i> (A and TA in art. <span class=\"ar\">خضع</span>.)</p><p><b class=\"ar\">أَضْرَعُ</b> : see <span class=\"ar\">ضَرَعٌ</span>: -A2- and for its fem., <span class=\"ar\">ضَرْعَآءُ</span>, see <span class=\"ar\">ضَرِيعٌ</span>, in three places.</p><p><b class=\"ar\">مُضْرِعٌ</b> an epithet applied to a she-camel [and app. to a ewe or she-goat]: see 4.</p><p>[ <b class=\"ar\">مُضَرِّعٌ</b> part. n. of the intrans. verb <span class=\"ar\">ضَرَّعَ</span>. -b2- In the TA, voce <span class=\"ar\">كَثْءٌ</span>, <span class=\"ar\">مصرع</span>, which is evidently a mistranscription for <span class=\"ar\">مُضَرِّعٌ</span>, is expl. as an epithet applied to a preparation of <span class=\"ar\">أَقِط</span> (q. v.) as meaning <i>Such as has become thick,</i> or <i>coagulated, and almost thoroughly cooked:</i> on the authority of AHát.]</p><p><b class=\"ar\">المُضَارِعُ</b> [as a conventional term of grammar] <i>The future tense;</i> [or rather <i>the aorist;</i> for it is properly <i>the present,</i> and tropically <i>the future:</i>] so called because it resembles nouns in admitting the desinential syntactical signs. (TA.)</p><p><b class=\"ar\">مُسْتَضْرِعٌ</b> : see <span class=\"ar\">ضَرَعٌ</span>.</p>"},"ضغث":{"mf":"الضِّغْثُ: قبضةُ ريحانٍ، أو حشيشٍ أو قُضْبَانٍ، وجمعه: أَضْغَاثٌ. قال تعالى: وَخُذْ بِيَدِكَ ضِغْثاً<br>[ص/ ٤٤]، وبه شبّه الأحلام المختلطة التي لا يتبيّن حقائقها، قالُوا أَضْغاثُ أَحْلامٍ<br>[يوسف/ ٤٤] : حزم أخلاط من الأحلام.","mq":[["التباس الشي بعضه ببعض"],"الضاد والغين والثاء أصلٌ واحدٌ يدلُّ على التباسِ الشَّئِ بعضِه ببعض. يقال للحالم: أضْغَثْتَ الرُّؤيا. والأضغاث: الأحلام الملتبِسة.<br>والضِّغْث: قُبضة (٣) [من (٤)<br>] قُضْبان أو حشيش، قال الخليل: أصل واحد.<br>ويقال ناقة ضَغوثٌ، إذا شَكَكْتَ فى سِمَنها فلمستَ أَبها طِرْقٌ. والضَّغْثُ كالمَرْس.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَغَثَ الشَّىْءَ</b> , aor <b class=\"ar\">ضَغَثَ</b> , inf. n. <span class=\"ar\">ضَغْثٌ</span>, <i>He collected together the thing:</i> whence <span class=\"ar\">ضِغْثٌ</span> signifying “ a handful of herbs &amp;c. ” (Msb.) See also 2. -b2- And [hence,] <span class=\"ar\">ضَغَثَ الحَدِيثَ</span>, (A, K,) aor. as above, (K,) and so the inf. n., (S,) (tropical:) <i>He confused,</i> or <i>confounded,</i> [or <i>related in a confused manner,</i>] <i>the tradition,</i> or <i>story,</i> or <i>the like.</i> (S, A, K) -b3- And <span class=\"ar\">ضَغَثَ الثَّوْبَ</span> (tropical:) <i>He washed the garment,</i> or <i>piece of cloth, without cleansing it,</i> (O, K, TA,) <i>so that it remained in a dubious state.</i> (TA.) -A2- <span class=\"ar\">ضَغَثَ السَّنَامَ</span>, aor. as above, (K,) and so the inf. n., (S,) <i>He felt the camel's hump in order to know whether it were fat or not:</i> (S, K:) and <span class=\"ar\">ضَغَثَهَا</span> <i>he felt her</i> [i. e. a she-camel] <i>for that purpose.</i> (TA.) -A3- <span class=\"ar\">ضَغَثَ</span>, accord. to the K, [and the O, as on the authority of Fr,] is also said of a <span class=\"ar\">وَرَل</span>, meaning <i>It uttered a cry:</i> but this is correctly with <span class=\"ar\">ب</span> [i. e. <span class=\"ar\">ضَغَبَ</span>]. (TA.)</p><p><b>2.</b> <b class=\"ar\">ضغّث النَّبَاتَ</b> <i>He made the plants,</i> or <i>herbage, what are termed</i> <span class=\"ar\">أَضْعَاث</span> [pl. of <span class=\"ar\">ضِعْثٌ</span>]. (A, TA.) -b2- [Hence,] <span class=\"ar\">ضغّث رَأْسَهُ</span> (assumed tropical:) <i>He poured water upon his head, and then divided the hair with his fingers into separate handfuls, in order that the water might reach to the skin.</i> (L, TA.) [But see what follows.] It is said in a trad. of 'Áïsheh, <span class=\"ar\">كَانَتْ</span> <span class=\"ar\">تُضَغِّثُ رَأْسَهَا</span>, (TA,) or <span class=\"ar\"> <span class=\"ar\">تَضْغَثُ</span>رأسها</span>, (so in the JM,) meaning <i>She used to rub about the hair of her head with her hand, in washing, as though mixing it together, in order that the water with which she washed might enter into it.</i> (TA.)</p><p><b>4.</b> <b class=\"ar\">اضغث الرُّؤْيَا</b> , said of a dreamer, (tropical:) <i>He related the dream confusedly.</i> (A, TA.)</p><p><b>8.</b> <b class=\"ar\">اضطغث ضِغْثًا</b> <i>He collected a handful of herbage, fresh and dry mixed together.</i> (K.)</p><p><b class=\"ar\">ضَغْثٌ</b> The <i>state of</i> a thing's <i>being confused, one part with another.</i> (TA.)</p><p><b class=\"ar\">ضِغْثٌ</b> <i>A handful of herbs,</i> (AHn, S, A, Mgh, Msb, K,) <i>mixed together,</i> (S, A, Msb, K,) <i>fresh and dry:</i> (S, Msb, K:) or <i>a handful of twigs of trees</i> or <i>shrubs;</i> (Mgh, * Msb;) or <i>of fruit-stalks of the raceme of a palm-tree:</i> (Mgh, Msb:) originally, <i>a number of twigs all having one root</i> or <i>stem:</i> and afterwards applied to <i>what is collected together:</i> (Msb:) or <i>a thing that one collects together, such as a bundle of</i> [<i>the species of trefoil called</i>] <span class=\"ar\">رَطْبَة</span>; and <i>of what has a stem, and grows tall:</i> (Fr, TA:) or <i>whatever is collected together, and grasped with the hand:</i> (AHeyth, TA:) or <i>a bundle of herbs mixed together;</i> or <i>of firewood:</i> pl. <span class=\"ar\">أَضْغَاثٌ</span>. (TA.) In the Kur xxxviii. 43, it is said to mean <i>A bundle of rushes</i> (<span class=\"ar\">أَسَل</span>, so in the Mgh and the O, in my copy of the Msb <span class=\"ar\">اثل</span> [which I think a mistranscription, on account of what follows]), <i>a hundred in number,</i> (O, Msb,) <i>consisting of slender stalks without leaves,</i> (Mgh, Msb,) <i>whereof mats are made.</i> (Msb.) See also a prov. cited and expl. voce <span class=\"ar\">إِلَالَةٌ</span>. Hence, in a trad., <span class=\"ar\">ضِغْثَانِ مِنْ نَارٍ</span>, meaning (tropical:) <i>Two bundles of lighted firewood.</i> (TA.) And, in another trad., <span class=\"ar\">مِنْهُمُ الآخِذُ الضِّغْثَ</span>, meaning (assumed tropical:) <i>Among them is he who obtains somewhat of worldly goods.</i> (TA.) -b2- Also (assumed tropical:) <i>What is confused, and without truth,</i> or <i>reality,</i> [of dreams, and] of news, or tidings, and of an affair. (Sh, TA.) <span class=\"ar\">أَضْغَاثُ أَحْلَامٍ</span>, [occurring in the Kur xii. 44 and xxi. 5,] of which the sing. is <span class=\"ar\">ضِغْثُ حُلْمٍ</span>, (Msb,) means (tropical:) <i>Complications of dreams;</i> (A;) or <i>medleys of dreams, falsely resembling true dreams:</i> (O, Msb:) or <i>a dream of which the interpretation will not prove true, because of its confusedness:</i> (ISh, S, K:) or <i>a false dream;</i> the pl. form being used to give emphasis to the meaning of unreality, or because the phrase comprehends various things: (Bd in xii. 44:) or <span class=\"ar\">أَضْغَاثُ الرُّؤْيَا</span> means <i>the terrors,</i> or <i>frightful things, of the dream.</i> (Mujáhid, O, TA.) One says also, <span class=\"ar\">أَتَانَا بِأَضْغَاثٍ</span> <span class=\"ar\">مِنَ الأَخْبَارِ</span>, meaning (tropical:) <i>He brought us</i> [<i>various</i>] <i>sorts of news,</i> or <i>tidings.</i> (TA.) <span class=\"ar\">ضِغْثٌ</span> means also (assumed tropical:) <i>A deed that is of a mixed kind, not pure,</i> or <i>not sincere.</i> (IAth and O, from a trad.) And <span class=\"ar\">كَلَامٌ ضِغْثٌ</span> (assumed tropical:) <i>Speech in which is no good:</i> pl. <span class=\"ar\">أَضْغَاثٌ</span>. (TA.)</p><p><b class=\"ar\">ضَغُوثٌ</b> , applied to a she-camel, <i>i. q.</i> <span class=\"ar\">ضَبُوثٌ</span>; (S, K;) i. e. <i>Of which one doubts whether she be fat, and which one therefore feels with his hand;</i> (S;) or <i>of which one feels the hump, in order to know whether she be fat or not:</i> pl. <span class=\"ar\">ضُغْثٌ</span>. (TA.) And A camel's hump <i>of which one doubts whether it be fat or not.</i> (Kr, TA.)</p><p><b class=\"ar\">ضَغِيثَةٌ</b> <i>A confused company</i> of men. (O.)</p><p><b class=\"ar\">ضَاغِثٌ</b> One <i>who hides himself in a thicket</i> or <i>the like, and frightens boys by a sound reiterated in his fauces:</i> (S:) the author of the K, following Sgh in the TS and O, and Az in the T, says that this is a mistake, and that the word is correctly written with <span class=\"ar\">ب</span> [i. e. <span class=\"ar\">ضَاغِبٌ</span>]; but IF and IM and others write it as in the S. (TA.)</p><p><b class=\"ar\">تَضْغِيثٌ</b> <i>Rain that moistens the earth and the herbage.</i> (K.)</p>"},"ضمم":{"mf":"الضَّمُّ: الجمعُ بين الشّيئين فصاعدا. قال تعالى: وَاضْمُمْ يَدَكَ إِلى جَناحِكَ<br>[طه/ ٢٢]، وَاضْمُمْ إِلَيْكَ جَناحَكَ [القصص/ ٣٢]، والإِضْمَامَةُ: جماعةُ من النّاس أو من الكتب أو الرّيحان أو نحو ذلك <strong>«١»</strong>، وأسد ضَمْضَمٌ وضُمَاضِمٌ: يَضُمُّ الشّيءَ إلى نفسه.<br>وقيل: بل هو المجتمع الخلق، وفرس سبّاقُ الأَضَامِيمِ: إذا سبق جماعة من الأفراس دفعة واحدة.","mq":[["ملاءمة بين شييين"],"الضاد والميم أصلٌ واحد يدلُّ على مُلاءَمةٍ بين شيئين. يقال ضَمَمت الشّئ إلى الشئ فأنا أضُمُّه ضمًّا. وهذه إضْمامةٌ من خَيل، أى جماعة.<br>وفرسٌ سَبّاق الأضاميم، أى الجماعات. وإضمامةٌ من كُتُب مثل إضْبارة.<br>ومن الباب: أسد ضَمْضَم وضُماضِمٌ: يضمُّ كلَّ شئ.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَمَّهُ</b> , [aor. <b class=\"ar\">ضَمُمَ</b> ,] inf. n. <span class=\"ar\">ضَمٌّ</span>, <i>He drew it, put it, brought it,</i> or <i>gathered it, together; collected it;</i> or <i>contracted it.</i> (Msb.) You say, <span class=\"ar\">ضَمَّ شَيْئًا</span> <span class=\"ar\">إِلَى شَىْءٌ</span>, (S, MA, K,) [aor. and] inf. n. as above, <i>He drew, put,</i> or <i>brought, together</i> [<i>and joined</i> or <i>adjoined</i>] <i>a thing to a thing.</i> (MA, K.) And <span class=\"ar\">ضَمَمْتُهُ إِلَى صَدْرِى</span> [<i>I drew him,</i> or <i>pressed him, to my bosom;</i>] <i>I embraced him.</i> (TA.) And <span class=\"ar\">ضَمَّ القَوْمُ</span>, [<span class=\"ar\">أَنْفُسَهُمْ</span> being app. understood, or perhaps it is correctly <span class=\"ar\">ضُمَّ</span>,] <i>The people,</i> or <i>party, collected themselves together,</i> or <i>became collected.</i> (TA.) And <span class=\"ar\">اَللَّهُمَّ ٱضْمُمْ نَشَرِى</span> (assumed tropical:) <i>O God, compose what is discomposed,</i> or <i>disorganized,</i> [lit. <i>bring together what is scattered,</i>] <i>of my affairs.</i> (K * and TA in art. <span class=\"ar\">نشر</span>.) And <span class=\"ar\">ضُمَّ جَنَاحَكَ عَنِ</span> <span class=\"ar\">النَّاسِ</span> (assumed tropical:) [<i>Contract thy side from men;</i>] meaning <i>be thou gentle, courteous, easy to deal with,</i> or <i>compliant, to men.</i> (TA.) And <span class=\"ar\">ضُمَّتْ عَلَيْهِ</span> <span class=\"ar\">الأَنَامِلُ</span> <i>The ends of the fingers were drawn together upon it.</i> (Ham p. 21. [See also a similar phrase in what follows, with the verb in the act. form, virtually meaning the same.]) -b2- [Also <i>He compacted it:</i> and <i>he compressed it.</i> -b3- And <i>He,</i> or <i>it, comprised it;</i> or <i>enclosed it:</i> and <i>he grasped it:</i> as also <span class=\"ar\">ضَمَّ عَلَيْهِ</span>, in both of these senses.] You say, <span class=\"ar\">ضَمَّتْ عَلَيْهِ الأَنَامِلُ</span> <i>The ends of the fingers grasped it.</i> (Ham p. 21. [See a similar phrase above.]) And <span class=\"ar\">ضَمَّ عَلَى المَالِ</span> <i>He took</i> [or <i>grasped</i>] <i>all the property.</i> (TA.) And <span class=\"ar\">ضَمَّ مِنْ مَالِهِ</span> <i>He took of his property.</i> (TA.) -b4- [<span class=\"ar\">ضَمَّ الحَرْفَ</span>, aor. and inf. n. as above, a conventional phrase in lexicology and grammar, <i>He pronounced the letter with the vowel-sound termed</i> <span class=\"ar\">ضَمّ</span>: and <i>he marked the letter with the sign of that vowel-sound.</i>]</p><p><b>3.</b> <b class=\"ar\">ضامّهُ</b> , (S, MA, K, TA,) inf. n. <span class=\"ar\">مُضَامَّةٌ</span>, (TA,) <i>He became,</i> or <i>drew, near,</i> or <i>close, to him; he became conjoined with him;</i> (MA;) <i>i. q.</i><span class=\"ar\"> <span class=\"ar\">انضمّ</span>إِلَيْهِ</span>; (S, * MA, K; *) and <span class=\"ar\"> <span class=\"ar\">تضامّ</span></span>. (K.) And <span class=\"ar\">ضَامَمْتُ الرَّجُلَ</span> <i>I continued conjoined with the man occupied in one affair.</i> (TA.) And <span class=\"ar\">ضامّ الشَّىْءُ إِلَى الشَّىْءِ</span> <i>The thing became</i> [<i>adjoined to the thing,</i> or] <i>conjoined with the thing.</i> (TA.) See also 6.</p><p><b>4.</b> <b class=\"ar\">أَضْمَمْتُهُ كِتَابًا إِلَى أَخِى</b> [app. <i>I made him,</i> or <i>it, to be accompanied by,</i> or <i>I made it to comprise, a letter to my brother</i>]. (TA.)</p><p><b>5.</b> <b class=\"ar\">تَضَمَّمْتُهُ</b> <i>I took it,</i> or <i>devoured it, altogether.</i> (TA in art. <span class=\"ar\">عب</span>.) [See also R. Q. 1.]</p><p><b>6.</b> <b class=\"ar\">تَضَامُّوا</b> <i>They became,</i> or <i>drew, near,</i> or <i>close, together,</i> or <i>one to another;</i> or <i>became conjoined, one with another.</i> (S, MA, TA. [See also 8.]) Hence the saying in a trad., <span class=\"ar\">لَا تَضَامُّونَ فِى رُؤْيَتِهِ</span> [originally <span class=\"ar\">تَتَضَامُّونَ</span>]; but some relate it otherwise, saying <span class=\"ar\">لا <span class=\"ar\">تُضَامُّونَ</span></span>; and some, <span class=\"ar\">لا تُضَامُونَ</span>, from <span class=\"ar\">الضَّيْمُ</span>; (TA in this art.;) and some, <span class=\"ar\">لا</span> <span class=\"ar\">تُضَارُّونَ</span>; and some, <span class=\"ar\">لا تُضَارُونَ</span>, from <span class=\"ar\">الضَّيْرُ</span>. (TA in art. <span class=\"ar\">ضر</span>: for explanations, see 3 in that art.) See also 3 above. [Hence,] <span class=\"ar\">تضامّ فِى</span> <span class=\"ar\">سُجُودِهِ وَجُلُوسِهِ</span> [<i>He drew himself together in his prostration and his sitting,</i> in prayer]. (S, * and K in art. <span class=\"ar\">حفز</span>.)</p><p><b>7.</b> <b class=\"ar\">انضمّ</b> <i>It was,</i> or <i>became, drawn, put, brought,</i> or <i>gathered, together; collected;</i> or <i>contracted.</i> (Msb.) <span class=\"ar\">انضمّ إِلَيْهِ</span> is <i>syn. with</i> <span class=\"ar\">ضَامَّهُ</span>, q. v. (S, * MA, K. *) [And it signifies also <i>He adjoined himself, got him</i> or <i>got himself, betook him</i> or <i>betook himself, repaired,</i> or <i>resorted, to him,</i> or <i>it.</i> And <span class=\"ar\">انضمّ عَلَيْهِ</span> <i>It became drawn together upon it.</i> <span class=\"ar\">انضمّ الى كَذَا</span> is expl. in the TA as meaning <span class=\"ar\">اِنْطَوَى</span>: but I think that <span class=\"ar\">الى</span> is evidently a mistranscription for <span class=\"ar\">عَلَى</span>; and that the meaning therefore is, <i>It infolded such a thing,</i> or <i>enclosed it,</i> like <span class=\"ar\">اضطمّ عليه</span>, q. v.]</p><p><b>8.</b> <b class=\"ar\">اضطمّ الشَّىْءَ</b> <i>He drew, brought,</i> or <i>gathered, the thing to himself:</i> (K:) the <span class=\"ar\">ط</span> is substituted for <span class=\"ar\">ت</span> because of the <span class=\"ar\">ض</span>. (Az, TA.) -b2- Hence, in a trad., <span class=\"ar\">اضطمّ بَعْضُهُمْ إِلَى بَعْضٍ</span> [<i>They drew near,</i> or <i>close, one to another</i>]. (TA. [See also 6.]) And, in another trad., <span class=\"ar\">اضطمّ عَلَيْهِ النَّاسُ</span> <i>The people,</i> or <i>men, pushed, pressed, crowded,</i> or <i>thronged, together upon him.</i> (TA.) -b3- And <span class=\"ar\">اضطمّ عَلَيْهِ</span> <i>It comprised it,</i> or <i>enclosed it.</i> (K.) You say, <span class=\"ar\">اِضْطَمَّتْ عَلَيْهِ الضُّلُوعُ</span> <i>The ribs comprised it,</i> or <i>enclosed it.</i> (S. [See also 7.])</p><p><b>R. Q. 1.</b> <b class=\"ar\">ضَمْضَمَ عَلَى المَالِ</b> <i>He took all the property;</i> (K;) as though he drew it, or gathered it, (<span class=\"ar\">ضَمَّهُ</span>,) to himself. (TA.) [See also 5.] -b2- And <span class=\"ar\">ضَمْضَمَ</span> <i>He</i> (a man, TA) <i>encouraged his heat;</i> or <i>became courageous in heart.</i> (K, accord. to different copies.) -b3- And, said of a lion, <i>He</i> [<i>roared,</i> or] <i>uttered a cry:</i> (K, TA:) inf. n. <span class=\"ar\">ضَمْضَمَةٌ</span>. (TA.)</p><p><b class=\"ar\">ضَمٌّ</b> inf. n. of 1 [q. v.]. (Msb, &amp;c.) -b2- [As a conventional term of lexicology and grammar, <i>A certain vowel-sound, well known.</i>]</p><p><b class=\"ar\">الضِّمُّ</b> and <span class=\"ar\"> <span class=\"ar\">الضِّمَامُ</span></span> <i>Severe calamity</i> or <i>misfortune;</i> (K, TA;) accord. to Lth: (TA:) but app. mistranscriptions, and correctly with <span class=\"ar\">ص</span> [i. e. <span class=\"ar\">الصِّمُّ</span> and, by implication, <span class=\"ar\">الصِّمَامُ</span>, but the latter is app. only <span class=\"ar\">صَمَامِ</span>, without the art., like <span class=\"ar\">قَطَامِ</span>]; (K, TA;) so says Az. (TA.)</p><p><b class=\"ar\">ضَمَّةٌ</b> [inf. n. un. of 1 (q. v.): and as such signifying] <i>An embracing.</i> (TA.) -b2- Also <i>A number of horses assembled from every quarter for a race:</i> (K, TA:) thus called because so assembled. (TA.) -b3- [And, as a conventional term in lexicology and grammar, The <i>sign of the vowel-sound termed</i> <span class=\"ar\">ضَمّ</span>.]</p><p><b class=\"ar\">ضُمَامٌ</b> : see what next follows.</p><p><b class=\"ar\">ضِمَامٌ</b> , (S, KL,) with kesr; (S;) or <span class=\"ar\"> <span class=\"ar\">ضُمَامٌ</span></span>, like <span class=\"ar\">غُرَابٌ</span>; (K;) [the former app. the right, being agreeable with analogy, like <span class=\"ar\">رِبَاطٌ</span> and <span class=\"ar\">وِثَاقٌ</span> and <span class=\"ar\">إِسَارٌ</span> and <span class=\"ar\">عِقَالٌ</span> &amp;c.;] <i>A thing,</i> (S, K,) or <i>thread, string, cord,</i> or <i>the like,</i> (KL,) <i>by means of which one thing is drawn, and joined,</i> or <i>adjoined, to another thing.</i> (S, K, KL.) One says, <span class=\"ar\">التَّقْوَى ضِمَامُ الخَيْرِ كُلِّهِ</span> [<i>Piety is that which draws and attaches</i> to its possessor <i>every good thing</i>]. (TA.) -A2- See also <span class=\"ar\">الضِّمُّ</span>, above.</p><p><b class=\"ar\">ضَمُومٌ</b> <i>Any valley along which one goes between two long hills of the kind termed</i> <span class=\"ar\">أَكَمَة</span>: or <i>any valley flowing</i> [<i>with water</i>] <i>between two long hills of that kind:</i> (so accord. to different copies of the K:) [the former explanation is app. the right; for] AHn says, when one goes along a valley between two long hills of the kind termed <span class=\"ar\">أَكَمَة</span>, that places is termed <span class=\"ar\">الضَّمُوم</span>. (TA.)</p><p><b class=\"ar\">ضَمِيمٌ</b> [<i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَضْمُومٌ</span></span>]. One says, <span class=\"ar\">أَرْسَلْتُ فُلَانًا</span> <span class=\"ar\">وَجَعَلْتُ ضَمِيمَهُ فُلَانًا</span> [<i>I sent such a one, and made such a one his adjunct</i>]. (TA.)</p><p><b class=\"ar\">ضِمَامَةٌ</b> : see <span class=\"ar\">إِضْمَامَةٌ</span>. -b2- <span class=\"ar\">ضِمَامَتَا المُصْحَفِ</span> means <i>The two sides</i> [or <i>boards</i>] <i>of the book, that embrace it between them.</i> (T and M and TA voce <span class=\"ar\">دَفَّةٌ</span>.) And in like manner, <span class=\"ar\">ضِمَامَتَا السَّرْجِ</span> and <span class=\"ar\">الرَّحْل</span> [<i>The two boards of the horse's saddle</i> and <i>of the camel's saddle, that embrace it between them</i>]. (M ibid.)</p><p><b class=\"ar\">ضَمَّامٌ</b> One <i>who collects together the seed-produce.</i> (TA.)</p><p><b class=\"ar\">ضَامٌّ</b> act. part. n. of 1 [q. v.]. (TA.)</p><p><b class=\"ar\">ضَامَّةٌ</b> [a subst. from <span class=\"ar\">ضَامٌّ</span>, rendered such by the affix <span class=\"ar\">ة</span>]. You say, <span class=\"ar\">نَهَضَ فُلَانٌ لِلْقِتَالِ وَهُوَ ضَامَّةُ</span> <span class=\"ar\">قَوْمِهِ</span> [<i>Such a one rose and sped to fight,</i> or <i>to the fight, he being the musterer of his people,</i> or <i>party</i>]. (TA.) -b2- Also <i>A want,</i> or <i>an object of want, that brings one and causes him to have recourse</i> [<i>to a thing</i>]. (Meyd, in explanation of a prov. cited voce <span class=\"ar\">ضَائِمٌ</span>, in art. <span class=\"ar\">ضيم</span>, q. v.)</p><p><b class=\"ar\">ضَمْضَمٌ</b> A lion <i>that grasps everything;</i> as also <span class=\"ar\"> <span class=\"ar\">ضُمَاضِمٌ</span></span>. (S.) [See also <span class=\"ar\">ضَمْضَامٌ</span>: and see what here follows.] -b2- Also, (S,) <i>Angry;</i> (S, K;) applied to a man: (S:) and, as also <span class=\"ar\"> <span class=\"ar\">ضُمَاضِمٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">صُمَضِمٌ</span></span>, <i>an angry lion:</i> (K, TA:) or simply <i>a lion:</i> (TA:) and <i>bold,</i> or <i>daring;</i> (K, TA;) applied to a man. (TA.) -b3- And <i>Big, bulky,</i> or <i>corpulent:</i> (K, TA:) but it is mentioned by IAar as with the unpointed <span class=\"ar\">ص</span>. (TA.)</p><p><b class=\"ar\">ضُمَضِمٌ</b> : see <span class=\"ar\">ضَمْضَمٌ</span>. -b2- Also <i>Niggardly in the utmost degree.</i> (IAar, TA.) [See also <span class=\"ar\">ضُمَاضِمٌ</span>.]</p><p><b class=\"ar\">ضِمْضِمَةٌ</b> : see <span class=\"ar\">زِمْزِمَةٌ</span> and <span class=\"ar\">صِمْصِمَةٌ</span>.</p><p><b class=\"ar\">ضَمْضَامٌ</b> One <i>who takes,</i> or <i>gets, everything within his grasp;</i> (K, TA;) <i>drawing it to him self.</i> (TA.) [See also <span class=\"ar\">ضَمْضَمٌ</span>.]</p><p><b class=\"ar\">ضُمَاضِمٌ</b> : see <span class=\"ar\">ضَمْضَمٌ</span>, in two places. -b2- Also One <i>who eats much; who has an inordinate appetite for food; who appropriates to himself exclusively of others:</i> or <i>who eats much, and does not become satiated.</i> (TA.) -b3- And A <i>niggardly</i> man. (TA.) [See also <span class=\"ar\">ضُمَضِمٌ</span>.]</p><p><b class=\"ar\">إِضْمَامَةٌ</b> <i>A bundle,</i> (<span class=\"ar\">حُزْمَةٌ</span>, Msb,) or <i>number put,</i> or <i>joined, together,</i> (TA,) <i>i. q.</i> <span class=\"ar\">إِضْبَارَةٌ</span>, (S, TA,) of books or writings; (S, Msb, TA;) as also <span class=\"ar\"> <span class=\"ar\">ضِمَامَةٌ</span></span>: (TA:) pl. of the former <span class=\"ar\">أَضَامِيمُ</span>. (S.) You say, <span class=\"ar\">جَآءَ فُلَانٌ بِإِضْمَامَةٍ مِنْ كُتُبٍ</span> [<i>Such a one brought a bundle of books</i> or <i>writings</i>]. (S.) -b2- And <i>A company,</i> or <i>collection,</i> (S, K, TA,) of men, or people, <i>not of one stock, but of different tribes mixed together;</i> [and <i>of horses;</i>] as though collected and joined, one to another: pl. as above. (TA.) One says, <span class=\"ar\">فَرَسٌ سَبَّاقُ</span> <span class=\"ar\">الأَضَامِيمِ</span> i. e. [<i>A horse that often outstrips</i>] <i>the collections</i> (S, K) <i>of horses.</i> (K.) -b3- And its pl. <span class=\"ar\">أَضَامِيمُ</span> signifies also <i>Stones:</i> (TA:) or <i>collections of stones:</i> (Mgh in art. <span class=\"ar\">صقع</span>:) occurring in a trad. respecting the stoning of an adulterer. (Mgh, TA.)</p><p><b class=\"ar\">مَضَمٌّ</b> <i>A place of assembling</i> of military forces. (TA.)</p><p><b class=\"ar\">مَضْمُومٌ</b> pass. part. n. of 1 [q. v.]. (TA.) See also <span class=\"ar\">ضَمِيمٌ</span>.</p><p><b class=\"ar\">مُنْضَمٌّ</b> [part. n. of 7, q. v. -b2- Hence,] <i>Lean;</i> or <i>slender and lean;</i> or <i>lean, and lank in the belly;</i> as though one part thereof were drawn and adjoined to another. (TA.)</p>"},"ضغن":{"mf":"الضِّغْنُ والضَّغْنُ: الحِقْدُ الشّديدُ، وجمعه:<br>أَضْغَانٌ. قال تعالى: أَنْ لَنْ يُخْرِجَ اللَّهُ أَضْغانَهُمْ<br>[محمد/ ٢٩]، وبه شبّه الناقة، فقالوا: ذاتُ ضِغْنٍ <strong>«٢»</strong>، وقناةٌ ضَغِنَةٌ: عوجاءُ والإِضْغَانُ: الاشتمالُ بالثّوب وبالسّلاح ونحوهما.","mq":[["تغطية شي في ميل واعوجاج"],"الضاد والغين والنون أصلٌ صحيحٌ يدلُّ على تغطية شئٍ فى ميل واعوِجاج، ولا يدلُّ على خَير. من ذلك الضِّغْن والضَّغَن: الحِقْد.<br>وفرسٌ ضاغن، إذا كان لا يُعطِى ما عنده من الجرى إلاّ بالضَّرب. ويقال ضَغِن صدرُ فلانٍ ضِغْناً وضَغَنا. وقناةٌ ضَغِنةٌ: عَوجاء. ويقولون: ناقةٌ ذات ضِغْن، عند نزاعها إِلى وطَنِها."],"ln":"<p><b>1.</b> <b class=\"ar\">ضَغِنَ</b> , (AZ, S, Msb, K,) aor. <b class=\"ar\">ضَغَنَ</b> , (Msb, K,) inf. n. <span class=\"ar\">ضَغَنٌ</span> (AZ, S, Msb, TA) and <span class=\"ar\">ضِغْنٌ</span>, (AZ, TA,) or the latter is a simple subst., (Msb,) <i>He,</i> (S, K,) or <i>it,</i> i. e. one's bosom, (Msb,) <i>was,</i> or <i>became, affected with rancour, malevolence, malice,</i> or <i>spite;</i> (S, Msb, K;) or, said of a man, <i>his bosom was,</i> or <i>became, affected therewith;</i> (AZ, TA;) <span class=\"ar\">عَلَيْهِ</span> <i>against him.</i> (S.) [See also <span class=\"ar\">ضِغْنٌ</span> below.] -b2- And, (IAar, S, K,) aor. and inf. ns. as above, (TA,) <i>He inclined,</i> (IAar, S, K, TA,) <span class=\"ar\">إِلَيْهِ</span> <i>towards him,</i> (IAar, TA,) and <span class=\"ar\">عَلَيْهِ</span> <i>against him,</i> (TA,) and <span class=\"ar\">إِلَى الدُّنْيَا</span> [<i>towards the present world,</i> or <i>worldly things</i>]. (S, K.) And <span class=\"ar\">ضَغِنَتِ</span> <span class=\"ar\">القَنَاةُ</span>, inf. n. <span class=\"ar\">ضَغَنٌ</span>, (tropical:) <i>The spear-shaft was,</i> or <i>became, crooked.</i> (TA.) -b3- Also, (K, TA,) aor. and inf. ns. as above, (TA,) <i>He was,</i> or <i>became, affected with desire,</i> or <i>with yearning</i> or <i>longing of the soul.</i> (K, TA.)</p><p><b>6.</b> <b class=\"ar\">تَضَاغُنٌ</b> The <i>conceiving,</i> or <i>being affected with, mutual rancour, malevolence, malice,</i> or <i>spite.</i> (KL, and Har p. 43.) You say, <span class=\"ar\">تضاغنوا</span> and <span class=\"ar\"> <span class=\"ar\">اضطغنوا</span></span> <i>They had,</i> or <i>held, in the heart, feelings of mutual rancour, malevolence, malice,</i> or <i>spite.</i> (S, K.)</p><p><b>8.</b> <b class=\"ar\">إِضْتَغَنَ</b> see what next precedes. -b2- One says also, <span class=\"ar\">اضطغن عَلَى فُلَانٍ ضَغِينَةً</span> <i>He conceived,</i> or <i>concealed,</i> [<i>in his heart,</i>] <i>rancour, malevolence, malice,</i> or <i>spite, against such a one.</i> (TA.) -b3- And <span class=\"ar\">اضطغنهُ</span> <i>He took it</i> (i. e. a thing, and weapon, S) <i>beneath his</i> <span class=\"ar\">حِضْن</span> [or <i>the part between his armpit and flank,</i> &amp;c.]: (S, K:) and <i>he carried him</i> (i. e. a child) <i>in that part,</i> or <i>in his bosom.</i> (TA.) -b4- <span class=\"ar\">الاِضْطِغَانُ</span> is also <i>syn. with</i> <span class=\"ar\">الاِشْتِمَالُ</span>, which is <i>The putting</i> [<i>a portion of</i>] <i>the garment beneath</i> [<i>and within</i>] <i>the right arm,</i> [app. <i>from behind,</i>] <i>and the other end beneath the left arm, and drawing it</i> [i. e. <i>the garment</i>] <i>together with the left hand.</i> (TA. [But see <span class=\"ar\">اِشْتَمَلَ</span>.])</p><p><b class=\"ar\">ضِغْنٌ</b> [said by some to be an inf. n.: (see 1:)] <i>Rancour, malevolence, malice,</i> or <i>spite;</i> (S, Msb, K;) as also <span class=\"ar\"> <span class=\"ar\">ضَغِينَةٌ</span></span>: (S, K:) or both signify <i>vehement rancour</i> &amp;c.; and <i>enmity;</i> and <i>violent hatred:</i> (TA:) the pl. of the former is <span class=\"ar\">أَضْغَانٌ</span>; (MA, Msb;) and that of ↓ the latter is <span class=\"ar\">ضَغَائِنُ</span>, (MA,) and <span class=\"ar\"> <span class=\"ar\">ضَغِينٌ</span></span> may be a pl. of <span class=\"ar\">ضَغِينَةٌ</span>, [or rather a coll. gen. n.,] or the <span class=\"ar\">ة</span> may be elided by poetic license; or these two may be dial. vars., like <span class=\"ar\">حُقٌّ</span> and <span class=\"ar\">حُقَّةٌ</span> [accord. to some], and <span class=\"ar\">بَيَاضٌ</span> and <span class=\"ar\">بَيَاضَةٌ</span>. (TA.) One says, when he has sought to gain a person's good will, or approval, <span class=\"ar\">سَلَلْتُ ضِغْنَ فُلَانٍ</span> and <span class=\"ar\"> <span class=\"ar\">ضَغِينَتَهُ</span></span> [<i>I drew forth the rancour,</i> &amp;c., <i>of such a one</i>]. (TA.) And a woman who hates her husband is said to be <span class=\"ar\">ذَاتُ ضِغْنٍ عَلَى زَوْجِهَا</span> [<i>One who has a feeling of rancour,</i> &amp;c., <i>against her husband</i>]. (TA.) -b2- And <i>Difficulty of disposition</i> in a beast: so in the phrase <span class=\"ar\">ذَاتُ ضِغْنٍ</span> [A beast (<span class=\"ar\">دَابَّةٌ</span>) <i>having a difficult disposition</i>]. (TA.) See also the phrase <span class=\"ar\">ذَاتُ شَغْبٍ وَضِغْنٍ</span>, applied to a she-ass, in art. <span class=\"ar\">شغب</span>. -b3- And <i>Inclination.</i> (S, K.) One says, <span class=\"ar\">ضِغْنِى إِلَى فُلَانٍ</span> <i>My inclination is towards such a one.</i> (S.) -b4- And <i>Desire;</i> or <i>yearning</i> or <i>longing of the soul.</i> (K, TA.) One says <span class=\"ar\">نَاقَةٌ ذَاتُ</span> <span class=\"ar\">ضِغْنٍ</span> meaning <i>A she-camel yearning towards,</i> or <i>longing for, her home,</i> or <i>accustomed place,</i> (S, TA,) <i>and her mates.</i> (S. [See a verse cited voce <span class=\"ar\">رِفَاقٌ</span>.]) And sometimes <span class=\"ar\">ضِغْنٌ</span> is thus used, metaphorically, in relation to women. (TA.) -A2- Also <i>A side;</i> or <i>a region, quarter,</i> or <i>tract;</i> syn. <span class=\"ar\">نَاحِيَةٌ</span>. (K.) -b2- And The <span class=\"ar\">إِبْط</span> [i. e. <i>foot, bottom,</i> or <i>lowest part,</i>] <i>of a mountain:</i> thus correctly, as in the “ Nawádir: ” in the copies of the K, <span class=\"ar\">الجَمَل</span> is erroneously put for <span class=\"ar\">الجَبَل</span>. (TA.)</p><p><b class=\"ar\">ضَغِنٌ</b> <i>Affected with rancour, malevolence, malice,</i> or <i>spite;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَاغِنٌ</span></span>. (Msb.) -b2- And <span class=\"ar\">قَنَاةٌ ضَغِنَةٌ</span> (tropical:) <i>A crooked spear-shaft.</i> (S, K, TA.) -b3- See also <span class=\"ar\">ضَاغِنٌ</span>.</p><p><b class=\"ar\">ضَغُونٌ</b> A horse, and a mare, <i>that runs like him who reverts from the state in which he was,</i> or <i>from the course that he was following.</i> (AO, TA. [See also <span class=\"ar\">ضَاغِنٌ</span>.])</p><p><b class=\"ar\">ضَغِينٌ</b> : see <span class=\"ar\">ضِغْنٌ</span>.</p><p><b class=\"ar\">ضَغِينَةٌ</b> : see <span class=\"ar\">ضِغْنٌ</span>, in three places.</p><p><b class=\"ar\">الضَّغِينِىُّ</b> <i>The lion:</i> (K, TA:) as though a rel. n. from <span class=\"ar\">الضَّغِينَةُ</span>: because he is very rancorous, malevolent, malicious, or spiteful. (TA.)</p><p><b class=\"ar\">ضَاغِنٌ</b> : see <span class=\"ar\">ضَغِنٌ</span>. -b2- Also A horse <i>that will not exert his power of running unless beaten;</i> (S, K, TA;) and so <span class=\"ar\"> <span class=\"ar\">ضَغِنٌ</span></span>. (S, * TA. [See also <span class=\"ar\">ضَغُونٌ</span>.])</p><p><b class=\"ar\">مُضَاغِنٌ</b> One <i>who treats,</i> or <i>regards, his brother with rancour, malevolence, malice,</i> or <i>spite,</i> or <i>with enmity, being so regarded,</i> or <i>treated, by him;</i> as also <span class=\"ar\"> <span class=\"ar\">مُضْطَغِنٌ</span></span>. (TA.)</p><p><b class=\"ar\">مُضْطَغِنٌ</b> : see what next precedes.</p>"},"ضأن":{"mf":"الضَّأْنُ معروفٌ. قال تعالى: مِنَ الضَّأْنِ اثْنَيْنِ [الأنعام/ ١٤٣]، وأَضْأَنَ الرّجلُ: إذا كثر ضَأْنُهُ، وقيل: الضَّائِنَةُ واحد الضَّأْنِ.","mq":[["بعض الانعام"],"الضاد والهمزة والنون أُصَيل صحيح، وهو بعض الأنعام.<br>من ذلك الضأن. يقال أضْأنَ الرجلُ، إذا كثُرَ ضأنُه. والضائنة الواحدة من الضأن. وحكى بعضُهم: فلان ضائن البطنِ: مسترخِيهِ.<br>[باب الضاد والباء وما يثلثهما]<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَأَنْتُ الضَّأْنَ</b> <i>I set apart the sheep</i> [<i>from</i> the goats]. (Az, TA, and K in art. <span class=\"ar\">معز</span>.) One says, <span class=\"ar\">اِضْأَنْ ضَأْنَكَ وَٱمْعَزْ مَعْزَكَ</span> <i>Set apart thy sheep from the goats, and set apart thy goats from the sheep.</i> (Az, TA.)</p><p><b>4.</b> <b class=\"ar\">اضأن</b> , (S, M, K,) said of a man, (S,) or of a party of men, (M,) <i>His,</i> or <i>their,</i> <span class=\"ar\">ضَأْن</span> [or <i>sheep</i>] <i>became numerous.</i> (S, M, K.)</p><p><b class=\"ar\">ضَأْنٌ</b> (S, M, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ضَأَنٌ</span></span> (S, M, K) and <span class=\"ar\"> <span class=\"ar\">ضَئِينٌ</span></span>, (S, M, Msb, K,) which is also pronounced <span class=\"ar\"> <span class=\"ar\">ضِئِينٌ</span></span>, with kesr to the first letter because of the kesr following, agreeably with a general rule applying to a word [of the measure <span class=\"ar\">فَعِيلٌ</span>] having any faucial letter [for its second radical], and <span class=\"ar\"> <span class=\"ar\">ضِينٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَيْنٌ</span></span>, which are mentioned by IAar, without <span class=\"ar\">ء</span>, and therefore extr., (M,) [<i>Sheep;</i>] <i>such as have wool, of what are termed</i> <span class=\"ar\">غَنَم</span>; one of which is called <span class=\"ar\"> <span class=\"ar\">ضَائِنٌ</span></span>; (Msb;) [i. e.] they are pls., (S, K,) or [rather] quasi-pl. ns., (M,) of <span class=\"ar\"> <span class=\"ar\">ضَائِنٌ</span></span>, (S, M, K,) which signifies <i>one that has wool,</i> (M,) or the <i>opposite of</i> <span class=\"ar\">مَاعِزٌ</span>, (S, K,) <i>of what are termed</i> <span class=\"ar\">غَنَم</span>: (M, K:) <span class=\"ar\">ضَأْنٌ</span> is of the fem. gender; (IAmb, Msb;) and has for its pl. <span class=\"ar\">أَضْؤُنٌ</span> [properly a pl. of pauc.] (IAmb, M, Msb) and <span class=\"ar\">آضُنٌ</span>, which occurs in poetry, and is formed by transposition from <span class=\"ar\">أَضْؤُنٌ</span>: (M:) the fem. of <span class=\"ar\"> <span class=\"ar\">ضَائِنٌ</span></span> is <span class=\"ar\">ضَائِنَةٌ</span>; (S, M, Msb, K;) the pl. of which is <span class=\"ar\">ضَوَائِنُ</span>. (S, M, K.) -b2- <span class=\"ar\">ضَأْنٌ</span> also signifies <i>A certain species of</i> [<i>the lizards called</i>] <span class=\"ar\">ضِبَاب</span> [pl. of <span class=\"ar\">ضَبٌّ</span>]; opposed to the <span class=\"ar\">مَاعِز</span>. (TA.) And <i>A certain species of jerboas, also called</i> <span class=\"ar\">شُفَارِىٌّ</span>; (T voce <span class=\"ar\">تَدْمُرِىٌّ</span>, q. v.; and TA in art. <span class=\"ar\">شفر</span>;) <i>differing from the</i> <span class=\"ar\">مَاعِز</span> thereof. (T and TA in art. <span class=\"ar\">دمر</span>.)</p><p><b class=\"ar\">ضَأَنٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ضَيْنٌ</b> and <span class=\"ar\">ضِينٌ</span>: see <span class=\"ar\">ضَأْنٌ</span>.</p><p><b class=\"ar\">ضَأْنَةٌ</b> <i>A</i> [<i>ring for the nose of a camel, such as is termed</i>] <span class=\"ar\">خِزَامَة</span>, <i>when made of sinew.</i> (Sh, K.) [But see <span class=\"ar\">ضَانَةٌ</span>, in art. <span class=\"ar\">ضون</span>.]</p><p><b class=\"ar\">ضِئْنِىٌّ</b> is an extr., distorted, rel. n. [from <span class=\"ar\">ضَأْنٌ</span>]. (M.) You say <span class=\"ar\">مِعْزًى ضِئْنِيَّةٌ</span> <i>Goats that keep to the</i> <span class=\"ar\">ضَأْن</span> [or <i>sheep</i>]. (M.) And <span class=\"ar\">سِقَآءٌ ضِئْنِىٌّ</span> <i>A wide,</i> (M,) or <i>large,</i> (K,) <i>skin, of the hide of a sheep,</i> (M, K,) <i>in which</i> [<i>milk such as is termed</i>] <span class=\"ar\">رَائِب</span> <i>is churned.</i> (K.)</p><p><b class=\"ar\">ضَئِينٌ</b> and <span class=\"ar\">ضِئِينٌ</span>: see <span class=\"ar\">ضَأْنٌ</span>.</p><p><b class=\"ar\">ضَائِنٌ</b> : see <span class=\"ar\">ضَأْنٌ</span>, in three places. -b2- It is also used as an epithet: one says <span class=\"ar\">كَبْشٌ ضَائِنٌ</span> [app. meaning <i>A ram:</i> <span class=\"ar\">كَبْشٌ</span> alone having several meanings]. (M.) -b3- And it signifies also (tropical:) <i>Weak:</i> (K, TA:) [opposed to <span class=\"ar\">مَاعِزٌ</span>:] or a <i>soft</i> man, as though he were a ewe: (M, TA:) or one <i>who ceases not to be goodly in body while a scanty eater:</i> (M, K: *) or <i>soft and flaccid in the belly.</i> (M, K. *) -b4- And (assumed tropical:) <i>Such as is white and broad,</i> of sands. (K, TA.)</p>"},"ضفدع":{"ln":"<p><b>Q. 1.</b> <b class=\"ar\">ضَفْدَعَ</b> , said of water, <i>It had in it</i> <span class=\"ar\">ضَفَادِع</span> [or <i>frogs</i>]. (O, K.) -A2- And, said of a man, <i>He shrank,</i> or <i>became contracted;</i> syn. <span class=\"ar\">تَقَبَّضَ</span>: or <i>he voided his excrement,</i> or <i>ordure;</i> or <i>thin excrement;</i> syn. <span class=\"ar\">سَلَحَ</span>: or <i>he emitted wind from the anus, with a sound.</i> (TA.)</p><p><b class=\"ar\">ضِفْدِعٌ</b> (S, O, Msb, K) and <span class=\"ar\">ضَفْدَعٌ</span> and <span class=\"ar\">ضُفْدَعٌ</span> (K) and <span class=\"ar\">ضِفْدَعٌ</span>, (S, O, Msb, K,) this last said by some, (S, O, Msb,) but most rare, or rejected, (K,) disallowed by Kh and a number of others, (Msb,) [for] accord. to Kh [and others] there are only four words of the measure <span class=\"ar\">فِعْلَلٌ</span> in the language, which are <span class=\"ar\">دِرْهَمٌ</span> and <span class=\"ar\">هِجْرَعٌ</span> and <span class=\"ar\">هِبْلَعٌ</span> and the proper name <span class=\"ar\">قِلْعَمٌ</span>, (S, O,) [The <i>frog;</i> and app. also the <i>water-toad;</i>] <i>a certain reptile</i> (<span class=\"ar\">دَابَّة</span>) <i>of the rivers,</i> (K, TA,) <i>generated in the river,</i> (TA,) <i>the flesh of which, cooked with oliveoil, is</i> [<i>said to be</i>] <i>an antidote to the poison of venomous creatures,</i> (K, TA,) <i>when put upon the place of the sting,</i> or <i>bite:</i> (TA:) and [<i>a certain reptile</i>] <i>of the land,</i> (K, TA,) [app. the <i>landtoad,</i>] <i>that lives,</i> or <i>grows, in caverns and caves,</i> (TA,) <i>the fat of which is</i> [<i>said to be</i>] <i>wonderful for the extraction of teeth</i> (K, TA) <i>without fatigue, and of the skin of which, tanned, the skull-cap that renders invisible</i> (<span class=\"ar\">طَاقِيَّةُ الإِخْفَآءِ</span> [a vulgar term]) <i>is made, as is said by the performers of legerdemain; and the flesh of this species is said to be poisonous:</i> (TA;) the fem., (S, O, Msb,) or the n. un., (K,) is with <span class=\"ar\">ة</span>: and the pl. is <span class=\"ar\">ضَفَادِعُ</span> (S, O, Msb, K) [and <span class=\"ar\">ضَفَادٍ</span>; in the Msb and K, <span class=\"ar\">ضَفَادِى</span>; in the O, correctly, <span class=\"ar\">الضَّفَادِى</span> is said to be a var. of <span class=\"ar\">الضَّفَادِعُ</span>, like <span class=\"ar\">الثَّعَالِى</span> and <span class=\"ar\">الأَرَانِى</span> of <span class=\"ar\">الثَّعَالِبُ</span> and <span class=\"ar\">الأَرَانِبُ</span>]. -b2- <span class=\"ar\">نَقَّتْ ضَفَادِعُ بَطْنِهِ</span> [lit. <i>The frogs of his belly croaked</i>] means (assumed tropical:) <i>he was,</i> or <i>became, hungry;</i> (O, K;) like <span class=\"ar\">نَقَّتْ عَصَافِيرُ بَطْنِهِ</span>. (O.) -b3- <span class=\"ar\">الضِّفْدِعُ الأَوَّلُ</span> is a name of (assumed tropical:) <i>The bright star</i> [ <b class=\"ar\">α</b>] <i>on the mouth of Piscis Australis;</i> (Kzw, Descr. of Aquarius;) <i>also called</i> <span class=\"ar\">فَمُ الحُوتِ</span>: (Idem, Descr. of Piscis Australis:) and <span class=\"ar\">الضِّفْدِعُ الثَّانِى</span> is the name of (assumed tropical:) <i>The star on the southern fork of the tail of Cetus.</i> (Idem.) -b4- And <span class=\"ar\">الضِّفْدِعُ</span>, (O, K,) thus only, (TA,) (assumed tropical:) <i>A certain bone</i> [or <i>horny substance,</i> which we, in like manner, call “ <i>the frog,</i> ”] <i>in the interior of the horse's hoof,</i> (O, K,) <i>in the sole thereof.</i> (O.) [See also <span class=\"ar\">نَسْرٌ</span>.]</p><p><b class=\"ar\">مُضَفْدِعَاتٌ</b> Waters <i>abounding with</i> <span class=\"ar\">ضَفَادِع</span> [or <i>frogs</i>]. (S, O.)</p>"},"ضهأ":{"ln":"<p><b>3.</b> <b class=\"ar\">مُضَاهَأَةٌ</b> is <i>syn. with</i> <span class=\"ar\">مُضَاهَاةٌ</span>, (K, TA, [the <span class=\"ar\">و</span> before <span class=\"ar\">المُضاهاةُ</span> in the CK should be erased,]) <i>i. q.</i> <span class=\"ar\">مُشَاكَلَةٌ</span>: (S, O, Msb, TA:) you say, <span class=\"ar\">ضَاهَأْتُهُ</span> and <span class=\"ar\">ضَاهَيْتُهُ</span>, ('Eyn, S, * O, * Msb, * TA,) i. e. <i>I resembled him;</i> syn. <span class=\"ar\">شَابَهْتُهُ</span>: ('Eyn, TA:) [or <i>I conformed with him:</i>] or <span class=\"ar\">ضَاهَأَهُ</span>, inf. n. as above, signifies <i>he imitated him;</i> syn. <span class=\"ar\">عَارَضَهُ</span> and <span class=\"ar\">بَارَاهُ</span>; and one says also, <span class=\"ar\">ضَاهَيْتُهُ</span>, inf. n. <span class=\"ar\">مُضَاهَاةٌ</span>: (Msb:) the verb is read both with and without <span class=\"ar\">ء</span> in the Kur [ix. 30]. (O, Msb, TA.) -b2- <span class=\"ar\">ضَاهَا بِهِ</span>, (A 'Obeyd, TA,) [or <span class=\"ar\">ضَاهَأَهُ</span>, like <span class=\"ar\">ضَاهَاهُ</span>, mentioned in art. <span class=\"ar\">ضهى</span>,] inf. n. as above, (K,) <i>He</i> (a man) <i>was,</i> or <i>became, gentle, tender,</i> or <i>courteous,</i> or <i>he acted,</i> or <i>behaved, gently,</i> &amp;c., <i>with him,</i> or <i>to him.</i> (A 'Obeyd, K, * TA.)</p><p><b class=\"ar\">ضَهْيَأٌ</b> and <span class=\"ar\">ضَهْيَأَةٌ</span>: see art. <span class=\"ar\">ضهيأ</span>.</p>"},"ضدد":{"mf":"قال قوم: الضِّدَّانِ الشيئان اللّذان تحت جنس واحدٍ <strong>«٢»</strong>، وينافي كلّ واحد منهما الآخر في أوصافه الخاصّة، وبينهما أبعد البعد كالسّواد والبياض، والشّرّ والخير، وما لم يكونا تحت جنس واحد لا يقال لهما ضِدَّانِ، كالحلاوة والحركة. قالوا: والضِّدُّ هو أحد المتقابلات، فإنّ المتقابلين هما الشيئان المختلفان، اللّذان كلّ واحد قبالة الآخر، ولا يجتمعان في شيء واحد في وقت واحد، وذلك أربعة أشياء:<br>الضِّدَّانِ كالبياض والسّواد، والمتناقضان:<br>كالضّعف والنّصف، والوجود والعدم، كالبصر والعمى، والموجبة والسّالبة في الأخبار، نحو: كلّ إنسان هاهنا، وليس كلّ إنسان هاهنا <strong>«٣»</strong>. وكثير من المتكلّمين وأهل اللغة يجعلون كلّ ذلك من المُتَضَادَّاتِ، ويقولون: الضِّدَّانِ ما لا يصحّ اجتماعهما في محلّ واحد. وقيل: الله تعالى لا ندّ له ولا ضِدَّ، لأنَّ النِّدَّ هو الاشتراك في الجوهر، والضِّدَّ هو أن يعتقب الشيئان المتنافيان على جنس واحد، والله تعالى منزّه عن أن يكون جوهرا، فإذا لا ضِدَّ له ولا ندّ، وقوله:<br>وَيَكُونُونَ عَلَيْهِمْ ضِدًّا [مريم/ ٨٢]، أي:<br>منافين لهم.","mq":[["في القياس"],"الضاد والدال كلمتان متباينتان فى القياس.<br>فالأولى: الضِّدّ ضِدّ الشئ. والمتضادّان: الشَّيئان لا يجوز اجتماعهما فى وقتٍ واحد، كالليل والنَّهار.<br>والكلمة الأخرى الضَّدُّ، وهو المَلْ ء، بفتح الضاد، يقال ضَدَّ القِربةَ:<br>ملأها، ضَدًّا.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَدَّهُ</b> , (AZ, K,) first pers. <span class=\"ar\">ضَدَدْتُهُ</span>, [aor. <b class=\"ar\">ضَدُدَ</b> ,] inf. n. <span class=\"ar\">ضَدٌّ</span>, <i>He overcame him:</i> (AZ, L:) and also, (AZ, L,) or <span class=\"ar\">ضَدَّهُ فِى الخُصُومَةِ</span>, (K,) <i>He overcame him in litigation, altercation,</i> or <i>contention.</i> (AZ, L, K.) -b2- And <span class=\"ar\">ضَدَّهُ عَنْهُ</span> <i>He averted him; turned him,</i> or <i>sent him, away,</i> or <i>back;</i> or <i>caused him to return,</i> or <i>go back,</i> or <i>revert; from it:</i> (L, K:) i. e., a thing, or an affair: (L:) and <i>prevented,</i> or <i>hindered, him from doing it;</i> (K;) <i>by gentle means:</i> (L, K:) as also <span class=\"ar\">صَدَّهُ</span>: heard by Aboo-Turáb from Záïdeh. (L.) -A2- <span class=\"ar\">ضَدَّ القِرْبَةِ</span>, (S, K,) aor. <b class=\"ar\">ضَدُدَ</b> , (S,) inf. n. <span class=\"ar\">ضَدٌّ</span>, (AA, S,) <i>He filled the water-skin.</i> (S, K.)</p><p><b>3.</b> <b class=\"ar\">ضادّهُ</b> , (inf. n. <span class=\"ar\">مُضَادَّةٌ</span>, Msb,) <i>He,</i> or <i>it, was,</i> or <i>became, contrary, opposed,</i> or <i>repugnant, to him,</i> or <i>it;</i> (AHeyth, S, * L, K;) said with respect to two men when one desires what is long, and the other, what is short; or one, darkness, and the other, light; or one, to pursue one course, and the other, to pursue another: (AHeyth, L:) or <i>he,</i> or <i>it, was,</i> or <i>became, separated from him,</i> or <i>it, by contrariety, opposition,</i> or <i>repugnance:</i> (Msb:) [or, accord. to the explanation of <span class=\"ar\">مُتَضَادَّانِ</span> in the Msb, <i>it was,</i> or <i>became inconsistent with it.</i>]</p><p><b>4.</b> <b class=\"ar\">اضدّ</b> <i>He</i> (a man, S) <i>was,</i> or <i>became, angry.</i> (S, K.) It is not, as some assert it to be, a quasi-pass. [of <span class=\"ar\">ضَدَّهُ</span>], like as <span class=\"ar\">أَكَبَّ</span> is of <span class=\"ar\">كَبَّهُ</span>. (TA.)</p><p><b>6.</b> <b class=\"ar\">تَضَاْدَدَ</b> [<span class=\"ar\">تضادّا</span> <i>They two were,</i> or <i>became, contrary, opposed,</i> or <i>repugnant, each to the other:</i> or, accord. to the explanation of <span class=\"ar\">مُتَضَادَّانِ</span> in the Msb, <i>they two were,</i> or <i>became, inconsistent, each with the other.</i>]</p><p><b class=\"ar\">ضِدٌّ</b> (S, L, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ضَدِيدٌ</span></span> (S, L, K) and <span class=\"ar\"> <span class=\"ar\">ضَدِيدَةٌ</span></span> (Th, M) The <i>contrary,</i> or <i>opposite,</i> (AA, IAar, S, * M, Msb, K,) of a thing: (AA, Msb:) or <span class=\"ar\">ضِدُّ شَىْءٍ</span> signifies <i>that which is repugnant to a thing, so that it would overcome it;</i> as black is to white, and death to life: (Lth, L:) [or, accord. to the explanation of <span class=\"ar\">مُتَضَادَّانِ</span> in the Msb, <i>that which is inconsistent with a thing:</i>] pl. of the first <span class=\"ar\">أَضَدَادٌ</span>. (S, Msb, &amp;c.) One says also, <span class=\"ar\">هُوَ ضِدُّكَ</span> and <span class=\"ar\"> <span class=\"ar\">ضَدِيدُكَ</span></span> <i>He is contrary,</i> or <i>opposed,</i> or <i>repugnant, to thee;</i> as when thou desirest what is long, and he, what is short; or thou, darkness, and he, light; or thou, to pursue one course, and he, to pursue another. (AHeyth, L.) And <span class=\"ar\">ضِدٌّ</span> is sometimes a pl., (K,) or sometimes denotes a collective body; (Akh, S, L;) as in the phrase <span class=\"ar\">يَكُونُونَ عَلَيْهِمْ ضِدًّا</span>, (S, L, K,) in the Kur [xix. 85], (S, L,) meaning <i>They shall be adversaries,</i> or <i>enemies, to them:</i> ('Ikrimeh, Jel:) or <i>helpers against them.</i> (Fr, Jel.) One says also, <span class=\"ar\">القَوْمُ</span> <span class=\"ar\">عَلَىَّ ضِدٌّ وَاحِدٌ</span>, meaning <i>The people are assembled together against me in contention,</i> or <i>altercation, with me.</i> (L.) -b2- <span class=\"ar\">ضِدٌّ</span> in lexicology signifies <i>A kind of</i> <span class=\"ar\">مُشْتَرَك</span> [or <i>homonym</i>]; being <i>a word that has two contrary meanings;</i> as <span class=\"ar\">جَوْنٌ</span>, which means both “ black ” and “ white; ” and <span class=\"ar\">جَلَلٌ</span>, which means both “ great ” and “ small ” pl. as above. (Mz, 26th <span class=\"ar\">نوع</span>.) [<span class=\"ar\">ضِدٌّ</span> is itself a word of this kind, as is shown by what here follows.] -b3- Also, (AA, Th, S, L, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">ضَدِيدٌ</span></span>, (S, L, K,) The <i>like,</i> or <i>equal,</i> (AA, Th, S, L, Msb, K,) of a thing. (AA, Msb.) Thus they have two contrary meanings. (K.) One says, <span class=\"ar\">لَا ضِدَّ لَهُ</span> and <span class=\"ar\">لَا <span class=\"ar\">ضَدِيدَ</span>لَهُ</span> <i>There is no like,</i> or <i>equal, to him,</i> or <i>it.</i> (S, L.) And <span class=\"ar\">لَقِىَ القَوْمُ</span> <span class=\"ar\">أَضْدَادَهُمْ</span> <i>The people,</i> or <i>party, found,</i> or <i>met, their equals,</i> or <i>fellows.</i> (L.)</p><p><b class=\"ar\">ضَدَدٌ</b> : see <span class=\"ar\">ضَادٌّ</span>.</p><p><b class=\"ar\">ضَدِيدٌ</b> : see <span class=\"ar\">ضَدٌّ</span>, in four places.</p><p><b class=\"ar\">ضَدِيدَةٌ</b> : see <span class=\"ar\">ضِدٌّ</span>, first sentence.</p><p><b class=\"ar\">ضَادٌّ</b> , or <span class=\"ar\"> <span class=\"ar\">ضَادِدٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَدَدٌ</span></span> <i>One who fills vessels for people when they seek,</i> or <i>demand, water:</i> pl. <span class=\"ar\">ضُدَدٌ</span>, [which is anomalous,] on the authority of AA. (L.)</p><p><b class=\"ar\">ضَادِدٌ</b> : see what next precedes.</p><p><b class=\"ar\">هُمَا مُتَضَادَّانِ</b> <i>They two are contrary, opposed,</i> or <i>repugnant, each to the other:</i> (S, * L, K:) or <i>they two are inconsistent;</i> or <i>such as cannot be,</i> or <i>exist, together;</i> as night and day. (Msb.)</p>"},"ضنك":{"mf":"قال تعالى: وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً<br>[طه/ ١٢٤]. أي: ضيّقا، وقد ضَنُكَ عيشُهُ، وامرأة ضِنَاكٌ: مُكْتَنِزَةٌ، والضُّنَاكُ:<br>الزُّكَامُ، والمَضْنُوكُ: المزكوم.","mq":[["وان قل فروعهما فالاول الضيق","مرض"],"الضاد والنون والكاف أصلان صحيحان وإن قلَّ فروعُهما فالأوّل الضِّيق، والآخر مرضٌ.<br>فالأوَّل الضَّنْك: الضِّيق. ومن الباب امرأةٌ ضِناكٌ: مكتنِزة اللحم، إذا اكتنز تَضَاغَطَ.<br>والأصل الآخر المضنوك: المزكوم. والضُّنَاك الزُّكام. واللّه أعلم.<br>[باب الضاد والهاء وما يثلثهما]<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَنُكَ</b> , aor. <b class=\"ar\">ضَنُكَ</b> , inf. n. <span class=\"ar\">ضَنْكٌ</span> and <span class=\"ar\">ضَنَاكَةٌ</span> and <span class=\"ar\">ضُنُوكَةٌ</span>, (O, K,) the first and third of these, (O,) or the first and second, (TA,) accord. to IDrd, used in relation to a place, and the second and third in relation to life, or sustenance, or means of subsistence, (O, TA,) <i>It was,</i> or <i>became, narrow,</i> or <i>strait.</i> (O, K, TA.) -b2- And <span class=\"ar\">ضَنُكَ</span> said of a man, inf. n. <span class=\"ar\">ضَنَاكَةٌ</span>, <i>He was,</i> or <i>became, weak in his judgment,</i> and <i>in his body,</i> and <i>in his soul,</i> and <i>in his intellect.</i> (K.) -b3- And <span class=\"ar\">ضَنُكَ</span> <span class=\"ar\">السَّحَابُ</span> <i>The clouds became thick, collected together, and dense.</i> (O, TA.) -A2- <span class=\"ar\">ضُنِكَ</span>, like <span class=\"ar\">عُنِىَ</span>, <i>He was,</i> or <i>became, affected with a coryza,</i> or <i>defluxion from the head and nose.</i> (K.)</p><p><b>4.</b> <b class=\"ar\">اضنكهُ</b> <i>He</i> (God) <i>caused him to be affected with a coryza,</i> or <i>defluxion from the head and nose.</i> (TA.)</p><p><b class=\"ar\">ضَنْكٌ</b> an inf. n. of <span class=\"ar\">ضَنُكَ</span>: (O, K:) its primary signification is <i>Narrowness,</i> or <i>straitness,</i> and <i>hardship.</i> (Aboo-Is-hák, TA.) -b2- And <i>Narrow,</i> or <i>strait;</i> syn. <span class=\"ar\">ضَيِّقٌ</span>; (S, M, O, K; [in the CK, and in a copy of the S, <span class=\"ar\">ضِيق</span>, which is also a correct explanation, as shown above; but not what is here meant, as appears from what follows;]) applied to anything, (M, K,) masc. and fem., (M, K, and Bd in xx. 123,) being an inf. n. used as an epithet. (Bd ibid.) [Like the Pers. <span class=\"ar\">تَنْگ</span>.] One says <span class=\"ar\">مَكَانٌ ضَنْكٌ</span> <i>A narrow,</i> or <i>strait, place.</i> (IDrd, O, TA.) And <span class=\"ar\">عَيْشٌ ضَنْكٌ</span> <i>A strait life;</i> or <i>strait sustenance,</i> or <i>means of subsistence;</i> (IDrd, O, TA;) as also <span class=\"ar\">عَيْشٌ <span class=\"ar\">ضَنِيكٌ</span></span>: (AA, O, K, TA:) and thus <span class=\"ar\">مَعِيشَةً ضَنْكًا</span> in the Kur xx. 123; where some read <span class=\"ar\"> <span class=\"ar\">ضَنْكَى</span></span>, like <span class=\"ar\">سَكْرَى</span>: (Bd:) or this means <i>such as is unlawful;</i> (O, TA;) every life that is unlawful being termed <span class=\"ar\">ضَنْكٌ</span>, accord. to Lth, even though it be ample: (O, TA: *) Aboo-Is-hák thinks it to mean [<i>subsistence</i>] <i>in the fire of Hell:</i> but says that most explain this phrase in the Kur as meaning <i>the punishment of the grave:</i> (TA:) thus it means accord. to Ibn-Mes'ood: (O:) or, accord. to Katádeh, <i>Hell:</i> (O, TA:) or, accord. to Ed-Dahhák, <i>forbidden gain:</i> (TA:) or, as some say, <span class=\"ar\">الضَّرِيعُ</span> [q. v.], and <span class=\"ar\">الزَّكُّومُ</span> [q. v.]. (Bd.)</p><p><b class=\"ar\">ضُنْكَةٌ</b> : see <span class=\"ar\">ضُنَاكٌ</span>.</p><p><b class=\"ar\">ضَنْكَى</b> : see <span class=\"ar\">ضَنْكٌ</span>.</p><p><b class=\"ar\">ضَنَاكٌ</b> : see <span class=\"ar\">ضِنَاكٌ</span>.</p><p><b class=\"ar\">ضُنَاكٌ</b> <i>A coryza,</i> or <i>defluxion from the head and nose;</i> syn. <span class=\"ar\">زُكَامٌ</span>; (S, O, K;) as also <span class=\"ar\"> <span class=\"ar\">ضُنْكَةٌ</span></span>. (K.)</p><p><b class=\"ar\">ضِنَاكٌ</b> ; (O, K, &amp;c.;) accord. to El-Fárábee, (O, TA,) and J [in the S], (TA,) <span class=\"ar\"> <span class=\"ar\">ضَنَاكٌ</span></span>; but accord. to others, with kesr, and this is the right; (O, TA;) <i>Compact in flesh;</i> applied to a woman: (El-Fárábee, S, O:) or <i>plump, and compact in flesh;</i> so applied: (Lth, TA:) or <i>heavy in the hinder part,</i> (K, TA,) <i>and large in body;</i> (TA;) so applied: (K, * TA:) or <i>having much flesh;</i> applied to a male and to a female, without <span class=\"ar\">ة</span>: (IAth, TA:) and <i>firm in make, and strong;</i> applied to a male and to a female; (K, TA;) of human beings, and of camels, and in like manner of palm-trees and of trees in general: (TA:) and, applied to a she-camel, <i>thick in the hinder part:</i> (TA:) and [<i>large;</i> applied to trees (<span class=\"ar\">شَجَرٌ</span>): or] <i>large trees.</i> (Ibn-'Abbád, O, K.)</p><p><b class=\"ar\">ضَنِيكٌ</b> : see <span class=\"ar\">ضَنْكٌ</span>. -b2- Also <i>Weak in his body,</i> and <i>in his intellect,</i> (AZ, O, K,) and <i>in his judgment,</i> and <i>in his soul.</i> (K,) -b3- And <i>A servant who works for his bread.</i> (AZ, O, K.) -b4- And <i>i. q.</i> <span class=\"ar\">مَقْطُوعٌ</span> [<i>Cut off;</i> &amp;c.]. (AA, O, K.)</p><p><b class=\"ar\">ضُنْأَكٌ</b> <i>Hard, and firm and compact in flesh;</i> (Lh, O, K;) applied to a man; (Lh, O;) as also <span class=\"ar\">ضَنْأَكٌ</span>: (K:) fem. <span class=\"ar\">ضُنْأَكَةٌ</span>; (Lh, O, K;) applied to a woman. (Lh, O.) And, applied to a she-camel, <i>Great,</i> (K, TA,) <i>and compact in make:</i> (TA:) as also with <span class=\"ar\">ة</span>. (K.)</p><p><b class=\"ar\">مُضْنَكٌ</b> , (TA,) or <span class=\"ar\"> <span class=\"ar\">مُتَضَنِّكٌ</span></span>, (O,) <i>Affected with a constant,</i> or <i>chronic, pervading disease;</i> or <i>emaciated by disease so as to be at the point of death.</i> (O, TA.)</p><p><b class=\"ar\">مَضْنُوكٌ</b> <i>Affected with the malady termed</i> <span class=\"ar\">ضُنَاك</span> [q. v.]. (S, O,)</p><p><b class=\"ar\">مُتَضَنِّكٌ</b> : see <span class=\"ar\">مُضْنَكٌ</span>.</p>"},"ضمر":{"mf":"الضَّامِرُ من الفرس: الخفيف اللّحم من الأعمال لا من الهزال. قال تعالى: وَعَلى كُلِّ ضامِرٍ<br>[الحج/ ٢٧]، يقال: ضَمَرَ ضُمُوراً <strong>«٢»</strong>، واضْطَمَرَ فهو مُضْطَمِرٌ، وضَمَّرِّتُهُ أنا، والمِضْمَارُ: الموضع الذي يُضْمَرُ فيه. والضَّمِيرُ:<br>ما ينطوي عليه القلب، ويدقّ على الوقوف عليه، وقد تسمّى القوّة الحافظة لذلك ضَمِيراً.","mq":[["يدل علي دقة في الشي","يدل علي غيبة وتستر"],"الضاد والميم والراء أصلان صحيحان: أحدهما يدلُّ على دِقّةٍ فى الشئ، والآخر يدلُّ على غَيبةٍ وتستُّر.<br>فالأوّل قولهم: ضَمَرَ الفرس وغيرُه ضَموراً، وذلك من خِفّة اللَّحم، وقد يكون من الهُزَال. ويقال للموضع الذى تُضمَّر فيه الخيل: المِضْمار. ورجل ضَمْرٌ:<br>خفيف الجسم. واللؤلؤ المضْطِر: الذى فى وسطه بعضُ ال"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَمَرَ</b> , (S, A, Mgh, Msb, K,) aor. <b class=\"ar\">ضَمُرَ</b> ; (S, Msb, K;) and <span class=\"ar\">ضَمُرَ</span>; (S, Msb, K;) inf. n. <span class=\"ar\">ضُمُورٌ</span>, of the former, and <span class=\"ar\">ضُمْرٌ</span>, (S, A, Mgh, Msb, K,) of the former also, (A, Mgh,) or of the latter, (Msb,) [also written <span class=\"ar\">ضُمُرٌ</span>, (see an ex., voce <span class=\"ar\">نَهَارٌ</span>,)] <i>He</i> (a horse, [&amp;c.,] S, A, &amp;c.) <i>was,</i> or <i>became, lean,</i> or <i>light of flesh:</i> (S:) or <i>slender, and lean:</i> (Msb:) or <i>lean, and lank in the belly:</i> (A, K:) or <i>lank in the belly by reason of leanness:</i> (Mgh:) and <span class=\"ar\"> <span class=\"ar\">اضطمر</span></span> signifies the same. (S, K.) [See also 5 and 8.] -b2- Also, inf. n. <span class=\"ar\">ضُمُورٌ</span>, <i>He became lean and weak.</i> (TA.) -b3- <span class=\"ar\">ضَمُرَ العِنَبُ</span> (assumed tropical:) <i>The grapes became withered, so as to be neither fresh grapes nor raisins.</i> (Sgh.) -b4- <span class=\"ar\">ضَمَرَتِ الحِنْطَةُ</span> (assumed tropical:) <i>The wheat,</i> being parched over the fire, <i>became contracted and small.</i> (Mgh.)</p><p><b>2.</b> <b class=\"ar\">ضمّرهُ</b> , inf. n. <span class=\"ar\">تَضْمِيرٌ</span>, <i>He made him</i> (a horse) <i>lean,</i> or <i>light of flesh;</i> [&amp;c.;] as also <span class=\"ar\"> <span class=\"ar\">اضمرهُ</span></span>. (S.) -b2- <i>He prepared him</i> (i. e. a horse) <i>for racing,</i> [or <i>for a military expedition,</i> (see <span class=\"ar\">مُضَمِّرٌ</span>,)] <i>by feeding him with food barely sufficient to sustain him, after he had become fat;</i> as also <span class=\"ar\"> <span class=\"ar\">اضمرهُ</span></span>. (Msb:) <i>he fed him with food barely sufficient to sustain him, after he had become fat;</i> as also <span class=\"ar\"> <span class=\"ar\">اضمرهُ</span></span>: (K:) or <i>he fed him with fodder so that he became fat, and then reduced him to food barely sufficient to sustain him; which is done during forty days:</i> (S:) or <i>he saddled him, and put on him a housing, in order that he might sweat under it, and so lose his flabbiness, and become firm in flesh; and then mounted upon him a light boy or young man, to make him run, but not to make him go so quick a pace as that which is termed</i> <span class=\"ar\">عَنَق</span>; <i>by the doing of which, one becomes in no fear of his losing his breath in running, and a quick run does not cut him short:</i> this (says AM) is what I have seen the Arabs practise; and they term it <span class=\"ar\">تَضْمِيرٌ</span>, and also <span class=\"ar\"> <span class=\"ar\">مِضْمَارٌ</span></span>. (T, L.) -b3- Also <i>He,</i> or <i>it, weakened, and subdued, and diminished, him:</i> and the same signification is assigned to it [tropically] when the objective complement is a word denoting a sensation or passion. (TA.) -b4- <span class=\"ar\">التَّضْمِيرُ</span> also signifies <i>The plaiting well,</i> and <i>the anointing well, the lock of hair termed</i> <span class=\"ar\">ضَمِيرَة</span>. (TA.)</p><p><b>4.</b> <b class=\"ar\">أَضْمَرَ</b> see 2, in three places. -A2- <span class=\"ar\">اضمرهُ</span> signifies also <i>He determined,</i> or <i>resolved, upon it,</i> <span class=\"ar\">فِى ضَمِيرِهِ</span> <i>in his heart,</i> or <i>mind.</i> (Msb.) -b2- <i>He conceived it</i> in his heart, or mind. (MA, KL.) -b3- <i>He concealed it,</i> syn. <span class=\"ar\">أَسَرَّهُ</span>, (A,) or <span class=\"ar\">أَخْفَاهُ</span>, (K,) <span class=\"ar\">فِى قَلْبِهِ</span> <i>in his heart,</i> (A,) or <span class=\"ar\">فى نَفْسِهِ</span> <i>in his mind.</i> (S.) -b4- [And hence, <i>He suppressed it,</i> (namely a word or the like,) <i>meaning it to be understood.</i> -b5- And hence also <span class=\"ar\">اضمر</span> meaning <i>He made use of a pronoun.</i>] -b6- And <span class=\"ar\">اضمر صَرْفَ الحَرْفِ</span> [<i>He suppressed the vowel of the</i> final <i>letter;</i>] <i>he made the movent</i> [final] <i>letter quiescent.</i> (TA.) -b7- And <span class=\"ar\">أَضْمَرَتُهُ البِلَادُ</span> (tropical:) <i>The lands,</i> or <i>countries, hid him, by his having travelled far:</i> (A:) and <span class=\"ar\">اضمرته</span> <span class=\"ar\">الأَرْضُ</span> (assumed tropical:) <i>the earth hid him,</i> either <i>by reason of travel,</i> or <i>by death.</i> (K, TA.) -A3- <span class=\"ar\">اضمر</span> is also <i>syn. with</i> <span class=\"ar\">اِسْتَقْصَى</span> [q. v.]. (O, K.) [Accord. to the TK, one says <span class=\"ar\">اضمر الشَّىْءَ</span> meaning <span class=\"ar\">استقصاهُ</span>.]</p><p><b>5.</b> <b class=\"ar\">تضمّر وَجْهُهُ</b> <i>His face became shrivelled,</i> or <i>contracted, by emaciation.</i> (Sgh, L, K.)</p><p><b>7.</b> <b class=\"ar\">انضمر</b> <i>It</i> (a branch, or twig,) <i>became dried up.</i> (TA.)</p><p><b>8.</b> <b class=\"ar\">اضطمر</b> : see 1. -b2- Also <i>He,</i> (a horse,) <i>after having been fed until he had become fat, was reduced to food barely sufficient to sustain him.</i> (TA.) [See 2.]</p><p><b class=\"ar\">ضَمْرٌ</b> : see <span class=\"ar\">ضَامِرٌ</span>, in two places. -b2- Hence, in the opinion of ISd, as he says in the M, it is also applied to a horse as meaning <span class=\"ar\">دَقِيقُ</span> <span class=\"ar\">الحَجَاجَيْنِ</span> [i. e. <i>Thin in the bones surrounding,</i> or <i>projecting over, the cavities of the eyes:</i> in the TA, <span class=\"ar\">الهجاجين</span>, an obvious mistranscription; and in the TK, <span class=\"ar\">الحجاجتين</span>, which is also wrong]: on the authority of Kr: in the copies of the K, <span class=\"ar\">الحَاجِبَيْنِ</span>. (TA.) -b3- And <i>Narrow;</i> (O, K;) applied to a place. (O.) -b4- And <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">ضَمِيرٌ</span></span> [app. in the first of the senses assigned to the latter below]. (O, K: in the CK <span class=\"ar\">ضِمِّير</span>.) See also. <span class=\"ar\">مُضْمَرٌ</span>.</p><p><b class=\"ar\">ضَمْرَانٌ</b> (S, O, K) and <span class=\"ar\"> <span class=\"ar\">ضُمْرَانٌ</span></span> (TA) <i>A certain plant,</i> (S, O, K,) <i>of the shrub-kind</i> (<span class=\"ar\">مِنْ دِقِّ</span> <span class=\"ar\">الشَّجَرِ</span>): (K:) or <i>of the kind called</i> <span class=\"ar\">حَمْض</span>: AM says, <i>it is not of the shrub-kind, and has</i> [<i>what are termed</i>] <span class=\"ar\">هَدَب</span> [q. v.] <i>like the</i> <span class=\"ar\">هَدَب</span> of the <span class=\"ar\">أَرْطَى</span>: (TA:) AHn says, <i>it resembles the</i> <span class=\"ar\">رِمْث</span>, <i>except that it is yellow</i> (<span class=\"ar\">أَصْفَرُ</span> [app. a mistranscription for <span class=\"ar\">أَصْغَرُ</span> i. e. <i>smaller</i>]), <i>and it has little wood,</i> [<i>and</i>] <i>the small and dry parts of its branches are fed upon</i> [<i>by the camels</i>] (<span class=\"ar\">يُحْتَطَبُ</span>): he adds, on the authority of the ancient Arabs of the desert, that <i>it is</i> [<i>of the kind called</i>] <span class=\"ar\">حَمْض</span>, <i>green, lank, pleasing to the camels:</i> and Aboo-Nasr says that <i>it is of the kind called</i> <span class=\"ar\">حَمْض</span>. (O.) -A2- See also what next follows.</p><p><b class=\"ar\">ضُمْرَانُ</b> (A 'Obeyd, S, O, K, TA) and <span class=\"ar\"> <span class=\"ar\">ضَمْرَان</span></span>, thus, with fet-h, as said by As on the authority of ISk; each of the names of dogs; (TA;) a name of a male dog; (O, K;) not of a bitch, as J asserts it to be. (K.) -A2- See also the next preceding paragraph.</p><p><b class=\"ar\">ضِمَارٌ</b> <i>A place,</i> or <i>a valley, that is depressed, concealing him who is journeying in it.</i> (O.) [Accord. to the K, <span class=\"ar\">الضِّمَارُ</span> is “ <i>A place;</i> ” i. e. the name of a certain place.] -b2- <span class=\"ar\">مَالٌ ضِمَارٌ</span> <i>Property of which one hopes not for the return:</i> (K:) or <i>absent property of which one hopes not for the return:</i> (A 'Obeyd, Msb, TA:) if not absent, it is not thus called. (A 'Obeyd, TA.) -b3- <span class=\"ar\">دَيْنٌ ضِمَارٌ</span> <i>A debt of which the payment is not hoped for:</i> (S:) or <i>for the payment of which no period is fixed.</i> (K, * TA.) -b4- <span class=\"ar\">عَطَآءٌ ضِمَارٌ</span> <i>A gift that is not hoped for.</i> (A.) -b5- <span class=\"ar\">وَعْدٌ ضِمَارٌ</span>, (S,) and <span class=\"ar\">عِدَةٌ</span> <span class=\"ar\">ضِمَارٌ</span>, (A, K, [<span class=\"ar\">من العَذابِ</span> in the CK being a mistranscription for <span class=\"ar\">مِنَ العِدَاتِ</span>, as in other copies of the K and in the TA, in which latter is added that <span class=\"ar\">عِدَات</span> is pl. of <span class=\"ar\">عِدَةٌ</span>, which is syn. with <span class=\"ar\">وَعْدٌ</span>,]) <i>A promise of which the fulfilment is not hoped for:</i> (S, A:) or <i>of which the fulfilment is delayed.</i> (K.) -b6- <span class=\"ar\">ضِمَارٌ</span> also signifies <i>Anything of which one is not confident,</i> or <i>sure.</i> (S.) -b7- And <i>A debt of which the payment is deferred by the creditor to a future period;</i> or <i>a sale upon credit, in which the payment is deferred to a definite period;</i> or <i>a postponement,</i> or <i>delay, as to the time of the payment of a debt</i> or <i>of the prince of a thing sold</i> &amp;c.; syn. <span class=\"ar\">نَسِيْئَةٌ</span>. (Fr, TA.) -b8- Also <i>Unseen; not apparent; contr. of</i> <span class=\"ar\">عِيَانٌ</span>. (K.) A poet says, censuring a certain man, <span class=\"ar\">وَعَيْنُهُ كَالكَالِئِ الضِّمَارِ</span> [<i>And his present gift is</i> a thing not hoped for, <i>like the unseen debt of which the payment is deferred by the creditor:</i>] meaning, his present gift is like the absent that is not hoped for. (TA.) -b9- <span class=\"ar\">ذَهَبُوا</span> <span class=\"ar\">بِمَالِى ضِمَارًا</span> means <i>They took away my property by gaming.</i> (Fr, TA.) -A2- Also <i>A certain idol, which was worshipped by El-Abbás Ibn-Mirdás.</i> (O, K, TA. [It is implied in the K that it is with the art. <span class=\"ar\">ال</span>; but it is not so accord. to the O and TA.])</p><p><b class=\"ar\">ضَمِيرٌ</b> <i>A thing that thou concealest,</i> or <i>conceivest,</i> or <i>determinest upon,</i> (<span class=\"ar\">تُضْمِرُهُ</span>,) <i>in thy heart,</i> or <i>mind:</i> (Lth, TA:) <i>a secret;</i> syn. <span class=\"ar\">سِرٌّ</span>: (K:) a subst. from <span class=\"ar\">أَضْمَرَ فِى نَفْسِهِ شَيْئًا</span>: (S:) pl. <span class=\"ar\">ضَمَائِرُ</span>. (S, K.) -b2- [Hence used as meaning <i>A pronoun;</i> which is also termed <span class=\"ar\"> <span class=\"ar\">مُضْمَرٌ</span></span>, and <span class=\"ar\">اِسْمٌ مُضْمَرٌ</span>, lit. <i>a concealed noun,</i> i. e. a noun of which the signification is not shown by itself alone; opposed to <span class=\"ar\">مُظْهَرٌ</span>: pl. of the first as above; and of the second <span class=\"ar\">مُضْمَرَاتٌ</span>.] -b3- See also <span class=\"ar\">ضَمْرٌ</span>. -b4- And <span class=\"ar\">الضَّمِيرُ</span> signifies <i>The heart</i> [itself]; <i>the mind; the recesses of the mind; the secret thoughts;</i> or <i>the soul;</i> syn. <span class=\"ar\">قَلْبُ الإِنْسَانِ</span>, and <span class=\"ar\">بَاطِنُهُ</span>, (Msb,) or <span class=\"ar\">دَاخِلُ</span> <span class=\"ar\">الخَاطِرِ</span>: (A, K:) pl. as above, (Msb, K,) the sing. being likened to <span class=\"ar\">سَرِيرَةٌ</span>, of which the pl. is <span class=\"ar\">سَرَائِرُ</span>. (Msb.) [See also <span class=\"ar\">مُضْمَرٌ</span>. And see an ex. in a verse cited in art. <span class=\"ar\">سيح</span>, 7th conj.] -A2- Also <i>Withered,</i> or <i>shrivelled, grapes,</i> (O, K,) <i>that are neither fresh grapes nor raisins.</i> (O.)</p><p><b class=\"ar\">لَقِيتُهُ بِالضُّمَيْرِ</b> is a phrase mentioned by Sgh [in the O] as meaning <i>I met him at sunset:</i> but it is correctly [<span class=\"ar\">بِالصُّمَيْرِ</span>,] with the unpointed <span class=\"ar\">ص</span>. (TA.)</p><p><b class=\"ar\">ضَمِيرَةٌ</b> <i>A lock,</i> or <i>plaited lock, of hair, such as is termed</i> <span class=\"ar\">ضَفِيرَةٌ</span> and <span class=\"ar\">غَدِيرَةٌ</span>: pl. <span class=\"ar\">ضَمَائِرُ</span>. (As, TA.)</p><p><b class=\"ar\">ضَامِرٌ</b> <i>Lean, and lank in the belly;</i> [&amp;c.; see 1;] (A, K;) applied to a he-camel, (K,) and to a horse, as also <span class=\"ar\"> <span class=\"ar\">ضَمْرٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">مُضَمَّرٌ</span></span>, and <span class=\"ar\"> <span class=\"ar\">مُضْطَمِرٌ</span></span>; (A;) and to a she-camel, (S, A, K,) as also <span class=\"ar\">ضَامِرَةٌ</span>; (S;) [and to a man;] <span class=\"ar\">ضَامِرٌ</span> applied to a she-camel being regarded as a possessive epithet [signifying <span class=\"ar\">ذَاتُ ضُمْرٍ</span>]: (TA:) and <span class=\"ar\"> <span class=\"ar\">ضَمْرٌ</span></span> signifies also <i>lank in the belly, and small and slender in person;</i> applied to a man: (S, A, K:) fem. with <span class=\"ar\">ة</span>: (A, K:) the pl. of <span class=\"ar\">ضَامِرٌ</span> is <span class=\"ar\">ضُمَّرٌ</span>. (Ham p. 473.) -b2- And A horse <i>in a state of preparation for racing, by his having been fed with food barely sufficient to sustain him, after having become fat:</i> and you say <span class=\"ar\">خَيْلٌ ضَامِرَةٌ</span> and <span class=\"ar\">ضَوَامِرُ</span>, meaning <i>horses in that state.</i> (Msb.) -b3- Applied to grain, it means <i>Thin,</i> or <i>slender:</i> (Mgh:) and to a branch or twig, <i>sapless; dried up;</i> as also <span class=\"ar\"> <span class=\"ar\">مُنْضَمِرٌ</span></span>. (K.)</p><p><b class=\"ar\">ضَوْمَرَانٌ</b> (S, O, Msb, K) and <span class=\"ar\">ضَوْمُرَانٌ</span> (Msb) and <span class=\"ar\"> <span class=\"ar\">ضَمْيُرَانٌ</span></span> (O, Msb, K) and <span class=\"ar\">ضَيْمَرَانٌ</span> (Msb) <i>A species of the</i> <span class=\"ar\">رَيَاحِين</span> [or <i>sweet-smelling plants</i>]: (S, O:) or <i>of the wild</i> <span class=\"ar\">رَيْحَان</span>: (K:) or the <span class=\"ar\">رَيْحَان فَارِسِىّ</span>: (Msb, K:) Aboo-Nasr says that the <span class=\"ar\">ضيمران</span> is the <span class=\"ar\">شَاهَسْفَرَم</span> [or <span class=\"ar\">شَاهِسْفَرَم</span>, i. e. <i>basil-royal,</i> or <i>common sweet basil, ocimum basilicum</i>]: AHn says, on the authority of an Arab of the desert, of El-Yemen, that the <span class=\"ar\">ضيمران</span> is <i>exactly like the</i> <span class=\"ar\">حَوْك</span> [which is one of the names now applied to <i>sweet basil</i>], <i>of sweet odour,</i> and is therefore asserted by some to be the <span class=\"ar\">شاهسفرم</span>, but the <span class=\"ar\">ضيمران</span> is <i>wild;</i> and he says that some call it <span class=\"ar\">ضَوْمَرَان</span>. (O.)</p><p><b class=\"ar\">ضَيْمُرَانٌ</b> and <span class=\"ar\">ضَيْمَرَانٌ</span>: see the next preceding paragraph.</p><p><b class=\"ar\">مُضْمَرٌ</b> <i>Concealed,</i> (K,) [or <i>conceived,</i>] in the mind. (S.) You say, <span class=\"ar\">هَوًى مُضْمَرٌ</span>, meaning <i>Concealed love;</i> as also <span class=\"ar\"> <span class=\"ar\">ضَمْرٌ</span></span>; as though the latter were believed to be an inf. n. [used in the sense of a pass. part. n.] from the unaugmented, for the augmented, verb. (TA.) See also <span class=\"ar\">ضَمِيرٌ</span>. -b2- Also The <i>place of concealment,</i> (K,) [or <i>of conception,</i>] in the mind. (S.) A poet, (S,) ElAhwas Ibn-Mohammad El-Ansáree, (TA,) says, <span class=\"ar\">سَتَبْقَى لَهَا فِى مُضْمَرِ القَلْبِ وَالحَشَا</span> <span class=\"ar\">سَرِيرَةُ وُدٍّ يَوْمَ تُبْلَى السَّرَائِرُ</span> [<i>There will remain to her, in the hiding-place of the heart and the bowels, a secret love,</i> (lit. a secret of love,) <i>on the day when secrets shall be revealed</i>]. (S, TA.)</p><p><b class=\"ar\">مُضَمَّرٌ</b> : see <span class=\"ar\">ضَامِرٌ</span>.</p><p><b class=\"ar\">مُضَمِّرٌ</b> One <i>who prepares his horses, by reducing them to scanty food,</i> (<span class=\"ar\">يُضَمِّرُهَا</span>,) <i>for a military expedition</i> or <i>for racing.</i> (TA.)</p><p><b class=\"ar\">مِضْمَارٌ</b> <i>A training-place in which horses are prepared for racing</i> [or <i>for military service</i>] <i>by being fed with food barely sufficient to sustain them, after they have become fat:</i> (S, * Msb, K: *) [a <i>hippodrome; a place where horses are exercised:</i>] pl. <span class=\"ar\">مَضَامِيرُ</span>. (A.) You say, <span class=\"ar\">جَرَى فِى</span> <span class=\"ar\">المِضْمَارِ</span> [<i>He ran in the hippodrome,</i> or <i>place of exercise</i>]. (A.) And <span class=\"ar\">الغِنَآءُ مِضْمَارُ الشِّعْرِ</span> (tropical:) [app. meaning <i>Singing is that in which the excellences of poetry are displayed, like as the excellences of a horse are displayed in the hippodrome</i>]. (A.) -b2- Also The <i>time, of forty days, during which a horse is reduced to food barely sufficient to sustain him, after his having been fed with fodder so that he has become fat;</i> (S, TA;) the <i>time during which a horse is thus prepared for racing</i> or <i>for an expedition against the enemy:</i> pl. as above. (TA.) It is said in a trad., <span class=\"ar\">اَلْيَوْمَ مِضْمَارٌ وَغَدًا</span> <span class=\"ar\">ٱلْسِّبَاقُ وَالسَّابِقُ مَنْ سَبَقَ ٱلْجَنَّةَ</span> [<i>To-day is a time for training, and to-morrow is the race, and the winner is he who wins Paradise:</i>] i. e., to-day one is to work, in the present world, for the desire of Paradise; like as a horse is trained for racing. (Sh.) [One of the explanations of <span class=\"ar\">المضمار</span> in the K is <span class=\"ar\">غَايَةُ الفَرَسِ فِى السِّبَاقِ</span>, or, as in the TA, <span class=\"ar\">لِلسِّبَاقِ</span>; app. meaning <i>The goal,</i> or <i>limit, of the horse in racing:</i> but in the TA, these words are made to form part of an explanation which I have given before, i. e., the time during which a horse is prepared for racing, &amp;c.] -A2- See also 2.</p><p><b class=\"ar\">لُؤْلُؤٌ مُضْطَمِرٌ</b> <i>Contracted pearls:</i> (K:) or <i>pearls having somewhat of contraction in the middle.</i> (S.) -b2- See also <span class=\"ar\">ضَامِرٌ</span>.</p><p><b class=\"ar\">مُنْضَمِرٌ</b> : see <span class=\"ar\">ضَامِرٌ</span>, last sentence.</p>"},"ضير":{"mf":"الضَّيْرُ: المَضَرَّةُ، يقال: ضارّه وضرّه. قال تعالى: لا ضَيْرَ إِنَّا إِلى رَبِّنا مُنْقَلِبُونَ<br>[الشعراء/ ٥٠]، وقوله: لا يَضُرُّكُمْ كَيْدُهُمْ شَيْئاً [آل عمران/ ١٢٠].","mq":[[],"الضاد والياء والراء كلمةٌ واحدة، وهو من الضيَّر والمضَرَّة.<br>ولا يَضِيرنى كذا، أى لا يضرُّنى. قال اللّه تعالى: ﴿وَإِنْ تَصْبِرُوا وَتَتَّقُوا لا يَضُرُّكُمْ كَيْدُهُمْ شَيْئاً (٣﴾.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَارَهُ</b> , aor. <span class=\"ar\">يَضِيرُ</span>, inf. n. <span class=\"ar\">ضَيْرٌ</span>; (S, M, A, Msb, K;) as also <span class=\"ar\">ضَارَهُ</span>, aor. <span class=\"ar\">يَضُورُ</span>, inf. n. <span class=\"ar\">ضَوْرٌ</span>; (S, M, K;) <i>It</i> (a thing, M, K) <i>harmed, injured, hurt, mischiefed,</i> or <i>damaged, him; i. q.</i> <span class=\"ar\">ضَرَّهُ</span>, (S, M, K,) or <span class=\"ar\">أَضَرَّ بِهِ</span>. (Msb.) You say, <span class=\"ar\">هٰذَا مِمَّا لَا</span> <span class=\"ar\">يَضِيرُكَ</span> [<i>This is of the things that will not harm thee</i>]: and <span class=\"ar\">لَوْ فَعَلْتَهُ لَمْ يَضِرْكَ</span> [<i>Hadst thou done it, it had not harmed thee</i>]: and <span class=\"ar\">لَا ضَيْرَ عَلَيْكَ</span> [<i>No harm shall befall thee</i>]. (A.) And <span class=\"ar\">مَا يَضِيرُكَ</span> <span class=\"ar\">عَلَى الضَّبِّ صِيْدٌ</span> <i>i. q.</i> <span class=\"ar\">مَا يَضُرُّكَ</span> q. v. (A in art. <span class=\"ar\">ضر</span>.) And Ks says that he had heard (from one of the people of El-' Áliyeh. TA) the phrase <span class=\"ar\">لَا يَنْفَعُنِى ذٰلِكَ وَلَا يَضُورُنِى</span> [<i>That will not benefit me, nor will it harm me</i>]. (S, TA.) See also a reading of a phrase in a trad. cited in art. <span class=\"ar\">ضر</span>. conj. 3.</p>"},"ضيز":{"mf":"قال تعالى: تِلْكَ إِذاً قِسْمَةٌ ضِيزى<br>[النجم/ ٢٢]، أي: ناقصة. أصله: فُعْلَى، فكسرت الضّاد للياء، وقيل: ليس في كلامهم فُعْلَى <strong>«١»</strong>.","mq":[[],"الضاد والياء والزاء قد مضى ذكره، وأصله فيما يقال الواو.<br>وقد قيل إنّه من بَنات الياء، فلذلك ذكرناه هاهنا. فالقِسمة الضَيزى: النّاقصة.<br>يقال ضِزْته حقَّه، إذا منعتَه. وحكى ناس ضَأَزَه، مهموز. وأنشدوا:<br>فحقُّك مَضْئُوزٌ وأنفُكَ راغمُ (١)<br>ليس فى الباب غيرُ هذا.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَازَ</b> , (S, K,) aor. <span class=\"ar\">يَضِيزُ</span>, inf. n. <span class=\"ar\">ضَيْزٌ</span>, (TA,) <i>He deviated from the right course;</i> or <i>acted unjustly, wrongfully, injuriously,</i> or <i>tyrannically;</i> (S, K;) <span class=\"ar\">فِى الحُكْمِ</span> <i>in the judgment:</i> (S:) like <span class=\"ar\">ضَأَزَ</span>. (TA in art. <span class=\"ar\">ضأز</span>.) -b2- <span class=\"ar\">ضَازَهُ حَقَّهُ</span>, aor. and inf. n. as above, <i>He deprived him,</i> or <i>defrauded him, of a part,</i> or <i>the whole, of his right,</i> or <i>due:</i> (S, M, K:) like <span class=\"ar\">ضَازَهُ</span>, aor. <span class=\"ar\">يَضُوزُهُ</span>: (K:) <i>he refused it to him,</i> or <i>withheld it from him:</i> (AZ, M, TA:) and sometimes one says <span class=\"ar\">ضَأَزَهُ</span>, aor. <span class=\"ar\">يَضْأَزُهُ</span>, inf. n. <span class=\"ar\">ضَأْزٌ</span>. (S, TA.)</p><p><b class=\"ar\">قِسْمَةٌ ضِيزَى</b> <i>An unjust,</i> (S, M,) or <i>a defective,</i> (K in art. <span class=\"ar\">ضأز</span>,) <i>division:</i> (S, M, K:) as also <span class=\"ar\">ضُوزَى</span>: (M:) <span class=\"ar\">ضيزى</span> in the Kur liii. 22 is read by all without hemz: (TA:) it is of the measure <span class=\"ar\">فُعْلَى</span>, like <span class=\"ar\">طُوبَى</span> and <span class=\"ar\">حُبْلَى</span>; but the <span class=\"ar\">ض</span> is with kesr in order that the <span class=\"ar\">ى</span> may remain unchanged; for there is not in the language an epithet of the measure <span class=\"ar\">فِعْلَى</span>; this being a measure of substantives, like <span class=\"ar\">الشِّعْرَى</span> and <span class=\"ar\">الدِّفْلَى</span>: (S:) or, accord. to Aboo-' Alee, it is not an epithet, but an inf. n., like <span class=\"ar\">ذِكْرَى</span>, as though the meaning were <span class=\"ar\">قِسْمَةٌ ذَاتُ جَوْرٍ</span>: (Har p. 524:) Fr says that some of the Arabs say <span class=\"ar\">ضَأْزَى</span>, and <span class=\"ar\">ضُؤْزَى</span>: and AHát mentions AZ's having heard the Arabs say <span class=\"ar\">ضِئْزَى</span>, with hemz. (S.)</p>"},"ضنن":{"mf":"قال تعالى: وَما هُوَ عَلَى الْغَيْبِ بِضَنِينٍ<br>[التكوير/ ٢٤]، أي: ما هو ببخيل، والضَّنَّةُ هو البخل بالشيء النّفيس، ولهذا قيل: عِلْقُ مَضَنَّةٍ ومَضِنَّةٍ، وفلانٌ ضِنِّي بين أصحابي، أي: هو النّفيس الذي أَضِنُّ به، يقال: ضَنَنْتُ بالشيء ضَنّاً وضَنَانَةً، وقيل: ضَنِنْتُ <strong>«٣»</strong>.","mq":[["بخل بالشي"],"الضاد والنون أصلٌ صحيح يدلُّ على بُخْلٍ بالشئ. يقال ضَنِنْتُ بالشّئِ أضَنُّ به ضَنًّا وضَنانةً، ورجلٌ ضَنين. وهذا عِلْقُ مَضَنَّةٍ ومَضِنّة، إذا كان نفيساً يُضَنُّ به. وفلانٌ ضِنِّى مِنْ بين إخوانى، إذا كان النّفِيسَ الذى يُضَنُّ به. وربما قالوا ضَنَنْت بفتح النون.<br>"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَنَّ بِهِ</b> , (Mgh, Msb,) first pers. <span class=\"ar\">ضَنِنْتُ بِهِ</span>, (S, Msb, *) [and one may say <span class=\"ar\">عَلَيْهِ</span>, and <span class=\"ar\">عَنْهُ</span>, in the place of <span class=\"ar\">بِهِ</span>, (see <span class=\"ar\">ضَنِينٌ</span>,)] and <span class=\"ar\">ضَنِنُوا</span> occurs, in a verse of Kaanab Ibn-Umm-Sáhib, used by poetic license for <span class=\"ar\">ضَنُّوا</span>, (S,) aor. <b class=\"ar\">ضَنَنَ</b> ; (S, Mgh, Msb, K;) and <span class=\"ar\">ضَنَّ</span>, (Msb,) first pers. <span class=\"ar\">ضَنَنْتُ</span>, (S, Msb, *) aor. <b class=\"ar\">ضَنِنَ</b> , (S, Msb, K,) accord to Fr, (S,) or, accord. to Th, Fr said, I have heard <span class=\"ar\">ضَنَنْتُ</span>, though I have not heard <span class=\"ar\">أَضِنُّ</span>, but this aor. is mentioned by Yaakoob; (TA;) inf. n. <span class=\"ar\">ضِنٌّ</span> (S, Mgh, Msb, K [in the CK <span class=\"ar\">ضِنَانًا</span> is erroneously put for <span class=\"ar\">ضِنًّا</span>]) and <span class=\"ar\">ضَنٌّ</span> (TA) and <span class=\"ar\">ضَنَانَةٌ</span>, (S, Mgh, Msb, K, TA,) with fet-h, (Msb, TA,) and <span class=\"ar\">ضِنَّةٌ</span>, (Msb,) or this last is a simple subst.; (Mgh;) <i>He was,</i> or <i>became, niggardly, tenacious, stingy,</i> or <i>avaricious,</i> (S, Mgh, Msb, K,) <i>of it.</i> (S, Mgh, Msb. [See also 8.]) You say, <span class=\"ar\">ضَنَّ عَلَيْهِ</span> <span class=\"ar\">بِكَذَا</span> <i>He was,</i> or <i>became, niggardly,</i> &amp;c., <i>to him, of such a thing.</i> (Mgh.) And <span class=\"ar\">إِنَّمَا يُضَنُّ <span class=\"ar\">بِالضَّنِينِ</span></span> [<i>Only he who clings is to be clung to</i>]: a prov., meaning that you should cling to fraternizing [only] with him who clings to fraternizing with you. (Meyd, and Har p. 42.) And <span class=\"ar\">ضَنِنْتُ</span> <span class=\"ar\">بِالمَنْزِلِ</span>, inf. n. <span class=\"ar\">ضِنٌّ</span> and <span class=\"ar\">ضَنَانَةٌ</span>, [<i>I kept tenaciously to,</i> or] <i>I did not quit,</i> or <i>relinquish, the place of alighting,</i> or <i>abode.</i> (TA.)</p><p><b>8.</b> <b class=\"ar\">اِضْطَنَّ</b> (originally <span class=\"ar\">اِضْتَنَّ</span>, TA) <i>He</i> (a man, TA) <i>was,</i> or <i>became, niggardly, tenacious, stingy,</i> or <i>avaricious.</i> (K.) [See also 1.]</p><p><b class=\"ar\">ضِنٌّ</b> an inf. n. of 1 [q. v.]. (S, &amp;c.) -b2- Also <i>A thing highly esteemed, of which one is tenacious.</i> (TA.) -b3- [Hence] one says, <span class=\"ar\">هُوَ ضِنِّى</span> <i>He is the person of whose affection I am tenacious;</i> as also <span class=\"ar\"> <span class=\"ar\">ضِنَّتِى</span></span> and <span class=\"ar\"> <span class=\"ar\">ضَنِينِى</span></span>: (TA:) or <i>he is my particular,</i> or <i>special, friend,</i> (K, TA,) <span class=\"ar\">مِنْ بَيْنِ</span> <span class=\"ar\">إِخْوَانِى</span> [<i>chosen from among my brethren</i>]; (S, TA;) as though I appropriated him specially to myself, and were tenacious of him because of the place that he held in my estimation: as is said in the S, it is like special appropriation [of the person to oneself]. (TA.) [And as <span class=\"ar\">ضِنٌّ</span> is originally an inf. n., it is used as an epithet applied to a pl. number:] it is said in a trad., <span class=\"ar\">إِنَّ لِلّٰهِ ضِنًّا مِنْ</span> <span class=\"ar\">خَلْقِهِ يُحْيِيهِمْ فِى عَافِيَةٍ وَيُمِيتُهُمْ فِى عَافِيَةٍ</span>, (S, TA,) or <span class=\"ar\"> <span class=\"ar\">ضَنَائِنَ</span>مِنْ خلقه</span>, (K, * TA,) accord. to different relations thereof, (TA,) i. e. [<i>Verily God has</i>] <i>specially-distinguished individuals</i> [<i>of his creatures, whom He causes to live in a state of freedom from disease,</i> or <i>from disease and trial, and whom He causes to die in a state of freedom</i> &amp;c.]: (K, TA:) the sing. of <span class=\"ar\">ضَنَائِن</span> is <span class=\"ar\"> <span class=\"ar\">ضَنِينَةٌ</span></span>, of the measure <span class=\"ar\">فَعِيلَةٌ</span> in the sense of the measure <span class=\"ar\">مَفْعُرلَةٌ</span>, and meaning <i>a thing that one specially appropriates to himself, and of which he is tenacious because of the place that it holds in his estimation.</i> (TA.)</p><p><b class=\"ar\">ضِنَّةٌ</b> an inf. n. of <span class=\"ar\">ضَنَّ</span>: (Msb:) or a subst. therefrom signifying <i>Niggardliness, tenaciousness, stinginess,</i> or <i>avarice:</i> (Mgh:) or <i>vehement niggardliness</i> &amp;c.; as also <span class=\"ar\"> <span class=\"ar\">مَضَنَّةٌ</span></span>. (TA.) -b2- See also <span class=\"ar\">ضِنٌّ</span>.</p><p><b class=\"ar\">ضَنَنٌ</b> <i>Courageous, brave,</i> or <i>strong-hearted.</i> (K.)</p><p><b class=\"ar\">ضَنِينٌ</b> <i>Niggardly, tenacious, stingy,</i> or <i>avaricious,</i> (S, Mgh, Msb, K,) <span class=\"ar\">بِشَىْءٍ</span> [<i>of a thing</i>], (S,) or <span class=\"ar\">بِشَىْءٍ</span> <span class=\"ar\">نَفِيسٍ</span> [<i>of a thing held in high estimation</i>]. (TA.) <span class=\"ar\">وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ</span>, in the Kur [lxxxi. 24], as some read it, others reading <span class=\"ar\">بِظَنِينٍ</span> [q. v.], is expl. by Zj as meaning, <i>And he is not a tenacious concealer of that which has been revealed</i> to him: and if <span class=\"ar\">عَن</span> or <span class=\"ar\">بِ</span> were substituted for <span class=\"ar\">عَلَى</span>, it would be correct. (TA.) -b2- See also 1. -b3- And see <span class=\"ar\">ضِنٌّ</span>.</p><p><b class=\"ar\">ضَنَانَةٌ</b> an inf. of 1 [q. v.]. (S &amp;c.) -b2- [Hence,] one says, <span class=\"ar\">هَجَمْتُ عَلَى القَوْمِ بِضَنَانَتِهِمْ</span>, meaning (assumed tropical:) [<i>I came suddenly upon the people,</i> or <i>party, in their close state,</i> i. e.,] <i>when they had not dispersed themselves.</i> (TA.) And <span class=\"ar\">أَخَذْتُ الأَمْرَ بِضَنَانَتِهِ</span> (assumed tropical:) [<i>I took to the affair</i>] <i>in its fresh state.</i> (TA.)</p><p><b class=\"ar\">ضَنِينَةٌ</b> ; and its pl. <span class=\"ar\">ضَنَائِنُ</span>: see <span class=\"ar\">ضِنٌّ</span>.</p><p><b class=\"ar\">مَضَنَّةٌ</b> : see <span class=\"ar\">ضِنَّةٌ</span>. -b2- <span class=\"ar\">هٰذَا عِلْقُ مَضَنَّةٍ</span> and <span class=\"ar\">مَضِنَّةٍ</span> [the former mentioned after the latter in the S] <i>This is a thing held in high estimation, of which one is tenacious,</i> (S, K, TA,) <i>and for which people vie in desire.</i> (TA.) [See also <span class=\"ar\">عِرْقٌ</span>, last sentence.]</p><p><b class=\"ar\">المَضْنُونُ</b> a name of [<i>The compound of perfumes commonly called</i>] <span class=\"ar\">الغَالِيَةُ</span>; (Ez-Zejjájee, S, K, TA;) as also <span class=\"ar\"> <span class=\"ar\">المَضْنُونَةُ</span></span>; (Ez-Zejjájee, S, * TA;) which latter is said by As to be <i>a sort of perfume;</i> and so is the former in the A: in the M the former is said to be <i>the oil of ben:</i> it is thus called because one is tenacious of it. (TA.) -b2- Also, (IKh, TA,) or <span class=\"ar\"> <span class=\"ar\">المَضْنُونَةُ</span></span>, (K, TA,) a name of <i>The well Zemzem.</i> (K, TA.)</p><p><b class=\"ar\">المَضْنُونَةُ</b> : see the next preceding paragraph, in two places.</p>"},"ضبح":{"mf":"قال تعالى: وَالْعادِياتِ ضَبْحاً<br>[العاديات/ ١]، قيل: الضَّبْحُ: صوتُ أنفاس الفرس تشبيها بالضِّبَاحِ، وهو صوت الثّعلب، وقيل: هو الخفيف العدو، وقد يقال ذلك للعدو، وقيل: الضَّبْحُ كالضّبع، وهو مدّ الضّبع في العدو، وقيل: أصله إحراق العود، شبّه عدوه به كتشبيهه بالنار في كثرة حركتها.","mq":[["صوت","تغير لون من فعل نار"],"الضاد والباء والحاء أصلانِ صحيحان: أحدهما صوتٌ، والآخَرُ تغيُّرُ لون من فعلِ نار.<br>فالأوَّل قولُهم: ضبَحَ الثّعلبُ يَضْبَح ضَبْحاً. وصَوْتُه الضُّبَاح، وهو ضابح.<br>قال:<br>دعوتُ ربِّى وهو لا يُخَيِّبُ … بأنّ فيها ضابحاً ثعَيلِبْ<br>فأمّا قولُه تعالى: ﴿وَاَلْعادِياتِ ضَبْحاً﴾ فيقال هو صوتُ أنفاسها، وهذا أقيَس"],"ln":"<p><b>1.</b> <b class=\"ar\">ضَبَحَتِ الخَيْلُ</b> , (AO, S, O, K, * [in the K <span class=\"ar\">ضَبَحَ</span>,]) aor. <b class=\"ar\">ضَبَحَ</b> , (K,) inf. n. <span class=\"ar\">ضَبْحٌ</span> (AO, S, K) and <span class=\"ar\">ضُبَاحٌ</span>, (K,) <i>i. q.</i> <span class=\"ar\">نَحَمَت</span>, i. e. [<i>The horses breathed pantingly,</i> or <i>hard, with a sound from the chest;</i> or] <i>made the breathing to be heard when running:</i> (S, O:) [or <i>breathed laboriously, when fatigued;</i> and in like manner one says of camels; for] <span class=\"ar\">ضَبْحٌ</span> signifies the <i>breathing</i> of horses and of camels <i>when fatigued:</i> (Suh, TA:) or <i>caused a sound to be heard from their mouths, different from neighing, and from the sound termed</i> <span class=\"ar\">حَمْحَمَةٌ</span>, (K, TA,) in their running: (TA:) [or it signifies also <i>the horses neighed;</i> for it is said that] <span class=\"ar\">الضُّبَاحُ</span> is also <i>syn. with</i> <span class=\"ar\">الصَّهِيلُ</span>: (TA:) or, [but probably only with the former of the two inf. ns. mentioned above,] <i>ran a pace less quick than that which is termed</i> <span class=\"ar\">تَقْرِيب</span>: (K, TA:) or <i>i. q.</i> <span class=\"ar\">ضَبَعَت</span>, (AO, S, O, TA,) which means <i>they stretched forth their arms,</i> (AO, TA,) <i>going along,</i> (AO, S, * O, TA,) or <i>running:</i> (AO, TA:) accord. to I'Ab, one does not say <span class=\"ar\">ضَبَحَتْ دَابَّةٌ</span> except in speaking of a dog or a horse: [he app. means that this verb is used thus only as denoting the uttering of a sound, or a manner of breathing:] some of the lexicologists say that those who use it in relation to a camel make <span class=\"ar\">ضَبْحٌ</span> to have the meaning of <span class=\"ar\">ضَبْعٌ</span>. (TA.) -b2- <span class=\"ar\">ضَبَحَ</span>, (L, TA,) inf. n. <span class=\"ar\">ضُبَاحٌ</span>, (S, A, O, L, K, TA,) as meaning <i>He,</i> or <i>it, uttered a cry,</i> or <i>sound,</i> is also said of the fox, (S, * A, * O, * L, K, * TA,) and of the hare, and of the serpent called <span class=\"ar\">أَسْوَد</span>, and of the owl, and of what is termed <span class=\"ar\">الصَّدَا</span> [which see, for it is variously explained]: (L, TA:) and is also expl. as meaning <span class=\"ar\">نَبَحَ</span> [<i>he barked,</i> &amp;c.]. (TA.) -b3- And <span class=\"ar\">ضَبَحَتِ القَوْسُ</span>, aor. as above, inf. n. <span class=\"ar\">ضَبْحٌ</span>, (assumed tropical:) <i>The bow</i> [<i>twanged,</i> or] <i>made a sound.</i> (TA.) -b4- And <span class=\"ar\">ضَبَحَ</span> is also used as meaning (tropical:) <i>He cried out, and entered into an altercation</i> for a person who had given him money. (IKt, O, * TA, from a trad.) -A2- <span class=\"ar\">ضَبَحَتْهُ</span> <span class=\"ar\">النَّارُ</span>, (S, O, K, TA,) and <span class=\"ar\">الشَّمْسُ</span>, aor. <b class=\"ar\">ضَبَحَ</b> , inf. n. <span class=\"ar\">ضَبْحٌ</span>, (TA,) <i>The fire,</i> and <i>the sun, altered it:</i> (TA:) or <i>altered its colour:</i> (T, TA:) or <i>altered it, but not in a great degree;</i> (S, O, K, TA;) namely, a thing, (K, TA,) such as a stick, and an arrow, and flesh-meat, &amp;c. (TA.) And <span class=\"ar\">ضَبَحَهُ</span> <span class=\"ar\">بِالنَّارِ</span>, aor. <b class=\"ar\">ضَبَحَ</b> , inf. n. <span class=\"ar\">ضَبْحٌ</span>, <i>He altered it in colour by fire;</i> namely, an arrow: and <i>he burned it in a portion of its upper parts;</i> namely, a stick, and flesh-meat, &amp;c. (L, TA.) And <span class=\"ar\">ضَبْحٌ</span> is expl. by AHn as meaning The act of <i>roasting, broiling,</i> or <i>frying.</i> (TA.)</p><p><b>3.</b> <b class=\"ar\">مُضَابَحَةٌ</b> The act of <i>mutual reviling,</i> or <i>vilifying,</i> and <i>encountering,</i> (K, TA,) and <i>contending,</i> or <i>striving, to repel.</i> (TA.)</p><p><b>6.</b> <b class=\"ar\">تضابح</b> [<i>It sent forth a sound</i>]. (Ham p. 615 [q. v.: it is there said to be from <span class=\"ar\">الضَّبْحُ</span> meaning <span class=\"ar\">الصَّوْتُ</span>].)</p><p><b>7.</b> <b class=\"ar\">انضبح</b> <i>It became altered,</i> (K, TA,) or <i>altered in colour,</i> (TA,) <i>but not in a great degree,</i> by fire, (K, TA,) and by the sun. (TA.) And <span class=\"ar\">انضبح لَوْنُهُ</span> <i>His,</i> or <i>its, colour became altered a little towards blackness.</i> (S, TA.)</p><p><b class=\"ar\">ضَبْحٌ</b> , (so in three copies of the S, and in the O,) or <span class=\"ar\"> <span class=\"ar\">ضِبْحٌ</span></span>, with kesr, (so accord. to the K,) <i>Ashes:</i> (S, O, K:) so called because of the alteration of their colour. (TA.)</p><p><b class=\"ar\">ضِبْحٌ</b> : see what next precedes.</p><p><b class=\"ar\">ضَبْحَةٌ</b> <i>A cry</i> of a fox [&amp;c.: an inf. n. un.]. (TA.)</p><p><b class=\"ar\">قَوْسٌ ضَبْحَآءُ</b> <i>A bow upon which fire has taken effect</i> (K, TA) <i>so as to alter its colour:</i> (TA:) like <span class=\"ar\">ضَهْبَآءُ</span>. (TA in art. <span class=\"ar\">ضهب</span>. [See also what next follows.])</p><p><b class=\"ar\">ضَبِيحٌ</b> An arrow <i>altered in colour</i> [by fire]; as also <span class=\"ar\"> <span class=\"ar\">مَضْبُوحٌ</span></span>. (TA. [See an ex. of the latter in a verse of Tarafeh cited voce <span class=\"ar\">مُجْمِدٌ</span>: and see also what here next precedes.]) It is also applied, (S, O,) in the same sense, (O,) to roasted flesh-meat. (S, O.) [And Freytag explains it as meaning, in the Deewan of Jereer, “ Cutis nigra, usta vulneribus. ”]</p><p><b class=\"ar\">ضَابِحٌ</b> A man <i>raising his voice in reading</i> or <i>reciting:</i> pl. <span class=\"ar\">ضَوَابِحُ</span>, which is anomalous, like <span class=\"ar\">فَوَارِسُ</span> [pl. of <span class=\"ar\">فَارِسٌ</span>]. (TA.) -b2- And <span class=\"ar\">خَيْلٌ ضَوَابِحُ</span> <i>Horses stretching forth their arms in their going along:</i> (A:) or <i>running vehemently;</i> like <span class=\"ar\">ضَوَابِعُ</span>. (TA in art. <span class=\"ar\">ضبع</span>.)</p><p><b class=\"ar\">مَضْبُوحٌ</b> : see <span class=\"ar\">ضَبِيحٌ</span>. -b2- Also The <i>stone that is in the</i> [<i>kind of ground called</i>] <span class=\"ar\">حَرَّة</span> [q. v.]: because of its blackness. (TA.) And <span class=\"ar\">مَضْبُوحَةٌ</span> <i>Stones from which one strikes fire,</i> (S, O, K,) <i>appearing as though burnt.</i> (S, O.)</p><p><b class=\"ar\">مَضَابِحُ</b> [a pl. of which the sing. is most probably <span class=\"ar\">مِضْبَحٌ</span>] <i>Frying-pans.</i> (AHn, TA.)</p>"}});
